# ----------------------------------------------------------------------------
# Счётчик сообщений: считает КАЖДОЕ сообщение в группе для /профиль и /топ.
# Зарегистрирован как outer-middleware, поэтому срабатывает независимо от того,
# какой (и есть ли вообще) хендлер обработает сообщение дальше.
# ----------------------------------------------------------------------------
# Список слов-фильтров в памяти (нижний регистр). Заполняется в load_caches()
# из db.list_filter_words(), обновляется по сигналу из панели (см.
# panel_action_reload_loop). Сообщения с этими словами бот удаляет.
WORD_FILTER: set[str] = set()


async def _enforce_word_filter(event: "Message") -> bool:
    """Удаляет сообщение, если в нём есть слово из фильтра. True — удалено (и
    дальше его обрабатывать не нужно).

    Админы (модератор и выше) освобождены: им нужно обсуждать модерацию и сам
    фильтр, и они не спамят. Проверяем и text, и caption — запрещённое слово
    прячут и в подписи к картинке.
    """
    if not WORD_FILTER or is_admin(event.from_user.id):
        return False
    hit = word_filter.find_banned(event.text or event.caption, WORD_FILTER)
    if hit is None:
        return False
    try:
        await event.delete()
    except (TelegramBadRequest, TelegramForbiddenError):
        # Нет прав на удаление или сообщение уже исчезло — не роняем поток.
        return True
    await db.add_log(
        "word_filter_deleted", chat_id=event.chat.id,
        actor_id=event.from_user.id, details=hit,
    )
    try:
        if not event.from_user.is_bot and await _enforce_auto_delete(event):
            return
    except Exception:
        logger.exception("Ошибка автоудаления")
    try:
        if not event.from_user.is_bot and await _enforce_word_filter(event):
            return
    except Exception:
        logger.exception("Ошибка фильтра слов")
    return True

async def _enforce_auto_delete(event: "Message") -> bool:
    """Удаляет сообщение, если автор — в списке автоудаления привязанного
    чата жалоб (settings.complaint_chat_id). True — удалено."""
    complaint_chat_id = settings.get("complaint_chat_id")
    if not complaint_chat_id or event.chat.id != complaint_chat_id:
        return False
    if is_admin(event.from_user.id):
        return False
    if not await db.is_auto_delete_target(complaint_chat_id, event.from_user.id):
        return False
    try:
        await event.delete()
    except (TelegramBadRequest, TelegramForbiddenError):
        return True
    return True


class MessageCounterMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        if (
            isinstance(event, Message)
            and event.chat.type in ("group", "supergroup")
            and event.from_user is not None
        ):
            # Фильтр слов — до счётчиков: удалённый спам не должен попадать ни
            # в статистику, ни в ленту, ни к обработчикам команд.
            try:
                if not event.from_user.is_bot and await _enforce_word_filter(event):
                    return
            except Exception:
                logger.exception("Ошибка фильтра слов")
            try:
                # Статистика/счётчики (/профиль, /топ, known_users) — только
                # по людям: иначе спам от ботов в чате искажал бы рейтинги.
                if not event.from_user.is_bot:
                    now = datetime.utcnow()
                    await db.increment_message_count(event.chat.id, event.from_user.id)
                    await db.increment_daily_count(event.chat.id, event.from_user.id, now.date())
                    await db.increment_hourly_count(event.chat.id, event.from_user.id, now.date(), now.hour)
                    await db.upsert_known_user(
                        event.chat.id,
                        event.from_user.id,
                        event.from_user.full_name or str(event.from_user.id),
                        event.from_user.username,
                    )
                    await db.upsert_current_user(
                        event.chat.id, event.from_user.id,
                        event.from_user.full_name or str(event.from_user.id), event.from_user.username,
                    )
                    await db.clear_unreg(event.chat.id, event.from_user.id)
                    user_registry[event.from_user.id] = {
                        "full_name": event.from_user.full_name or str(event.from_user.id),
                        "username": event.from_user.username,
                    }
                    await check_message_achievements(event.chat.id, event.from_user.id, now)
                    # +рстик: изредка бот сам кидает случайный стикер из набора
                    # цитат чата (созданного через .цитата стикер). Кубик бросаем
                    # синхронно и без БД; проверку тумблера и отправку — в фон,
                    # чтобы не тормозить обработку самого сообщения.
                    if event.sticker is None and random.random() < RSTICK_CHANCE:
                        asyncio.create_task(_send_random_sticker_if_on(event.chat.id))
                # А вот кольцевой буфер последних сообщений («.стикер N») —
                # по ВСЕМ, включая ботов: иначе сообщение бота нельзя
                # склеить в стикер вместе с соседними человеческими.
                await _remember_recent_message(event)
            except Exception:
                logger.exception("Не удалось обновить счётчик сообщений")
            try:
                if not event.from_user.is_bot and await _enforce_word_filter(event):
                    return
            except Exception:
                logger.exception("Ошибка фильтра слов")
            try:
                if not event.from_user.is_bot and await _enforce_slowmode(event):
                    return
            except Exception:
                logger.exception("Ошибка медленного режима")
        cleanup_token = None
        complaint_chat_id = settings.get("complaint_chat_id")
        if (
            isinstance(event, Message)
            and complaint_chat_id
            and event.chat.id == complaint_chat_id
            and is_command_like(event.text or event.caption)
        ):
            minutes = cmd_cleanup_minutes()
            if minutes > 0:
                delete_at = datetime.utcnow() + timedelta(minutes=minutes)
                try:
                    await db.add_cleanup_entry(event.chat.id, event.message_id, delete_at)
                except Exception:
                    logger.exception("Не удалось запланировать очистку команды")
                cleanup_token = _cleanup_context.set((event.chat.id, delete_at))

        try:
            return await handler(event, data)
        finally:
            if cleanup_token is not None:
                _cleanup_context.reset(cleanup_token)


router.message.outer_middleware(MessageCounterMiddleware())


# ----------------------------------------------------------------------------
# Учёт новых участников: как только человек вступает в чат, бот заносит его
# в known_users сразу — не нужно ждать, пока он что-то напишет. Так список
# для выбора цели жалобы пополняется быстрее (но по-прежнему это не «все
# участники чата», а те, кого бот видел — Telegram Bot API не отдаёт ботам
# полный список участников группы). Заодно фиксируем first_seen_at (для
# «Олды»/«Новички») и invited_by — кто пригласил (для «Кто добавил»),
# если это сделал не сам вступивший, а кто-то другой.
# ----------------------------------------------------------------------------
# ----------------------------------------------------------------------------
# Входы и выходы приходят боту двумя разными путями:
#   • служебным сообщением в чате (new_chat_members / left_chat_member);
#   • апдейтом chat_member — единственным, который Telegram шлёт и в больших
#     супергруппах, где служебных сообщений уже нет.
#
# Обрабатывать надо оба, иначе в реальной супергруппе выходы теряются, и в
# базе копятся «мёртвые души»: роли остаются занятыми людьми, которых давно
# нет в чате. Но в маленьких группах приходят ОБА события сразу, поэтому
# ниже стоит защита от повторной обработки.
# ----------------------------------------------------------------------------
_MEMBER_EVENT_TTL = 60.0
_member_events_seen: dict = {}


def _member_event_is_new(chat_id: int, user_id: int, kind: str) -> bool:
    """False — такое же событие уже обработали только что (пришло вторым путём)."""
    now = time.monotonic()
    for key, seen_at in list(_member_events_seen.items()):
        if now - seen_at > _MEMBER_EVENT_TTL:
            _member_events_seen.pop(key, None)
    key = (chat_id, user_id, kind)
    if key in _member_events_seen:
        return False
    _member_events_seen[key] = now
    return True


async def handle_member_joined(chat_id: int, user, inviter_id: Optional[int]) -> None:
    """Общая обработка вступления — из служебного сообщения или из chat_member."""
    if user is None or user.is_bot:
        return
    if not _member_event_is_new(chat_id, user.id, "join"):
        return
    try:
        await db.upsert_known_user(
            chat_id,
            user.id,
            user.full_name or str(user.id),
            user.username,
            invited_by=inviter_id if inviter_id != user.id else None,
        )
        await db.upsert_current_user(
            chat_id, user.id, user.full_name or str(user.id), user.username,
        )
        user_registry[user.id] = {
            "full_name": user.full_name or str(user.id),
            "username": user.username,
        }
        # Модуль «Роли»: если за этим человеком была бронь роли — она
        # реализуется в момент вступления (см. ТЗ, сценарий 2, п.3).
        granted = await db.resolve_reservations_on_join(chat_id, user.id)
        for role in granted:
            await db.add_log("role_grant_on_join", chat_id=chat_id, actor_id=user.id, details=role["name"])
            await sync_role_title(chat_id, user.id)
            try:
                await bot.send_message(
                    chat_id,
                    f"🎖 {mention_id(user.id)}, за вами была бронь — роль «{html.escape(role['name'])}» "
                    "закреплена за вами."
                )
            except Exception:
                pass

        # Настраиваемое приветствие в самой группе (см. admin-панель →
        # «Тексты сообщений» → «Приветствие в группе (вход)»).
        join_text = group_join_text()
        if join_text:
            try:
                rendered = join_text.format(user=mention_id(user.id))
            except Exception:
                rendered = join_text  # в тексте нет {user} или он сломан — шлём как есть
            try:
                await bot.send_message(chat_id, rendered)
            except Exception:
                logger.exception("Не удалось отправить приветствие в группе для user_id=%s", user.id)

        # Уведомление «зашёл в чат» (если включено «+входы»). Отдельно от
        # приветствия выше: приветствие обращено к самому новичку, а это —
        # короткая строчка для чата, с текущим числом участников.
        if await is_join_notify_enabled(chat_id):
            phrase = random.choice(_JOIN_PHRASES).format(user=mention_id(
                user.id, full_name=user.full_name, username=user.username
            ))
            total = await _members_count(chat_id)
            if total:
                phrase += f" Нас уже {total}."
            try:
                await bot.send_message(chat_id, phrase)
            except Exception:
                logger.exception("Не удалось отправить уведомление о входе")

        # Если в чате настроен список ролей и у вступившего ещё нет роли/брони —
        # просим выбрать её в личке с ботом (если бронь только что закрыла
        # вопрос — prompt_role_pick_after_join сам тихо ничего не пришлёт).
        await prompt_role_pick_after_join(chat_id, user.id)
    except Exception:
        logger.exception("Не удалось сохранить нового участника чата")


async def handle_member_left(chat_id: int, user) -> None:
    """Общая обработка выхода: чистим ростер, подписки и освобождаем роль.

    Роль именно освобождается, а не удаляется — она остаётся в списке чата и
    снова доступна для выбора.
    """
    if user is None or user.is_bot:
        return
    if not _member_event_is_new(chat_id, user.id, "leave"):
        return
    try:
        if await is_leave_notify_enabled(chat_id):
            phrase = random.choice(_LEAVE_PHRASES).format(user=mention_id(
                user.id, full_name=user.full_name, username=user.username
            ))
            total = await _members_count(chat_id)
            if total:
                phrase += f" Осталось {total}."
            try:
                await bot.send_message(chat_id, phrase)
            except Exception:
                logger.exception("Не удалось отправить уведомление о выходе")

        await db.delete_current_user(chat_id, user.id)
        await db.delete_call_data(chat_id, user.id)
        # подписки вышедшего — и его собственные, и чужие на него
        await db.delete_subscriptions_of_user(chat_id, user.id)
        await db.delete_reputation_of_user(chat_id, user.id)
        freed_name = await db.release_role_by_holder(chat_id, user.id)
        if freed_name:
            await db.add_log("role_free_on_leave", chat_id=chat_id, actor_id=user.id, details=freed_name)
            try:
                await bot.send_message(
                    chat_id, f"Роль «{html.escape(freed_name)}» освобождена — участник покинул чат."
                )
            except Exception:
                pass
    except Exception:
        logger.exception("Не удалось обработать выход участника из чата")


@router.message(F.chat.type.in_({"group", "supergroup"}), F.new_chat_members)
async def track_new_chat_members(message: Message):
    inviter_id = message.from_user.id if message.from_user else None
    for user in message.new_chat_members:
        await handle_member_joined(message.chat.id, user, inviter_id)


@router.message(F.chat.type.in_({"group", "supergroup"}), F.left_chat_member)
async def track_left_chat_member(message: Message):
    await handle_member_left(message.chat.id, message.left_chat_member)


@router.chat_member(ChatMemberUpdatedFilter(member_status_changed=JOIN_TRANSITION))
async def track_member_joined_update(event: ChatMemberUpdated):
    """Вступление через chat_member — работает и там, где Telegram уже не
    присылает служебных сообщений."""
    if event.chat.type not in ("group", "supergroup"):
        return
    inviter_id = event.from_user.id if event.from_user else None
    await handle_member_joined(event.chat.id, event.new_chat_member.user, inviter_id)


@router.chat_member(ChatMemberUpdatedFilter(member_status_changed=LEAVE_TRANSITION))
async def track_member_left_update(event: ChatMemberUpdated):
    """Выход/кик/бан через chat_member — основной путь в супергруппах."""
    if event.chat.type not in ("group", "supergroup"):
        return
    await handle_member_left(event.chat.id, event.new_chat_member.user)


# ----------------------------------------------------------------------------
