@router.message(CommandStart(), F.chat.type == "private")
async def cmd_start(message: Message, state: FSMContext):
    await state.clear()
    if is_admin(message.from_user.id):
        status = "✅ Бот полностью настроен." if settings_configured() else "⚠️ Настройка ещё не завершена."
        my_level = get_level(message.from_user.id)
        panel_hint = (
            "Кнопка «Админка» ниже (или слово «админка») откроет панель настроек."
            if my_level >= LEVEL_SENIOR
            else "Панель настроек («админка») доступна только старшим администраторам (3 уровень) и владельцу."
        )
        role_hint = (
            "\nКнопка «Моя роль» — временно посмотреть на бота глазами участника, "
            "модератора, администратора или старшего, и вернуть полные права в один тап."
            if is_owner(message.from_user.id)
            else ""
        )
        await message.answer(
            "Привет, админ! Это бот для приёма заявок на вход в группу + РП-система в чатах.\n\n"
            "Пользователи пишут сюда сообщение с просьбой на вход, вы видите его в "
            "топике вашей группы и можете ответить прямо оттуда или выдать ссылку одной кнопкой.\n\n"
            f"Ваш уровень прав: {level_name(my_level)}\n"
            f"{status}\n\n"
            f"{panel_hint}\n"
            "Кнопка «Логи» — последние события бота.\n"
            "Слово «помощь» в группе — список всех команд модерации (там же появятся кнопки быстрого доступа)."
            f"{role_hint}\n\n"
            "Ниже — кнопки для самых частых действий, чтобы не набирать команды вручную."
        )
        await message.answer("⌨️ Быстрые кнопки:", reply_markup=private_menu_kb(message.from_user.id))
        return
    if message.from_user.id in custom_responses:
        await message.answer(custom_responses[message.from_user.id], reply_markup=private_menu_kb(message.from_user.id))
        return
    await message.answer(welcome_text(), reply_markup=private_menu_kb(message.from_user.id))
    # await _maybe_ask_birthday(message)
    existing_bday = await db.get_birthday(message.from_user.id)
    
    if not existing_bday:
        await message.answer(
            "🎂 Хотите, буду поздравлять вас с днём рождения в чате? "
            "Можно указать дату сейчас или пропустить — вернуться к этому можно "
            "в любой момент командой «мой днр».",
            reply_markup=birthday_ask_kb(),
        )

