BIRTHDAY_RE = re.compile(r"^(\d{1,2})[.\-/](\d{1,2})(?:[.\-/](\d{2,4}))?$")


@router.message(StateFilter(BirthdayStates.waiting_birthday), F.chat.type == "private")
async def birthday_process_input(message: Message, state: FSMContext):
    text = (message.text or "").strip()
    m = BIRTHDAY_RE.match(text)
    if not m:
        await message.answer("Не понял дату. Пришлите в формате <b>ДД.ММ</b>, например 05.09.")
        return

    day, month, year = int(m.group(1)), int(m.group(2)), m.group(3)
    year = int(year) if year else None
    if year and year < 100:
        year += 2000 if year < 30 else 1900

    try:
        date(year or 2000, month, day)  # валидация существования даты
    except ValueError:
        await message.answer("Такой даты не существует. Проверьте и пришлите ещё раз, например 05.09.")
        return

    await db.set_birthday(message.from_user.id, day, month, year)
    await state.clear()
    await message.answer(
        f"✅ Записал: {day:02d}.{month:02d}. Буду поздравлять в чатах, где вы есть. "
        "Изменить дату можно командой «мой днр»."
    )


