# ----------------------------------------------------------------------------
# Поиск по справке: «помощь ачивки», «помощь бан», «помощь как позвать».
# Команд почти две сотни, и листать кнопками в поисках нужной — долго;
# поиск сразу показывает и сами команды, и разделы, где про них написано.
# ----------------------------------------------------------------------------
HELP_SEARCH_MAX_COMMANDS = 12
HELP_SEARCH_MAX_SECTIONS = 6


def _search_commands(query: str) -> list:
    """Команды из реестра, подходящие под запрос."""
    q = query.casefold()
    found = []
    for key, meta in COMMAND_REGISTRY.items():
        haystack = f"{meta['phrase']} {key} {meta['category']}".casefold()
        if q in haystack:
            found.append((key, meta))
    return found


def _search_help_sections(query: str) -> list:
    """Подразделы справки, в тексте которых встречается запрос."""
    q = query.casefold()
    found = []
    for section_key, section in HELP_SECTIONS.items():
        for sub_key, sub in (section.get("subsections") or {}).items():
            haystack = f"{sub.get('title', '')} {sub.get('text', '')}".casefold()
            if q in haystack:
                found.append((section_key, sub_key, section["title"], sub["title"]))
    return found


@router.message(
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] in ("помощь", "хелп")
                and len(t.strip().split()) > 1)
)
async def cmd_help_search(message: Message):
    query = message.text.strip().split(maxsplit=1)[1].strip()
    if len(query) < 2:
        await message.reply("Что искать? Например: <code>помощь ачивки</code>")
        return

    commands = _search_commands(query)
    sections = _search_help_sections(query)

    if not commands and not sections:
        await message.reply(
            f"🔍 По запросу «{html.escape(query)}» ничего не нашлось.\n"
            "Попробуйте одно слово — например «бан», «роль», «ачивки». "
            "Или откройте разделы командой «помощь»."
        )
        return

    lines = [f"🔍 <b>Поиск: «{html.escape(query)}»</b>"]

    if commands:
        lines.append("")
        lines.append(f"<b>Команды ({len(commands)}):</b>")
        for key, meta in commands[:HELP_SEARCH_MAX_COMMANDS]:
            level = required_level(key)
            suffix = f" — <i>{level_name(level)}+</i>" if level else ""
            lines.append(f"• {html.escape(meta['phrase'])}{suffix}")
        if len(commands) > HELP_SEARCH_MAX_COMMANDS:
            lines.append(f"…и ещё {len(commands) - HELP_SEARCH_MAX_COMMANDS}. Уточните запрос.")

    buttons: list = []
    if sections:
        lines.append("")
        lines.append("<b>Разделы справки:</b>")
        seen = set()
        for section_key, sub_key, section_title, sub_title in sections[:HELP_SEARCH_MAX_SECTIONS]:
            if (section_key, sub_key) in seen:
                continue
            seen.add((section_key, sub_key))
            lines.append(f"• {section_title} → {sub_title}")
            buttons.append([InlineKeyboardButton(
                text=sub_title, callback_data=f"help_subsec:{section_key}:{sub_key}"
            )])

    buttons.append([InlineKeyboardButton(text="📖 Все разделы", callback_data="help_menu")])
    await message.reply(
        "\n".join(lines), reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons)
    )


