async def process_rest_template(message: Message, state: FSMContext):
    if not has_level(message.from_user.id, LEVEL_SENIOR):
        return
    raw = (message.text or "").strip()
    if raw == "-":
        # Пустая настройка = «взять DEFAULT_REST_TEMPLATE» (см. rest_template()),
        # поэтому сброс — это очистка, а не запись дефолта в базу: обновится
        # текст в коде — обновится и памятка.
        await db.save_setting("rest_rules_template", "")
        settings["rest_rules_template"] = ""
        await message.answer("↩️ Памятка возвращена к тексту по умолчанию.")
        await _show_rest_menu(message, state)
        return
    value = message.html_text or message.text
    if not value or not value.strip():
        await message.answer("Нужен текст. Пришлите памятку или «-» для сброса.", reply_markup=cancel_kb())
        return
    await db.save_setting("rest_rules_template", value)
    settings["rest_rules_template"] = value
    await message.answer("✅ Памятка о ресте обновлена.")
    await _show_rest_menu(message, state)


