@router.message(StateFilter(AdminStates.waiting_rest_limit), F.chat.type == "private")
async def process_rest_limit(message: Message, state: FSMContext):
    if not has_level(message.from_user.id, LEVEL_SENIOR):
        return
    key = (await state.get_data()).get("rest_limit_key")
    if key not in REST_LIMIT_FIELDS:
        # Данные состояния потерялись (перезапуск бота с памятью в RAM) —
        # молча вернуть в меню честнее, чем сохранить число не туда.
        await _show_rest_menu(message, state)
        return
    field = REST_LIMIT_FIELDS[key]
    raw = (message.text or "").strip()

    if field["kind"] == "date":
        if raw == "-":
            value = ""
        elif rest_rules.parse_settings_date(raw) is not None:
            value = raw
        else:
            await message.answer(
                "Не похоже на дату. Нужен формат ДД.ММ.ГГГГ, например 01.08.2026, "
                "либо «-», чтобы убрать дату чистки.",
                reply_markup=cancel_kb(),
            )
            return
    else:
        days = rest_rules.parse_days_setting(raw)
        if days is None:
            await message.answer(
                f"Нужно целое число дней от 0 до {rest_rules.DAYS_SETTING_MAX}. "
                "0 — правило не проверяется.",
                reply_markup=cancel_kb(),
            )
            return
        value = str(days)

    await db.save_setting(key, value)
    settings[key] = value
    await message.answer(f"✅ Сохранено: <code>{rest_limit_display(key)}</code>")
    await _show_rest_menu(message, state)


