@router.message(StateFilter(AdminStates.waiting_new_admin), F.chat.type == "private")
async def process_new_admin(message: Message, state: FSMContext):
    actor_level = get_level(message.from_user.id)
    if actor_level < LEVEL_SENIOR:
        return

    new_id = None
    if message.forward_from:
        new_id = message.forward_from.id
    elif message.text and message.text.strip().isdigit():
        new_id = int(message.text.strip())

    if new_id is None:
        await message.answer(
            "Не удалось распознать пользователя. Перешлите его сообщение или пришлите числовой ID.",
            reply_markup=cancel_kb(),
        )
        return

    if new_id in OWNER_IDS:
        await message.answer("Этот пользователь уже владелец бота.")
        await _show_main_menu(message, state)
        return

    # Максимальный уровень, который actor может выдать — свой уровень минус 1
    # (владелец, у которого actor_level=99, может выдавать вплоть до 3).
    max_grantable = LEVEL_SENIOR if actor_level >= OWNER_LEVEL else actor_level - 1
    pending_confirmations[message.from_user.id] = {"action": "new_admin", "target_id": new_id}
    await state.set_state(AdminStates.menu_admin_level_pick)
    await message.answer(
        f"👤 Пользователь: {mention_id(new_id)}\n\nВыберите уровень прав:",
        reply_markup=admin_level_pick_kb(max_grantable),
    )


@router.message(F.chat.type == "private", StateFilter(AdminStates.menu_admin_level_pick), F.text == BTN_CANCEL)
async def admin_add_level_cancel(message: Message, state: FSMContext):
    pending_confirmations.pop(message.from_user.id, None)
    await state.set_state(AdminStates.menu_admins)
    await message.answer(await admins_list_text(message.from_user.id), reply_markup=admins_menu_kb(message.from_user.id))


@router.message(F.chat.type == "private", StateFilter(AdminStates.menu_admin_level_pick))
async def admin_add_level(message: Message, state: FSMContext):
    actor_id = message.from_user.id
    actor_level = get_level(actor_id)
    level = None
    for lvl, name in LEVEL_NAMES.items():
        if (message.text or "").strip() == name:
            level = lvl
            break
    if level is None:
        await message.answer("Пожалуйста, выберите уровень с клавиатуры ниже.")
        return
    max_grantable = LEVEL_SENIOR if actor_level >= OWNER_LEVEL else actor_level - 1
    if level > max_grantable or level < LEVEL_MODERATOR:
        await message.answer("Нельзя выдать уровень выше своего.")
        return

    payload = pending_confirmations.pop(actor_id, None)
    if not payload or payload.get("action") != "new_admin":
        await message.answer("Запрос устарел, начните заново.")
        await _show_main_menu(message, state)
        return
    new_id = payload["target_id"]

    await db.set_admin(new_id, level, added_by=actor_id)
    admin_levels[new_id] = level
    await db.add_log("admin_added", actor_id=actor_id, target_id=new_id, details=level_name(level))

    await message.answer(f"✅ Пользователь {mention_id(new_id)} назначен: {level_name(level)}.")
    await state.set_state(AdminStates.menu_admins)
    await message.answer(await admins_list_text(actor_id), reply_markup=admins_menu_kb(actor_id))

    try:
        await bot.send_message(
            new_id,
            f"🎉 Вас назначили администратором бота ({level_name(level)}).\n"
            "Слово «админка» — открыть панель (если доступна вашему уровню), «помощь» — список команд модерации.",
        )
    except Exception:
        pass


@router.message(F.chat.type == "private", StateFilter(AdminStates.menu_admins), F.text.func(lambda t: bool(t) and re.match(r"^❌ .+\((\d+)\)$", t.strip())))
async def admin_remove_ask(message: Message, state: FSMContext):
    actor_id = message.from_user.id
    target_id = int(re.match(r"^❌ .+\((\d+)\)$", message.text.strip()).group(1))
    target_level = get_level(target_id)
    if get_level(actor_id) <= target_level:
        await message.answer("Можно снимать только админов уровнем ниже своего.")
        return
    await state.update_data(remove_target=target_id)
    await state.set_state(AdminStates.menu_admin_remove_confirm)
    await message.answer(
        confirm_text(
            "Удалить администратора?",
            [f"🛡 {mention_id(target_id)} ({level_name(target_level)})", "Человек потеряет свои права в боте."],
            irreversible=False,
        ),
        reply_markup=private_confirm_kb("❌ Да, удалить"),
    )


@router.message(F.chat.type == "private", StateFilter(AdminStates.menu_admin_remove_confirm), F.text.func(lambda t: bool(t) and t.strip().startswith("❌ Да, удалить")))
async def admin_remove(message: Message, state: FSMContext):
    actor_id = message.from_user.id
    data = await state.get_data()
    target_id = data.get("remove_target")
    target_level = get_level(target_id) if target_id is not None else None
    if target_id is None or get_level(actor_id) <= target_level:
        await message.answer("Можно снимать только админов уровнем ниже своего.")
    elif target_id in admin_levels:
        await db.remove_admin(target_id)
        admin_levels.pop(target_id, None)
        await db.add_log("admin_removed", actor_id=actor_id, target_id=target_id)
        await message.answer("Удалено ✅")
    await state.set_state(AdminStates.menu_admins)
    await message.answer(await admins_list_text(actor_id), reply_markup=admins_menu_kb(actor_id))


