def special_menu_text() -> str:
    if not custom_responses:
        return (
            "🎭 <b>Особые ответы для пользователей</b>\n\n"
            "Список пуст. Добавьте пользователя, чтобы вместо обычной заявки/приветствия "
            "он получал от бота настроенный вами текст."
        )
    lines = []
    for user_id, text in custom_responses.items():
        preview = html.escape(text[:60]) + ("…" if len(text) > 60 else "")
        lines.append(f"👤 {mention_id(user_id)} — {preview}")
    return (
        f"🎭 <b>Особые ответы для пользователей</b> — {len(custom_responses)}\n{DIVIDER}\n"
        + "\n".join(lines)
        + "\n\nТакие пользователи вместо обычной заявки/приветствия получат в личке "
        "именно этот текст, что бы они ни написали боту."
    )


