# ----------------------------------------------------------------------------
# Жалобы — полностью в личке бота.
#   «жалоба»  — любой пользователь: подать жалобу (на кого / аноним или нет / причина)
#   «жалобы»  — админы (уровень настраивается, ключ «complaints»): раздел разбора жалоб
# ----------------------------------------------------------------------------
async def user_label(user_id: int) -> str:
    """Тег/имя-ссылка пользователя для показа в личке админа, без привязки к чату.
    Пытается получить актуальные данные напрямую у Telegram (работает, если бот
    когда-либо взаимодействовал с этим пользователем), иначе — берёт из кэша."""
    try:
        chat = await bot.get_chat(user_id)
        username = getattr(chat, "username", None)
        full_name = getattr(chat, "full_name", None)
        return mention_id(user_id, full_name=full_name, username=username)
    except Exception:
        return mention_id(user_id)


def complaint_cancel_kb() -> ReplyKeyboardMarkup:
    return _reply_kb([[BTN_CANCEL]])


def complaint_visibility_kb() -> ReplyKeyboardMarkup:
    return _reply_kb([
        ["🙈 Анонимно", "🙋 Публично"],
        [BTN_CANCEL],
    ])


COMPLAINT_PICKER_PAGE_SIZE = 8


async def sync_known_admins(chat_id: int) -> None:
    """Подтягивает администраторов чата в known_users, даже если они сами
    ни разу не писали сообщений — список админов Telegram отдаёт боту всегда,
    в отличие от полного списка участников."""
    try:
        members = await bot.get_chat_administrators(chat_id)
    except Exception:
        return
    for member in members:
        user = member.user
        if user.is_bot:
            continue
        try:
            await db.upsert_known_user(chat_id, user.id, user.full_name or str(user.id), user.username)
            await db.upsert_current_user(chat_id, user.id, user.full_name or str(user.id), user.username)
            user_registry[user.id] = {
                "full_name": user.full_name or str(user.id),
                "username": user.username,
            }
        except Exception:
            logger.exception("Не удалось сохранить администратора чата в known_users")


async def complaint_picker_page(chat_id: int, page: int, query: Optional[str] = None) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    """Инлайн-список известных боту участников чата `chat_id`, постранично,
    с опциональным поиском по имени/юзернейму. Список — это не «все участники
    чата» (Telegram Bot API такого не отдаёт), а те, кого бот реально видел:
    кто писал сообщения, вступал в чат при бote, или является администратором."""
    page = max(page, 0)
    if query:
        rows, total = await db.search_known_users(chat_id, query, limit=COMPLAINT_PICKER_PAGE_SIZE, offset=page * COMPLAINT_PICKER_PAGE_SIZE)
    else:
        rows, total = await db.list_known_users(chat_id, limit=COMPLAINT_PICKER_PAGE_SIZE, offset=page * COMPLAINT_PICKER_PAGE_SIZE)

    if not rows:
        if query:
            return f"По запросу «{html.escape(query)}» никого не нашлось.", None
        return "Список участников этого чата пока пуст — бот ещё никого там не видел.", None

    buttons = []
    for row in rows:
        label = row["full_name"]
        if row.get("username"):
            label += f" (@{row['username']})"
        buttons.append([InlineKeyboardButton(text=label[:64], callback_data=f"cpick:{row['user_id']}")])

    pages = (total + COMPLAINT_PICKER_PAGE_SIZE - 1) // COMPLAINT_PICKER_PAGE_SIZE
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"cpick_page:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"cpick_page:{page + 1}"))
    if nav:
        buttons.append(nav)

    prefix = f"Результаты по «{html.escape(query)}»" if query else f"Известно боту участников: {total}"
    return prefix, InlineKeyboardMarkup(inline_keyboard=buttons)


@router.callback_query(F.data.startswith("cpick_page:"), StateFilter(ComplaintStates.waiting_target))
async def complaint_picker_paginate(callback: CallbackQuery, state: FSMContext):
    try:
        page = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось открыть эту страницу.", show_alert=True)
        return
    data = await state.get_data()
    chat_id = data.get("complaint_picker_chat")
    query = data.get("complaint_picker_query")
    if not chat_id:
        await callback.answer("Список устарел, начните заново словом «жалоба».", show_alert=True)
        return
    text, kb = await complaint_picker_page(chat_id, page, query)
    try:
        await callback.message.edit_text("Выберите из списка (или напишите часть имени для поиска):\n\n" + text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("cpick:"), StateFilter(ComplaintStates.waiting_target))
async def complaint_picker_select(callback: CallbackQuery, state: FSMContext):
    try:
        target_id = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось распознать пользователя.", show_alert=True)
        return

    if target_id == callback.from_user.id:
        await callback.answer("Нельзя пожаловаться на самого себя 🙂", show_alert=True)
        return
    if target_id == bot.id:
        await callback.answer("На бота жаловаться нет смысла 🤖", show_alert=True)
        return

    await state.update_data(complaint_target=target_id)
    await state.set_state(ComplaintStates.waiting_visibility)
    try:
        await callback.message.edit_text("✅ Пользователь выбран.")
    except TelegramBadRequest:
        pass
    await callback.answer()

    label = await user_label(target_id)
    await bot.send_message(
        callback.from_user.id,
        f"🎯 Жалоба на: {label}\n\n"
        "Показать администраторам, кто пожаловался?\n"
        "🙈 Анонимно — админы не увидят вас\n"
        "🙋 Публично — админы увидят, кто пожаловался",
        reply_markup=complaint_visibility_kb(),
    )


def complaints_targets_text(rows: list[dict]) -> str:
    if not rows:
        return "🚨 <b>Жалобы</b>\n\nПока ни на кого не жаловались."
    lines = []
    for row in rows:
        pending = row["pending"] or 0
        badge = f" · 🆕{pending}" if pending else ""
        lines.append(f"• {mention_id(row['target_id'])} — жалоб: {row['total']}{badge}")
    return f"🚨 <b>Жалобы — фигурирует {len(rows)} чел.</b>\n{DIVIDER}\n" + "\n".join(lines)


def complaints_targets_kb(rows: list[dict]) -> ReplyKeyboardMarkup:
    items = []
    for row in rows:
        pending = row["pending"] or 0
        items.append(f"👤 {row['target_id']} — {row['total']}" + (f" (🆕{pending})" if pending else ""))
    kb_rows = _grid(items)
    kb_rows.append(["👥 Список для жалоб", "🔄 Обновить"])
    kb_rows.append([BTN_BACK])
    return _reply_kb(kb_rows)


def complaint_roster_text(rows: list[dict]) -> str:
    if not rows:
        return (
            "👥 <b>Список людей для жалоб</b>\n\n"
            "Пока никого нет. Добавьте людей вручную — они появятся кнопками у того, "
            "кто будет подавать жалобу через «жалоба»."
        )
    lines = []
    for row in rows:
        label = html.escape(row["full_name"])
        if row.get("username"):
            label += f" (@{row['username']})"
        link = f'<a href="tg://user?id={row["user_id"]}">{label}</a>'
        lines.append(f"• {link} — <code>{row['user_id']}</code>")
    return f"👥 <b>Список людей для жалоб ({len(rows)})</b>\n{DIVIDER}\n" + "\n".join(lines)


def complaint_roster_kb(rows: list[dict]) -> ReplyKeyboardMarkup:
    items = [f"🗑 {row['full_name']} — {row['user_id']}" for row in rows]
    kb_rows = _grid(items, cols=1)
    kb_rows.append(["➕ Добавить человека", BTN_BACK])
    return _reply_kb(kb_rows)


def complaint_detail_text(target_id: int, rows: list[dict]) -> str:
    status_icon = {"pending": "🕓", "accepted": "✅", "declined": "❌"}
    lines = []
    for c in rows:
        who = "Аноним" if c["anonymous"] else mention_id(c["reporter_id"])
        when = fmt_dt(c["created_at"])
        reason = html.escape(c["reason"])
        lines.append(f"{status_icon[c['status']]} <b>№{c['id']}</b> · от {who} · {when}\n{reason}")
    return f"🚨 <b>Жалобы на {mention_id(target_id)}</b>\n{DIVIDER}\n\n" + "\n\n".join(lines)


def complaint_detail_kb(rows: list[dict]) -> ReplyKeyboardMarkup:
    kb_rows = []
    for c in rows:
        if c["status"] == "pending":
            kb_rows.append([f"✅ Принять №{c['id']}", f"❌ Отклонить №{c['id']}"])
        kb_rows.append([f"🗑 Удалить жалобу №{c['id']}"])
    kb_rows.append([BTN_BACK])
    return _reply_kb(kb_rows)


