@router.message(StateFilter(ComplaintStates.waiting_target), F.chat.type == "private")
async def process_complaint_target(message: Message, state: FSMContext):
    target_id = None
    if message.forward_from:
        target_id = message.forward_from.id
    elif message.text and message.text.strip().isdigit():
        target_id = int(message.text.strip())

    if target_id is None:
        data = await state.get_data()
        complaint_chat_id = data.get("complaint_picker_chat")
        query = (message.text or "").strip()
        if complaint_chat_id and query:
            await state.update_data(complaint_picker_query=query)
            text, kb = await complaint_picker_page(complaint_chat_id, 0, query)
            await message.answer(
                "Выберите из списка (или напишите часть имени для поиска):\n\n" + text,
                reply_markup=kb,
            )
            return

        await message.answer(
            "Не удалось распознать пользователя. Перешлите его сообщение или пришлите числовой ID.",
            reply_markup=complaint_cancel_kb(),
        )
        return
    if target_id == message.from_user.id:
        await message.answer("Нельзя пожаловаться на самого себя 🙂", reply_markup=complaint_cancel_kb())
        return
    if target_id == bot.id:
        await message.answer("На бота жаловаться нет смысла 🤖", reply_markup=complaint_cancel_kb())
        return

    await state.update_data(complaint_target=target_id)
    await state.set_state(ComplaintStates.waiting_visibility)
    label = await user_label(target_id)
    await message.answer(
        f"🎯 Жалоба на: {label}\n\n"
        "Показать администраторам, кто пожаловался?\n"
        "🙈 Анонимно — админы не увидят вас\n"
        "🙋 Публично — админы увидят, кто пожаловался",
        reply_markup=complaint_visibility_kb(),
    )


@router.message(StateFilter(ComplaintStates.waiting_visibility), F.chat.type == "private")
async def process_complaint_visibility(message: Message, state: FSMContext):
    text = (message.text or "").strip()
    if text.startswith("🙈"):
        mode = "anon"
    elif text.startswith("🙋"):
        mode = "public"
    else:
        await message.answer("Пожалуйста, выберите вариант с клавиатуры ниже.", reply_markup=complaint_visibility_kb())
        return

    data = await state.get_data()
    if data.get("complaint_target") is None:
        await state.clear()
        await message.answer("Запрос устарел, начните заново словом «жалоба».", reply_markup=private_menu_kb(message.from_user.id))
        return

    await state.update_data(complaint_anonymous=(mode == "anon"))
    await state.set_state(ComplaintStates.waiting_reason)
    await message.answer(
        "📝 Опишите причину жалобы одним сообщением.",
        reply_markup=complaint_cancel_kb(),
    )


@router.message(StateFilter(ComplaintStates.waiting_reason), F.chat.type == "private")
async def process_complaint_reason(message: Message, state: FSMContext):
    if not message.text or not message.text.strip():
        await message.answer("Нужен текстовый ответ. Опишите причину жалобы.", reply_markup=complaint_cancel_kb())
        return

    data = await state.get_data()
    target_id = data.get("complaint_target")
    anonymous = bool(data.get("complaint_anonymous"))
    if target_id is None:
        await state.clear()
        await message.answer("⚠️ Что-то пошло не так, начните заново словом «жалоба».")
        return

    reason = message.text.strip()
    await db.add_complaint(target_id, message.from_user.id, anonymous, reason)
    global pending_complaints_count
    pending_complaints_count += 1
    await db.add_log(
        "complaint_filed", actor_id=message.from_user.id, target_id=target_id, details=reason[:200]
    )

    # Уведомление в notifications_chat_id о новой жалобе
    notify_chat_id = settings.get("notify_chat_id")
    if notify_chat_id:
        target_label = await user_label(target_id)
        if anonymous:
            reporter_label = "Аноним"
        else:
            reporter_label = await user_label(message.from_user.id)
        notify_text = (
            "🚨 <b>Новая жалоба</b>\n\n"
            f"На кого: {target_label}\n"
            f"От кого: {reporter_label}\n"
            f"Текст: {html.escape(reason)}"
        )
        try:
            await bot.send_message(
                chat_id=notify_chat_id,
                message_thread_id=settings.get("notify_topic_id"),
                text=notify_text,
            )
        except Exception:
            logger.exception("Не удалось отправить уведомление о жалобе в notifications_chat_id")

    await state.clear()
    await message.answer(
        "✅ Жалоба отправлена администраторам. Спасибо, что сообщили — мы её рассмотрим.",
        reply_markup=private_menu_kb(message.from_user.id),
    )


