# ----------------------------------------------------------------------------
# «Рест» из личных сообщений — то же самое, что и в группе, но чтобы не
# засорять группу заявками (особенно если их много) можно оформить рест
# прямо в личке бота. Привязываем заявку к основному чату, настроенному
# командой «жалобы сюда» (settings.complaint_chat_id) — тому же, что
# используется для выбора цели жалобы. Обязательно регистрируем этот
# хендлер РАНЬШЕ общего catch-all'а личных сообщений (handle_user_message
# ниже), иначе он проглотит текст «рест ...» как обычную заявку на
# вступление.
# ----------------------------------------------------------------------------
async def _private_rest_target() -> tuple[Optional[int], str]:
    """chat_id + название чата, к которому привязывается рест из личных
    сообщений (см. «жалобы сюда»), или (None, "") если он ещё не настроен."""
    target_chat_id = settings.get("complaint_chat_id")
    if not target_chat_id:
        return None, ""
    try:
        chat = await bot.get_chat(target_chat_id)
        chat_title = chat.title or str(target_chat_id)
    except Exception:
        chat_title = str(target_chat_id)
    return target_chat_id, chat_title


REST_NO_TARGET_TEXT = (
    "⚠️ Рест из личных сообщений пока недоступен — админы ещё не привязали основной чат "
    "командой «жалобы сюда» (отправляется в нужной группе). "
    "Попробуйте написать «рест ...» прямо в группе."
)


@router.message(
    F.chat.type == "private",
    StateFilter(None),
    F.text.func(
        lambda t: bool(t)
        and (t.strip().casefold().split() or [""])[0] == "рест"
        and t.strip().casefold() not in REST_CANCEL_TRIGGERS
        and not _is_rest_list_cmd(t)
    ),
)
async def cmd_rest_request_private(message: Message):
    if message.from_user.id in custom_responses:
        # У пользователя настроен «особый ответ» (см. custom_responses) — это
        # приоритетнее, отдаём сообщение catch-all'у ниже, как и для любого
        # другого текста от таких пользователей.
        raise SkipHandler
    target_chat_id, chat_title = await _private_rest_target()
    if not target_chat_id:
        await message.answer(REST_NO_TARGET_TEXT)
        return
    await _process_rest_request(
        message, target_chat_id=target_chat_id, chat_title=chat_title, reply=message.answer
    )


# ----------------------------------------------------------------------------
# Кнопочный флоу «🌴 Рест» — то же самое, что текстовая команда «рест 3д
# причина», но пошагово через ReplyKeyboardMarkup: срок выбирается кнопкой
# (или вводится вручную), причина — тоже кнопкой «Без причины» или текстом.
# Сделано, чтобы не заставлять человека вручную вспоминать синтаксис команды.
# ----------------------------------------------------------------------------
REST_DURATION_PRESETS: list[tuple[str, timedelta]] = [
    ("3 часа", timedelta(hours=3)),
    ("12 часов", timedelta(hours=12)),
    ("1 день", timedelta(days=1)),
    ("3 дня", timedelta(days=3)),
    ("1 неделя", timedelta(weeks=1)),
    ("1 месяц", timedelta(days=30)),
]
REST_CUSTOM_DURATION_BTN = "✏️ Свой срок"
REST_NO_REASON_BTN = "🙈 Без причины"


def rest_duration_kb() -> ReplyKeyboardMarkup:
    rows = _grid([label for label, _ in REST_DURATION_PRESETS])
    rows.append([REST_CUSTOM_DURATION_BTN])
    rows.append([BTN_CANCEL])
    return _reply_kb(rows)


def rest_custom_duration_kb() -> ReplyKeyboardMarkup:
    return _reply_kb([[BTN_CANCEL]])


def rest_reason_kb() -> ReplyKeyboardMarkup:
    return _reply_kb([[REST_NO_REASON_BTN], [BTN_CANCEL]])


@router.message(
    F.chat.type == "private",
    StateFilter(None),
    F.text == "🌴 Рест",
)
async def cmd_rest_button(message: Message, state: FSMContext):
    if message.from_user.id in custom_responses:
        raise SkipHandler
    target_chat_id, _ = await _private_rest_target()
    if not target_chat_id:
        await message.answer(REST_NO_TARGET_TEXT)
        return
    existing_active = await db.get_active_rest(target_chat_id, message.from_user.id)
    if existing_active:
        until: datetime = existing_active["expires_at"]
        await message.answer(f"Вы уже в ресте до <b>{fmt_dt(until)}</b>.")
        return
    existing_pending = await db.get_pending_rest_request(target_chat_id, message.from_user.id)
    if existing_pending:
        await message.answer("У вас уже есть заявка на рест, которая ждёт решения администраторов.")
        return
    await state.set_state(RestStates.waiting_duration)
    await message.answer(
        "🌴 <b>Рест</b>\n\nНа какой срок хотите уйти в рест? Выберите вариант или укажите свой.",
        reply_markup=rest_duration_kb(),
    )


@router.message(
    F.chat.type == "private",
    StateFilter(RestStates.waiting_duration, RestStates.waiting_custom_duration, RestStates.waiting_reason),
    F.text == BTN_CANCEL,
)
async def rest_button_cancel(message: Message, state: FSMContext):
    await state.clear()
    await message.answer("Отменено — заявка на рест не отправлена.", reply_markup=private_menu_kb(message.from_user.id))


@router.message(F.chat.type == "private", StateFilter(RestStates.waiting_duration))
async def rest_pick_duration(message: Message, state: FSMContext):
    text = (message.text or "").strip()
    if text == REST_CUSTOM_DURATION_BTN:
        await state.set_state(RestStates.waiting_custom_duration)
        await message.answer(
            "Напишите срок вручную, например: <code>3ч</code>, <code>2 дня</code>, <code>1мес</code>, <code>1год</code>.",
            reply_markup=rest_custom_duration_kb(),
        )
        return
    preset = next((d for label, d in REST_DURATION_PRESETS if label == text), None)
    if preset is None:
        await message.answer("Пожалуйста, выберите вариант с клавиатуры ниже.", reply_markup=rest_duration_kb())
        return
    await state.update_data(rest_duration_seconds=int(preset.total_seconds()))
    await state.set_state(RestStates.waiting_reason)
    await message.answer(
        "📝 Укажите причину (болезнь, отпуск и т.п.) или нажмите «Без причины».",
        reply_markup=rest_reason_kb(),
    )


@router.message(F.chat.type == "private", StateFilter(RestStates.waiting_custom_duration))
async def rest_custom_duration(message: Message, state: FSMContext):
    text = (message.text or "").strip()
    duration, extra_reason = _extract_leading_duration(text, skip_words=0)
    if duration is None:
        await message.answer(
            "Не понял срок. Примеры: <code>3ч</code>, <code>2 дня</code>, <code>1нед</code>, "
            "<code>1мес</code>, <code>1год</code>.",
            reply_markup=rest_custom_duration_kb(),
        )
        return
    if duration > REST_MAX_DURATION:
        await message.answer(
            f"⚠️ Слишком большой срок. Максимум — {format_duration_ru(REST_MAX_DURATION)}.",
            reply_markup=rest_custom_duration_kb(),
        )
        return
    await state.update_data(rest_duration_seconds=int(duration.total_seconds()))
    if extra_reason:
        # Пользователь сразу написал причину вместе со сроком («2 дня учёба») —
        # не переспрашиваем её отдельным шагом.
        await _finish_rest_button_flow(message, state, reason=extra_reason)
        return
    await state.set_state(RestStates.waiting_reason)
    await message.answer(
        "📝 Укажите причину (болезнь, отпуск и т.п.) или нажмите «Без причины».",
        reply_markup=rest_reason_kb(),
    )


@router.message(F.chat.type == "private", StateFilter(RestStates.waiting_reason))
async def rest_pick_reason(message: Message, state: FSMContext):
    text = (message.text or "").strip()
    reason = None if text == REST_NO_REASON_BTN else (text or None)
    await _finish_rest_button_flow(message, state, reason=reason)


async def _finish_rest_button_flow(message: Message, state: FSMContext, reason: Optional[str]) -> None:
    data = await state.get_data()
    duration_seconds = data.get("rest_duration_seconds")
    await state.clear()
    menu_kb = private_menu_kb(message.from_user.id)

    async def _reply_with_menu(text: str) -> None:
        await message.answer(text, reply_markup=menu_kb)

    if not duration_seconds:
        await _reply_with_menu("⚠️ Что-то пошло не так, начните заново кнопкой «🌴 Рест».")
        return
    target_chat_id, chat_title = await _private_rest_target()
    if not target_chat_id:
        await _reply_with_menu(REST_NO_TARGET_TEXT)
        return
    await _process_rest_request(
        message,
        target_chat_id=target_chat_id,
        chat_title=chat_title,
        reply=_reply_with_menu,
        duration=timedelta(seconds=duration_seconds),
        reason=reason,
        parse_from_text=False,
    )


