ROLE_SEARCH_LIMIT = 15


def _is_role_search_cmd(text: Optional[str]) -> bool:
    if not text or not text.strip():
        return False
    low = text.strip().casefold()
    return low.startswith("роль найти ") or low.startswith("найти роль ")


@router.message(F.text.func(_is_role_search_cmd))
async def cmd_role_search(message: Message):
    """«роль найти Аска» — поиск по названию, категории и по держателю.

    Раньше в чате были только списки: чтобы узнать, занята ли роль или что за
    роль у человека, приходилось глазами читать весь список. Ищет тот же
    запрос, что и веб-панель (db.search_chat_roles), — чтобы результаты
    совпадали.
    """
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата (см. «чат сюда»).")
        return

    raw = message.text.strip()
    query = raw.split(maxsplit=2)[2].strip() if len(raw.split(maxsplit=2)) > 2 else ""
    if not query:
        await message.reply("Что искать? Например: <code>роль найти Аска</code>.")
        return

    rows, total = await db.search_chat_roles(chat_id, q=query, limit=ROLE_SEARCH_LIMIT)
    if not rows:
        await message.reply(f"По запросу «{html.escape(query)}» ничего не нашлось.")
        return

    # Держателей показываем только в группе — так же, как в общем списке ролей:
    # в личке чужие роли не раскрываем.
    show_holder = message.chat.type in ("group", "supergroup")
    lines = [f"🔍 <b>Поиск ролей: «{html.escape(query)}»</b>", DIVIDER]
    for row in rows:
        category = f" <i>({html.escape(row['category'])})</i>" if row.get("category") else ""
        if row["status"] == "taken":
            who = mention_id(row["holder_user_id"]) if show_holder and row.get("holder_user_id") else "занята"
            state = f"⚔️ {who}"
        elif row["status"] == "reserved":
            who = mention_id(row["reserved_user_id"]) if show_holder and row.get("reserved_user_id") else "бронь"
            state = f"🗡 {who}"
        else:
            state = "свободна"
        lines.append(f"№{row['id']} «{html.escape(row['name'])}»{category} — {state}")

    if total > len(rows):
        lines.append(f"\n<i>Показаны первые {len(rows)} из {total} — уточните запрос.</i>")
    await message.reply("\n".join(lines))


