# ----------------------------------------------------------------------------
# «участники без ролей» — известные боту участники чата, у которых нет ни
# занятой, ни забронированной роли. Удобно для админов, чтобы понять, кого
# ещё позвать выбрать себе роль (в отличие от «свободные роли»/«занятые
# роли» выше, которые смотрят на список РОЛЕЙ, эта команда смотрит на
# список ЛЮДЕЙ). Уровень доступа — как у остальных «*роли» команд (0,
# доступно всем), это просто информационный список.
# ----------------------------------------------------------------------------
@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "участники без ролей"))
async def cmd_members_without_role(message: Message):
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата (см. «чат сюда»).")
        return
    rows, total = await db.list_current_users_without_role(chat_id, limit=ROSTER_LIST_LIMIT)
    if not rows:
        await message.reply("🎉 У всех известных боту участников есть роль (занятая или бронь).")
        return

    # current_users может отставать от реального состава чата (Telegram не
    # всегда присылает событие выхода — особенно в обычных, не супер-группах).
    # Подстраховываемся: сверяем каждого через get_chat_member и тихо чистим
    # тех, кого в чате уже нет, не показывая их в списке.
    alive_rows = []
    for r in rows:
        try:
            member = await bot.get_chat_member(chat_id, r["user_id"])
        except (TelegramBadRequest, TelegramForbiddenError):
            # Telegram сказал «такого тут нет» — чистим запись.
            await db.delete_current_user(chat_id, r["user_id"])
            continue
        except Exception:
            # Сеть моргнула, лимит, 5xx. Это НЕ повод считать человека
            # вышедшим и уж тем более не повод ронять всю команду: раньше
            # любая такая ошибка обрывала список целиком, и админ не получал
            # ответа вовсе. Оставляем строку как есть и идём дальше.
            logger.warning(
                "Не удалось проверить участника %s в чате %s — оставляю в списке",
                r["user_id"], chat_id,
            )
            alive_rows.append(r)
            continue
        if member.status in ("left", "kicked"):
            await db.delete_current_user(chat_id, r["user_id"])
            continue
        alive_rows.append(r)

    if not alive_rows:
        await message.reply("🎉 У всех известных боту участников есть роль (занятая или бронь).")
        return

    lines = [
        f"• {mention_id(r['user_id'], full_name=r.get('full_name'), username=r.get('username'))}"
        for r in alive_rows
    ]
    more = f"\n\n…и ещё {total - len(rows)}" if total > len(rows) else ""
    await message.reply(
        f"🙈 <b>Без роли — {len(alive_rows)}</b>\n\n<blockquote expandable>" + "\n".join(lines) + "</blockquote>" + more
    )


