@router.callback_query(F.data == "role_menu_change")
async def role_menu_change_callback(callback: CallbackQuery):
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Чат для ролей не настроен.", show_alert=True)
