@router.callback_query(F.data.startswith("rpick_page:"))
async def role_pick_paginate(callback: CallbackQuery):
    try:
        page = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Чат для ролей не настроен.", show_alert=True)
        return
    text, kb = await role_pick_page(chat_id, page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("rpick:"))
async def role_pick_select(callback: CallbackQuery):
    try:
        role_id = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Чат для ролей не настроен.", show_alert=True)
        return
    user_id = callback.from_user.id
    role = await db.get_role(chat_id, role_id)
    if role is None:
        await callback.answer("Эта роль больше не существует.", show_alert=True)
        return
    member = await is_chat_member(chat_id, user_id)
    if member:
        ok = await db.take_role(chat_id, role_id, user_id)
        if not ok:
            await callback.answer("Увы, эту роль уже кто-то занял.", show_alert=True)
            return
        await db.add_log("role_take", chat_id=chat_id, actor_id=user_id, details=role["name"])
        await grant_achievement(chat_id, user_id, "role_taken")
        await sync_role_title(chat_id, user_id)
        try:
            await callback.message.edit_text(f"✅ Роль «{html.escape(role['name'])}» закреплена за вами.")
        except TelegramBadRequest:
            pass
        await callback.answer()
    else:
        ok = await db.reserve_role(chat_id, role_id, user_id)
        if not ok:
            await callback.answer("Увы, эту роль уже кто-то занял или забронировал.", show_alert=True)
            return
        await db.add_log("role_reserve", chat_id=chat_id, actor_id=user_id, details=role["name"])
        try:
            await callback.message.edit_text(
                f"🗡 Роль «{html.escape(role['name'])}» забронирована за вами.\n"
                f"Она закрепится автоматически, как только вы вступите в группу "
                f"(бронь действует {ROLE_RESERVE_TIMEOUT_HOURS} ч.)."
            )
        except TelegramBadRequest:
            pass
        await callback.answer()
        # Если заявка на вход ещё не рассмотрена — сообщаем админам, что
        # заявитель выбрал роль и теперь ему можно выдать ссылку.
        if await db.get_request_status(user_id) in (None, "pending"):
            notify_chat = settings.get("notify_chat_id")
            if notify_chat:
                try:
                    await bot.send_message(
                        notify_chat,
                        message_thread_id=settings.get("notify_topic_id"),
                        text=(
                            f"🎭 {mention_id(user_id)} выбрал роль «{html.escape(role['name'])}» — "
                            "теперь можно выдать ссылку («Дать ссылку на вход» под его заявкой)."
                        ),
                    )
                except Exception:
                    logger.exception("Не удалось уведомить админов о выборе роли заявителем")


@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "снять роль"))
async def cmd_role_release(message: Message):
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    role = await db.get_user_role(chat_id, message.from_user.id)
    if role is None:
        reservation = await db.get_user_reservation(chat_id, message.from_user.id)
        if reservation is not None:
            await db.cancel_reservation(chat_id, reservation["id"])
            await db.add_log("role_cancel_reservation", chat_id=chat_id, actor_id=message.from_user.id, details=reservation["name"])
            await message.reply(f"Бронь роли «{html.escape(reservation['name'])}» снята.")
            return
        await message.reply("У вас сейчас нет ни закреплённой роли, ни брони.")
        return
    await db.release_role(chat_id, role["id"])
    await sync_role_title(chat_id, message.from_user.id) 
    await db.add_log("role_release", chat_id=chat_id, actor_id=message.from_user.id, details=role["name"])
    await message.reply(f"Роль «{html.escape(role['name'])}» освобождена.")


def role_proposal_kb(role_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(text="✅ Принять", callback_data=f"rprop_approve:{role_id}"),
                InlineKeyboardButton(text="❌ Отклонить", callback_data=f"rprop_reject:{role_id}"),
            ]
        ]
    )


def role_pending_kb(rows: list[dict]) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(text=f"✅ №{r['id']} {r['name'][:40]}", callback_data=f"rprop_approve:{r['id']}"),
                InlineKeyboardButton(text="❌", callback_data=f"rprop_reject:{r['id']}"),
            ]
            for r in rows
        ]
    )


@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("предложить роль")))
async def cmd_role_propose(message: Message):
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    raw = message.text.strip()
    name = raw[len("предложить роль"):].strip(" :—-")
    if not name:
        await message.reply("Укажите название: «предложить роль» + название, например «предложить роль Капитан».")
        return
    if len(name) > 64:
        await message.reply("Слишком длинное название (максимум 64 символа).")
        return
    role_id = await db.propose_role(chat_id, name, category=None, proposed_by=message.from_user.id)
    if role_id is None:
        await message.reply("Роль с таким названием уже есть в списке (свободна, занята или на модерации).")
        return
    await db.add_log("role_propose", chat_id=chat_id, actor_id=message.from_user.id, details=name)
    await message.reply(f"📝 Заявка на роль «{html.escape(name)}» отправлена на модерацию (№{role_id}).")
    notify_chat = settings.get("notify_chat_id")
    if notify_chat:
        try:
            sent = await bot.send_message(
                notify_chat,
                message_thread_id=settings.get("notify_topic_id"),
                text=(
                    f"📝 Новая заявка на роль «{html.escape(name)}» от {mention_id(message.from_user.id)}."
                ),
                reply_markup=role_proposal_kb(role_id),
            )
            # Запоминаем карточку: решение, принятое в веб-панели, правит именно
            # её — иначе в чате остались бы активные кнопки по уже закрытой
            # заявке (см. db.ensure_role_proposal_message_columns).
            await db.set_role_proposal_message(chat_id, role_id, sent.chat.id, sent.message_id)
        except Exception:
            logger.exception("Не удалось уведомить о новой заявке на роль")


@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "роли заявки"))
async def cmd_role_pending(message: Message):
    if not has_level(message.from_user.id, required_level("role_pending")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Смотреть заявки на роли может «{level_name(required_level('role_pending'))}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    rows = await db.list_pending_role_proposals(chat_id)
    if not rows:
        await message.reply("Заявок на новые роли нет.")
        return
    lines = ["📝 <b>Заявки на роли</b>", DIVIDER]
    for r in rows:
        lines.append(f"№{r['id']} — «{html.escape(r['name'])}» от {mention_id(r['proposed_by'])}")
    await message.reply("\n".join(lines), reply_markup=role_pending_kb(rows))


async def _role_proposal_decision(callback: CallbackQuery, approve: bool) -> None:
    """Общая логика принятия/отклонения заявки на роль по нажатию inline-кнопки:
    ответ отображается изменением того же сообщения (без отдельного текста)."""
    if not has_level(callback.from_user.id, required_level("role_approve" if approve else "role_reject")):
        await callback.answer(
            f"⛔ {'Одобрять' if approve else 'Отклонять'} роли может «"
            f"{level_name(required_level('role_approve' if approve else 'role_reject'))}» и выше.",
            show_alert=True,
        )
        return
    try:
        role_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Роли пока не настроены для этого чата.", show_alert=True)
        return

    base_text = callback.message.html_text or callback.message.text or ""

    if approve:
        role = await db.approve_role_proposal(chat_id, role_id)
        if role is None:
            await callback.answer("Такой заявки нет (возможно, уже обработана).", show_alert=True)
            return
        proposer = role.get("proposed_by")
        status_note = ""
        if proposer and not await is_chat_member(chat_id, proposer):
            if await db.reserve_role(chat_id, role_id, proposer):
                status_note = " (забронирована за автором — он ещё не в группе)"
        await db.add_log("role_approve", chat_id=chat_id, actor_id=callback.from_user.id, details=role["name"])
        decision_line = (
            f"\n\n✅ Принято ({mention_id(callback.from_user.id)}){status_note}"
        )
        if proposer:
            try:
                await bot.send_message(proposer, f"✅ Ваша заявка на роль «{html.escape(role['name'])}» одобрена.")
            except Exception:
                pass
        alert_text = f"Роль «{role['name']}» добавлена в список."
    else:
        role = await db.get_role(chat_id, role_id)
        if not await db.reject_role_proposal(chat_id, role_id):
            await callback.answer("Такой заявки нет (возможно, уже обработана).", show_alert=True)
            return
        await db.add_log(
            "role_reject", chat_id=chat_id, actor_id=callback.from_user.id,
            details=role["name"] if role else str(role_id),
        )
        decision_line = f"\n\n❌ Отклонено ({mention_id(callback.from_user.id)})"
        if role and role.get("proposed_by"):
            try:
                await bot.send_message(
                    role["proposed_by"], f"❌ Ваша заявка на роль «{html.escape(role['name'])}» отклонена."
                )
            except Exception:
                pass
        alert_text = "Заявка отклонена."

    try:
        await callback.message.edit_text(base_text + decision_line, reply_markup=None)
    except TelegramBadRequest:
        pass
    await callback.answer(alert_text)


@router.callback_query(F.data.startswith("rprop_approve:"))
async def role_proposal_approve_callback(callback: CallbackQuery):
    await _role_proposal_decision(callback, approve=True)


@router.callback_query(F.data.startswith("rprop_reject:"))
async def role_proposal_reject_callback(callback: CallbackQuery):
    await _role_proposal_decision(callback, approve=False)


