# Удалять можно и по названию («роль удалить Каору»), и по номеру из списка
# («роль удалить 12»). Название — основной способ: номер это id из базы, а он
# не совпадает с позицией роли в списке, и раньше «роль удалить 5» сносило не
# ту роль, на которую смотрел админ. Теперь номера видны в самом списке ролей.
@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("роль удалить ")))
async def cmd_role_delete(message: Message):
    if not has_level(message.from_user.id, required_level("role_delete")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Удалять роли из списка может «{level_name(required_level('role_delete'))}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return

    query = message.text.strip()[len("роль удалить "):].strip(" :—-")
    if not query:
        await message.reply("Укажите название роли: <code>роль удалить Каору</code>")
        return

    if query.isdigit():
        role = await db.get_role(chat_id, int(query))
    else:
        role = await db.get_role_by_name(chat_id, query)
    if role is None:
        await message.reply(
            f"Роль «{html.escape(query)}» не найдена. Посмотрите список командой «роли»."
        )
        return

    # Занятую или забронированную роль не сносим молча: держатель узнал бы о
    # пропаже роли только постфактум, а восстановить её нельзя — имя владельца
    # хранится в той же строке. Кнопочное меню «роли удалить» ведёт себя так же.
    if role["status"] != "free":
        holder = role.get("holder_user_id") or role.get("reserved_user_id")
        who = mention_id(holder) if holder else "кем-то"
        state = "занята" if role["status"] == "taken" else "забронирована"
        await message.reply(
            f"⛔ Роль «{html.escape(role['name'])}» сейчас {state} ({who}).\n"
            "Сначала освободите её командой «роль снять», потом удаляйте."
        )
        return

    if not await db.delete_role(chat_id, role["id"]):
        await message.reply("Роль не удалась — возможно, её уже удалили.")
        return
    await db.add_log("role_delete", chat_id=chat_id, actor_id=message.from_user.id, details=role["name"])
    await message.reply(f"🗑 Роль «{html.escape(role['name'])}» удалена из списка.")


# ----------------------------------------------------------------------------
# «роль добавить» — прямое добавление роли в список админом, БЕЗ модерации
# (в отличие от «предложить роль», доступной всем и уходящей в очередь на
# подтверждение). Роль сразу появляется свободной. Поддерживает необязательную
# категорию через «/»: «роль добавить Ангелы / Уриэль» — категория «Ангелы»,
# название «Уриэль». Без «/» — категория не указывается.
# ----------------------------------------------------------------------------
@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("роль добавить")))
async def cmd_role_add(message: Message):
    if not has_level(message.from_user.id, required_level("role_add")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Добавлять роли в список может «{level_name(required_level('role_add'))}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата (см. «чат сюда»).")
        return
    raw = message.text.strip()
    payload = raw[len("роль добавить"):].strip(" :—-")
    if not payload:
        await message.reply(
            "Укажите название: «роль добавить Название» или «роль добавить Категория / Название», "
            "например «роль добавить Ангелы / Уриэль»."
        )
        return
    if "/" in payload:
        category_part, _, name_part = payload.partition("/")
        category = category_part.strip() or None
        name = name_part.strip()
    else:
        category = None
        name = payload.strip()
    if not name:
        await message.reply("Укажите название роли после категории (после «/»).")
        return
    if len(name) > 64:
        await message.reply("Слишком длинное название (максимум 64 символа).")
        return
    if category and len(category) > 64:
        await message.reply("Слишком длинное название категории (максимум 64 символа).")
        return
    role_id = await db.propose_role(
        chat_id, name, category=category, proposed_by=message.from_user.id, auto_approved=True
    )
    if role_id is None:
        await message.reply("Роль с таким названием уже есть в списке (свободна, занята или на модерации).")
        return
    await db.add_log("role_add", chat_id=chat_id, actor_id=message.from_user.id, details=name)
    cat_note = f" (категория «{html.escape(category)}»)" if category else ""
    await message.reply(f"✅ Роль «{html.escape(name)}» добавлена в список как свободная{cat_note}.")


@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "роли импорт"))
async def cmd_role_import(message: Message):
    """Одноразовый импорт стартового списка ролей (ROLE_SEED_DATA). Уже
    существующие по названию роли пропускаются, так что команду безопасно
    повторить, если список пополнили в коде."""
    if not has_level(message.from_user.id, LEVEL_SENIOR):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Импортировать список ролей может только «{level_name(LEVEL_SENIOR)}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Сначала привяжите чат командой «чат сюда» в нужной группе.")
        return
    added = await db.seed_roles(chat_id, ROLE_SEED_DATA)
    await db.add_log("role_import", chat_id=chat_id, actor_id=message.from_user.id, details=str(added))
    await message.reply(
        f"✅ Импорт завершён: добавлено {added} из {len(ROLE_SEED_DATA)} ролей "
        "(остальные уже были в списке).\n\n"
        "У ролей со статусом «занята» пока не проставлен держатель — назначьте его "
        "командой «роль отдать» + название (ответом на сообщение игрока в группе, "
        "либо «роль отдать @username Название» — тоже из ЛС боту)."
    )



# Меню «роли удалить» стоит именно здесь, ВЫШЕ приёма личных сообщений:
# handle_user_message ниже перехватывает в личке любой текст и отправляет его
# админам как заявку на вступление. Зарегистрированное после него меню в ЛС
# просто не срабатывало — команда уходила в заявки (та же история уже была с
# кнопкой «🎭 Роли»). Вспомогательные role_delete_page/role_delete_kb
# определены ниже по файлу — они ищутся в момент вызова, не при регистрации.
@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "роли удалить"))
async def cmd_roles_delete_menu(message: Message):
    if not has_level(message.from_user.id, required_level("role_delete")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Удалять роли из списка может «{level_name(required_level('role_delete'))}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    text, kb = await role_delete_page(chat_id, 0)
    if kb is None:
        await message.reply(text)
        return
    await message.reply(text, reply_markup=kb)


# ----------------------------------------------------------------------------
# Приём заявок и последующих сообщений от пользователей (личка)
# ----------------------------------------------------------------------------
@router.message(F.chat.type == "private", StateFilter(None), ~F.text.startswith("/"))
async def handle_user_message(message: Message):
    user_id = message.from_user.id
    in_test_mode = user_id in test_mode_admins

    if user_id in custom_responses:
        await message.answer(custom_responses[user_id])
        return

    if is_admin(user_id) and not in_test_mode:
        await message.answer("Вы админ. Напишите «админка» для настройки бота.")
        return

    if not settings_configured():
        await message.answer("⚠️ Бот пока не настроен администраторами. Попробуйте написать чуть позже.")
        logger.warning("Получено сообщение, но бот не настроен (нет notify_chat_id или invite_link)")
        return

    user = message.from_user
    is_first_message = not await db.has_any_request(user.id)

    full_name = user.full_name or "Без имени"
    username_str = f"@{user.username}" if user.username else "нет юзернейма"
    mention = mention_id(user.id, full_name=full_name, username=user.username)
    user_text = message.text or message.caption or "(сообщение без текста)"
    test_tag = "🧪 <b>ТЕСТОВАЯ ЗАЯВКА (проверка админом)</b>\n\n" if in_test_mode else ""

    if is_first_message:
        notify_text = (
            f"{test_tag}📩 <b>Новая заявка на вступление</b>\n\n"
            f"👤 Профиль: {mention}\n"
            f"💬 Юзернейм: {username_str}\n\n"
            f"📝 Сообщение:\n{user_text}\n\n"
            "<i>Ответьте (reply) на это сообщение, чтобы написать заявителю напрямую.</i>"
        )
        reply_to = None
    else:
        notify_text = f"{test_tag}💬 <b>{mention}</b> ({username_str}):\n{user_text}"
        reply_to = await db.get_anchor_message_id(user.id)

    try:
        sent = await bot.send_message(
            chat_id=settings["notify_chat_id"],
            message_thread_id=settings["notify_topic_id"],
            text=notify_text,
            reply_markup=request_button_kb(user.id) if is_first_message else None,
            reply_to_message_id=reply_to,
        )
    except Exception as e:
        logger.exception("Не удалось отправить сообщение в группу: %s", e)
        await message.answer("⚠️ Не удалось передать сообщение администраторам. Попробуйте позже.")
        return

    await db.add_request_message(sent.message_id, user.id, is_anchor=is_first_message)

    if is_first_message:
        try:
            await bot.pin_chat_message(
                chat_id=settings["notify_chat_id"],
                message_id=sent.message_id,
                disable_notification=True,
            )
        except Exception as e:
            logger.warning("Не удалось закрепить заявку (нет прав на закреп?): %s", e)

        await db.add_log("request_created", actor_id=user.id, details=user_text[:200])
        confirm_text = "✅ Ваша заявка отправлена администраторам."
        if in_test_mode:
            confirm_text += (
                "\n\n🧪 Это тестовая заявка (режим «Входящего» включён). Она появится в топике "
                "как обычная — проверьте кнопки «Дать ссылку»/«Отказать». После первого решения "
                "тестовый режим выключится автоматически."
            )
        await message.answer(confirm_text)
        # Модуль «Роли»: если в целевом чате настроены роли, выбор одной из
        # свободных — ОБЯЗАТЕЛЬНОЕ условие для получения ссылки (см. ТЗ:
        # «первым, при входе в группу, перед получением ссылки человек
        # обязательно выберет роль из свободных»). Ссылку админ сможет выдать
        # только после того, как за заявителем закрепится роль/бронь —
        # см. проверку в handle_give_link().
        await prompt_role_pick_for_applicant(user.id)
    else:
        await react(message.chat.id, message.message_id, "👀")


async def prompt_role_pick_for_applicant(user_id: int) -> None:
    """Отправляет заявителю обязательный выбор роли (если в чате, куда он
    подаёт заявку, вообще настроен список ролей). Пока роль не выбрана —
    «Дать ссылку» для админов будет заблокирована, см. handle_give_link()."""
    chat_id = settings.get("notify_chat_id")
    if not chat_id:
        return
    rows = await db.list_roles(chat_id)
    if not rows:
        # Модуль ролей в чате не используется — не требуем ничего.
        return
    if await db.get_user_role(chat_id, user_id) or await db.get_user_reservation(chat_id, user_id):
        # Роль/бронь уже есть (например, из предыдущей заявки) — не мешаем.
        return
    text, kb = await role_pick_page(chat_id, 0)
    if kb is None:
        # Свободных ролей нет — не блокируем вступление, но предупреждаем.
        try:
            await bot.send_message(
                user_id,
                "⚠️ Сейчас все роли заняты или забронированы — как только освободится "
                "хотя бы одна, вы сможете выбрать её через «сменить роль». Это не "
                "помешает получению ссылки.",
            )
        except Exception:
            pass
        return
    try:
        await bot.send_message(
            user_id,
            "🎭 <b>Прежде чем вы получите ссылку — выберите роль</b>\n\n"
            "Это обязательный шаг: администратор сможет выдать вам ссылку только "
            f"после того, как вы выберете одну из свободных ролей ниже.\n\n{text}",
            reply_markup=kb,
        )
    except Exception:
        logger.exception("Не удалось отправить обязательный выбор роли заявителю user_id=%s", user_id)


async def prompt_role_pick_after_join(chat_id: int, user_id: int) -> None:
    """Просит только что вступившего в группу человека выбрать роль в личке
    с ботом — не обязательный шаг (в отличие от prompt_role_pick_for_applicant,
    который блокирует выдачу ссылки ДО вступления), а мягкое напоминание уже
    после входа: пригодится тем, кто попал в группу не через обычную заявку
    (например, по прямой ссылке-приглашению)."""
    rows = await db.list_roles(chat_id)
    if not rows:
        # Модуль ролей в этом чате не используется.
        return
    if await db.get_user_role(chat_id, user_id) or await db.get_user_reservation(chat_id, user_id):
        # Роль/бронь уже есть — ничего просить не нужно.
        return
    text, kb = await role_pick_page(chat_id, 0)
    if kb is None:
        # Свободных ролей нет — просто молчим, не дёргаем человека почём зря.
        return
    try:
        await bot.send_message(
            user_id,
            f"🎭 <b>Добро пожаловать!</b> Выберите себе роль, чтобы освоиться в чате:\n\n{text}",
            reply_markup=kb,
        )
    except Exception:
        # Частая причина — человек ни разу не писал боту в личку, Telegram
        # такое отправлять не даёт. Это не ошибка, просто тихо пропускаем.
        logger.info("Не удалось отправить выбор роли новому участнику user_id=%s (не писал боту в лс?)", user_id)


# ----------------------------------------------------------------------------
# Ответ администратора заявителю (reply на сообщение-заявку в группе/топике)
# ----------------------------------------------------------------------------
@router.message(F.chat.type.in_({"group", "supergroup"}), F.reply_to_message)
async def handle_admin_reply(message: Message):
    if settings.get("notify_chat_id") != message.chat.id:
        raise SkipHandler

    target_user_id = await db.get_user_by_message(message.reply_to_message.message_id)
    if target_user_id is None:
        raise SkipHandler

    if not is_admin(message.from_user.id):
        await react(message.chat.id, message.message_id, "🤷")
        return

    reply_text = message.text or message.caption
    if not reply_text:
        await message.reply("⚠️ Можно переслать заявителю только текстовые сообщения.")
        return

    try:
        await bot.send_message(target_user_id, f"💬 Администратор:\n{reply_text}")
    except TelegramForbiddenError:
        await message.reply("⚠️ Не удалось отправить: пользователь заблокировал бота.")
        return
    except Exception as e:
        logger.exception("Ошибка пересылки ответа: %s", e)
        await message.reply("⚠️ Произошла ошибка при отправке.")
        return

    # Чтобы дальнейшие ответы пользователя продолжали попадать в этот же тред
    await db.add_request_message(message.message_id, target_user_id, is_anchor=False)

    await react(message.chat.id, message.message_id, "✅")


# ----------------------------------------------------------------------------
# Обработка нажатия «Дать ссылку на вход»
# ----------------------------------------------------------------------------
@router.callback_query(F.data.startswith("give_link:"))
async def handle_give_link(callback: CallbackQuery):
    if not is_admin(callback.from_user.id):
        await callback.answer("⛔ Только администратор может это сделать.", show_alert=True)
        return

    if not settings.get("invite_link"):
        await callback.answer("Ссылка не настроена. Задайте её через «админка».", show_alert=True)
        return

    target_user_id = int(callback.data.split(":", 1)[1])

    # Модуль «Роли»: если в чате настроены роли, заявитель ОБЯЗАН сначала
    # выбрать одну из свободных (см. prompt_role_pick_for_applicant) — без
    # этого ссылку выдать нельзя (ТЗ, сценарий «роли участников», п.1).
    roles_chat_id = settings.get("notify_chat_id")
    if roles_chat_id and await db.list_roles(roles_chat_id):
        has_role = await db.get_user_role(roles_chat_id, target_user_id)
        has_reservation = await db.get_user_reservation(roles_chat_id, target_user_id)
        if not has_role and not has_reservation:
            await callback.answer(
                "⛔ Заявитель ещё не выбрал роль. Ссылку можно выдать только после того, "
                "как за ним закрепится роль или бронь.",
                show_alert=True,
            )
            try:
                await prompt_role_pick_for_applicant(target_user_id)
            except Exception:
                logger.exception("Не удалось повторно отправить выбор роли заявителю")
            return

    try:
        await bot.send_message(chat_id=target_user_id, text=link_message(settings["invite_link"]))
    except TelegramForbiddenError:
        await callback.answer("Не удалось отправить: пользователь заблокировал бота.", show_alert=True)
        return
    except Exception as e:
        logger.exception("Ошибка отправки ссылки: %s", e)
        await callback.answer("Произошла ошибка при отправке ссылки.", show_alert=True)
        return

    admin_username = mention_id(
        callback.from_user.id, full_name=callback.from_user.full_name, username=callback.from_user.username
    )
    try:
        new_text = (callback.message.html_text or callback.message.text or "") + (
            f"\n\n✅ Ссылка отправлена (выдал {admin_username})"
        )
        await callback.message.edit_text(new_text)
    except TelegramBadRequest:
        pass

    anchor_id = await db.get_anchor_message_id(target_user_id)
    if anchor_id:
        await db.mark_request_decided(anchor_id, "accepted", callback.from_user.id)
        try:
            await bot.unpin_chat_message(chat_id=settings["notify_chat_id"], message_id=anchor_id)
        except Exception as e:
            logger.warning("Не удалось открепить заявку: %s", e)
    await db.add_log("request_accepted", actor_id=callback.from_user.id, target_id=target_user_id)

    if target_user_id in test_mode_admins:
        await db.disable_test_mode(target_user_id)
        test_mode_admins.discard(target_user_id)
        await db.add_log("testmode_off", actor_id=target_user_id)
        try:
            await bot.send_message(target_user_id, "🧪 Тестовый режим «Входящего» выключен автоматически.")
        except Exception:
            pass

    await callback.answer("Ссылка отправлена пользователю ✅")


# ----------------------------------------------------------------------------
# Обработка отказа заявителю: запрос подтверждения -> подтверждение/отмена
# ----------------------------------------------------------------------------
@router.callback_query(F.data.startswith("reject_ask:"))
async def handle_reject_ask(callback: CallbackQuery):
    if not is_admin(callback.from_user.id):
        await callback.answer("⛔ Только администратор может это сделать.", show_alert=True)
        return
    target_user_id = int(callback.data.split(":", 1)[1])
    try:
        await callback.message.edit_reply_markup(reply_markup=reject_confirm_kb(target_user_id))
    except TelegramBadRequest:
        pass
    await callback.answer("Подтвердите отказ")


@router.callback_query(F.data.startswith("reject_cancel:"))
async def handle_reject_cancel(callback: CallbackQuery):
    if not is_admin(callback.from_user.id):
        await callback.answer("⛔ Только администратор может это сделать.", show_alert=True)
        return
    target_user_id = int(callback.data.split(":", 1)[1])
    try:
        await callback.message.edit_reply_markup(reply_markup=request_button_kb(target_user_id))
    except TelegramBadRequest:
        pass
    await callback.answer("Отменено")


@router.callback_query(F.data.startswith("reject_confirm:"))
async def handle_reject_confirm(callback: CallbackQuery):
    if not is_admin(callback.from_user.id):
        await callback.answer("⛔ Только администратор может это сделать.", show_alert=True)
        return

    target_user_id = int(callback.data.split(":", 1)[1])

    try:
        await bot.send_message(chat_id=target_user_id, text=reject_text())
    except TelegramForbiddenError:
        await callback.answer("Не удалось отправить: пользователь заблокировал бота.", show_alert=True)
        return
    except Exception as e:
        logger.exception("Ошибка отправки отказа: %s", e)
        await callback.answer("Произошла ошибка при отправке отказа.", show_alert=True)
        return

    admin_username = mention_id(
        callback.from_user.id, full_name=callback.from_user.full_name, username=callback.from_user.username
    )
    try:
        new_text = (callback.message.html_text or callback.message.text or "") + (
            f"\n\n❌ Отказано (отказал {admin_username})"
        )
        await callback.message.edit_text(new_text)
    except TelegramBadRequest:
        pass

    anchor_id = await db.get_anchor_message_id(target_user_id)
    if anchor_id:
        await db.mark_request_decided(anchor_id, "rejected", callback.from_user.id)
        try:
            await bot.unpin_chat_message(chat_id=settings["notify_chat_id"], message_id=anchor_id)
        except Exception as e:
            logger.warning("Не удалось открепить заявку: %s", e)
    await db.add_log("request_rejected", actor_id=callback.from_user.id, target_id=target_user_id)

    if target_user_id in test_mode_admins:
        await db.disable_test_mode(target_user_id)
        test_mode_admins.discard(target_user_id)
        await db.add_log("testmode_off", actor_id=target_user_id)
        try:
            await bot.send_message(target_user_id, "🧪 Тестовый режим «Входящего» выключен автоматически.")
        except Exception:
            pass

    await callback.answer("Отказ отправлен пользователю")


