# «Бот Инфа»: шуточное определение вероятности чего-либо.
# Триггер — сообщение, начинающееся с «бот инфа » (регистр не важен).
# ============================================================================

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().lower().startswith("бот инфа")),
)
async def cmd_bot_infa(message: Message):
    raw = message.text.strip()
    # Отрезаем префикс "бот инфа" (учитываем регистр исходного текста)
    phrase = raw[len("бот инфа"):].strip()

    if not phrase:
        await message.reply(
            "🤔 Напишите: <code>бот инфа {фраза}</code>\n"
            "Например: <code>бот инфа что сегодня будет дождь</code>"
        )
        return

    chance = random.randint(0, 101)
    await message.reply(f"🤔 Я думаю, что вероятность {phrase}  {chance} %")


# ============================================================================
# Закрытие/открытие чата (как у Iris-бота): «-чат» запрещает всем, кроме
# админов, писать в группе, «+чат» (или кнопка «Открыть чат») возвращает
# прежние права. Доступно только модераторам бота и выше.
# ============================================================================

# Права, которые выставляются всем участникам при закрытии чата
CHAT_LOCK_PERMISSIONS = ChatPermissions(
    can_send_messages=False,
    can_send_audios=False,
    can_send_documents=False,
    can_send_photos=False,
    can_send_videos=False,
    can_send_video_notes=False,
    can_send_voice_notes=False,
    can_send_polls=False,
    can_send_other_messages=False,
    can_add_web_page_previews=False,
)


def _chat_lock_key(chat_id: int) -> str:
    return f"chatlock:{chat_id}"


def _permissions_to_dict(perms: Optional[ChatPermissions]) -> dict:
    if perms is None:
        return {}
    return {
        "can_send_messages": perms.can_send_messages,
        "can_send_audios": perms.can_send_audios,
        "can_send_documents": perms.can_send_documents,
        "can_send_photos": perms.can_send_photos,
        "can_send_videos": perms.can_send_videos,
        "can_send_video_notes": perms.can_send_video_notes,
        "can_send_voice_notes": perms.can_send_voice_notes,
        "can_send_polls": perms.can_send_polls,
        "can_send_other_messages": perms.can_send_other_messages,
        "can_add_web_page_previews": perms.can_add_web_page_previews,
        "can_change_info": perms.can_change_info,
        "can_invite_users": perms.can_invite_users,
        "can_pin_messages": perms.can_pin_messages,
        "can_manage_topics": perms.can_manage_topics,
    }


def chat_unlock_kb(chat_id: int) -> InlineKeyboardMarkup:
    """Клавиатура под сообщением «Чат закрыт»: помимо общего «Открыть чат» —
    точечные кнопки «выключить писать» для каждого уровня бот-админов
    (модераторам/администраторам/старшим). Кто может нажать какую кнопку —
    проверяется в cb_chat_lock_level (строго старше выключаемого уровня)."""
    return InlineKeyboardMarkup(
        inline_keyboard=[
            [InlineKeyboardButton(text="🔓 Открыть чат", callback_data=f"chat_unlock:{chat_id}")],
            [InlineKeyboardButton(
                text="🔇 Выключить модераторам",
                callback_data=f"chat_lock_level:{chat_id}:{LEVEL_MODERATOR}",
            )],
            [InlineKeyboardButton(
                text="🔇 Выключить администраторам",
                callback_data=f"chat_lock_level:{chat_id}:{LEVEL_ADMIN}",
            )],
            [InlineKeyboardButton(
                text="🔇 Выключить старшим",
                callback_data=f"chat_lock_level:{chat_id}:{LEVEL_SENIOR}",
            )],
        ]
    )


async def _lock_chat(chat_id: int, until: Optional[datetime] = None) -> bool:
    """Закрывает чат: запоминает текущие права (и срок автооткрытия, если есть)."""
    try:
        chat = await bot.get_chat(chat_id)
    except (TelegramBadRequest, TelegramForbiddenError):
        chat = None
    previous = _permissions_to_dict(getattr(chat, "permissions", None))

    try:
        await bot.set_chat_permissions(chat_id, permissions=CHAT_LOCK_PERMISSIONS)
    except TelegramForbiddenError:
        return False
    except TelegramBadRequest:
        return False

    payload = {"permissions": previous, "until": until.isoformat() if until else None}
    await db.set_data(_chat_lock_key(chat_id), json.dumps(payload))
    return True


async def _unlock_chat(chat_id: int) -> bool:
    """Открывает чат обратно, восстанавливая права, которые были до закрытия."""
    row = await db.get_data(_chat_lock_key(chat_id))
    restore_kwargs = {}
    if row and row.get("data_value"):
        try:
            data = json.loads(row["data_value"])
        except (ValueError, TypeError):
            data = {}
        if isinstance(data, dict):
            # Новый формат: {"permissions": {...}, "until": ...}. Старый формат
            # (до появления сроков) — просто словарь с самими правами.
            restore_kwargs = data.get("permissions", data) if "permissions" in data else data

    if not restore_kwargs:
        restore_kwargs = _permissions_to_dict(UNMUTE_PERMISSIONS)

    try:
        await bot.set_chat_permissions(chat_id, permissions=ChatPermissions(**restore_kwargs))
    except TelegramForbiddenError:
        return False
    except TelegramBadRequest:
        return False

    await db.delete_data(_chat_lock_key(chat_id))
    return True


def _chat_level_lock_key(chat_id: int, level: int) -> str:
    return f"chatlock_level:{chat_id}:{level}"


async def _lock_chat_level(chat_id: int, level: int) -> tuple[int, int]:
    """Точечно запрещает писать в чате всем бот-админам указанного уровня —
    работает как массовый мут, а не как общие права чата (иначе обычные
    ChatPermissions вообще не действуют на реальных тг-админов). Кто
    оказался настоящим админом Telegram — сначала разжалуется (Telegram не
    даёт ограничивать админов напрямую, см. _demote_admin/_restore_admin_rights
    в модуле «Холды администраторов»), остальные — обычный restrictChatMember.
    Список пострадавших сохраняется в БД, чтобы при открытии чата вернуть
    права именно им.
    Возвращает (сколько реально выключили, признак «уже было выключено»:
    0 — ок, -1 — этот уровень уже выключен ранее)."""
    existing = await db.get_data(_chat_level_lock_key(chat_id, level))
    if existing and existing.get("data_value"):
        return 0, -1

    records: list[dict] = []
    target_ids = [uid for uid, lvl in admin_levels.items() if lvl == level]
    for user_id in target_ids:
        try:
            member = await bot.get_chat_member(chat_id, user_id)
        except (TelegramForbiddenError, TelegramBadRequest):
            continue
        if member.status in ("left", "kicked", "creator"):
            continue

        was_admin = member.status == "administrator"
        rights = _snapshot_admin_rights(member) if was_admin else None
        custom_title = getattr(member, "custom_title", None) if was_admin else None

        if was_admin and not await _demote_admin(chat_id, user_id):
            continue  # этого админа назначал не бот — трогать не можем, пропускаем

        try:
            await bot.restrict_chat_member(chat_id=chat_id, user_id=user_id, permissions=MUTE_PERMISSIONS)
        except (TelegramForbiddenError, TelegramBadRequest):
            if was_admin:
                await _restore_admin_rights(chat_id, user_id, rights, custom_title)
            continue

        records.append({"user_id": user_id, "was_admin": was_admin, "rights": rights, "custom_title": custom_title})

    await db.set_data(_chat_level_lock_key(chat_id, level), json.dumps(records))
    return len(records), 0


async def _unlock_chat_level(chat_id: int, level: int) -> int:
    """Возвращает права всем, кого затронула _lock_chat_level для этого уровня."""
    row = await db.get_data(_chat_level_lock_key(chat_id, level))
    if not row or not row.get("data_value"):
        return 0
    try:
        records = json.loads(row["data_value"])
    except (ValueError, TypeError):
        records = []
    if not isinstance(records, list):
        records = []

    restored = 0
    for rec in records:
        user_id = rec.get("user_id")
        if user_id is None:
            continue
        try:
            await bot.restrict_chat_member(chat_id=chat_id, user_id=user_id, permissions=UNMUTE_PERMISSIONS)
        except (TelegramForbiddenError, TelegramBadRequest):
            pass
        if rec.get("was_admin"):
            await _restore_admin_rights(chat_id, user_id, rec.get("rights") or {}, rec.get("custom_title"))
        restored += 1

    await db.delete_data(_chat_level_lock_key(chat_id, level))
    return restored


async def _unlock_all_chat_levels(chat_id: int) -> list[str]:
    """Общее открытие чата («+чат» / кнопка «Открыть чат») должно вернуть
    права и тем, кого выключали точечно по уровням, иначе замученные
    модераторы/админы/старшие так и останутся немыми. Возвращает названия
    уровней, которым реально что-то восстановили (для текста уведомления)."""
    restored_names = []
    for level in (LEVEL_MODERATOR, LEVEL_ADMIN, LEVEL_SENIOR):
        count = await _unlock_chat_level(chat_id, level)
        if count:
            restored_names.append(level_name(level))
    return restored_names


async def _auto_unlock_chat(chat_id: int, delay_seconds: float, expected_until: str) -> None:
    """Фоновая задача: открывает чат сама по себе, когда истёк срок из «-чат 5м»."""
    await asyncio.sleep(delay_seconds)

    row = await db.get_data(_chat_lock_key(chat_id))
    if not row or not row.get("data_value"):
        return
    try:
        data = json.loads(row["data_value"])
    except (ValueError, TypeError):
        return
    if not isinstance(data, dict) or data.get("until") != expected_until:
        # Чат уже открыли вручную либо закрыли заново с другим сроком — ничего не делаем.
        return

    if not await _unlock_chat(chat_id):
        return
    restored_levels = await _unlock_all_chat_levels(chat_id)
    levels_line = f"\nТакже вернул права: {', '.join(restored_levels)}" if restored_levels else ""
    try:
        await bot.send_message(chat_id, f"🔓 <b>Чат открыт автоматически</b>\nСрок закрытия истёк.{levels_line}")
    except Exception:
        pass
    await db.add_log("chat_unlock", chat_id=chat_id, details="авто (истёк срок)")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "-чат"),
)
async def cmd_chat_off(message: Message):
    if not has_level(message.from_user.id, required_level("chat_lock")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('chat_lock'))}» и выше.")
        return

    parts = message.text.strip().split(maxsplit=1)
    duration: Optional[timedelta] = None
    if len(parts) > 1:
        duration = parse_duration(parts[1])
        if duration is None:
            await message.reply(
                "⚠️ Не понял срок. Формат: <code>-чат 5м</code>\n"
                "Единицы: <b>с</b> — секунды, <b>м</b> — минуты, <b>ч</b> — часы, "
                "<b>д</b> — дни, <b>нед</b> — недели, <b>мес</b> — месяцы.\n"
                "Например: <code>-чат 30м</code>, <code>-чат 2ч</code>, <code>-чат 1мес</code>."
            )
            return

    until = datetime.utcnow() + duration if duration is not None else None

    ok = await _lock_chat(message.chat.id, until=until)
    if not ok:
        await message.reply("⚠️ Не удалось закрыть чат. Проверьте, что у бота есть права администратора.")
        return

    actor_name = await display_name(message.chat.id, message.from_user)
    until_line = (
        f"\n⏳ Откроется автоматически через {format_duration_ru(duration)} "
        f"({fmt_dt(until)})"
        if until else ""
    )
    await message.answer(
        f"🔒 <b>Чат закрыт</b>\nТеперь писать могут только администраторы.\n👤 Закрыл: {actor_name}{until_line}",
        reply_markup=chat_unlock_kb(message.chat.id),
    )
    await db.add_log(
        "chat_lock", chat_id=message.chat.id, actor_id=message.from_user.id,
        details=parts[1] if len(parts) > 1 else None,
    )

    if until is not None:
        asyncio.create_task(_auto_unlock_chat(message.chat.id, duration.total_seconds(), until.isoformat()))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "+чат"),
)
async def cmd_chat_on(message: Message):
    if not has_level(message.from_user.id, required_level("chat_unlock")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('chat_unlock'))}» и выше.")
        return

    ok = await _unlock_chat(message.chat.id)
    if not ok:
        await message.reply("⚠️ Не удалось открыть чат. Проверьте, что у бота есть права администратора.")
        return

    restored_levels = await _unlock_all_chat_levels(message.chat.id)
    levels_line = f"\nТакже вернул права: {', '.join(restored_levels)}" if restored_levels else ""
    actor_name = await display_name(message.chat.id, message.from_user)
    await message.answer(f"🔓 <b>Чат открыт</b>\nВсе снова могут писать сообщения.\n👤 Открыл: {actor_name}{levels_line}")
    await db.add_log("chat_unlock", chat_id=message.chat.id, actor_id=message.from_user.id)


@router.callback_query(F.data.startswith("chat_unlock:"))
async def cb_chat_unlock(callback: CallbackQuery):
    if not has_level(callback.from_user.id, LEVEL_MODERATOR):
        await callback.answer("⛔ Недостаточно прав.", show_alert=True)
        return

    chat_id = int(callback.data.split(":", 1)[1])
    ok = await _unlock_chat(chat_id)
    if not ok:
        await callback.answer("⚠️ Не удалось открыть чат.", show_alert=True)
        return

    restored_levels = await _unlock_all_chat_levels(chat_id)
    levels_line = f"\nТакже вернул права: {', '.join(restored_levels)}" if restored_levels else ""
    actor_name = await display_name(chat_id, callback.from_user)
    try:
        await callback.message.edit_text(
            f"🔓 <b>Чат открыт</b>\nВсе снова могут писать сообщения.\n👤 Открыл: {actor_name}{levels_line}"
        )
    except TelegramBadRequest:
        pass
    await db.add_log("chat_unlock", chat_id=chat_id, actor_id=callback.from_user.id)
    await callback.answer("Чат открыт")


@router.callback_query(F.data.startswith("chat_lock_level:"))
async def cb_chat_lock_level(callback: CallbackQuery):
    """Точечное выключение чата для конкретного уровня бот-админов (кнопки
    под сообщением «Чат закрыт»). Иерархия: выключить уровень может только
    тот, чей собственный уровень СТРОГО ВЫШЕ выключаемого — старший админ
    (99/3) может выключить админам и модерам, обычный админ (2) — только
    модерам. Кнопка «Выключить старшим» доступна только владельцу/выше.
    Обычным участникам чат и так закрывает базовая «-чат» (см. cmd_chat_off)."""
    try:
        _, chat_id_str, level_str = callback.data.split(":", maxsplit=2)
        chat_id = int(chat_id_str)
        level = int(level_str)
    except ValueError:
        await callback.answer()
        return

    actor_level = get_level(callback.from_user.id)
    if actor_level <= level:
        await callback.answer(
            f"⛔ Выключить «{level_name(level)}» может только уровень выше.", show_alert=True
        )
        return

    muted, status = await _lock_chat_level(chat_id, level)
    if status == -1:
        await callback.answer(f"«{level_name(level)}» уже выключены — сначала откройте чат.", show_alert=True)
        return

    actor_name = await display_name(chat_id, callback.from_user)
    try:
        await callback.message.answer(
            f"🔇 <b>{level_name(level)}</b> больше не могут писать в этом чате — до открытия чата.\n"
            f"Затронуто: {muted}\n👤 Выключил: {actor_name}"
        )
    except Exception:
        pass
    await db.add_log(
        "chat_lock_level", chat_id=chat_id, actor_id=callback.from_user.id, details=f"{level}:{muted}"
    )
    await callback.answer(f"Выключено: {muted}" if muted else "Некого выключать — в чате никого с этим уровнем нет.")


# ============================================================================
# Модерация: мут, бан, удаление сообщений (работают только в группах, только
# для админов бота — is_admin(); проверяется по OWNER_IDS + таблице admins)
# ============================================================================

_DURATION_UNITS = {
    "с": "seconds", "сек": "seconds", "секунда": "seconds", "секунды": "seconds", "секунд": "seconds",
    "м": "minutes", "мин": "minutes", "минута": "minutes", "минуты": "minutes", "минут": "minutes",
    "ч": "hours", "час": "hours", "часа": "hours", "часов": "hours",
    "д": "days", "дн": "days", "день": "days", "дня": "days", "дней": "days",
    "н": "weeks", "нед": "weeks", "неделя": "weeks", "недели": "weeks", "недель": "weeks",
    "мес": "months", "месяц": "months", "месяца": "months", "месяцев": "months",
    "г": "years", "год": "years", "года": "years", "лет": "years",
}
# Принимает как слитную запись ("30м", "2ч", "1мес"), так и полное слово,
# в том числе отдельно от числа через пробел ("2 часа", "7 дней").
_DURATION_RE = re.compile(
    r"^(\d+)\s*("
    r"сек(?:унд[аы]?)?|с|"
    r"мин(?:ут[аы]?)?|м|"
    r"час(?:а|ов)?|ч|"
    r"д(?:ень|ня|ней|н)?|"
    r"нед(?:ел[яию]|ель)?|н|"
    r"мес(?:яц[аев]*)?|"
    r"год(?:а|ов)?|лет|г"
    r")$",
    re.IGNORECASE,
)


def parse_duration(token: str) -> Optional[timedelta]:
    """Разбирает строки вида '30м', '2ч', '7д', '1нед', '1мес', '1год', а также
    '2 часа', '7 дней' и т.п. в timedelta. None, если не похоже на длительность."""
    normalized = re.sub(r"\s+", "", token.strip().lower())
    match = _DURATION_RE.match(normalized)
    if not match:
        return None
    amount = int(match.group(1))
    unit_token = match.group(2)
    unit = _DURATION_UNITS.get(unit_token)
    if unit is None:
        return None
    if unit == "months":
        # В timedelta нет месяцев — считаем месяц приблизительно как 30 дней.
        return timedelta(days=30 * amount)
    if unit == "years":
        # Аналогично — год приблизительно как 365 дней.
        return timedelta(days=365 * amount)
    return timedelta(**{unit: amount})



def has_infinite_money(user_id: int) -> bool:
    return user_id in INFINITE_MONEY_USERS


async def spend_coins(chat_id: int, user_id: int, amount: int) -> bool:
    """Списывает amount i¢ из кошелька, если хватает средств. Владельцу с
    включённым «+бесконечность» баланс не трогается — проверка всегда
    проходит, деньги не тратятся ни на что."""
    if amount <= 0:
        return True
    if has_infinite_money(user_id):
        return True
    if await is_account_frozen(chat_id, user_id):
        return False
    wallet = await db.get_wallet(chat_id, user_id)
    if int(wallet.get("coins", 0)) < amount:
        return False
    await db.add_coins(chat_id, user_id, -amount)
    return True



# Отдельное слово-число ("3") и отдельное слово-единица ("часа") нужно
# уметь распознавать вместе, даже когда после команды они разбиты пробелом,
# а не только слитно ("3ч"). Раньше команды вида "мут 3 часа" не находили
# срок (т.к. проверялось только первое слово "3" без единицы) и вместо мута
# на 3 часа тихо ставили ПЕРМАНЕНТНЫЙ мут с причиной "3 часа" — это и есть
# дыра, которую здесь закрываем.
_LONE_NUMBER_RE = re.compile(r"^\d+$")
# Разбор сумм с сокращениями: 10000 / 10к / 10k / 1.5к / 2м / 1млн / 1млрд
_AMOUNT_SUFFIXES = {
    "к": 1_000, "k": 1_000, "тыс": 1_000,
    "м": 1_000_000, "m": 1_000_000, "млн": 1_000_000,
    "млрд": 1_000_000_000, "b": 1_000_000_000, "б": 1_000_000_000,
}
_AMOUNT_RE = re.compile(
    r"^(-?\d+(?:[.,]\d+)?)\s*(тыс|млрд|млн|к|k|m|м|b|б)?$", re.IGNORECASE
)


def parse_amount(text: str) -> Optional[int]:
    """Разбирает '10000', '10к', '1.5к', '2м', '1млрд' и т.п. в целое число.
    None, если строка не похожа на сумму."""
    if not text:
        return None
    match = _AMOUNT_RE.match(text.strip().replace(" ", ""))
    if not match:
        return None
    number = float(match.group(1).replace(",", "."))
    multiplier = _AMOUNT_SUFFIXES.get((match.group(2) or "").casefold(), 1)
    return int(round(number * multiplier))


def find_amount(text: str) -> Optional[int]:
    """Ищет первую сумму (с суффиксом или без) в свободном тексте."""
    m = re.search(r"-?\d+(?:[.,]\d+)?\s*(?:тыс|млрд|млн|к|k|m|м|b|б)?", text, re.IGNORECASE)
    return parse_amount(m.group()) if m else None

def _extract_leading_duration(text: str, skip_words: int = 0) -> tuple[Optional[timedelta], Optional[str]]:
    """Достаёт срок в начале команды (после skip_words первых слов — обычно
    самого слова-команды) и возвращает (duration, reason_остаток).

    Понимает оба варианта записи:
      - слитно:  "мут 30м спам", "мут 2ч"
      - раздельно: "мут 3 часа спам", "мут 7 дней"

    Если срок не распознан — duration is None, а reason содержит весь
    остаток текста как есть (ничего не проглатывается и не подменяется)."""
    tokens = text.split()
    tokens = tokens[skip_words:]
    if not tokens:
        return None, None

    # Вариант "слитно": первое слово само по себе валидный срок ("30м", "2ч").
    single = parse_duration(tokens[0])
    if single is not None:
        rest = " ".join(tokens[1:])
        return single, (rest or None)

    # Вариант "раздельно": число, затем слово-единица ("3" + "часа").
    if len(tokens) >= 2 and _LONE_NUMBER_RE.match(tokens[0]):
        combined = parse_duration(tokens[0] + tokens[1])
        if combined is not None:
            rest = " ".join(tokens[2:])
            return combined, (rest or None)

    # Срок не найден — весь остаток уходит в причину без изменений.
    rest = " ".join(tokens)
    return None, (rest or None)


def _plural_ru(n: int, one: str, few: str, many: str) -> str:
    """Верное русское склонение числительного: 1 день, 2 дня, 5 дней и т.п."""
    n_abs = abs(n)
    if 11 <= n_abs % 100 <= 14:
        return many
    last = n_abs % 10
    if last == 1:
        return one
    if 2 <= last <= 4:
        return few
    return many


def format_duration_ru(td: timedelta) -> str:
    """Человекочитаемая длительность вроде «2 дня 3 часа» или «45 минут» —
    полными словами (день/час/минута/секунда), а не однобуквенными кодами.
    Показывает два самых крупных ненулевых разряда, чтобы не загромождать вывод."""
    total_seconds = int(td.total_seconds())
    if total_seconds <= 0:
        return "0 секунд"
    days, rem = divmod(total_seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, seconds = divmod(rem, 60)
    units = [
        (days, "день", "дня", "дней"),
        (hours, "час", "часа", "часов"),
        (minutes, "минута", "минуты", "минут"),
        (seconds, "секунда", "секунды", "секунд"),
    ]
    parts = [f"{value} {_plural_ru(value, one, few, many)}" for value, one, few, many in units if value]
    return " ".join(parts[:2]) if parts else "0 секунд"


def compact_elapsed_ru(dt: datetime) -> str:
    total_seconds = max(int((datetime.utcnow() - dt).total_seconds()), 0)
    if total_seconds < 60:
        return "меньше минуты"
    days, rem = divmod(total_seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    if days >= 30:
        months, rem_days = divmod(days, 30)
        return (
            f"{months} {_plural_ru(months, 'месяц', 'месяца', 'месяцев')} "
            f"{rem_days} {_plural_ru(rem_days, 'день', 'дня', 'дней')}"
        )
    if days:
        return f"{days} {_plural_ru(days, 'день', 'дня', 'дней')} {hours} ч"
    if hours:
        return f"{hours} ч {minutes} мин"
    return f"{minutes} мин"

def relative_time_ru(dt: Optional[datetime]) -> str:
    """«только что» / «N мин назад» / «N ч назад» / «N дн назад» / дата — для
    строки «Последний актив» в карточке профиля (как у Iris)."""
    if dt is None:
        return "неизвестно"
    total_seconds = max(int((datetime.utcnow() - dt).total_seconds()), 0)
    if total_seconds < 120:
        return "только что"
    minutes = total_seconds // 60
    if minutes < 60:
        return f"{minutes} {_plural_ru(minutes, 'минуту', 'минуты', 'минут')} назад"
    hours = minutes // 60
    if hours < 24:
        return f"{hours} {_plural_ru(hours, 'час', 'часа', 'часов')} назад"
    days = hours // 24
    if days < 14:
        return f"{days} {_plural_ru(days, 'день', 'дня', 'дней')} назад"
    return fmt_date(dt)


