# ----------------------------------------------------------------------------
# Общий резолвер цели команды из ТЕКСТА (без reply) — «мут @username причина»,
# «бан 123456789 причина» и т.п. Приоритет источников цели описан в вызывающем
# коде (сначала пробуем это, потом падаем на reply_to_message).
#
# target возвращается как SimpleNamespace с теми же полями, что нужны
# остальному коду от aiogram.types.User: .id, .full_name, .username, .is_bot —
# этого достаточно и для display_name()/mention_id(), и для проверок «не бот»
# в _require_moderation_target. Если юзернейм есть в тексте, но бот его не
# знает (не встречал в известных участниках чата) — id=None, это отдельный
# сигнал вызывающему коду вывести понятную ошибку, а не молча падать на reply.
# ----------------------------------------------------------------------------
async def resolve_command_target(
    message: Message, trigger_words: int = 1, allow_bare_id: bool = True, text: Optional[str] = None
) -> tuple[Optional[SimpleNamespace], str]:
    """Пытается вынуть цель команды прямо из текста команды.

    trigger_words — сколько первых слов текста составляют само слово-триггер
    команды (обычно 1, например «мут»; но у «+тг админ» триггер — 2 слова,
    цель по голому ID тогда третьим словом, а не вторым). На поиск entity
    (mention/text_mention) не влияет — они ищутся по всему тексту вне
    зависимости от положения относительно триггера.

    allow_bare_id — разрешить трактовать голое число сразу после триггера как
    ID цели. Выключается для команд, где число на этой позиции означает
    что-то другое (например, «наградить 5» — 5 это степень награды, а не
    ID; для такой команды указать цель по голому ID нельзя в принципе —
    только @username/text_mention/reply, это не ошибка, а неустранимая
    синтаксическая неоднозначность).

    Порядок проверки:
      1. entity text_mention — Telegram сам прикрепляет к тексту .user (когда
         текст со ссылкой tg://user?id=... переслали/скопировали) — цель
         известна напрямую, поход в БД не нужен.
      2. entity mention — обычный @username, набранный вручную — ищем среди
         известных боту участников ЭТОГО чата (db.get_known_user_by_username_in_chat).
      3. (если allow_bare_id) слово сразу после триггера состоит только из
         цифр — трактуем как голый Telegram user_id (полностью доверяем
         вызывающему, дальше есть отдельные проверки прав/бот/уровень там,
         где они нужны).

    Возвращает (target, remaining_text). remaining_text — это message.text
    с вырезанным токеном цели, чтобы существующие парсеры длительности/причины
    (_extract_leading_duration и т.п.) увидели текст так, будто цели в нём
    никогда и не было — сигнатуры этих парсеров не меняются.

    Если ничего не подошло — возвращает (None, message.text) без изменений,
    вызывающий код должен упасть на старую ветку "нужен reply".

    Примечание: entity.offset/length у Telegram считаются в UTF-16 code units,
    а срез Python-строки — в code points. Для обычного текста (кириллица,
    латиница, цифры, @) это одно и то же; расхождение возможно только если
    перед токеном цели в этом же сообщении встретится не-BMP символ (редкие
    эмодзи и т.п.) — этим случаем осознанно пренебрегаем, как и остальной код
    проекта, работающий с entity.offset напрямую."""
    text = text if text is not None else (message.text or "")
    if not text.strip():
        return None, text

    for entity in message.entities or []:
        if entity.type == "text_mention" and entity.user is not None:
            u = entity.user
            remaining = text[:entity.offset] + text[entity.offset + entity.length:]
            target = SimpleNamespace(id=u.id, full_name=u.full_name, username=u.username, is_bot=u.is_bot)
            return target, remaining
        if entity.type == "mention":
            username = text[entity.offset + 1: entity.offset + entity.length]  # без ведущего @
            remaining = text[:entity.offset] + text[entity.offset + entity.length:]
            known = await db.get_known_user_by_username_in_chat(message.chat.id, username)
            if known:
                target = SimpleNamespace(
                    id=known["user_id"],
                    full_name=known.get("full_name"),
                    username=known.get("username") or username,
                    is_bot=False,
                )
            else:
                target = SimpleNamespace(id=None, full_name=None, username=username, is_bot=None)
            return target, remaining

    if not allow_bare_id:
        return None, text

    words = text.split()
    if len(words) > trigger_words and words[trigger_words].isdigit():
        remaining = " ".join(words[:trigger_words] + words[trigger_words + 1:])
        target = SimpleNamespace(id=int(words[trigger_words]), full_name=None, username=None, is_bot=None)
        return target, remaining

    return None, text


async def _require_moderation_target(
    message: Message, command_key: str = "mute"
) -> tuple[Optional[SimpleNamespace], str]:
    """Общие проверки для команд модерации: уровень прав (по дереву команд),
    цель (текстом @username/ID — приоритет, иначе ответ на сообщение), не
    бот, не админ равного/более высокого уровня.

    Возвращает (target, remaining_text). target — не Message: вызывающий код
    берёт .id/.full_name/.username/.is_bot напрямую, без .from_user.
    remaining_text — message.text с вырезанным токеном цели (если цель была
    в тексте) — передавать дальше в _extract_leading_duration и т.п. вместо
    message.text.strip(), чтобы токен цели не попал в причину/длительность.
    При любой ошибке уже отправлен ответ пользователю; target is None —
    сигнал вызывающему коду молча выйти."""
    min_level = required_level(command_key)
    actor_level = get_level(message.from_user.id)
    if actor_level < min_level:
        if actor_level > 0:
            await message.reply(
                f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше."
            )
        return None, message.text

    target, remaining = await resolve_command_target(message)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после команды."
        )
        return None, message.text
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел "
            "в этом чате. Попробуйте ответом на его сообщение, если оно есть."
        )
        return None, message.text
    if target.id == message.from_user.id:
        await message.reply("Нельзя применить команду к самому себе 🙂")
        return None, message.text
    if target.is_bot:
        await message.reply("Ботов это не касается 🤖")
        return None, message.text
    target_level = get_level(target.id)
    if target_level > 0 and target_level >= actor_level:
        await message.reply("Нельзя применить команду к администратору равного или более высокого уровня 🙂")
        return None, message.text
    return target, remaining


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "мут"),
)
async def cmd_mute(message: Message):
    target, remaining = await _require_moderation_target(message, command_key="mute")
    if target is None:
        return

    duration, reason = _extract_leading_duration(remaining.strip(), skip_words=1)
    duration = duration if duration is not None else MUTE_DEFAULT_DURATION

    until = datetime.utcnow() + duration

    try:
        member = await bot.get_chat_member(message.chat.id, target.id)
    except Exception:
        member = None
    if member is not None and member.status == "administrator":
        await _start_admin_action_confirm(message, target, "mute", until, duration, reason)
        return
    if member is not None and member.user.is_bot:
        await message.reply("Ботов это не касается 🤖")
        return

    try:
        await bot.restrict_chat_member(
            chat_id=message.chat.id,
            user_id=target.id,
            permissions=MUTE_PERMISSIONS,
            until_date=until,
        )
    except TelegramForbiddenError:
        await message.reply("⚠️ У бота недостаточно прав, чтобы ограничивать участников.")
        return
    except TelegramBadRequest as e:
        await message.reply(f"⚠️ Не удалось замутить: {e.message}")
        return

    await db.add_mute(message.chat.id, target.id, message.from_user.id, until, reason)
    if until is not None:
        asyncio.create_task(_auto_unmute(message.chat.id, target.id, until.isoformat()))

    actor_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    if until:
        until_text = f"{format_duration_ru(duration)} (до {fmt_dt(until)})"
    else:
        until_text = "навсегда"
    reason_text = html.escape(reason) if reason else "не указана"
    await message.reply(
        "🔇 <b>Мут выдан</b>\n"
        "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"👤 Кто: {actor_name}\n"
        f"🎯 Кому: {target_name}\n"
        f"⏳ Срок: {until_text}\n"
        f"📝 Причина: {reason_text}"
    )
    await db.add_log(
        "mute", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=reason,
    )

async def reschedule_user_mutes() -> None:
    """При старте бота восстанавливает задачи авто-снятия мута для обычных
    участников (не через холд администратора)."""
    rows = await db.list_all_active_mutes()
    restored = 0
    for row in rows:
        asyncio.create_task(_auto_unmute(row["chat_id"], row["user_id"], row["muted_until"].isoformat()))
        restored += 1
    if restored:
        logger.info("Восстановлено пользовательских мутов: %d", restored)


