async def cmd_ban(message: Message):
    target, remaining = await _require_moderation_target(message, command_key="ban")
    if target is None:
        return

    parts = remaining.strip().split(maxsplit=1)[1:]
    reason = parts[0] if parts else None

    try:
        member = await bot.get_chat_member(message.chat.id, target.id)
    except Exception:
        member = None
    if member is not None and member.user.is_bot:
        await message.reply("Ботов это не касается 🤖")
        return
    if member is not None and member.status == "administrator":
        await _start_admin_action_confirm(message, target, "ban", None, None, reason)
        return

    target_name = await display_name(message.chat.id, target)
    pending_confirmations[message.from_user.id] = {
        "action": "ban",
        "chat_id": message.chat.id,
        "target_id": target.id,
        "reason": reason,
    }
    kb = confirm_kb(
        yes_data=f"ban_yes:{message.from_user.id}",
        no_data=f"ban_no:{message.from_user.id}",
        yes_text="🔨 Да, забанить",
    )
    reason_text = html.escape(reason) if reason else "не указана"
