@router.callback_query(F.data.startswith("ban_yes:"))
async def confirm_ban(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return
    if not has_level(callback.from_user.id, required_level("ban")):
        await callback.answer(f"⛔ Только «{level_name(required_level('ban'))}» и выше может это сделать.", show_alert=True)
        return

    payload = pending_confirmations.pop(initiator_id, None)
    if not payload or payload.get("action") != "ban":
        await callback.answer("Запрос устарел, попробуйте снова.", show_alert=True)
        return

    chat_id = payload["chat_id"]
    target_id = payload["target_id"]
    reason = payload.get("reason")

    try:
        await bot.ban_chat_member(chat_id=chat_id, user_id=target_id)
    except TelegramForbiddenError:
        await callback.message.edit_text("⚠️ У бота недостаточно прав, чтобы банить участников.")
        await callback.answer()
        return
    except TelegramBadRequest as e:
        await callback.message.edit_text(f"⚠️ Не удалось забанить: {e.message}")
        await callback.answer()
        return

    await db.add_ban(chat_id, target_id, initiator_id, reason)
    await db.remove_mute(chat_id, target_id)

    actor_name = await display_name_by_id(chat_id, initiator_id)
    target_name = await display_name_by_id(chat_id, target_id)
    reason_text = html.escape(reason) if reason else "не указана"
    try:
        await callback.message.edit_text(
            f"🔨 <b>Бан выдан</b>\n{DIVIDER}\n"
            f"👤 Кто: {actor_name}\n"
            f"🎯 Кому: {target_name}\n"
            f"📝 Причина: {reason_text}"
        )
    except TelegramBadRequest:
        pass
    await db.add_log("ban", chat_id=chat_id, actor_id=initiator_id, target_id=target_id, details=reason)
    await callback.answer("Забанен(а) 🔨")


