# ----------------------------------------------------------------------------
# «Аварийный рубильник»: /nurd123helpg15 — доступен ТОЛЬКО владельцам из .env
# (OWNER_IDS), больше никому и никак не выдаётся и не проверяется по
# admin_levels/БД. Название команды намеренно бессмысленное и не в общем
# списке команд — чтобы её не находили случайно и не знали о её существовании
# рядовые админы. От любого, кто не владелец, бот отвечает молчанием (как на
# неизвестную команду), не подтверждая даже сам факт её существования.
#
# Делает необратимо и максимально полно (в рамках того, что вообще разрешено
# Bot API — у ботов НЕТ доступа к полному «удалить группу навсегда», это
# может сделать только создатель группы руками в приложении Telegram):
#   1. снимает права администратора со всех админов чата (кроме самого бота);
#   2. банит (удаляет из чата) всех участников, известных боту (known_users);
#   3. пытается удалить как можно больше сообщений чата (перебором message_id
#      назад от текущего — Bot API не даёт списка сообщений, поэтому это
#      единственный способ; получится не всё — свежий стандартный лимит
#      Telegram на удаление чужих сообщений ботом составляет 48 часов, более
#      старые чужие сообщения бот удалить не может при всём желании);
#   4. выходит из чата.
# ----------------------------------------------------------------------------
NUKE_COMMAND = "/nurd123helpg15"
NUKE_DELETE_MAX_MESSAGES = 20000  # предохранитель, чтобы не уйти в бесконечный перебор на старых огромных чатах


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].split("@")[0].casefold() == NUKE_COMMAND),
)
async def cmd_nuke(message: Message):
    if not is_owner(message.from_user.id):
        return  # молчание — не подтверждаем, не отказываем, просто ничего не происходит

    pending_confirmations[message.from_user.id] = {
        "action": "nuke",
        "chat_id": message.chat.id,
    }
    kb = confirm_kb(
        yes_data=f"nuke_yes:{message.from_user.id}",
        no_data=f"nuke_no:{message.from_user.id}",
        yes_text="☢️ Да, снести всё",
    )
    await message.reply(
        confirm_text(
            "Полный снос чата?",
            [
                "Со всех админов будут сняты права.",
                "Все известные боту участники будут удалены (бан).",
                "Бот попытается удалить максимум сообщений чата.",
                "После этого бот выйдет из чата.",
            ],
        ),
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("nuke_yes:"))
async def confirm_nuke(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return
    if not is_owner(callback.from_user.id):
        await callback.answer()
        return

    payload = pending_confirmations.pop(initiator_id, None)
    if not payload or payload.get("action") != "nuke":
        await callback.answer("Запрос устарел, попробуйте снова.", show_alert=True)
        return

    chat_id = payload["chat_id"]
    last_message_id = callback.message.message_id

    try:
        await callback.message.edit_text("☢️ Начинаю снос чата, это может занять время...")
    except TelegramBadRequest:
        pass
    await callback.answer()

    await db.add_log("nuke_started", chat_id=chat_id, actor_id=initiator_id)

    # 1. Снимаем права администратора со всех, кого Telegram считает админами
    # этого чата (кроме самого бота — себя бот разжаловать не может, да и не
    # нужно: он и так уйдёт из чата последним шагом).
    demoted = 0
    try:
        admins = await bot.get_chat_administrators(chat_id)
    except Exception:
        admins = []
    me = await bot.get_me()
    for member in admins:
        if member.user.id == me.id or member.user.is_bot:
            continue
        if member.status == "creator":
            continue  # создателя группы у Telegram снять с прав нельзя в принципе
        try:
            await bot.promote_chat_member(
                chat_id,
                member.user.id,
                can_manage_chat=False,
                can_delete_messages=False,
                can_manage_video_chats=False,
                can_restrict_members=False,
                can_promote_members=False,
                can_change_info=False,
                can_invite_users=False,
                can_pin_messages=False,
            )
            demoted += 1
        except Exception:
            pass
        await asyncio.sleep(0.1)

    # 2. Баним всех известных боту участников чата.
    banned = 0
    known_users, _total = await db.list_known_users(chat_id, limit=1_000_000, offset=0)
    for row in known_users:
        user_id = row["user_id"]
        if user_id == me.id or user_id in OWNER_IDS:
            continue
        try:
            await bot.ban_chat_member(chat_id, user_id)
            banned += 1
        except Exception:
            pass
        await asyncio.sleep(0.05)

    # 3. Перебором пытаемся удалить как можно больше сообщений чата — с
    # текущего message_id и назад. Bot API не даёт список сообщений чата,
    # поэтому это единственный доступный ботам способ; часть сообщений не
    # удалится (старше 48 часов, чужие без прав, уже удалённые и т.п.) —
    # это ожидаемо и не является ошибкой.
    deleted = 0
    start_id = last_message_id
    end_id = max(1, start_id - NUKE_DELETE_MAX_MESSAGES)
    for msg_id in range(start_id, end_id - 1, -1):
        try:
            ok = await bot.delete_message(chat_id, msg_id)
            if ok:
                deleted += 1
        except TelegramForbiddenError:
            break  # бота вот-вот выкинут/у бота нет прав вообще — дальше пробовать бессмысленно
        except Exception:
            pass
        if msg_id % 25 == 0:
            await asyncio.sleep(0.3)  # не долбить Telegram флудом

    await db.add_log(
        "nuke_finished",
        chat_id=chat_id,
        actor_id=initiator_id,
        details=f"demoted={demoted} banned={banned} deleted={deleted}",
    )

    # 4. Выходим из чата.
    try:
        await bot.send_message(
            chat_id,
            f"☢️ Готово: снято прав — {demoted}, удалено участников — {banned}, "
            f"удалено сообщений — {deleted}. Бот покидает чат.",
        )
    except Exception:
        pass
    try:
        await bot.leave_chat(chat_id)
    except Exception:
        pass


@router.callback_query(F.data.startswith("nuke_no:"))
async def cancel_nuke(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id:
        await callback.answer()
        return
    pending_confirmations.pop(initiator_id, None)
    try:
        await callback.message.edit_text("Отменено — снос чата не выполнен.")
    except TelegramBadRequest:
        pass
    await callback.answer()


