# ----------------------------------------------------------------------------
# Владелец: заморозка счёта и конфискация i¢ — доступно ТОЛЬКО OWNER_IDS (.env),
# по тому же принципу, что и «+бесконечность» выше (молчание для всех остальных,
# существование команды не выдаётся). Заморозка хранится в bot_data
# (db.set_data/get_data/delete_data) под ключом frozen:{chat_id}:{user_id} —
# как и другие лёгкие тумблеры бота (+чат, +рстик и т.п.).
# ----------------------------------------------------------------------------
def _frozen_key(chat_id: int, user_id: int) -> str:
    return f"frozen:{chat_id}:{user_id}"


async def is_account_frozen(chat_id: int, user_id: int) -> bool:
    row = await db.get_data(_frozen_key(chat_id, user_id))
    return bool(row and row.get("data_value") == "1")


def _is_freeze_command(text: Optional[str]) -> bool:
    if not text:
        return False
    words = text.strip().casefold().split()
    return len(words) >= 2 and words[0] in ("заморозить", "разморозить") and words[1] in ("счет", "счёт")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_freeze_command),
)
async def cmd_freeze_account(message: Message):
    if not is_owner(message.from_user.id):
        return  # молчание — как и у +бесконечность, не выдаём существование команды

    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после «заморозить счет»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате."
        )
        return

    freeze = (message.text.strip().casefold().split() or [""])[0] == "заморозить"
    key = _frozen_key(message.chat.id, target.id)
    name = await display_name(message.chat.id, target)
    if freeze:
        await db.set_data(key, "1", updated_by=message.from_user.id)
        await message.reply(f"🧊 Счёт {name} заморожен — фарм, покупки и переводы недоступны.")
    else:
        await db.delete_data(key)
        await message.reply(f"✅ Счёт {name} разморожен.")
    await db.add_log(
        "account_freeze", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=str(freeze),
    )


def _is_confiscate_command(text: Optional[str]) -> bool:
    if not text:
        return False
    return (text.strip().casefold().split() or [""])[0] == "конфисковать"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_confiscate_command),
)
async def cmd_confiscate(message: Message):
    if not is_owner(message.from_user.id):
        return

    target, remaining = await resolve_command_target(message, trigger_words=1, allow_bare_id=False)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username сразу после «конфисковать»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате."
        )
        return

    wallet = await db.get_wallet(message.chat.id, target.id)
    balance = int(wallet.get("coins", 0))

    amount = find_amount(remaining)  # без суммы — забрать всё, поддерживает 1к/1м/3млрд
    if amount is None:
        amount = balance
    amount = max(0, min(amount, balance))

    if amount <= 0:
        await message.reply("У этого пользователя нечего конфисковывать (баланс 0 i¢).")
        return

    await db.add_coins(message.chat.id, target.id, -amount)
    name = await display_name(message.chat.id, target)
    await message.reply(f"👮 Конфисковано у {name}: <b>{amount}</b> i¢. Остаток: {balance - amount} i¢.")
    await db.add_log(
        "account_confiscate", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=str(amount),
    )

