@router.callback_query(F.data.startswith("duel_accept:"))
async def cb_duel_accept(callback: CallbackQuery):
    err = await _duel_do_accept(callback.message.chat.id, callback.from_user.id)
    if err:
        await callback.answer(err, show_alert=True)
        return
    await _duel_try_remove_markup(callback)
    await callback.answer()


