# ============================================================================
# Модуль «Разное» — простые утилитные команды без обращения к БД (по образцу
# Iris): рандом, инфа/выбери/данет/жребий/кто, пинг-команды, «!скажи».
# Все команды по умолчанию доступны всем (level=0, overridable=True) — порог
# при желании меняется как обычно через «право»/«дк» (см. COMMAND_REGISTRY,
# ключи misc_*).
# ============================================================================
_RANDOM_RE = re.compile(r"(?i)^рандом(?:\s+(-?\d+)(?:\s+(-?\d+))?)?\s*$")


def _check_misc_access(user_id: int, key: str) -> bool:
    """Общая проверка доступа для команд «Разное» — по умолчанию открыты всем,
    но админ мог поднять порог командой «право»/«дк»."""
    return has_level(user_id, required_level(key))


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and _RANDOM_RE.match(t.strip()) is not None),
)
async def cmd_misc_random(message: Message):
    if not _check_misc_access(message.from_user.id, "misc_random"):
        return
    match = _RANDOM_RE.match(message.text.strip())
    first, second = match.group(1), match.group(2)
    if first is None:
        await message.reply(
            "Использование: <code>рандом {число_1} {число_2}</code>\n"
            "Второй параметр необязателен — тогда диапазон от 0 до {число_1}.\n"
            "Например: <code>рандом 100</code> или <code>рандом 10 20</code>"
        )
        return
    low, high = (0, int(first)) if second is None else (int(first), int(second))
    if low > high:
        low, high = high, low
    await message.answer(f"🎲 {random.randint(low, high)}")


