# ============================================================================
# Модуль «Фото-команды» (.сдб, .цитата) и «Озвучка» (.скажи) — по образцу
# команд из https://teletype.in/@celestiana/photo-commands и
# https://teletype.in/@celestiana/misc-commands. Картинки рисуются на лету
# через Pillow (без внешних шаблонов/API), озвучка — через gTTS + ffmpeg.
# ============================================================================


async def _fetch_avatar_bytes(user_id: int) -> Optional[bytes]:
    """Скачивает текущее фото профиля пользователя (самое крупное доступное).
    None, если фото нет или Telegram не отдал (приватность/бот и т.п.) —
    вызывающий код рисует заглушку вместо реального аватара."""
    try:
        photos = await bot.get_user_profile_photos(user_id, limit=1)
        if not photos.photos:
            return None
        file_id = photos.photos[0][-1].file_id
        buf = BytesIO()
        await bot.download(file_id, destination=buf)
        buf.seek(0)
        return buf.read()
    except Exception:
        return None


def _load_font(size: int, bold: bool = False, italic: bool = False) -> ImageFont.FreeTypeFont:
    """Ищет DejaVu Sans (кириллица «из коробки» почти на любом Linux-сервере
    с установленным пакетом fonts-dejavu-core — часто уже стоит как
    зависимость matplotlib/Pillow). Если не нашли — падаем на растровый
    шрифт Pillow по умолчанию (без кириллицы, но хотя бы не падаем)."""
    if italic and bold:
        names = ["DejaVuSans-BoldOblique.ttf"]
    elif italic:
        names = ["DejaVuSans-Oblique.ttf"]
    elif bold:
        names = ["DejaVuSans-Bold.ttf"]
    else:
        names = ["DejaVuSans.ttf"]
    dirs = ["/usr/share/fonts/truetype/dejavu/", "/usr/share/fonts/truetype/liberation/", ""]
    for d in dirs:
        for name in names:
            try:
                return ImageFont.truetype(d + name, size)
            except Exception:
                continue
    return ImageFont.load_default()


def _circular_avatar(data: Optional[bytes], size: int) -> Image.Image:
    """Аватар, вписанный в круг размером size×size (RGBA с альфа-маской).
    Если данных нет/не открылись — рисует нейтральную серую заглушку."""
    im = None
    if data:
        try:
            im = ImageOps.fit(Image.open(BytesIO(data)).convert("RGB"), (size, size), Image.LANCZOS)
        except Exception:
            im = None
    if im is None:
        im = Image.new("RGB", (size, size), (100, 100, 112))
        d = ImageDraw.Draw(im)
        d.ellipse([size * 0.28, size * 0.16, size * 0.72, size * 0.58], fill=(160, 160, 172))
        d.ellipse([size * 0.08, size * 0.60, size * 0.92, size * 1.25], fill=(160, 160, 172))
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size, size), fill=255)
    out = Image.new("RGBA", (size, size))
    out.paste(im, (0, 0), mask)
    return out


async def _plain_target_name(chat_id: int, target: SimpleNamespace) -> str:
    """Имя цели БЕЗ HTML-разметки — для рисования текста на изображении
    (в отличие от display_name_by_id, который всегда возвращает <a> ссылку)."""
    nickname = await db.get_nickname(chat_id, target.id) if target.id else None
    if nickname:
        return nickname
    if getattr(target, "full_name", None):
        return target.full_name
    if getattr(target, "username", None):
        return f"@{target.username}"
    return str(target.id) if target.id else "Неизвестный"


# ---- .сдб — «сертификат долбоёба» -----------------------------------------
SDB_REASONS = [
    "за выдающиеся успехи в области дурости",
    "за отвагу в чтении переписки без очков",
    "за героическое поедание майонеза ложкой",
    "за попытки решить чужие проблемы советами из интернета",
    "за уверенное владение навыком «не читал, но осуждаю»",
    "за виртуозное умение путать сарказм с фактами",
    "за настойчивость в спорах с модераторами",
    "за профессиональный сон на созвонах",
    "за коллекционирование единиц в чатах не по делу",
    "за отправку войсов вместо текста в 3 часа ночи",
    "за упорный отказ читать закреплённые сообщения",
    "за легендарное чувство юмора уровня «баян 2012 года»",
]


def _render_sdb_certificate(name: str, avatar_bytes: Optional[bytes], reason: str, percent: int) -> BytesIO:
    W, H = 1000, 680
    img = Image.new("RGB", (W, H), (245, 236, 210))
    draw = ImageDraw.Draw(img)

    border = (120, 40, 40)
    draw.rectangle([20, 20, W - 20, H - 20], outline=border, width=6)
    draw.rectangle([32, 32, W - 32, H - 32], outline=border, width=2)

    title_font = _load_font(44, bold=True)
    sub_font = _load_font(22)
    name_font = _load_font(38, bold=True)
    reason_font = _load_font(22, italic=True)
    small_font = _load_font(18)
    seal_font = _load_font(14, bold=True)

    title = "СЕРТИФИКАТ ДОЛБОЁБА"
    draw.text(((W - draw.textlength(title, font=title_font)) / 2, 58), title, font=title_font, fill=(120, 20, 20))

    sub = "настоящим удостоверяется, что"
    draw.text(((W - draw.textlength(sub, font=sub_font)) / 2, 126), sub, font=sub_font, fill=(70, 60, 40))

    avatar_size = 170
    avatar = _circular_avatar(avatar_bytes, avatar_size)
    ax, ay = (W - avatar_size) // 2, 168
    ring = 6
    draw.ellipse([ax - ring, ay - ring, ax + avatar_size + ring, ay + avatar_size + ring], outline=(180, 140, 40), width=4)
    img.paste(avatar, (ax, ay), avatar)

    ny = ay + avatar_size + 22
    draw.text(((W - draw.textlength(name, font=name_font)) / 2, ny), name, font=name_font, fill=(40, 30, 20))

    reason_text = f"«{reason}»"
    draw.text(((W - draw.textlength(reason_text, font=reason_font)) / 2, ny + 56), reason_text, font=reason_font, fill=(90, 70, 40))

    footer = f"Профпригодность к долбоёбству: {percent}%"
    draw.text(((W - draw.textlength(footer, font=small_font)) / 2, H - 90), footer, font=small_font, fill=(70, 60, 40))

    date_text = f"Дата выдачи: {local_now().strftime('%d.%m.%Y')}"
    draw.text((60, H - 60), date_text, font=small_font, fill=(70, 60, 40))

    scx, scy, sr = W - 130, H - 110, 55
    draw.ellipse([scx - sr, scy - sr, scx + sr, scy + sr], outline=(120, 20, 20), width=3)
    draw.ellipse([scx - sr + 8, scy - sr + 8, scx + sr - 8, scy + sr - 8], outline=(120, 20, 20), width=1)
    seal_text = "УТВЕРЖДЕНО"
    draw.text((scx - draw.textlength(seal_text, font=seal_font) / 2, scy - 8), seal_text, font=seal_font, fill=(120, 20, 20))

    buf = BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return buf


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[:1] == [".сдб"]),
)
async def cmd_sdb(message: Message):
    if not _check_misc_access(message.from_user.id, "photo_sdb"):
        return
    target, _ = await resolve_command_target(message, trigger_words=1)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply("Укажите участника: «.сдб @username» (или «.сдб ID»), либо ответом на его сообщение.")
        return
    if target.id is None:
        await message.reply("Не удалось определить участника по этому username — попробуйте ответом на его сообщение.")
        return

    name = await _plain_target_name(message.chat.id, target)
    avatar_bytes = await _fetch_avatar_bytes(target.id)
    reason = random.choice(SDB_REASONS)
    percent = random.randint(69, 100)
    try:
        buf = await asyncio.to_thread(_render_sdb_certificate, name, avatar_bytes, reason, percent)
    except Exception:
        logger.exception("Не удалось сгенерировать сертификат долбоёба")
        await message.reply("Не получилось сгенерировать сертификат, попробуйте позже.")
        return
    await message.reply_photo(BufferedInputFile(buf.read(), filename="sdb.png"))


