def _list_local_bg_files() -> list[str]:
    """Свои картинки-фоны: любые .jpg/.jpeg/.png/.webp в папке images/ рядом
    с bot.py (кроме служебной подпапки _cache с кэшем скачанных ссылок).
    Если положить сюда файлы — они в приоритете перед скачиванием по ссылкам."""
    if not os.path.isdir(QUOTE_BG_DIR):
        return []
    out = []
    for fn in os.listdir(QUOTE_BG_DIR):
        if fn.startswith("_"):
            continue
        if fn.lower().endswith((".jpg", ".jpeg", ".png", ".webp")):
            out.append(os.path.join(QUOTE_BG_DIR, fn))
    return out


def _download_bg_url(url: str) -> Optional[bytes]:
    """Скачивает картинку по ссылке (с таймаутом) и кэширует на диск в
    images/_cache/<hash>.jpg — повторно эта же ссылка из сети уже не тянется."""
    os.makedirs(QUOTE_BG_CACHE_DIR, exist_ok=True)
    key = hashlib.sha1(url.encode()).hexdigest()[:16]
    cache_path = os.path.join(QUOTE_BG_CACHE_DIR, f"{key}.jpg")
    if os.path.isfile(cache_path):
        try:
            with open(cache_path, "rb") as f:
                return f.read()
        except Exception:
            pass
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=8) as resp:
            data = resp.read()
        with open(cache_path, "wb") as f:
            f.write(data)
        return data
    except Exception:
        logger.warning("Не удалось скачать фон карточки-цитаты (%s)", url)
        return None


def _pick_quote_bg_photo() -> Optional[bytes]:
    """Байты фото для фона карточки: сперва пробуем локальную папку images/,
    если она пустая/отсутствует — случайную ссылку из QUOTE_BG_URLS (пробуя
    по очереди, пока какая-то не скачается)."""
    local = _list_local_bg_files()
    if local:
        path = random.choice(local)
        try:
            with open(path, "rb") as f:
                return f.read()
        except Exception:
            pass
    urls = QUOTE_BG_URLS.copy()
    random.shuffle(urls)
    for url in urls:
        data = _download_bg_url(url)
        if data:
            return data
    return None


# Палитры для запасного «атмосферного» фона — используются только если не
# нашлось ни локальных картинок, ни рабочего интернета для скачивания ссылок.
_QUOTE_BG_PALETTES = [
    {"base": (26, 19, 15), "blobs": [(95, 62, 40), (150, 95, 50), (40, 30, 26)]},
    {"base": (13, 21, 21), "blobs": [(30, 62, 56), (52, 84, 74), (17, 30, 30)]},
    {"base": (17, 13, 24), "blobs": [(62, 40, 82), (94, 62, 114), (23, 17, 32)]},
    {"base": (23, 16, 13), "blobs": [(124, 72, 40), (166, 104, 62), (30, 22, 18)]},
    {"base": (11, 18, 25), "blobs": [(30, 52, 84), (52, 84, 124), (15, 24, 34)]},
]


def _generate_quote_bg_fallback(w: int, h: int) -> Image.Image:
    """Аварийный процедурный фон (без фото) — на случай, если нет ни своих
    картинок в images/, ни доступа в сеть, чтобы скачать их по ссылке."""
    palette = random.choice(_QUOTE_BG_PALETTES)
    bw, bh = w * 2, h * 2
    img = Image.new("RGB", (bw, bh), palette["base"])
    draw = ImageDraw.Draw(img, "RGBA")
    for _ in range(random.randint(5, 8)):
        color = random.choice(palette["blobs"])
        r = random.randint(int(bw * 0.22), int(bw * 0.5))
        cx = random.randint(0, bw)
        cy = random.randint(0, bh)
        alpha = random.randint(90, 160)
        draw.ellipse([cx - r, cy - r, cx + r, cy + r], fill=(*color, alpha))
    img = img.filter(ImageFilter.GaussianBlur(radius=bw * 0.045))
    img = img.resize((w, h), Image.LANCZOS)
    vignette = Image.new("L", (w, h), 0)
    vd = ImageDraw.Draw(vignette)
    vd.ellipse([-w * 0.2, -h * 0.3, w * 1.2, h * 1.3], fill=255)
    vignette = vignette.filter(ImageFilter.GaussianBlur(radius=min(w, h) * 0.25))
    dark = Image.new("RGB", (w, h), (0, 0, 0))
    img = Image.composite(img, dark, vignette)
    return img


def _generate_quote_bg(w: int, h: int) -> Image.Image:
    """Фон карточки-цитаты: настоящее фото (своё из images/ или скачанное по
    ссылке, кадрированное под размер карточки) с лёгким затемнением; если фото
    достать не удалось — аварийный процедурный «туманный» фон вместо него."""
    photo_bytes = _pick_quote_bg_photo()
    if photo_bytes:
        try:
            photo = Image.open(BytesIO(photo_bytes)).convert("RGB")
            img = ImageOps.fit(photo, (w, h), Image.LANCZOS)
            # лёгкое общее затемнение, чтобы разные фото давали похожий по
            # контрасту результат и текст поверх всегда читался
            overlay = Image.new("RGB", (w, h), (0, 0, 0))
            img = Image.blend(img, overlay, 0.28)
            return img
        except Exception:
            logger.warning("Не удалось открыть фото-фон карточки-цитаты, использую запасной фон")
    return _generate_quote_bg_fallback(w, h)


def _render_quote_card_image(name: str, text: str, avatar_bytes: Optional[bytes]) -> Image.Image:
    W, H = 700, 400
    pad_left = 40
    avatar_size = 96
    name_font = _load_font(22, bold=True)
    text_font = _load_font(25, italic=True)
    quote_font = _load_font(90, bold=True)
    watermark_font = _load_font(19)
    meta_font = _load_font(16)

    dummy = Image.new("RGB", (10, 10))
    dd = ImageDraw.Draw(dummy)
    max_text_width = int(W * 0.58) - pad_left

    words = text.split()
    lines: list[str] = []
    cur = ""
    for w in words:
        trial = f"{cur} {w}".strip()
        if dd.textlength(trial, font=text_font) <= max_text_width or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    truncated = len(lines) > 6
    lines = lines[:6]
    if truncated and lines:
        lines[-1] = lines[-1].rstrip() + "…"

    img = _generate_quote_bg(W, H).convert("RGB")

    # тёмная дымка слева направо — чтобы текст поверх фона оставался читаемым
    scrim = Image.new("L", (W, H), 0)
    sd = ImageDraw.Draw(scrim)
    scrim_w = int(W * 0.66)
    for x in range(scrim_w):
        alpha = int(215 * (1 - x / scrim_w) ** 1.3)
        sd.line([(x, 0), (x, H)], fill=alpha)
    dark_layer = Image.new("RGB", (W, H), (8, 8, 10))
    img = Image.composite(dark_layer, img, scrim)

    draw = ImageDraw.Draw(img, "RGBA")

    # декоративные крупные кавычки в углах
    draw.text((26, -34), "\u201c", font=quote_font, fill=(255, 255, 255, 55))
    draw.text((W - 96, H - 150), "\u201d", font=quote_font, fill=(255, 255, 255, 40))

    # водяной знак команды
    wm = ".цитата"
    wm_w = dd.textlength(wm, font=watermark_font)
    draw.text((W - wm_w - 36, H // 2 - 8), wm, font=watermark_font, fill=(255, 255, 255, 70))

    # аватар с тонкой обводкой
    avatar = _circular_avatar(avatar_bytes, avatar_size)
    ax, ay = pad_left, 34
    ring = Image.new("RGBA", (avatar_size + 8, avatar_size + 8), (0, 0, 0, 0))
    ImageDraw.Draw(ring).ellipse([0, 0, avatar_size + 7, avatar_size + 7], outline=(255, 255, 255, 170), width=3)
    img.paste(ring, (ax - 4, ay - 4), ring)
    img.paste(avatar, (ax, ay), avatar)

    ty = ay + avatar_size + 26
    for i, line in enumerate(lines):
        draw.text((pad_left, ty + i * 34), line, font=text_font, fill=(238, 238, 238))
    name_y = ty + len(lines) * 34 + 10
    draw.text((pad_left, name_y), f"— {name}", font=name_font, fill=(185, 195, 255))

    # подпись снизу слева: ник автора цитаты + дата
    today = local_now().strftime("%d.%m.%Y")
    draw.text((pad_left, H - 46), f"© {name}", font=meta_font, fill=(215, 215, 215))
    draw.text((pad_left, H - 26), f"@ {today}", font=meta_font, fill=(215, 215, 215))

    return img


def _render_quote_card(name: str, text: str, avatar_bytes: Optional[bytes]) -> BytesIO:
    """Тонкая обёртка над _render_quote_card_image — кодирует готовую
    карточку в PNG (для .цитата). Для стикера (.цитата стикер) используется
    напрямую _render_quote_card_image + _to_sticker_webp, без лишнего
    PNG-круга кодирования/декодирования."""
    img = _render_quote_card_image(name, text, avatar_bytes)
    buf = BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return buf


# ---- экспорт карточки-цитаты / произвольного текста в Telegram-стикер -----

_QUOTE_STICKER_EMOJI = "💬"
_QUOTE_STICKER_SET_MAX = 120  # лимит Telegram на статичный набор стикеров
_QUOTE_STICKER_SET_MAX_PARTS = 20  # защита от бесконечного цикла в форс-мажоре


def _to_sticker_webp(img: Image.Image) -> BytesIO:
    """Готовит изображение под требования Telegram-стикеров: ужимает так,
    чтобы большая сторона была ровно 512px, сохраняет в WEBP и при
    необходимости снижает качество, чтобы уложиться в лимит файла (512 КБ).

    Холст намеренно НЕ квадратный: Telegram требует 512 только по одной
    стороне, а дополнение до квадрата прозрачными полями визуально уменьшало
    бы сам стикер — широкий пузырь показывался бы вдвое мельче, чем может.
    """
    img = img.convert("RGBA")
    # обрезаем пустые поля, иначе они съедают часть от лимита в 512px
    bbox = img.getbbox()
    if bbox:
        img = img.crop(bbox)

    w, h = img.size
    scale = 512 / max(w, h)
    canvas = img.resize(
        (max(1, round(w * scale)), max(1, round(h * scale))), Image.LANCZOS
    )

    quality = 90
    buf = BytesIO()
    while True:
        buf.seek(0)
        buf.truncate(0)
        canvas.save(buf, format="WEBP", quality=quality, method=6)
        size = buf.tell()
        if size <= 512 * 1024 or quality <= 30:
            break
        quality -= 15
    buf.seek(0)
    return buf


async def _add_to_quote_sticker_set(user_id: int, chat_id: int, webp_bytes: bytes) -> str:
    """Добавляет стикер в набор чата «quotes_<chat_id>[_N]_by_<bot>»: если
    текущая часть набора заполнена (лимит Telegram — 120 стикеров в статичном
    наборе) или создание/добавление не удалось — пробует следующую часть
    («_2», «_3», ...). Возвращает имя набора, в который добавили стикер.
    Бросает исключение, если ни одна часть не подошла (например Telegram
    требует, чтобы user_id хотя бы раз написал боту в личку, прежде чем от
    его имени можно будет создавать наборы стикеров)."""
    me = await bot.get_me()
    bot_username = me.username
    safe_chat_id = str(chat_id).replace("-", "n")

    last_error: Optional[Exception] = None
    for part in range(1, _QUOTE_STICKER_SET_MAX_PARTS + 1):
        suffix = "" if part == 1 else f"_{part}"
        set_name = f"quotes_{safe_chat_id}{suffix}_by_{bot_username}"

        try:
            existing = await bot.get_sticker_set(set_name)
        except TelegramBadRequest:
            existing = None

        sticker_input = InputSticker(
            sticker=BufferedInputFile(webp_bytes, filename="quote.webp"),
            format="static",
            emoji_list=[_QUOTE_STICKER_EMOJI],
        )

        if existing is None:
            try:
                await bot.create_new_sticker_set(
                    user_id=user_id,
                    name=set_name,
                    title=f"Цитаты чата {chat_id}",
                    stickers=[sticker_input],
                    sticker_type="regular",
                )
                return set_name
            except TelegramBadRequest as e:
                last_error = e
                logger.warning("Не удалось создать набор стикеров %s: %s", set_name, e)
                continue

        if len(existing.stickers) >= _QUOTE_STICKER_SET_MAX:
            continue

        try:
            await bot.add_sticker_to_set(user_id=user_id, name=set_name, sticker=sticker_input)
            return set_name
        except TelegramBadRequest as e:
            last_error = e
            logger.warning("Не удалось добавить стикер в набор %s: %s", set_name, e)
            continue

    raise last_error or RuntimeError("Не удалось найти или создать подходящий набор стикеров")


# ----------------------------------------------------------------------------
# «+рстик / -рстик»: когда включено, бот изредка сам кидает в чат случайный
# стикер из набора цитат этого чата (созданного через «.цитата стикер»).
# Тумблер хранится в bot_data под ключом rstick:{chat_id}. Кубик бросается в
# middleware синхронно (без БД), а сюда попадаем уже редко — можно ходить в БД
# и в Telegram. Плюс мягкий откат на чат, чтобы не спамить в активной беседе.
# ----------------------------------------------------------------------------
RSTICK_CHANCE = 0.02/200             # шанс на каждое человеческое сообщение (когда включено)
RSTICK_COOLDOWN_SECONDS = 180*20*2    # не чаще раза в 3 минуты на чат
_rstick_last_sent: dict[int, datetime] = {}
_bot_username_cache: Optional[str] = None


def _rstick_key(chat_id: int) -> str:
    return f"rstick:{chat_id}"


async def _random_chat_sticker(chat_id: int) -> Optional[str]:
    """Случайный file_id из наборов «цитат» чата (quotes_<chat>[_N]_by_<bot>).
    None, если у чата ещё нет ни одного созданного стикера."""
    global _bot_username_cache
    if _bot_username_cache is None:
        _bot_username_cache = (await bot.get_me()).username
    safe_chat_id = str(chat_id).replace("-", "n")
    file_ids: list[str] = []
    for part in range(1, _QUOTE_STICKER_SET_MAX_PARTS + 1):
        suffix = "" if part == 1 else f"_{part}"
        set_name = f"quotes_{safe_chat_id}{suffix}_by_{_bot_username_cache}"
        try:
            existing = await bot.get_sticker_set(set_name)
        except TelegramBadRequest:
            break  # нет этой части — дальше частей тоже нет
        file_ids.extend(st.file_id for st in existing.stickers)
    return random.choice(file_ids) if file_ids else None


async def _send_random_sticker_if_on(chat_id: int) -> None:
    """Вызывается из middleware только когда кубик уже выпал. Проверяет тумблер
    и откат, затем шлёт случайный стикер набора чата."""
    now = datetime.utcnow()
    last = _rstick_last_sent.get(chat_id)
    if last and (now - last).total_seconds() < RSTICK_COOLDOWN_SECONDS:
        return
    if not await db.get_data(_rstick_key(chat_id)):
        return  # тумблер выключен
    _rstick_last_sent[chat_id] = now  # троттлим попытки, даже если стикеров ещё нет
    try:
        file_id = await _random_chat_sticker(chat_id)
        if file_id:
            await bot.send_sticker(chat_id, file_id)
    except Exception:
        logger.warning("Не удалось отправить случайный стикер в чат %s", chat_id, exc_info=True)


async def _reply_sticker_and_add_to_set(message: Message, img: Image.Image, filename: str) -> None:
    """Общий хвост для .цитата стикер / .стикер: кодирует картинку в WEBP,
    отправляет стикером в чат и пробует добавить в набор стикеров чата."""
    try:
        webp_buf = await asyncio.to_thread(_to_sticker_webp, img)
    except Exception:
        logger.exception("Не удалось подготовить WEBP для стикера")
        await message.reply("Не получилось сгенерировать стикер, попробуйте позже.")
        return

    webp_bytes = webp_buf.getvalue()
    try:
        await message.reply_sticker(BufferedInputFile(webp_bytes, filename=filename))
    except Exception:
        logger.exception("Не удалось отправить стикер")
        await message.reply("Не получилось отправить стикер, попробуйте позже.")
        return

    try:
        set_name = await _add_to_quote_sticker_set(message.from_user.id, message.chat.id, webp_bytes)
        await message.reply(f"Добавил в набор стикеров чата: t.me/addstickers/{set_name}")
    except TelegramBadRequest:
        await message.reply(
            "Стикер отправлен, но не смог добавить его в набор — Telegram требует, чтобы вы "
            "хотя бы раз написали мне в личные сообщения, прежде чем я смогу создавать наборы "
            "стикеров от вашего имени."
        )
    except Exception:
        logger.exception("Не удалось добавить стикер в набор чата")
        await message.reply("Стикер отправлен, но добавить его в набор чата не получилось.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == ".цитата стикер"),
)
async def cmd_quote_sticker(message: Message):
    if not _check_misc_access(message.from_user.id, "photo_quote_sticker"):
        return
    src = message.reply_to_message
    if src is None:
        await message.reply("Ответьте этой командой («.цитата стикер») на сообщение, которое нужно процитировать.")
        return
    text = src.text or src.caption
    if not text:
        await message.reply("В цитируемом сообщении нет текста для цитаты.")
        return
    author = src.from_user
    if author is None:
        await message.reply("Не удалось определить автора цитируемого сообщения.")
        return

    nickname = await db.get_nickname(message.chat.id, author.id)
    name = nickname or author.full_name or (f"@{author.username}" if author.username else str(author.id))
    avatar_bytes = await _fetch_avatar_bytes(author.id)
    try:
        img = await asyncio.to_thread(_render_quote_card_image, name, text, avatar_bytes)
    except Exception:
        logger.exception("Не удалось сгенерировать карточку цитаты для стикера")
        await message.reply("Не получилось сгенерировать цитату, попробуйте позже.")
        return

    await _reply_sticker_and_add_to_set(message, img, "quote.webp")
    quote_count = await _increment_quote_count(message.chat.id, message.from_user.id)
    if quote_count >= 10:
        await grant_achievement(message.chat.id, message.from_user.id, "quotes_10")


STICKER_CMD_RE = re.compile(r"^\.стикер(?:\s+(\d{1,2}))?$", re.IGNORECASE)


def _fallback_text_for(msg: Message) -> Optional[str]:
    """Текст сообщения для карточки-стикера: сам текст/подпись, либо
    человекочитаемое описание вложения (голосовое, фото и т.п.), либо None,
    если сообщение вообще нечего показать (например, служебное)."""
    text = msg.text or msg.caption
    if text:
        return text
    if msg.voice is not None:
        return "🎤 Голосовое сообщение"
    if msg.video_note is not None:
        return "🎥 Видеосообщение"
    if msg.photo:
        return "🖼 Фото"
    if msg.video is not None:
        return "📹 Видео"
    if msg.sticker is not None:
        return "Стикер"
    return None


async def _fetch_message_media(msg: Message) -> Optional[bytes]:
    """Картинка из сообщения, чтобы вставить её прямо в бабл цитаты.

    None для всего, что Pillow не откроет — видео, гифок, анимированных и
    видео-стикеров; для них останется текстовая пометка из _fallback_text_for.
    """
    file_id = None
    if msg.photo:
        file_id = msg.photo[-1].file_id
    elif msg.sticker is not None and not msg.sticker.is_animated and not msg.sticker.is_video:
        file_id = msg.sticker.file_id
    if file_id is None:
        return None
    try:
        buf = BytesIO()
        await bot.download(file_id, destination=buf)
        buf.seek(0)
        return buf.read()
    except Exception:
        logger.warning("Не удалось скачать медиа для цитаты", exc_info=True)
        return None


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(STICKER_CMD_RE.match(t.strip()))),
)
async def cmd_text_sticker(message: Message):
    if not _check_misc_access(message.from_user.id, "photo_text_sticker"):
        return
    src = message.reply_to_message
    if src is None:
        await message.reply(
            "Ответьте этой командой на сообщение с текстом:\n"
            "«.стикер» — стикер из одного сообщения\n"
            "«.стикер 3» — склеит это сообщение и 2 предыдущих в один стикер (макс. "
            f"{STICKER_CMD_MAX_MESSAGES})"
        )
        return

    match = STICKER_CMD_RE.match(message.text.strip())
    count = int(match.group(1)) if match and match.group(1) else 1
    count = max(1, min(count, STICKER_CMD_MAX_MESSAGES))

    avatar_cache: dict = {}

    async def _avatar_for(uid: int) -> Optional[bytes]:
        if uid not in avatar_cache:
            avatar_cache[uid] = await _fetch_avatar_bytes(uid)
        return avatar_cache[uid]

    entries: list = []

    if count == 1:
        author = src.from_user
        if author is None:
            await message.reply("Не удалось определить автора сообщения.")
            return

        media_bytes = await _fetch_message_media(src)
        # с картинкой в бабле подписью служит caption, а без неё — пометка
        # вида «🎤 Голосовое сообщение» из _fallback_text_for
        text = (src.text or src.caption or "") if media_bytes else (_fallback_text_for(src) or "")
        if not text and media_bytes is None:
            await message.reply("В этом сообщении нет текста, чтобы сделать стикер.")
            return

        nickname = await db.get_nickname(message.chat.id, author.id)
        name = nickname or author.full_name or (f"@{author.username}" if author.username else str(author.id))
        quote = QuoteMessage(
            user_id=author.id,
            name=name,
            text=text,
            entities=list(src.entities or src.caption_entities or []),
            avatar_bytes=await _avatar_for(author.id),
            media_bytes=media_bytes,
        )

        # если процитированное сообщение само было ответом на другое —
        # рисуем сверху маленькую плашку-реплай, как настоящий Telegram. Но
        # ТОЛЬКО когда у нас есть реальное сообщение, на которое отвечали, и в
        # нём есть что показать: если Telegram не приложил его содержимого (или
        # там нечего показать) — реплай не выдумываем и плашку не рисуем.
        quoted = src.reply_to_message
        if quoted is not None and quoted.from_user is not None:
            quoted_text = _fallback_text_for(quoted)
            if quoted_text:
                q_nick = await db.get_nickname(message.chat.id, quoted.from_user.id)
                quote.reply_name = q_nick or quoted.from_user.full_name or (
                    f"@{quoted.from_user.username}" if quoted.from_user.username else str(quoted.from_user.id)
                )
                quote.reply_chat_id = quoted.from_user.id
                quote.reply_text = quoted_text

        entries.append(quote)
    else:
        # склеиваем это сообщение с несколькими предыдущими из кольцевого
        # буфера чата (см. recent_chat_messages / _remember_recent_message)
        buf = recent_chat_messages.get(message.chat.id) or deque()
        buf_list = list(buf)
        ids = [m["message_id"] for m in buf_list]
        if src.message_id in ids:
            idx = ids.index(src.message_id)
            window = buf_list[max(0, idx - (count - 1)): idx + 1]
        else:
            # Сообщение, на которое ответили, не в буфере — это НЕ обязательно
            # значит, что буфер пуст. Частый случай: src — сообщение ДРУГОГО
            # бота, а Telegram принципиально не присылает нашему боту чужие
            # бот-сообщения отдельными апдейтами (см. Bots FAQ на core.telegram.org:
            # «bots will not be able to see messages from other bots regardless
            # of mode» — единственное исключение — реплай именно на этого бота).
            # Поэтому не выбрасываем буфер целиком, а достраиваем его вокруг
            # src: берём count-1 предыдущих (по message_id, то есть точно
            # отправленных раньше src) сообщений из буфера + сам src,
            # реконструированный из reply_to_message (Telegram прикладывает
            # его содержимое к самому реплаю независимо от истории апдейтов).
            src_item = {
                "message_id": src.message_id,
                "user_id": src.from_user.id if src.from_user else None,
                "full_name": src.from_user.full_name if src.from_user else None,
                "username": src.from_user.username if src.from_user else None,
                "text": _fallback_text_for(src),
                "kind": None,
            }
            prior = [m for m in buf_list if m["message_id"] < src.message_id]
            window = prior[-(count - 1):] + [src_item] if count > 1 else [src_item]

        for item in window:
            uid = item.get("user_id")
            text = item.get("text") or item.get("kind")
            if uid is None or not text:
                continue
            nickname = await db.get_nickname(message.chat.id, uid)
            name = nickname or item.get("full_name") or (
                f"@{item['username']}" if item.get("username") else str(uid)
            )
            entries.append(QuoteMessage(
                user_id=uid,
                name=name,
                text=text,
                avatar_bytes=await _avatar_for(uid),
            ))

    if not entries:
        await message.reply("В этих сообщениях нет текста, чтобы сделать стикер.")
        return

    try:
        img = await asyncio.to_thread(render_quote, entries)
    except Exception:
        logger.exception("Не удалось сгенерировать стикер-цитату")
        await message.reply("Не получилось сгенерировать стикер, попробуйте позже.")
        return

    await _reply_sticker_and_add_to_set(message, img, "text.webp")


