# ============================================================================
# Модуль «Экономика» — ферма боти-коинов (по образцу Iris). Сумма зависит от
# чат-настройки «урожайность» (ферма урожайность {%}, по умолчанию 100%) и
# личной «звёздности», которая растёт сама по мере фарма (см. db.record_farm) —
# коины и звёздность хранятся per-chat, не общие между чатами бота.
# ============================================================================
FARM_COOLDOWN = timedelta(hours=4)
STOCK_MAX_INVEST = 100_000       # максимум вложений на человека
STOCK_DIVIDEND_RATE = 0.1      # 10% от invested в сутки
STOCK_MIN_CHANGE = -0.10        # -10%
STOCK_MAX_CHANGE = 0.50         # +50%
FARM_TRIGGERS = {"ферма", "!бизнес", "фарма", "фармить"}
FARM_BASE_MIN = 40
FARM_BASE_MAX = 120
FARM_STAR_CAP = 10
FARM_FARMS_PER_STAR = 20
FARM_STAR_BONUS_PER_LEVEL = 0.05  # +5% к множителю за каждую звезду
# «Везение» — случайная добавка к множителю на конкретный фарм (не хранится,
# каждый раз заново), отображается отдельно в скобках рядом с расчётом.
FARM_LUCK_MIN = 0.85
FARM_LUCK_MAX = 1.15


def _ru_decimal(value: float, digits: int = 2) -> str:
    """Число с запятой вместо точки, как принято в русской локали (1,17)."""
    return f"{value:.{digits}f}".replace(".", ",")


async def _farm_execute(chat_id: int, user_id: int) -> str:
    """Основная логика фарма — вынесена из обработчика команды «ферма», чтобы
    её же мог дёрнуть таймер (см. TIMER_RUNNABLE_COMMANDS ниже), если на нём
    поставили текст «ферма» вместо обычного напоминания."""
    if await is_account_frozen(chat_id, user_id):
        return "🧊 Ваш счёт заморожен администрацией — фарм недоступен."
    wallet = await db.get_wallet(chat_id, user_id)
    now = datetime.utcnow()
    if wallet.get("last_farm_at"):
        elapsed = now - wallet["last_farm_at"]
        if elapsed < FARM_COOLDOWN:
            remaining = FARM_COOLDOWN - elapsed
            return (
                f"❌ НЕЗАЧЁТ! Фармить можно раз в {format_duration_ru(FARM_COOLDOWN)}. "
                f"Следующая добыча через {format_duration_ru(remaining)}"
            )

    yield_percent = await db.get_farm_yield(chat_id)
    star_level = int(wallet.get("star_level") or 0)
    star_bonus = 1 + star_level * FARM_STAR_BONUS_PER_LEVEL
    luck = random.uniform(FARM_LUCK_MIN, FARM_LUCK_MAX)
    multiplier = (yield_percent / 100) * star_bonus * luck
    base = random.randint(FARM_BASE_MIN, FARM_BASE_MAX)
    amount = max(1, round(base * multiplier))

    updated = await db.record_farm(chat_id, user_id, amount, now, star_cap=FARM_STAR_CAP, farms_per_star=FARM_FARMS_PER_STAR)
    luck_percent = round(luck * 100)
    multiplier_str = _ru_decimal(multiplier)
    await _check_coin_achievements(chat_id, user_id)
    return (
        f"✅ ЗАЧЁТ! ☢️ +{amount} i¢ = {base}×{multiplier_str} ({luck_percent}%)\n"
        f"✨ Сила звёздности: {int(updated.get('star_level') or 0)}\n"
        f"⏳ Урожайность: {multiplier_str}"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in FARM_TRIGGERS),
)
async def cmd_farm_run(message: Message):
    if not _check_misc_access(message.from_user.id, "farm_run"):
        return
    await message.answer(await _farm_execute(message.chat.id, message.from_user.id))


