BCOIN_RE = re.compile(r"(?i)^бкоин\s+(\S+)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BCOIN_RE.match(t.strip()))),
)
async def cmd_bcoin(message: Message):
    """«Бкоин {число}» — переводит указанное число бтои-коинов из личного
    кошелька в общий баланс ЧАТА (безвозвратно — обратной команды «-Бкоин»
    нет, как и у Iris). История вложений — «Бтоп стата»."""
    if not _check_misc_access(message.from_user.id, "chat_coin_invest"):
        return
    amount = parse_amount(BCOIN_RE.match(message.text.strip()).group(1))
    if amount is None:
        await message.reply("Не понял сумму. Можно так: 500, 10к, 1.5м.")
        return


    if amount <= 0:
        await message.reply("Число монет должно быть больше нуля.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    wallet = await db.get_wallet(chat_id, user_id)
    if int(wallet.get("coins", 0)) < amount:
        await message.reply(
            f"Недостаточно монет в мешке: у вас {wallet.get('coins', 0)} i¢, нужно {amount}."
        )
        return

    new_chat_balance = await db.record_chat_investment(chat_id, user_id, amount)
    await db.add_log("chat_coin_invest", chat_id=chat_id, actor_id=user_id, details=str(amount))
    await message.reply(
        f"☢️ Вы вложили <b>{amount}</b> i¢ в баланс чата!\n"
        f"Баланс чата теперь: <b>{new_chat_balance}</b> i¢"
    )


