TRANSFER_CMD_RE = re.compile(r"(?i)^(?:перевод|перевести)\b")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(TRANSFER_CMD_RE.match(t.strip()))),
)
async def cmd_transfer(message: Message):
    """«Перевод @username сумма» (или ответом на сообщение) — переводит i¢
    из личного кошелька отправителя получателю в пределах этого чата.
    Необязательное сообщение к переводу — второй строкой."""
    if not _check_misc_access(message.from_user.id, "coin_transfer"):
        return

    text = message.text.strip()
    first_line, _, rest = text.partition("\n")
    note = rest.strip()[:200] or None

    # allow_bare_id=False: число после «перевод» — это сумма, а не ID цели.
    # Цель указывается только @username/text_mention или ответом на сообщение.
    target, remaining = await resolve_command_target(
        message, trigger_words=1, allow_bare_id=False, text=first_line
    )
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Использование: <code>Перевод @username сумма</code> (или ответом на сообщение)\n"
            "Можно добавить сообщение к переводу второй строкой:\n"
            "<code>Перевод @username 100\nНа мороженое</code>"
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.id == message.from_user.id:
        await message.reply("Самому себе переводить не имеет смысла 🙂")
        return
    if getattr(target, "is_bot", False):
        await message.reply("Боты монеты не тратят 🤖")
        return

    amount = find_amount(remaining)
    if amount is None:
        await message.reply(
            "Укажите сумму перевода, например:\n<code>Перевод @username 100</code> или <code>Перевод @username 10к</code>"
        )
        return
    if amount <= 0:
        await message.reply("Сумма перевода должна быть больше нуля.")
        return

    if await is_account_frozen(message.chat.id, message.from_user.id):
        await message.reply("🧊 Ваш счёт заморожен — переводы недоступны.")
        return

    if has_infinite_money(message.from_user.id):
        await db.add_coins(message.chat.id, target.id, amount)
    else:
        wallet = await db.get_wallet(message.chat.id, message.from_user.id)
        if int(wallet.get("coins", 0)) < amount:
            await message.reply(f"Недостаточно монет: у вас {wallet.get('coins', 0)} i¢, нужно {amount}.")
            return
        ok = await db.transfer_coins(message.chat.id, message.from_user.id, target.id, amount)
        if not ok:
            await message.reply("Не удалось выполнить перевод — попробуйте ещё раз.")
            return

    await db.add_log(
        "coin_transfer", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=str(amount),
    )
    sender_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    note_line = f"\n📝 с комментарием: {html.escape(note)}" if note else ""
    await message.reply(
        f"💸 {sender_name} перевёл(а) {target_name} <b>{amount}</b> i¢{note_line}"
    )


ITEM_USE_RE = re.compile(r"(?i)^использовать\s+(\S+)")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(ITEM_USE_RE.match(t.strip()))),
)
async def cmd_item_use(message: Message):
    """«использовать {ключ} @username» (или ответом на сообщение) — применяет
    предмет из инвентаря на цель. У каждого предмета лимит 10 применений
    всего — после 10-го использования предмет полностью пропадает из
    инвентаря (независимо от quantity)."""
    if not _check_misc_access(message.from_user.id, "item_use"):
        return

    match = ITEM_USE_RE.match(message.text.strip())
    item_key = match.group(1).casefold()

    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Использование: <code>использовать {ключ} @username</code> (или ответом на сообщение).\n"
            "Посмотреть ключи предметов — «инвентарь»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if getattr(target, "is_bot", False):
        await message.reply("На ботов предметы не действуют 🤖")
        return

    chat_id, user_id = message.chat.id, message.from_user.id

    items = await db.list_inventory(chat_id, user_id)
    item = next((i for i in items if i["item_key"] == item_key), None)
    if item is None:
        await message.reply(f"У вас нет предмета «{html.escape(item_key)}». Проверьте «инвентарь».")
        return

    item_name = item.get("name") or item_key
    emoji = item.get("emoji") or "🎁"

    new_count = await db.increment_item_usage(chat_id, user_id, item_key)

    actor_name = await display_name(chat_id, message.from_user)
    target_name = await display_name(chat_id, target)
    await message.answer(
        f"{emoji} {actor_name} использовал(а) «{html.escape(item_name)}» на {target_name}"
    )
    await db.add_log(
        "item_use", chat_id=chat_id, actor_id=user_id, target_id=target.id, details=item_key
    )

    if new_count >= db.ITEM_USE_LIMIT:
        await db.remove_inventory_item_completely(chat_id, user_id, item_key)
        await db.reset_item_usage(chat_id, user_id, item_key)

        # Предмет исчез из инвентаря целиком — если он был закреплён, снимаем закреп
        card = await db.get_profile_card(chat_id, user_id)
        if card and card.get("pinned_item") == item_key:
            await db.set_pinned_item(chat_id, user_id, None)

        await message.answer(
            f"⚠️ «{html.escape(item_name)}» исчерпал лимит применений ({db.ITEM_USE_LIMIT}) и пропал из инвентаря."
        )


SELL_ITEM_RE = re.compile(r"(?i)^!продать\s+(\S+)(?:\s+(\d+))?$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(SELL_ITEM_RE.match(t.strip()))),
)
async def cmd_sell_item(message: Message):
    """«!продать {ключ} [количество]» — продаёт предмет(ы) из инвентаря за 80%
    их цены в магазине. Продать можно только предмет, который ни разу не
    использовался (см. item_usage / ITEM_USE_LIMIT)."""
    match = SELL_ITEM_RE.match(message.text.strip())
    item_key = match.group(1).casefold()
    amount = int(match.group(2)) if match.group(2) else 1
    if amount <= 0:
        await message.reply("Количество должно быть больше нуля.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id

    items = await db.list_inventory(chat_id, user_id)
    item = next((i for i in items if i["item_key"] == item_key), None)
    if item is None:
        await message.reply(f"У вас нет предмета «{html.escape(item_key)}».")
        return
    if item["quantity"] < amount:
        await message.reply(f"У вас только {item['quantity']} шт. — не хватает, чтобы продать {amount}.")
        return

    used = await db.get_item_usage_count(chat_id, user_id, item_key)
    if used > 0:
        await message.reply("⚠️ Этот предмет уже был в использовании — продать его нельзя.")
        return

    shop_item = await db.get_shop_item(chat_id, item_key)
    if shop_item is None or shop_item.get("price") is None:
        await message.reply("Этот предмет нельзя продать — он не продаётся в магазине.")
        return

    price = int(shop_item["price"])
    total_sell = max(int(price * amount * 0.8), 0)

    ok = await db.remove_inventory_item(chat_id, user_id, item_key, amount)
    if not ok:
        await message.reply("Не удалось продать — попробуйте ещё раз.")
        return

    await db.add_coins(chat_id, user_id, total_sell)

    card = await db.get_profile_card(chat_id, user_id)
    if card and card.get("pinned_item") == item_key:
        remaining = await db.list_inventory(chat_id, user_id)
        if not any(i["item_key"] == item_key for i in remaining):
            await db.set_pinned_item(chat_id, user_id, None)

    item_name = shop_item["name"]
    emoji = shop_item.get("emoji") or "🎁"
    await message.reply(
        f"✅ Продано: {emoji} <b>{html.escape(item_name)}</b> × {amount} за <b>{total_sell}</b> i¢ "
        f"(80% от {price * amount} i¢)."
    )
    await db.add_log("item_sell", chat_id=chat_id, actor_id=user_id, details=f"{item_key}x{amount}")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[:2] == ["ферма", "урожайность"]),
)
async def cmd_farm_set_yield(message: Message):
    if not has_level(message.from_user.id, required_level("farm_yield_set")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Настраивать урожайность фермы может «{level_name(required_level('farm_yield_set'))}» и выше.")
        return
    parts = message.text.strip().split()
    if len(parts) < 3 or not parts[2].replace(".", "", 1).isdigit():
        await message.reply(
            "Использование: <code>ферма урожайность {число}</code> — множитель выдачи в % "
            "(100 — обычная сумма).\nНапример: <code>ферма урожайность 150</code>"
        )
        return
    percent = float(parts[2])
    percent = max(10.0, min(1000.0, percent))
    await db.set_farm_yield(message.chat.id, percent)
    await db.add_log("farm_yield_set", actor_id=message.from_user.id, details=f"{message.chat.id} -> {percent}")
    await message.reply(f"✅ Урожайность фермы этого чата: <b>{percent:g}%</b>.")



def _is_robbery_command(text: Optional[str]) -> bool:
    if not text or not text.strip():
        return False
    first = (text.strip().casefold().split() or [""])[0]
    return first in ("!ограбить", "ограбить")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_robbery_command),
)
async def cmd_robbery(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_run"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    stats = await db.get_robbery_stats(chat_id, user_id)
    if await db.is_under_surveillance(chat_id, user_id):
        await message.reply(
            "🚨 Вы под надзором — грабежи для вас недоступны.\n"
            f"Снять надзор: <code>купить откуп</code> ({robbery.SURVEILLANCE_PARDON_PRICE} i¢)."
        )
        return
    now = datetime.utcnow()
    last = stats.get("last_robbery_at")
    if last and (now - last) < robbery.ROBBERY_COOLDOWN:
        remaining = robbery.ROBBERY_COOLDOWN - (now - last)
        await message.reply(f"⏳ Слишком рано — следующая попытка через {format_duration_ru(remaining)}.")
        return

    text = message.text.strip()
    tokens = text.split(maxsplit=1)
    rest = tokens[1].strip() if len(tokens) > 1 else ""
    using_binokl = rest.casefold().startswith("бинокль")

    inventory = await db.list_inventory(chat_id, user_id)
    inv_qty = {i["item_key"]: i["quantity"] for i in inventory}

    victim_id: Optional[int] = None
    if using_binokl:
        if inv_qty.get("binokl", 0) <= 0:
            await message.reply("У вас нет 🔭 бинокля — купите его в «магазин».")
            return
        target_obj, _ = await resolve_command_target(message, trigger_words=2)
        if target_obj is None and message.reply_to_message:
            target_obj = message.reply_to_message.from_user
        if target_obj is None or target_obj.id is None:
            await message.reply("Укажите цель: «!ограбить бинокль @username» или ответом на его сообщение.")
            return
        if target_obj.id == user_id:
            await message.reply("Себя грабить бессмысленно 🙂")
            return
        if getattr(target_obj, "is_bot", False):
            await message.reply("Ботов грабить нет смысла 🤖")
            return
        victim_id = target_obj.id

    if victim_id is None:
        victim_row = await db.pick_random_robbery_victim(chat_id, user_id, robbery.ROBBERY_MIN_VICTIM_BALANCE)
        if victim_row is None:
            await message.reply("😔 Грабить некого — ни у кого поблизости нет достаточно денег.")
            return
        victim_id = victim_row["user_id"]

    victim_wallet = await db.get_wallet(chat_id, victim_id)
    victim_balance = int(victim_wallet.get("coins") or 0)
    if victim_balance < robbery.ROBBERY_MIN_VICTIM_BALANCE:
        await message.reply("😔 У этой цели слишком пусто в кошельке — грабить нечего.")
        return

    if using_binokl:
        await db.remove_inventory_item(chat_id, user_id, "binokl", 1)

    victim_inventory = await db.list_inventory(chat_id, victim_id)
    victim_bronik = next((i["quantity"] for i in victim_inventory if i["item_key"] == "bronik"), 0)
    actor_name = await display_name(chat_id, message.from_user)
    if victim_bronik > 0:
        await db.remove_inventory_item(chat_id, victim_id, "bronik", 1)
        await db.apply_robbery_blocked(chat_id, user_id, victim_id)
        await message.answer(
            f"🦺 {actor_name} попытался(-лась) кого-то ограбить, но жертву спас бронежилет — "
            "попытка провалилась без последствий."
        )
        return

    has_rabbit_paw = inv_qty.get("rabbit_paw", 0) > 0
    has_gold_pig = inv_qty.get("gold_pig", 0) > 0
    has_lucky_coin = inv_qty.get("lucky_coin", 0) > 0
    has_dymovushka = inv_qty.get("dymovushka", 0) > 0
    has_getaway_car = inv_qty.get("getaway_car", 0) > 0

    if has_rabbit_paw:
        await db.remove_inventory_item(chat_id, user_id, "rabbit_paw", 1)
    success = robbery.roll_success(has_rabbit_paw)

    victim_name = await display_name_by_id(chat_id, victim_id)
    robber_wallet = await db.get_wallet(chat_id, user_id)

    if success:
        amount = robbery.compute_steal_amount(victim_balance, has_gold_pig)
        if has_gold_pig:
            await db.remove_inventory_item(chat_id, user_id, "gold_pig", 1)
        await db.apply_robbery_success(chat_id, user_id, victim_id, amount)
        await message.answer(f"🥷 {actor_name} успешно ограбил(а) {victim_name} на <b>{amount}</b> i¢!")
        stats = await db.get_robbery_stats(chat_id, user_id)
        if stats.get("successes", 0) >= 20:
            await grant_achievement(chat_id, user_id, "robber_20")
    else:
        loss = robbery.compute_fail_loss(int(robber_wallet.get("coins") or 0), has_lucky_coin, has_gold_pig)
        if has_lucky_coin:
            await db.remove_inventory_item(chat_id, user_id, "lucky_coin", 1)
        elif has_gold_pig:
            await db.remove_inventory_item(chat_id, user_id, "gold_pig", 1)
        await db.apply_robbery_fail(chat_id, user_id, loss)
        loss_text = f"потерял(а) {loss} i¢" if loss else "ничего не потерял(а)"

        has_pass = inv_qty.get(robbery.SURVEILLANCE_PASS_ITEM_KEY, 0) > 0
        surveillance_line = ""
        if has_pass:
            await db.remove_inventory_item(chat_id, user_id, robbery.SURVEILLANCE_PASS_ITEM_KEY, 1)
            surveillance_line = "\n🕶️ Отмазка сработала — этот провал не пошёл в счёт «под надзором»."
        else:
            strikes, newly_caught = await db.add_robbery_strike(
                chat_id, user_id, robbery.SURVEILLANCE_STRIKES_LIMIT
            )
            if newly_caught:
                surveillance_line = (
                    f"\n🚨 Вас поймали {strikes}-й раз — теперь вы <b>под надзором</b> и не можете "
                    f"грабить.\nСнять: <code>купить откуп</code> ({robbery.SURVEILLANCE_PARDON_PRICE} i¢)."
                )
            elif strikes < robbery.SURVEILLANCE_STRIKES_LIMIT:
                left = robbery.SURVEILLANCE_STRIKES_LIMIT - strikes
                surveillance_line = f"\n⚠️ Поимка {strikes}/{robbery.SURVEILLANCE_STRIKES_LIMIT} — ещё {left} и попадёте под надзор."

        if has_dymovushka:
            await db.remove_inventory_item(chat_id, user_id, "dymovushka", 1)
            await message.answer(
                f"💨 Кто-то попытался кого-то ограбить, но замешкался и {loss_text}. "
                f"Личность осталась загадкой.{surveillance_line}"
            )
        else:
            await message.answer(
                f"🚨 {actor_name} попытался(-лась) ограбить {victim_name}, не вышло — {loss_text}.{surveillance_line}"
            )

    if has_getaway_car:
        await db.remove_inventory_item(chat_id, user_id, "getaway_car", 1)
        await db.set_robbery_last_at(chat_id, user_id, datetime.utcnow() - robbery.ROBBERY_COOLDOWN / 2)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("стата ограблений", "моя стата ограблений")),
)
async def cmd_robbery_stats(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_stats"):
        return
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    stats = await db.get_robbery_stats(message.chat.id, target.id)
    name = await display_name(message.chat.id, target)
    await message.reply(
        f"🥷 <b>Стата ограблений — {name}</b>\n{DIVIDER}\n"
        f"Попыток: {stats['attempts']} (успешных {stats['successes']}, неудачных {stats['fails']}, "
        f"заблокировано бронёй {stats['blocked']})\n"
        f"Награблено всего: {stats['stolen_total']} i¢\n"
        f"Потеряно на провалах: {stats['lost_total']} i¢\n"
        f"Обокрали вас: {stats['times_robbed']} раз(а), на {stats['money_lost_as_victim']} i¢"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "топ грабителей"),
)
async def cmd_robbery_top(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_top"):
        return
    rows = await db.list_robbery_top(message.chat.id, limit=10)
    if not rows:
        await message.reply("Пока никто никого не ограбил.")
        return
    lines = ["🥷 <b>Топ грабителей</b>", DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = await display_name_by_id(message.chat.id, row["user_id"])
        rate = f"{row['successes']}/{row['attempts']}" if row["attempts"] else "0/0"
        lines.append(f"{i}. {name} — награблено {row['stolen_total']} i¢ ({rate})")
    await message.reply("\n".join(lines))



@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("купить откуп", "откуп")),
)
async def cmd_robbery_pardon(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_pardon"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    if not await db.is_under_surveillance(chat_id, user_id):
        await message.reply("Вы и так не под надзором.")
        return
    wallet = await db.get_wallet(chat_id, user_id)
    price = robbery.SURVEILLANCE_PARDON_PRICE
    if int(wallet.get("coins", 0)) < price:
        await message.reply(f"Недостаточно монет: у вас {wallet.get('coins', 0)} i¢, нужно {price}.")
        return
    await db.add_coins(chat_id, user_id, -price)
    await db.clear_robbery_surveillance(chat_id, user_id)
    await message.reply(f"✅ Откуп оплачен ({price} i¢) — надзор снят, можно грабить снова.")
    await db.add_log("robbery_pardon", chat_id=chat_id, actor_id=user_id)

# ============================================================================
# Казино: Рулетка (красное/чёрное/зелёное) — ставка i¢ из личного кошелька.
# Классическая механика: число 0-36, 0 — зелёное, остальные 18/18 по цветам.
# Выигрыш красное/чёрное — x2, зелёное — x14 (шанс всего 1/37, поэтому выше).
# ============================================================================
CASINO_COLOR_ALIASES = {
    "красное": "red", "красный": "red", "red": "red", "кр": "red", "р": "red",
    "черное": "black", "чёрное": "black", "черный": "black", "чёрный": "black",
    "black": "black", "чб": "black", "ч": "black",
    "зеленое": "green", "зелёное": "green", "зеленый": "green", "зелёный": "green",
    "green": "green", "зел": "green", "з": "green",
}
CASINO_COLOR_EMOJI = {"red": "🔴", "black": "⚫", "green": "🟢"}
CASINO_COLOR_LABEL = {"red": "Красное", "black": "Чёрное", "green": "Зелёное"}
CASINO_ROULETTE_RE = re.compile(r"(?i)^\.рулетка\s+(\S+)\s+(\S+)$")
CASINO_ROULETTE_MAX_BET = 100_000  # предохранитель от переполнения/абсурдных ставок
CASINO_DAILY_BONUS = 100
CASINO_MAX_BET = 100_000
CASINO_DICE_RE = re.compile(r"(?i)^!кости\s+(\S+)\s+([1-6])$")
CASINO_COIN_RE = re.compile(r"(?i)^!(орёл|орел|решка)\s+(\S+)$")
CASINO_POKER_RE = re.compile(r"(?i)^!покер\s+(\S+)$")
CASINO_TOPUP_RE = re.compile(r"(?i)^!казино\s+пополнить\s+(\S+)$")

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CASINO_ROULETTE_RE.match(t.strip()))),
)
async def cmd_casino_roulette(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_roulette"):
        return

    m = CASINO_ROULETTE_RE.match(message.text.strip())
    bet_amount = parse_amount(m.group(1))
    color = CASINO_COLOR_ALIASES.get(m.group(2).casefold())

    if color is None:
        await message.reply(
            "Использование: <code>.рулетка {ставка} {цвет}</code>\n"
            "Цвет — красное / чёрное / зелёное.\n"
            "Например: <code>.рулетка 100 красное</code>"
        )
        return
    if bet_amount is None or bet_amount <= 0:
        await message.reply("Ставка должна быть больше нуля.")
        return
    if bet_amount > CASINO_ROULETTE_MAX_BET:
        await message.reply(f"Слишком большая ставка (максимум {CASINO_ROULETTE_MAX_BET} i¢).")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    wallet = await db.get_wallet(chat_id, user_id)
    if int(wallet.get("coins", 0)) < bet_amount:
        await message.reply(
            f"Недостаточно монет: у вас {wallet.get('coins', 0)} i¢, ставка {bet_amount} i¢."
        )
        return

    number = random.randint(0, 36)
    result_color = roulette_number_color(number)

    if result_color == color:
        multiplier = 14 if color == "green" else 2
        winnings = bet_amount * multiplier
        delta = winnings - bet_amount  # ставка не сгорает, засчитывается в выигрыш
        await db.add_coins(chat_id, user_id, delta)
        outcome_text = f"✅ <b>Выигрыш!</b> +{delta} i¢ (x{multiplier})"
    else:
        await db.add_coins(chat_id, user_id, -bet_amount)
        outcome_text = f"❌ <b>Проигрыш.</b> -{bet_amount} i¢"

    await message.answer(
        "🎰 <b>Казино: Рулетка</b>\n"
        f"{DIVIDER}\n"
        f"Ставка: {bet_amount} i¢ на {CASINO_COLOR_LABEL[color]}\n"
        f"Выпало: {CASINO_COLOR_EMOJI[result_color]} <b>{number}</b> ({CASINO_COLOR_LABEL[result_color]})\n"
        f"{outcome_text}"
    )
    await db.add_log(
        "casino_roulette", chat_id=chat_id, actor_id=user_id,
        details=f"bet={bet_amount} color={color} number={number}",
    )
# ---------- Покер: оценка руки из 5 карт ----------
POKER_SUITS = "♠♥♦♣"
POKER_RANK_NAMES = {11: "J", 12: "Q", 13: "K", 14: "A"}


def _poker_rank_label(rank: int) -> str:
    return POKER_RANK_NAMES.get(rank, str(rank))


def _draw_poker_hand() -> list[tuple[int, str]]:
    deck = [(rank, suit) for rank in range(2, 15) for suit in POKER_SUITS]
    return random.sample(deck, 5)


def _evaluate_poker_hand(cards: list[tuple[int, str]]) -> tuple[int, str]:
    """(множитель выигрыша, название комбинации). 0 — без выигрыша."""
    ranks = sorted((r for r, _ in cards), reverse=True)
    suits = [s for _, s in cards]
    is_flush = len(set(suits)) == 1

    unique_ranks = sorted(set(ranks), reverse=True)
    is_straight = False
    if len(unique_ranks) == 5:
        if unique_ranks[0] - unique_ranks[4] == 4:
            is_straight = True
        elif unique_ranks == [14, 5, 4, 3, 2]:  # туз как низшая карта (А-2-3-4-5)
            is_straight = True

    counts: dict[int, int] = {}
    for r in ranks:
        counts[r] = counts.get(r, 0) + 1
    count_values = sorted(counts.values(), reverse=True)

    if is_straight and is_flush:
        return 10, "стрит-флеш"
    if count_values[0] == 4:
        return 10, "каре"
    if count_values[0] == 3 and count_values[1] == 2:
        return 8, "фулл-хаус"
    if is_flush:
        return 6, "флеш"
    if is_straight:
        return 5, "стрит"
    if count_values[0] == 3:
        return 3, "тройка"
    if count_values[0] == 2 and count_values[1] == 2:
        return 2, "две пары"
    return 0, "пусто (пара или меньше)"


def _format_poker_hand(cards: list[tuple[int, str]]) -> str:
    return " ".join(f"{_poker_rank_label(r)}{s}" for r, s in cards)


# ---------- Казино: баланс + ежедневный бонус ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "!казино баланс"),
)
async def cmd_casino_balance(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_balance"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    bonus_given, balance = await db.claim_daily_bonus(chat_id, user_id, CASINO_DAILY_BONUS)
    lines = ["🎰 <b>Казино: баланс</b>", DIVIDER, f"💰 {balance} i¢"]
    if bonus_given:
        lines.append(f"\n🎁 Начислен ежедневный бонус: +{CASINO_DAILY_BONUS} i¢!")
    else:
        lines.append("\n(бонус на сегодня уже получен — заходите завтра)")
    await message.answer("\n".join(lines))


CASINO_WITHDRAW_RE = re.compile(r"(?i)^!казино\s+вывести\s+(\S+)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CASINO_WITHDRAW_RE.match(t.strip()))),
)
async def cmd_casino_withdraw(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_withdraw"):
        return
    amount = parse_amount(CASINO_WITHDRAW_RE.match(message.text.strip()).group(1))
    if amount is None or amount <= 0:
        await message.reply("Сумма вывода должна быть больше нуля.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    wallet = await db.get_casino_wallet(chat_id, user_id)
    if int(wallet.get("balance", 0)) < amount:
        await message.reply(
            f"Недостаточно средств в казино: у вас {wallet.get('balance', 0)} i¢, нужно {amount}."
        )
        return

    await db.add_casino_balance(chat_id, user_id, -amount)
    new_balance = await db.add_coins(chat_id, user_id, amount)
    await message.reply(
        f"✅ Выведено {amount} i¢ из казино в кошелёк.\n"
        f"Баланс кошелька: {new_balance} i¢"
    )
    await db.add_log("casino_withdraw", chat_id=chat_id, actor_id=user_id, details=str(amount))


