# ============================================================================
# Банк: вклады под простые проценты (rate% в день × число дней, фиксируется
# в момент открытия) и кредиты с комиссией и дневной пеней за просрочку.
# Ставки и параметры кредита настраиваются админами командами «банк ...».
# ============================================================================
BANK_STATUS_RE = re.compile(r"(?i)^!банк$")
BANK_DEPOSIT_RE = re.compile(r"(?i)^!банк\s+вклад\s+(\S+)\s+(\d+)$")
BANK_WITHDRAW_RE = re.compile(r"(?i)^!банк\s+снять$")
BANK_CREDIT_RE = re.compile(r"(?i)^!банк\s+кредит\s+(\S+)$")
BANK_REPAY_RE = re.compile(r"(?i)^!банк\s+погасить\s+(\S+)$")

BANK_RATE_SET_RE = re.compile(r"(?i)^банк\s+ставка\s+(1|3|7)д?\s+(\d+(?:\.\d+)?)$")
BANK_CREDIT_FEE_RE = re.compile(r"(?i)^банк\s+кредит\s+комиссия\s+(\d+(?:\.\d+)?)$")
BANK_CREDIT_PENALTY_RE = re.compile(r"(?i)^банк\s+кредит\s+пеня\s+(\d+(?:\.\d+)?)$")
BANK_CREDIT_TERM_RE = re.compile(r"(?i)^банк\s+кредит\s+срок\s+(\d+)$")
BANK_MIN_DEPOSIT_RE = re.compile(r"(?i)^банк\s+мин\s+вклад\s+(\S+)$")

BANK_RATE_COLUMN = {"1": "rate_1d", "3": "rate_3d", "7": "rate_7d"}


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_STATUS_RE.match(t.strip()))),
)
async def cmd_bank_status(message: Message):
    if not _check_misc_access(message.from_user.id, "bank_status"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    account = await db.get_bank_account(chat_id, user_id)
    settings_row = await db.get_bank_settings(chat_id)

    lines = ["🏦 <b>Банк</b>", DIVIDER]

    if account["deposit_amount"]:
        matures: datetime = account["deposit_matures_at"]
        rate = float(account["deposit_rate"])
        days = int(account["deposit_days"])
        payout = int(account["deposit_amount"] + account["deposit_amount"] * rate / 100 * days)
        if datetime.utcnow() >= matures:
            lines.append(
                f"💰 Вклад готов к снятию: {account['deposit_amount']} i¢ → выплата {payout} i¢\n"
                "Снять: «!банк снять»"
            )
        else:
            remaining = matures - datetime.utcnow()
            lines.append(
                f"💰 Вклад: {account['deposit_amount']} i¢ на {days} дн. под {rate:g}%/день\n"
                f"⏳ Созреет через {format_duration_ru(remaining)} — тогда выплата {payout} i¢"
            )
    else:
        lines.append("💰 Вклада нет. Открыть: «!банк вклад {сумма} {срок: 1/3/7}»")

    lines.append("")
    if account["credit_debt"]:
        due: datetime = account["credit_due_at"]
        overdue = datetime.utcnow() >= due
        status = "⚠️ просрочен, начисляется пеня" if overdue else f"до {fmt_dt(due)}"
        lines.append(
            f"💳 Долг по кредиту: {account['credit_debt']} i¢ ({status})\n"
            "Погасить: «!банк погасить {сумма}»"
        )
    else:
        lines.append("💳 Активного кредита нет. Взять: «!банк кредит {сумма}»")

    lines.append("")
    lines.append(
        f"📊 Ставки вклада: 1д — {float(settings_row['rate_1d']):g}%/день, "
        f"3д — {float(settings_row['rate_3d']):g}%/день, "
        f"7д — {float(settings_row['rate_7d']):g}%/день\n"
        f"📊 Минимальный вклад: {settings_row['min_deposit']} i¢\n"
        f"📊 Кредит: комиссия {float(settings_row['credit_fee_percent']):g}%, "
        f"срок {settings_row['credit_term_days']} дн., "
        f"пеня за просрочку {float(settings_row['credit_penalty_percent']):g}%/день"
    )
    await message.reply("\n".join(lines))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_DEPOSIT_RE.match(t.strip()))),
)
async def cmd_bank_deposit(message: Message):
    if not _check_misc_access(message.from_user.id, "bank_deposit"):
        return
    m = BANK_DEPOSIT_RE.match(message.text.strip())
    amount, days = parse_amount(m.group(1)), int(m.group(2))
    if amount is None:
        await message.reply("Не понял сумму вклада.")
        return

    if days not in (1, 3, 7):
        await message.reply("Срок вклада может быть только 1, 3 или 7 дней.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    settings_row = await db.get_bank_settings(chat_id)
    min_deposit = int(settings_row["min_deposit"])
    if amount < min_deposit:
        await message.reply(f"Минимальная сумма вклада — {min_deposit} i¢.")
        return

    account = await db.get_bank_account(chat_id, user_id)
    if account["deposit_amount"]:
        await message.reply("У вас уже есть открытый вклад — сначала снимите его («!банк снять»).")
        return

    if not await spend_coins(chat_id, user_id, amount):
        await message.reply(f"Недостаточно монет: нужно {amount}.")
        return

    rate = float(settings_row[BANK_RATE_COLUMN[str(days)]])
    await db.open_bank_deposit(chat_id, user_id, amount, days, rate)

    payout = int(amount + amount * rate / 100 * days)
    await message.reply(
        f"✅ Вклад открыт: {amount} i¢ на {days} дн. под {rate:g}%/день.\n"
        f"По истечении срока получите: {payout} i¢."
    )
    await db.add_log("bank_deposit_open", chat_id=chat_id, actor_id=user_id, details=f"{amount}@{days}d")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_WITHDRAW_RE.match(t.strip()))),
)
async def cmd_bank_withdraw(message: Message):
    if not _check_misc_access(message.from_user.id, "bank_withdraw"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    account = await db.get_bank_account(chat_id, user_id)
    if not account["deposit_amount"]:
        await message.reply("У вас нет открытого вклада.")
        return

    matures: datetime = account["deposit_matures_at"]
    if datetime.utcnow() < matures:
        remaining = matures - datetime.utcnow()
        await message.reply(
            f"⏳ Вклад ещё заморожен — созреет через {format_duration_ru(remaining)} "
            f"({fmt_dt(matures)}). Досрочно снять нельзя."
        )
        return

    rate = float(account["deposit_rate"])
    days = int(account["deposit_days"])
    payout = int(account["deposit_amount"] + account["deposit_amount"] * rate / 100 * days)
    await db.add_coins(chat_id, user_id, payout)
    await db.close_bank_deposit(chat_id, user_id)
    await message.reply(f"✅ Вклад закрыт, получено: {payout} i¢.")
    await db.add_log("bank_deposit_close", chat_id=chat_id, actor_id=user_id, details=str(payout))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_CREDIT_RE.match(t.strip()))),
)
async def cmd_bank_credit(message: Message):
    if not _check_misc_access(message.from_user.id, "bank_credit"):
        return
    amount = int(BANK_CREDIT_RE.match(message.text.strip()).group(1))
    if amount <= 0:
        await message.reply("Сумма кредита должна быть больше нуля.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    account = await db.get_bank_account(chat_id, user_id)
    if account["credit_debt"]:
        await message.reply(
            f"У вас уже есть непогашенный кредит: {account['credit_debt']} i¢. "
            "Сначала погасите его («!банк погасить {сумма}»)."
        )
        return

    if await db.is_bank_blacklisted(chat_id, user_id):
        await message.reply("⛔ Вам закрыт доступ к кредитам банка — вы в чёрном списке.")
        return

    if await is_bank_auto_reject_enabled(chat_id):
        await message.reply("❌ Кредиты в этом чате временно не выдаются — заявка автоматически отклонена.")
        await db.add_log("bank_credit_auto_rejected", chat_id=chat_id, actor_id=user_id, details=str(amount))
        return

    if not settings.get("notify_chat_id"):
        await message.reply("⚠️ Кредиты пока некому одобрять — админы не настроили «топик сюда»/«чат сюда».")
        return

    pending_key = f"bank_credit_pending:{chat_id}:{user_id}"
    if await db.get_data(pending_key):
        await message.reply("У вас уже есть заявка на кредит, которая ждёт решения администраторов.")
        return

    settings_row = await db.get_bank_settings(chat_id)
    fee_percent = float(settings_row["credit_fee_percent"])
    term_days = int(settings_row["credit_term_days"])
    debt = int(round(amount * (1 + fee_percent / 100)))

    await db.set_data(pending_key, json.dumps({"amount": amount, "debt": debt, "term_days": term_days}))

    mention = mention_id(message.from_user.id, full_name=message.from_user.full_name, username=message.from_user.username)
    notify_text = (
        "🏦 <b>Заявка на кредит</b>\n\n"
        f"👤 {mention}\n"
        f"💰 Сумма: {amount} i¢\n"
        f"📈 К возврату: {debt} i¢ (комиссия {fee_percent:g}%)\n"
        f"⏳ Срок: {term_days} дн.\n"
        f"📍 Чат: {html.escape(message.chat.title or str(chat_id))}"
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="✅ Одобрить", callback_data=f"bankcredit_yes:{chat_id}:{user_id}"),
        InlineKeyboardButton(text="❌ Отклонить", callback_data=f"bankcredit_no:{chat_id}:{user_id}"),
    ]])
    try:
        await bot.send_message(
            chat_id=settings["notify_chat_id"],
            message_thread_id=settings.get("notify_topic_id"),
            text=notify_text,
            reply_markup=kb,
        )
    except Exception:
        logger.exception("Не удалось отправить заявку на кредит админам")
        await db.delete_data(pending_key)
        await message.reply("⚠️ Не удалось передать заявку администраторам. Попробуйте позже.")
        return

    await message.reply(
        f"📨 Заявка на кредит {amount} i¢ отправлена администраторам на рассмотрение.\n"
        "Как только её одобрят или отклонят — вам придёт уведомление."
    )
    await db.add_log("bank_credit_requested", chat_id=chat_id, actor_id=user_id, details=f"{amount}->{debt}")


@router.callback_query(F.data.startswith("bankcredit_yes:"))
async def confirm_bank_credit(callback: CallbackQuery):
    if not is_admin(callback.from_user.id):
        await callback.answer("⛔ Только администратор может это сделать.", show_alert=True)
        return
    try:
        _, chat_id_str, user_id_str = callback.data.split(":", maxsplit=2)
        chat_id, user_id = int(chat_id_str), int(user_id_str)
    except (ValueError, IndexError):
        await callback.answer("Заявка устарела.", show_alert=True)
        return

    pending_key = f"bank_credit_pending:{chat_id}:{user_id}"
    row = await db.get_data(pending_key)
    if not row or not row.get("data_value"):
        await callback.answer("Заявка уже обработана.", show_alert=True)
        return
    data = json.loads(row["data_value"])

    account = await db.get_bank_account(chat_id, user_id)
    if account["credit_debt"]:
        await db.delete_data(pending_key)
        await callback.answer("У пользователя уже появился другой непогашенный кредит.", show_alert=True)
        try:
            await callback.message.edit_text("⚠️ Заявка отменена — у пользователя уже есть непогашенный кредит.")
        except TelegramBadRequest:
            pass
        return

    await db.open_bank_credit(chat_id, user_id, data["amount"], data["debt"], data["term_days"])
    await db.add_coins(chat_id, user_id, data["amount"])
    await db.delete_data(pending_key)

    admin_label = mention_id(callback.from_user.id, full_name=callback.from_user.full_name, username=callback.from_user.username)
    try:
        new_text = (callback.message.html_text or callback.message.text or "") + f"\n\n✅ Одобрено ({admin_label})"
        await callback.message.edit_text(new_text)
    except TelegramBadRequest:
        pass
    try:
        chat_obj = await bot.get_chat(chat_id)
        await bot.send_message(
            user_id,
            f"✅ Ваш кредит на {data['amount']} i¢ одобрен и зачислен в чате "
            f"{html.escape(chat_obj.title or str(chat_id))}.\n"
            f"К возврату: {data['debt']} i¢ в течение {data['term_days']} дн.",
        )
    except Exception:
        pass
    await db.add_log("bank_credit_approved", chat_id=chat_id, actor_id=callback.from_user.id, target_id=user_id)
    await callback.answer("Одобрено ✅")


