@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_REPAY_RE.match(t.strip()))),
)
async def cmd_bank_repay(message: Message):
    if not _check_misc_access(message.from_user.id, "bank_repay"):
        return
    amount = parse_amount(BANK_REPAY_RE.match(message.text.strip()).group(1))
    if amount is None or amount <= 0:
        await message.reply("Сумма погашения должна быть больше нуля.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    account = await db.get_bank_account(chat_id, user_id)
    if not account["credit_debt"]:
        await message.reply("У вас нет активного кредита.")
        return

    wallet = await db.get_wallet(chat_id, user_id)
    pay = min(amount, int(account["credit_debt"]))
    if int(wallet.get("coins", 0)) < pay:
        await message.reply(f"Недостаточно монет: у вас {wallet.get('coins', 0)} i¢, нужно {pay}.")
        return

    await db.add_coins(chat_id, user_id, -pay)
    remaining = await db.reduce_bank_credit_debt(chat_id, user_id, pay)
    if remaining:
        await message.reply(f"✅ Погашено {pay} i¢. Остаток долга: {remaining} i¢.")
    else:
        await message.reply(f"✅ Погашено {pay} i¢. Кредит полностью закрыт!")
    await db.add_log("bank_credit_repay", chat_id=chat_id, actor_id=user_id, details=str(pay))


# ---------- Настройка банка (админы) ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_RATE_SET_RE.match(t.strip()))),
)
async def cmd_bank_rate_set(message: Message):
    if not has_level(message.from_user.id, required_level("bank_manage")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Настраивать банк может «{level_name(required_level('bank_manage'))}» и выше.")
        return
    m = BANK_RATE_SET_RE.match(message.text.strip())
    term, percent = m.group(1), float(m.group(2))
    await db.set_bank_rate(message.chat.id, BANK_RATE_COLUMN[term], percent)
    await db.add_log("bank_rate_set", chat_id=message.chat.id, actor_id=message.from_user.id, details=f"{term}d={percent}")
    await message.reply(f"✅ Ставка вклада на {term} дн.: {percent:g}%/день.")


