def _bank_auto_reject_key(chat_id: int) -> str:
    return f"bank_autoreject:{chat_id}"


async def is_bank_auto_reject_enabled(chat_id: int) -> bool:
    row = await db.get_data(_bank_auto_reject_key(chat_id))
    return row is not None and row.get("data_value") == "1"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("+банк автоотказ-кредит", "-банк автоотказ-кредит")),
)
async def cmd_bank_auto_reject_toggle(message: Message):
    min_level = required_level("bank_auto_reject_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    enable = message.text.strip().casefold() == "+банк автоотказ-кредит"
    key = _bank_auto_reject_key(message.chat.id)
    if enable:
        await db.set_data(key, "1", updated_by=message.from_user.id)
        await message.reply(
            "🚫 Автоотказ кредитов включён — новые заявки на кредит теперь отклоняются "
            "автоматически, без рассмотрения администраторами."
        )
    else:
        await db.delete_data(key)
        await message.reply("✅ Автоотказ кредитов выключен — заявки снова идут на рассмотрение администраторам.")
    await db.add_log(
        "bank_auto_reject_toggle", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(enable)
    )


