# ---------- Фоновая пеня за просроченные кредиты ----------
BANK_PENALTY_CHECK_INTERVAL = 3600  # проверяем раз в час, начисляем не чаще раза в сутки на кредит


async def bank_penalty_loop() -> None:
    while True:
        try:
            await asyncio.sleep(BANK_PENALTY_CHECK_INTERVAL)
            rows = await db.list_overdue_bank_credits()
            for row in rows:
                chat_id, user_id = row["chat_id"], row["user_id"]
                penalty_percent = float(row["credit_penalty_percent"])
                new_debt = int(round(int(row["credit_debt"]) * (1 + penalty_percent / 100)))
                principal = row.get("credit_amount")

                # Пеня «съела» больше 200% от исходной суммы кредита (долг
                # вырос минимум втрое от принципала) — дальше не ждём:
                # варн и принудительное списание всего долга, даже в минус.
                if principal and new_debt >= principal * 3:
                    await db.reduce_bank_credit_debt(chat_id, user_id, new_debt)
                    await db.add_coins(chat_id, user_id, -new_debt)
                    warn_count = await db.add_warn(
                        chat_id, user_id, 0,
                        "Просрочка кредита — пеня превысила 200%",
                        datetime.utcnow() + WARN_DEFAULT_DURATION,
                    )
                    try:
                        await bot.send_message(
                            chat_id,
                            f"🚨 {mention_id(user_id)}, пеня по кредиту превысила 200% — "
                            f"долг ({new_debt} i¢) списан принудительно (баланс мог уйти в минус), "
                            f"выдано предупреждение ({warn_count}/{WARN_LIMIT}).",
                        )
                    except Exception:
                        pass
                    await db.add_log(
                        "bank_credit_force_collected", chat_id=chat_id, target_id=user_id, details=str(new_debt)
                    )
                    continue

                await db.apply_bank_credit_penalty(chat_id, user_id, new_debt)
                try:
                    await bot.send_message(
                        chat_id,
                        f"⚠️ {mention_id(user_id)}, кредит просрочен — начислена пеня "
                        f"{penalty_percent:g}%. Новый долг: {new_debt} i¢. "
                        "Погасить: «!банк погасить {сумма}».",
                    )
                except Exception:
                    pass
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле пени по кредитам банка")



# ============================================================================
# Титулы: покупные в магазине (см. «купить титул») + выдаваемые автоматически
# за ачивки (см. правку grant_achievement() ниже). Активный титул хранится
# в profile_cards.active_title и показывается в /профиль рядом с именем.
# ============================================================================
TITLE_BUY_RE = re.compile(r"(?i)^купить\s+титул\s+(\S+)$")
TITLE_EQUIP_RE = re.compile(r"(?i)^титул\s+(\S+)$")

async def titles_list_page(chat_id: int, user_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    owned = {t["title_key"] for t in await db.list_user_titles(chat_id, user_id)}
    all_titles = await db.list_titles()
    if not all_titles:
        return "🎖 <b>Титулы</b>\n\nПока нет ни одного титула.", None

    page = max(page, 0)
    total_pages = max((len(all_titles) + TITLES_LIST_PAGE_SIZE - 1) // TITLES_LIST_PAGE_SIZE, 1)
    page = min(page, total_pages - 1)
    chunk = all_titles[page * TITLES_LIST_PAGE_SIZE : (page + 1) * TITLES_LIST_PAGE_SIZE]

    lines = ["🎖 <b>Титулы</b>", DIVIDER]
    for t in chunk:
        key = t["title_key"]
        if key in owned:
            status = "✅ у вас"
        elif t.get("price") is not None:
            status = f"{t['price']} i¢"
        else:
            status = "🔒 только за ачивку"
        lines.append(f"{t['name']} (<code>{key}</code>) — {status}")
    lines.append("")
    lines.append("Купить: <code>купить титул {ключ}</code>")
    lines.append("Надеть: <code>титул {ключ}</code> · снять: <code>-титул</code>")
    text = "\n".join(lines)

    if total_pages == 1:
        return text, None

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"titles_page:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{total_pages}", callback_data="noop"))
    if page + 1 < total_pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"titles_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[nav])



@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "титулы"),
)
async def cmd_titles_list(message: Message):
    if not _check_misc_access(message.from_user.id, "titles_list"):
        return
    text, kb = await titles_list_page(message.chat.id, message.from_user.id, 0)
    await message.reply(text, reply_markup=kb)

@router.callback_query(F.data == "noop")
async def cb_noop(callback: CallbackQuery):
    await callback.answer()

@router.callback_query(F.data.startswith("titles_page:"))
async def paginate_titles_list(callback: CallbackQuery):
    if not _check_misc_access(callback.from_user.id, "titles_list"):
        await callback.answer()
        return
    try:
        page = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось открыть эту страницу.", show_alert=True)
        return
    text, kb = await titles_list_page(callback.message.chat.id, callback.from_user.id, page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(TITLE_BUY_RE.match(t.strip()))),
)
async def cmd_title_buy(message: Message):
    if not _check_misc_access(message.from_user.id, "title_buy"):
        return
    key = TITLE_BUY_RE.match(message.text.strip()).group(1).casefold()
    title = await db.get_title(key)
    if title is None or title.get("price") is None:
        await message.reply("Такого титула нет в продаже. Список — «титулы».")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    if await db.has_title(chat_id, user_id, key):
        await message.reply("У вас уже есть этот титул.")
        return

    if not await spend_coins(chat_id, user_id, title["price"]):
        await message.reply(f"Недостаточно монет: нужно {title['price']} i¢.")
        return
    await db.grant_title(chat_id, user_id, key)
    await db.add_log("title_bought", chat_id=chat_id, actor_id=user_id, details=key)
    await message.reply(f"✅ Куплено: {title['name']} за {title['price']} i¢.\nНадеть: «титул {key}»")


