def profession_level_from_xp(xp: int) -> int:
    level = 1
    for lvl in range(1, PROFESSION_MAX_LEVEL + 1):
        if xp >= PROFESSION_LEVEL_XP[lvl]:
            level = lvl
    return level


async def _profession_execute_work(chat_id: int, user_id: int) -> str:
    stats = await db.get_profession_stats(chat_id, user_id)
    prof_key = stats.get("profession_key")
    if not prof_key or prof_key not in PROFESSIONS:
        return "❌ У вас пока нет профессии. Выберите: <code>!работа устроиться {профессия}</code>."

    now = datetime.utcnow()
    last = stats.get("last_work_at")
    if last and (now - last) < PROFESSION_WORK_COOLDOWN:
        remaining = PROFESSION_WORK_COOLDOWN - (now - last)
        return f"❌ НЕЗАЧЁТ! Следующая смена через {format_duration_ru(remaining)}."

    prof = PROFESSIONS[prof_key]
    has_tools = await db.has_profession_upgrade(chat_id, user_id, "инструменты")
    energy_cost = prof["energy"] // 2 if has_tools else prof["energy"]

    if stats["energy"] < energy_cost:
        return f"❌ Не хватает энергии ({stats['energy']}/{energy_cost}). Отдохните: «!работа перерыв»."

    level = stats["prof_level"]
    mood_multiplier = 0.5 + (stats["mood"] / 200)
    base_income = random.randint(*prof["income"])
    level_bonus = 1 + PROFESSION_LEVEL_INCOME_BONUS.get(level, 0)
    courses_bonus = 1.2 if await db.has_profession_upgrade(chat_id, user_id, "курсы") else 1.0
    final_income = int(base_income * mood_multiplier * level_bonus * courses_bonus)

    quality = random.uniform(0.8, 1.2)
    xp_gain = int(final_income / 10) + int(quality * 2)

    today = now.date()
    last_day = stats.get("last_shift_day")
    if last_day == today - timedelta(days=1):
        new_streak = stats["work_streak"] + 1
    elif last_day == today:
        new_streak = stats["work_streak"]
    else:
        new_streak = 1
    if new_streak >= 30:
        xp_gain += 100
    elif new_streak >= 10:
        xp_gain += 25
    elif new_streak >= 5:
        xp_gain += 10

    event_text = ""
    energy_delta = -energy_cost
    mood_delta = -random.randint(0, 5)
    health_delta = 0
    if random.random() < 0.15:
        roll = random.choice(["premium", "hurt", "insight", "theft", "treat", "bonus"])
        if roll == "premium":
            final_income = int(final_income * 1.5)
            event_text = "🎉 Премия! +50% к доходу за смену."
        elif roll == "hurt":
            health_delta -= 20
            mood_delta -= 10
            event_text = "💔 Несчастный случай: -20 здоровья, -10 настроения."
        elif roll == "insight":
            xp_gain += 30
            event_text = "🧠 Озарение! +30 XP."
        elif roll == "theft":
            final_income = int(final_income * 0.7)
            event_text = "💸 Кража: -30% от дохода."
        elif roll == "treat":
            energy_delta += 20
            event_text = "🤝 Коллега угостил: +20 энергии."
        else:
            final_income += 50
            event_text = "📈 Курс вырос: +50 i¢ бонус."

    await db.add_coins(chat_id, user_id, final_income)
    stats = await db.update_profession_after_shift(
        chat_id, user_id, xp_gain, final_income, energy_delta, mood_delta,
        health_delta, new_streak, today,
    )

    new_level = profession_level_from_xp(stats["prof_xp"])
    level_up_text = ""
    if new_level > stats["prof_level"]:
        await db.set_profession_level(chat_id, user_id, new_level)
        level_up_text = f"\n🎉 <b>Повышение!</b> Новый уровень: {new_level}"
        await grant_achievement(chat_id, user_id, "prof_level5" if new_level >= 5 else "prof_level_up", announce=False)
        if new_level >= 10:
            await grant_achievement(chat_id, user_id, "prof_level10", announce=False)

    lines = [
        "💼 <b>Рабочая смена завершена!</b>",
        f"{prof['emoji']} Профессия: {prof['name']} ({new_level} уровень)",
        f"💰 Доход: {final_income} i¢",
        f"⭐ Опыт: +{xp_gain} XP",
        f"⚡ Энергия: {stats['energy']}/100 · 🙂 Настроение: {stats['mood']}/100 · ❤️ Здоровье: {stats['health']}/100",
    ]
    if event_text:
        lines.append(f"\n🎲 Событие: {event_text}")
    lines.append(level_up_text) if level_up_text else None
    return "\n".join(l for l in lines if l)

def _is_prof_cmd(t: Optional[str], sub: str) -> bool:
    if not t:
        return False
    words = t.strip().casefold().split()
    return len(words) >= 2 and words[0] =="!работа" and words[1] == sub


