@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: _is_prof_cmd(t, "устроиться")),
)
async def cmd_prof_join(message: Message):
    parts = message.text.strip().split(maxsplit=2)
    key = parts[2].strip().casefold() if len(parts) > 2 else ""
    prof = PROFESSIONS.get(key)
    if prof is None:
        names = ", ".join(f"{p['emoji']} {p['name']} ({k})" for k, p in PROFESSIONS.items())
        await message.reply(f"Укажите профессию: <code>!работа устроиться уборщик</code>\n\nДоступные: {names}")
        return

    stats = await db.get_profession_stats(message.chat.id, message.from_user.id)
    if stats.get("profession_key"):
        await message.reply("У вас уже есть профессия. Сначала «!работа уволиться».")
        return

    first_seen = await db.get_member_first_seen(message.chat.id, message.from_user.id)
    days_in_chat = (datetime.utcnow() - first_seen).days if first_seen else 0
    if days_in_chat < prof["req_days"]:
        await message.reply(f"⛔ Нужно быть в чате минимум {prof['req_days']} дн. (сейчас {days_in_chat}).")
        return
    wallet = await db.get_wallet(message.chat.id, message.from_user.id)
    if wallet.get("coins", 0) < prof["req_coins"]:
        await message.reply(f"⛔ Нужно {prof['req_coins']} i¢ на входе (у вас {wallet.get('coins', 0)}).")
        return

    await db.set_profession(message.chat.id, message.from_user.id, key)
    await message.reply(f"✅ Вы устроились: {prof['emoji']} <b>{prof['name']}</b>!\nПервая смена — «!работа».")


