async def shop_list_page(chat_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    await db.seed_default_shop_items(chat_id)
    await db.seed_robbery_items(chat_id, robbery.ROBBERY_SHOP_ITEMS)
    items = await db.list_shop_items(chat_id)
    items.sort(key=lambda i: (i.get("stock") == 0, i["price"]))
    if not items:
        return (
            "🏪 Магазин этого чата пока пуст.\n"
            "Админы могут добавить товар: <code>магазин добавить ключ цена Название</code>",
            None,
        )

    page = max(page, 0)
    total_pages = max((len(items) + SHOP_LIST_PAGE_SIZE - 1) // SHOP_LIST_PAGE_SIZE, 1)
    page = min(page, total_pages - 1)
    chunk = items[page * SHOP_LIST_PAGE_SIZE : (page + 1) * SHOP_LIST_PAGE_SIZE]

    lines = ["🏪 <b>Магазин чата</b>", DIVIDER]
    lines.extend(shop_item_line(i) for i in chunk)
    lines.append("\nКупить: <code>купить ключ</code>")
    text = "\n".join(lines)

    if total_pages == 1:
        return text, None

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"shop_page:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{total_pages}", callback_data="noop"))
    if page + 1 < total_pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"shop_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[nav])
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("магазин","магаз")),
)
async def cmd_shop_list(message: Message):
    text, kb = await shop_list_page(message.chat.id, 0)
    await message.reply(text, reply_markup=kb)


@router.callback_query(F.data.startswith("shop_page:"))
async def paginate_shop_list(callback: CallbackQuery):
    try:
        page = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось открыть эту страницу.", show_alert=True)
        return
    text, kb = await shop_list_page(callback.message.chat.id, page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(SHOP_ADD_RE.match(t.strip()))),
)
async def cmd_shop_add(message: Message):
    min_level = required_level("shop_manage")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Управлять магазином может «{level_name(min_level)}» и выше.")
        return
    m = SHOP_ADD_RE.match(message.text.strip())
    item_key, price_s, name = m.group(1).casefold(), m.group(2), m.group(3).strip()
    price = parse_amount(price_s)
    if price is None or price <= 0:
        await message.reply("Не понял цену. Можно так: 500, 5к, 1.2м.")
        return
    if len(item_key) > 64 or len(name) > 64:
        await message.reply("⚠️ Слишком длинный ключ или название (максимум 64 символа).")
        return
    ok = await db.add_shop_item(message.chat.id, item_key, name[:64], price)
    if not ok:
        await message.reply(f"Товар с ключом «{html.escape(item_key)}» уже есть в магазине.")
        return
    await db.add_log("shop_item_added", chat_id=message.chat.id, actor_id=message.from_user.id, details=item_key)
    await message.reply(
        f"✅ Добавлено в магазин: 🎁 <b>{html.escape(name)}</b> ({item_key}) — {price} i¢"
    )

def shop_menu_kb(items: list[dict]) -> ReplyKeyboardMarkup:
    labels = []
    for i in items:
        stock = i.get("stock")
        stock_part = "∞" if stock is None else str(stock)
        status = "✅" if i["is_active"] else "🚫"
        labels.append(f"{status} {i['item_key']} · {i['name']} · {stock_part}")
    rows = _grid(labels, cols=1)
    rows.append([BTN_SHOP_ADD, BTN_BACK])
    return _reply_kb(rows)


def shop_item_menu_kb(is_active: bool) -> ReplyKeyboardMarkup:
    toggle_text = "🚫 Выключить" if is_active else "✅ Включить"
    return _reply_kb([
        ["💰 Цена", "📦 Остаток"],
        ["🔁 Пополнение", toggle_text],
        ["🗑 Удалить"],
        [BTN_BACK],
    ])


def shop_menu_text(items: list[dict]) -> str:
    if not items:
        return f"🏪 <b>{LBL_SHOP}</b>\n\nТоваров пока нет. Нажмите «{BTN_SHOP_ADD}», чтобы добавить первый."
    return f"🏪 <b>{LBL_SHOP}</b> — {len(items)} товар(ов)\n{DIVIDER}\nВыберите товар, чтобы им управлять."


def _shop_chat_id() -> Optional[int]:
    return settings.get("complaint_chat_id")


async def _show_shop_menu(message: Message, state: FSMContext) -> None:
    chat_id = _shop_chat_id()
    if not chat_id:
        await message.answer("⚠️ Сначала привяжите основной чат командой «чат сюда» или «топик сюда».")
        return
    items = await db.list_shop_items(chat_id, active_only=False)
    await state.set_state(AdminStates.menu_shop)
    await message.answer(shop_menu_text(items), reply_markup=shop_menu_kb(items))


