@router.message(StateFilter(AdminStates.waiting_shop_new_stock), F.chat.type == "private")
async def shop_add_stock(message: Message, state: FSMContext):
    raw = (message.text or "").strip()
    if raw == BTN_SHOP_UNLIMITED:
        stock = None
    elif raw.isdigit() and int(raw) >= 0:
        stock = int(raw)
    else:
        await message.answer(
            f"Нужно неотрицательное целое число, либо «{BTN_SHOP_UNLIMITED}».",
            reply_markup=_reply_kb([[BTN_SHOP_UNLIMITED], [BTN_CANCEL]]),
        )
        return
    await state.update_data(shop_stock=stock)
    await state.set_state(AdminStates.waiting_shop_new_description)
    await message.answer("Добавьте короткое описание товара (или «Пропустить»):",
                          reply_markup=_reply_kb([["Пропустить"], [BTN_CANCEL]]))


