@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "-смс"),
)
async def cmd_delete_message(message: Message):
    if not has_level(message.from_user.id, required_level("delete_message")):
        if get_level(message.from_user.id) > 0:
            await message.reply("⛔ Команда доступна только администраторам.")
        return

    parts = message.text.strip().split(maxsplit=1)
    count: Optional[int] = None
    if len(parts) > 1 and parts[1].strip().isdigit():
        count = int(parts[1].strip())

    # Режим "-смс N" — удалить N последних сообщений (включая саму команду),
    # без привязки к reply.
    if count is not None:
        if count < 1:
            await message.reply("⚠️ Число должно быть больше нуля.")
            return
        count = min(count, 100)  # предохранитель: за раз Bot API позволяет удалить максимум 100
        message_ids = list(range(message.message_id - count + 1, message.message_id + 1))
        try:
            await bot.delete_messages(chat_id=message.chat.id, message_ids=message_ids)
        except TelegramForbiddenError:
            await message.reply("⚠️ У бота недостаточно прав, чтобы удалять сообщения.")
            return
        except TelegramBadRequest as e:
            await message.reply(f"⚠️ Не удалось удалить сообщения: {e.message}")
            return
        await db.add_log(
            "delete_messages_bulk", chat_id=message.chat.id,
            actor_id=message.from_user.id, details=str(count),
        )
        return

    # Обычный режим — ответом на конкретное сообщение.
    if not message.reply_to_message:
        await message.reply(
            "Ответьте этой командой на сообщение, которое нужно удалить, "
            "либо укажите число, например <code>-смс 3</code> — удалить последние 3 сообщения."
        )
        return

    target_id = message.reply_to_message.from_user.id
    try:
        await message.reply_to_message.delete()
    except TelegramForbiddenError:
        await message.reply("⚠️ У бота недостаточно прав, чтобы удалять сообщения.")
        return
    except TelegramBadRequest as e:
        await message.reply(f"⚠️ Не удалось удалить сообщение: {e.message}")
        return

    try:
        await message.delete()  # удаляем и саму команду "-смс"
    except TelegramBadRequest:
        pass

    await db.add_log(
        "delete_message", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target_id
    )


MODERATION_PAGE_SIZE = 10


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "муты"),
)
async def cmd_list_mutes(message: Message):
    if not has_level(message.from_user.id, required_level("list_mutes")):
        if get_level(message.from_user.id) > 0:
            await message.reply("⛔ Команда доступна только администраторам.")
        return
    rows, total = await db.list_mutes(message.chat.id, limit=MODERATION_PAGE_SIZE)
    if not rows:
        await message.reply("🔇 Сейчас в этом чате никто не замучен.")
        return
    lines = []
    for row in rows:
        name = await display_name_by_id(message.chat.id, row["user_id"])
        until = row["muted_until"]
        if until:
            remaining = until - datetime.utcnow()
            remaining_text = f", осталось {format_duration_ru(remaining)}" if remaining.total_seconds() > 0 else ", истекает"
            until_text = f"до {fmt_dt(until)}{remaining_text}"
        else:
            until_text = "навсегда"
        reason_text = f" — {html.escape(row['reason'])}" if row["reason"] else ""
        lines.append(f"• {name} ({until_text}){reason_text}")
    more = f"\n\n…и ещё {total - len(rows)}" if total > len(rows) else ""
    await message.reply(f"🔇 <b>Муты в этом чате — {total}</b>\n\n" + "\n".join(lines) + more)


