# ============================================================================
# Модуль «Таймеры» (аналог модуля 25 у Iris) — отложенные действия.
# Команды модерации в этом боте требуют реплая на сообщение цели (а не
# ссылку на пользователя), поэтому «отложенно выполнить» их через таймер
# технически не имеет смысла — для них таймер просто отправит в чат текст,
# который вы указали при создании (напоминание/объявление от бота).
#
# НО для узкого набора команд без цели (см. TIMER_RUNNABLE_COMMANDS ниже —
# сейчас это «ферма» и её синонимы, «монеты»/«баланс», «топ монет») таймер
# умеет не просто напомнить текстом, а по-настоящему ВЫПОЛНИТЬ команду от
# имени того, кто поставил таймер, когда срок наступит — как будто человек
# сам написал её в чат. Если текст таймера (без учёта регистра, без лишних
# пробелов) совпадает с одной из этих фраз — сработает выполнение, иначе —
# как и раньше, обычное текстовое напоминание.
# ============================================================================
TIMER_MIN_DURATION = timedelta(minutes=1)
TIMER_MAX_DURATION = timedelta(days=366)
# Live-настройка из settings.timer_limit (см. WARN_LIMIT в начале файла).
_TIMER_LIMIT_DEFAULT = int(os.getenv("TIMER_LIMIT", "5"))  # активных таймеров одновременно на чат
TIMER_LIMIT = _TIMER_LIMIT_DEFAULT

_TIMER_THROUGH_RE = re.compile(r"(?is)^таймер\s+через\s+(\S+)\s*\n(.+)$")
_TIMER_AT_RE = re.compile(
    r"(?is)^таймер\s+на\s+(\d{1,2}\.\d{1,2}\.\d{2,4})(?:\s+(\d{1,2}:\d{2}))?\s*\n(.+)$"
)


def _timer_runnable_commands() -> dict[str, Callable[[int, int], Awaitable[str]]]:
    """Реестр команд, которые таймер умеет по-настоящему ВЫПОЛНИТЬ (а не просто
    напомнить текстом), собранный из уже существующих исполнителей команд —
    так список никогда не разойдётся с тем, что реально работает. Каждая
    команда — async функция (chat_id, user_id) -> текст результата. Годятся
    только команды без цели (не требующие reply на чьё-то сообщение)."""
    registry: dict[str, Callable[[int, int], Awaitable[str]]] = {}
    for trigger in FARM_TRIGGERS:
        registry[trigger] = _farm_execute
    for trigger in ("монеты", "баланс","мешок"):
        registry[trigger] = _farm_balance_text
    registry["топ монет"] = lambda chat_id, user_id: _farm_top_text(chat_id)
    return registry


# Строится один раз при старте (после того, как определены _farm_execute и
# т.п. выше по файлу) — см. использование в _fire_timer/_create_timer ниже.
TIMER_RUNNABLE_COMMANDS = _timer_runnable_commands()


def _timer_runnable_command(text: str) -> Optional[Callable[[int, int], Awaitable[str]]]:
    return TIMER_RUNNABLE_COMMANDS.get(text.strip().casefold())


async def _fire_timer(timer_id: int, chat_id: int, delay: float, text: str) -> None:
    """Ждёт указанное время, затем либо ВЫПОЛНЯЕТ команду (если текст таймера
    совпадает с одной из TIMER_RUNNABLE_COMMANDS), либо отправляет текст как
    обычное напоминание — если таймер к моменту срабатывания не был удалён
    вручную."""
    if delay > 0:
        await asyncio.sleep(delay)
    row = await db.get_timer(timer_id, chat_id)
    if row is None:
        return  # успели удалить командой «-Таймер» до срабатывания

    runnable = _timer_runnable_command(text)
    try:
        if runnable is not None:
            result = await runnable(chat_id, row["user_id"])
            author = mention_id(row["user_id"])
            await bot.send_message(
                chat_id,
                f"⏰ <b>Таймер выполнил команду «{html.escape(text.strip())}»</b> "
                f"(от имени {author})\n{DIVIDER}\n{result}",
            )
        else:
            await bot.send_message(chat_id, f"⏰ <b>Таймер сработал</b>\n{html.escape(text)}")
    except Exception:
        logger.exception("Не удалось обработать срабатывание таймера #%s", timer_id)
    await db.delete_timer(timer_id, chat_id)
    await db.add_log(
        "timer_fired" if runnable is None else "timer_fired_command",
        chat_id=chat_id, details=text[:100],
    )


async def _create_timer(message: Message, fire_at: datetime, text: str) -> None:
    text = text.strip()
    if not text:
        await message.reply("⚠️ Укажите текст таймера на новой строке после срока/даты.")
        return
    if len(text) > 3800:
        await message.reply("⚠️ Текст таймера слишком длинный (максимум 3800 символов).")
        return
    active = await db.count_timers(message.chat.id)
    if active >= TIMER_LIMIT:
        await message.reply(
            f"⚠️ Достигнут лимит одновременных таймеров в чате ({TIMER_LIMIT}). "
            "Удалите лишний командой «-Таймер номер» (список — командой «Таймеры»)."
        )
        return
    timer_id = await db.add_timer(message.chat.id, message.from_user.id, fire_at, text)
    delay = (fire_at - datetime.utcnow()).total_seconds()
    asyncio.create_task(_fire_timer(timer_id, message.chat.id, max(delay, 0), text))

    is_runnable = _timer_runnable_command(text) is not None
    action_line = (
        f"⚙️ По готовности сам выполнит команду «{html.escape(text[:300])}» от вашего имени"
        if is_runnable
        else f"📝 Текст: {html.escape(text[:300])}"
    )
    await message.reply(
        "⏰ <b>Таймер установлен</b>\n"
        "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"🆔 Номер: <code>{timer_id}</code>\n"
        f"📅 Сработает через: {format_duration_ru(fire_at - datetime.utcnow())} "
        f"({fmt_dt(fire_at)})\n"
        f"{action_line}"
    )
    await db.add_log(
        "timer_created", chat_id=message.chat.id, actor_id=message.from_user.id, details=text[:100]
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(_TIMER_THROUGH_RE.match(t.strip()))),
)
async def cmd_timer_through(message: Message):
    """«Таймер через {период}\n{текст}» — сработает через указанный период
    (от 1 минуты до 1 года: минуты/часы/дни/недели/месяцы)."""
    if not has_level(message.from_user.id, required_level("timer")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('timer'))}» и выше.")
        return
    match = _TIMER_THROUGH_RE.match(message.text.strip())
    period_token, text = match.group(1), match.group(2)
    duration = parse_duration(period_token)
    if duration is None:
        await message.reply(
            "⚠️ Не понял срок. Формат:\n<code>Таймер через 2ч\nТекст напоминания</code>\n"
            "Единицы: <b>м</b> — минуты, <b>ч</b> — часы, <b>д</b> — дни, "
            "<b>нед</b> — недели, <b>мес</b> — месяцы."
        )
        return
    if duration < TIMER_MIN_DURATION or duration > TIMER_MAX_DURATION:
        await message.reply("⚠️ Срок таймера должен быть от 1 минуты до 1 года.")
        return
    await _create_timer(message, datetime.utcnow() + duration, text)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(_TIMER_AT_RE.match(t.strip()))),
)
async def cmd_timer_at(message: Message):
    """«Таймер на {дд.мм.гг} [чч:мм]\n{текст}» — сработает в указанную дату/время (UTC)."""
    if not has_level(message.from_user.id, required_level("timer")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('timer'))}» и выше.")
        return
    match = _TIMER_AT_RE.match(message.text.strip())
    date_token, time_token, text = match.group(1), match.group(2), match.group(3)
    time_token = time_token or "00:00"
    day_str, month_str, year_str = date_token.split(".")
    if len(year_str) == 2:
        year_str = "20" + year_str
    try:
        fire_at = datetime.strptime(f"{day_str}.{month_str}.{year_str} {time_token}", "%d.%m.%Y %H:%M")
    except ValueError:
        await message.reply(
            "⚠️ Не понял дату. Формат:\n<code>Таймер на 25.12.26 18:00\nТекст напоминания</code>"
        )
        return
    now = datetime.utcnow()
    if fire_at <= now:
        await message.reply("⚠️ Указанное время уже в прошлом.")
        return
    if fire_at - now > TIMER_MAX_DURATION:
        await message.reply("⚠️ Таймер можно установить максимум на 1 год вперёд.")
        return
    await _create_timer(message, fire_at, text)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "таймеры"),
)
async def cmd_list_timers(message: Message):
    if not has_level(message.from_user.id, required_level("timer")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('timer'))}» и выше.")
        return
    rows = await db.list_timers(message.chat.id)
    if not rows:
        await message.reply("⏰ В этом чате сейчас нет активных таймеров.")
        return
    lines = []
    for row in rows:
        author = await display_name_by_id(message.chat.id, row["user_id"])
        fire_at: datetime = row["fire_at"]
        remaining = fire_at - datetime.utcnow()
        remaining_text = format_duration_ru(remaining) if remaining.total_seconds() > 0 else "вот-вот"
        is_runnable = _timer_runnable_command(row["text"]) is not None
        preview = f"⚙️ выполнит «{html.escape(row['text'][:60])}»" if is_runnable else html.escape(row["text"][:60])
        lines.append(
            f"• #{row['id']} — через {remaining_text} ({fmt_dt(fire_at)})\n"
            f"   👤 {author} — {preview}"
        )
    await message.reply(
        f"⏰ <b>Активные таймеры чата — {len(rows)}/{TIMER_LIMIT}</b>\n\n" + "\n".join(lines)
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "-таймер"),
)
async def cmd_delete_timer(message: Message):
    if not has_level(message.from_user.id, required_level("timer")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('timer'))}» и выше.")
        return
    parts = message.text.strip().split(maxsplit=1)
    if len(parts) < 2 or not parts[1].strip().isdigit():
        await message.reply("Использование: <code>-Таймер номер</code> (номер указан в списке команды «Таймеры»).")
        return
    timer_id = int(parts[1].strip())
    deleted = await db.delete_timer(timer_id, message.chat.id)
