# ============================================================================
# Выдача/снятие прав администратора прямо в чате (ответом на сообщение).
#   +модератор / +админ / +старший  — выдать уровень 1 / 2 / 3
#   -админ \ снять                  — снять права (любой уровень)
# Правило иерархии: выдать/снять можно только уровень СТРОГО ниже своего.
# Владелец (.env) может выдавать/снимать любой уровень.
# ============================================================================
def _is_grant_level_command(t: Optional[str]) -> bool:
    if not t or not t.strip().startswith("+"):
        return False
    parts = t.strip().casefold().lstrip("+").split()
    if not parts:
        return False
    return parts[0] in LEVEL_ALIASES


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_grant_level_command),
)
async def cmd_grant_level(message: Message):
    actor_id = message.from_user.id
    actor_level = get_level(actor_id)
    if actor_level < LEVEL_SENIOR:
        await message.reply("⛔ Выдавать права может старший администратор или владелец.")
        return

    word = message.text.strip().casefold().lstrip("+").split()[0]
    level = LEVEL_ALIASES[word]
    max_grantable = LEVEL_SENIOR if actor_level >= OWNER_LEVEL else actor_level - 1
    if level > max_grantable:
        await message.reply(f"⛔ Вы не можете выдать уровень выше своего ({level_name(max_grantable)}).")
        return

    target, _remaining = await resolve_command_target(message)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после команды."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.is_bot:
        await message.reply("Ботам права не нужны 🤖")
        return
    target_level = get_level(target.id)
    if target_level >= actor_level:
        await message.reply("Нельзя менять права администратора равного или более высокого уровня 🙂")
        return

    await db.set_admin(target.id, level, added_by=actor_id)
    admin_levels[target.id] = level
    await db.add_log("admin_added", chat_id=message.chat.id, actor_id=actor_id, target_id=target.id, details=level_name(level))

    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ {target_name} назначен(а): {level_name(level)}")
    try:
        await bot.send_message(target.id, f"🎉 Вам выданы права: {level_name(level)} (в чате {message.chat.title or message.chat.id}).")
    except Exception:
        pass


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() in ("-админ","снять")),
)
async def cmd_revoke_admin(message: Message):
    actor_id = message.from_user.id
    actor_level = get_level(actor_id)

    target, _remaining = await resolve_command_target(message)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после команды."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    target_level = get_level(target.id)

    if target_level == 0:
        await message.reply("Этот пользователь и так не администратор.")
        return
    if actor_level <= target_level:
        await message.reply("⛔ Снимать права можно только у админа уровнем ниже своего.")
        return

    await db.remove_admin(target.id)
    admin_levels.pop(target.id, None)
    await db.add_log("admin_removed", chat_id=message.chat.id, actor_id=actor_id, target_id=target.id)

    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ С {target_name} сняты права администратора.")


# ----------------------------------------------------------------------------
# «Повысить» / «Понизить» — сдвиг уровня прав на одну ступень (0 — участник,
# 1 — модератор, 2 — админ, 3 — старший), либо сразу на конкретный уровень,
# если он указан числом: «повысить 2», «понизить @user 1» и т.п.
# Права и иерархия — те же, что у +модератор/+админ/+старший и -админ выше:
# менять может только старший администратор/владелец, и только тех, чей
# уровень строго ниже своего, не выше своего максимума.
# ----------------------------------------------------------------------------
PROMOTE_LEVEL_WORDS = {"0": 0, "1": LEVEL_MODERATOR, "2": LEVEL_ADMIN, "3": LEVEL_SENIOR}


def _is_promote_demote_command(t: Optional[str]) -> bool:
    if not t or not t.strip():
        return False
    return (t.strip().casefold().split() or [""])[0] in ("повысить", "понизить")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_promote_demote_command),
)
async def cmd_promote_demote(message: Message):
    actor_id = message.from_user.id
    actor_level = get_level(actor_id)
    if actor_level < LEVEL_SENIOR:
        if actor_level > 0:
            await message.reply("⛔ Повышать/понижать права может только старший администратор или владелец.")
        return

    direction = (message.text.strip().casefold().split() or [""])[0]
    is_promote = direction == "повысить"

    # allow_bare_id=False: голое число после команды означает УРОВЕНЬ
    # («повысить 2»), а не ID цели — цель указывается только @username,
    # text_mention или reply.
    target, remaining = await resolve_command_target(message, allow_bare_id=False)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            f"Укажите цель: ответьте этой командой на сообщение нужного человека, "
            f"либо укажите @username сразу после «{direction}».\n"
            f"Можно сразу задать уровень: «{direction} 2» "
            "(0 — участник, 1 — модератор, 2 — админ, 3 — старший)."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.id == actor_id:
        await message.reply("Нельзя изменить уровень самому себе 🙂")
        return
    if target.is_bot:
        await message.reply("Ботам права не нужны 🤖")
        return

    target_level = get_level(target.id)
    if target_level >= actor_level and not is_owner(actor_id):
        await message.reply("Нельзя менять права администратора равного или более высокого уровня 🙂")
        return

    explicit_level = None
    for tok in remaining.strip().split():
        if tok in PROMOTE_LEVEL_WORDS:
            explicit_level = PROMOTE_LEVEL_WORDS[tok]
            break

    if explicit_level is not None:
        new_level = explicit_level
    else:
        new_level = target_level + (1 if is_promote else -1)
    new_level = max(0, min(new_level, LEVEL_SENIOR))

    if new_level == target_level:
        current_name = level_name(target_level) if target_level else "обычный пользователь"
        await message.reply(f"У этого пользователя уже такой уровень: {current_name}.")
        return

    max_grantable = LEVEL_SENIOR if actor_level >= OWNER_LEVEL else actor_level - 1
    if new_level > max_grantable:
        await message.reply(f"⛔ Вы не можете выдать уровень выше своего ({level_name(max_grantable)}).")
        return

    target_name = await display_name(message.chat.id, target)
    arrow = "⬆️" if new_level > target_level else "⬇️"

    if new_level == 0:
        await db.remove_admin(target.id)
        admin_levels.pop(target.id, None)
        await db.add_log(
            "admin_removed", chat_id=message.chat.id, actor_id=actor_id,
            target_id=target.id, details="понижен до участника",
        )
        await message.reply(f"{arrow} {target_name} понижен(а) до обычного участника.")
        return

    await db.set_admin(target.id, new_level, added_by=actor_id)
    admin_levels[target.id] = new_level
    await db.add_log(
        "admin_added", chat_id=message.chat.id, actor_id=actor_id,
        target_id=target.id, details=level_name(new_level),
    )
    await message.reply(f"{arrow} {target_name} теперь: {level_name(new_level)}")
    try:
        await bot.send_message(
            target.id,
            f"{'🎉' if new_level > target_level else 'ℹ️'} Ваш уровень прав в боте изменён: "
            f"{level_name(new_level)} (в чате {message.chat.title or message.chat.id}).",
        )
    except Exception:
        pass


# ============================================================================
# Интеграция с Telegram: выдача/снятие РЕАЛЬНОГО статуса администратора чата
# средствами самого Telegram (не путать с внутренними уровнями бота выше).
#   +тг админ [должность]  — назначить реальным админом (ответом на смс)
#   -тг админ               — снять реальный статус админа (ответом на смс)
#   тг админы                — показать текущих Telegram-администраторов чата
# Как у Iris: доступно только 3 уровню/владельцу; боту самому нужны права
# администратора с возможностью назначать других администраторов.
# ============================================================================
# Набор прав «обычного администратора» живёт в admin_holds.py — тем же набором
# панель назначает админов по умолчанию.
TG_ADMIN_RIGHTS = dict(
    admin_holds.DEFAULT_ADMIN_RIGHTS,
    can_post_messages=False,
    can_edit_messages=False,
)
ROLE_TAG_NO_RIGHTS = dict(
    is_anonymous=False, can_manage_chat=False, can_delete_messages=False,
    can_manage_video_chats=False, can_restrict_members=False, can_promote_members=False,
    can_change_info=False, can_invite_users=False, can_pin_messages=False,
    can_post_messages=False, can_edit_messages=False,
)

def _role_tag_flag_key(chat_id: int, user_id: int) -> str:
    return f"roletag:{chat_id}:{user_id}"

def _build_role_title(role_name: str, is_resting: bool) -> str:
    """custom_title: максимум 16 симв., эмодзи запрещены Telegram API —
    поэтому рест помечаем текстом, а не пальмой."""
    suffix = " рест" if is_resting else ""
    max_name_len = 16 - len(suffix)
    name = role_name[:max_name_len].rstrip()
    return f"{name}{suffix}"[:16]

async def sync_role_title(chat_id: int, user_id: int) -> None:
    """Приводит тег участника в соответствие с его ролью и статусом реста.
    Вызывать после любого назначения/снятия роли и после одобрения/снятия/
    истечения реста."""
    role = await db.get_user_role(chat_id, user_id)
    was_tagged = bool(await db.get_data(_role_tag_flag_key(chat_id, user_id)))

    if role is None:
        if was_tagged:
            try:
                await bot.promote_chat_member(chat_id, user_id, **ROLE_TAG_NO_RIGHTS)
            except (TelegramForbiddenError, TelegramBadRequest):
                pass
            await db.delete_data(_role_tag_flag_key(chat_id, user_id))
        return

    rest = await db.get_active_rest(chat_id, user_id)
    title = _build_role_title(role["name"], is_resting=bool(rest))

    try:
        member = await bot.get_chat_member(chat_id, user_id)
    except Exception as e:
        logger.warning("sync_role_title(%s, %s): get_chat_member failed: %s", chat_id, user_id, e)
        return

    if member.status == "administrator":
        # уже реальный админ (или уже помечен нами) — просто обновляем тег
        try:
            await bot.set_chat_administrator_custom_title(chat_id, user_id, title)
        except (TelegramForbiddenError, TelegramBadRequest) as e:
            logger.warning(
                "sync_role_title(%s, %s): set_chat_administrator_custom_title (already admin) failed: %s",
                chat_id, user_id, e,
            )
        return

    if member.status != "member":
        logger.info(
            "sync_role_title(%s, %s): пропущено, статус участника = %s", chat_id, user_id, member.status
        )
        return  # создателя/вышедшего/ограниченного не трогаем
    logger.info("sync_role_title(%s, %s): title=%r, member.status=%s", chat_id, user_id, title, member.status)
    try:
        await bot.promote_chat_member(chat_id, user_id, **ROLE_TAG_NO_RIGHTS)
        await bot.set_chat_administrator_custom_title(chat_id, user_id, title)
        await db.set_data(_role_tag_flag_key(chat_id, user_id), "1")
    except (TelegramForbiddenError, TelegramBadRequest) as e:
        logger.warning("sync_role_title(%s, %s): promote/set_custom_title failed: %s", chat_id, user_id, e)
    else:
        logger.info("sync_role_title(%s, %s): успешно установлен тег %r", chat_id, user_id, title)




def _is_tg_admin_grant_command(t: Optional[str]) -> bool:
    if not t:
        return False
    parts = t.strip().casefold().split()
    return len(parts) >= 2 and parts[0] == "+тг" and parts[1] == "админ"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_tg_admin_grant_command),
)
async def cmd_tg_admin_grant(message: Message):
    if not has_level(message.from_user.id, required_level("tg_admin_grant")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('tg_admin_grant'))}» и выше.")
        return

    # Триггер здесь — "+тг админ", то есть 2 слова, поэтому голый ID (если он
    # есть) ищем третьим словом, а не вторым.
    target, remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после «+тг админ»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return

    words = remaining.strip().split(maxsplit=2)
    position = words[2].strip() if len(words) > 2 else None
    if position and len(position) > 16:
        await message.reply("⚠️ Должность слишком длинная (максимум 16 символов).")
        return

    try:
        await bot.promote_chat_member(chat_id=message.chat.id, user_id=target.id, **TG_ADMIN_RIGHTS)
        if position:
            await bot.set_chat_administrator_custom_title(
                chat_id=message.chat.id, user_id=target.id, custom_title=position
            )
    except TelegramForbiddenError:
        await message.reply("⚠️ У бота недостаточно прав. Сделайте бота администратором с правом «Добавление новых администраторов».")
        return
    except TelegramBadRequest as e:
        await message.reply(f"⚠️ Не удалось назначить: {e.message}")
        return

    await db.add_log(
        "tg_admin_granted", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=position,
    )
    target_name = await display_name(message.chat.id, target)
    suffix = f" — «{html.escape(position)}»" if position else ""

    try:
        member = await bot.get_chat_member(message.chat.id, target.id)
    except Exception:
        member = None

    if member is not None and member.status == "administrator":
        await message.reply(
            f"✅ {target_name} назначен(а) администратором Telegram в этом чате{suffix}.\n{DIVIDER}\n"
            f"Ниже — тонкая настройка его прав (нажимайте, чтобы включить ✅ / выключить ❌):",
            reply_markup=_tg_rights_kb(target.id, member),
        )
    else:
        await message.reply(f"✅ {target_name} назначен(а) администратором Telegram в этом чате{suffix}.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[:2] == ["-тг", "админ"]),
)
async def cmd_tg_admin_revoke(message: Message):
    if not has_level(message.from_user.id, required_level("tg_admin_revoke")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('tg_admin_revoke'))}» и выше.")
        return

    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после «-тг админ»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    try:
        await bot.promote_chat_member(
            chat_id=message.chat.id, user_id=target.id,
            is_anonymous=False, can_manage_chat=False, can_delete_messages=False,
            can_manage_video_chats=False, can_restrict_members=False, can_promote_members=False,
            can_change_info=False, can_invite_users=False, can_pin_messages=False,
            can_post_messages=False, can_edit_messages=False,
        )
    except TelegramForbiddenError:
        await message.reply("⚠️ У бота недостаточно прав, либо этого администратора назначал не бот.")
        return
    except TelegramBadRequest as e:
        await message.reply(f"⚠️ Не удалось снять права: {e.message}")
        return

    await db.add_log("tg_admin_revoked", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target.id)
    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ С {target_name} сняты права администратора Telegram в этом чате.")


# ----------------------------------------------------------------------------
# «Тг права» — тонкая настройка прав уже назначенного Telegram-администратора
# через инлайн-кнопки (как «Тг права» у Iris). В отличие от +тг админ/-тг админ,
# которые выдают/снимают фиксированный набор прав, тут можно включать и
# выключать каждое право по отдельности: закрепы, удаление сообщений, мут/бан,
# приглашения, видеочаты, изменение инфы чата, назначение других админов,
# анонимность. Собственного хранилища не нужно — Telegram сам хранит текущие
# права администратора, панель просто читает и переключает их через
# get_chat_member/promote_chat_member.
# ----------------------------------------------------------------------------
# Сам список прав и логика их снятия/возврата живут в admin_holds.py — тот же
# код нужен веб-панели, а она работает отдельным процессом и импортировать
# bot.py не может.
TG_RIGHTS_FIELDS = admin_holds.TG_RIGHTS_FIELDS
TG_RIGHTS_FIELD_SET = admin_holds.TG_RIGHTS_FIELD_SET


# ----------------------------------------------------------------------------
# Модуль «Холды администраторов»: см. add_admin_hold в db.py. Снимает права
# администратора Telegram перед мутом/баном (Telegram не даёт ограничивать
# админов напрямую), запоминает их и возвращает позже — автоматически по
# истечении срока мута, либо вручную вместе со снятием мута/бана.
# ----------------------------------------------------------------------------
def _snapshot_admin_rights(member) -> dict:
    return admin_holds.snapshot_admin_rights(member)


async def _demote_admin(chat_id: int, user_id: int) -> bool:
    return await admin_holds.demote_admin(bot, chat_id, user_id)


async def _restore_admin_rights(chat_id: int, user_id: int, rights: dict, custom_title: Optional[str]) -> tuple[bool, bool]:
    return await admin_holds.restore_admin_rights(bot, chat_id, user_id, rights, custom_title)


async def _finish_admin_hold(chat_id: int, user_id: int, hold: dict, manual: bool) -> None:
    # Имя строим здесь: display_name_by_id знает про теги и настройки чата,
    # а общий модуль — нет (он подставит имя из known_users, если не передать).
    name = await display_name_by_id(chat_id, user_id)
    await admin_holds.finish_admin_hold(bot, chat_id, user_id, hold, manual=manual, name=name)


async def _auto_restore_admin_hold(chat_id: int, user_id: int, expected_until_iso: str) -> None:
    """Фоновая задача: ждёт истечения срока мута и возвращает права. Если холд
    к этому моменту уже сняли вручную или пересоздали с другим сроком — ничего
    не делает (проверяет, что until в БД совпадает с ожидаемым)."""
    until_dt = datetime.fromisoformat(expected_until_iso)
    delay = (until_dt - datetime.utcnow()).total_seconds()
    if delay > 0:
        await asyncio.sleep(delay)

    hold = await db.get_admin_hold(chat_id, user_id)
    if not hold:
        return
    hold_until = hold.get("until")
    # ВАЖНО: колонка `until` в БД — DATETIME без дробных секунд, а until_dt в
    # Python почти всегда содержит микросекунды (datetime.utcnow()). MySQL
    # обрезает микросекунды при записи, поэтому сравнение строк isoformat()
    # почти никогда не совпадало и функция всегда выходила досрочно, так и не
    # восстанавливая права. Сравниваем с точностью до секунды.
    if hold_until is None or hold_until.replace(microsecond=0) != until_dt.replace(microsecond=0):
        return

    await _finish_admin_hold(chat_id, user_id, hold, manual=False)


async def _auto_unmute(chat_id: int, user_id: int, expected_until_iso: str) -> None:
    """Фоновая задача: сама снимает мут по истечении срока, не полагаясь на
    автоматическое снятие ограничения Telegram по until_date (та же схема,
    что и у _auto_unlock_chat/_auto_restore_admin_hold)."""
    until_dt = datetime.fromisoformat(expected_until_iso)
    delay = (until_dt - datetime.utcnow()).total_seconds()
    if delay > 0:
        await asyncio.sleep(delay)

    mute = await db.get_mute(chat_id, user_id)
    if not mute:
        return  # уже сняли вручную
    mute_until = mute.get("muted_until")
    if mute_until is None or mute_until.replace(microsecond=0) != until_dt.replace(microsecond=0):
        return  # мут успели переустановить с другим сроком

    try:
        await bot.restrict_chat_member(chat_id=chat_id, user_id=user_id, permissions=UNMUTE_PERMISSIONS)
    except (TelegramForbiddenError, TelegramBadRequest):
        pass

    await db.remove_mute(chat_id, user_id)
    try:
        name = await display_name_by_id(chat_id, user_id)
        await bot.send_message(chat_id, f"🔊 Мут {name} истёк — снят автоматически.")
    except Exception:
        pass
    await db.add_log("unmute", chat_id=chat_id, target_id=user_id, details="авто (истёк срок)")



async def _start_admin_action_confirm(
    message: Message, target, action_type: str,
    until: Optional[datetime], duration: Optional[timedelta], reason: Optional[str],
) -> None:
    """Мут/бан нацелен на действующего администратора Telegram — напрямую это
    не сработает (ограничение самого Telegram). Показываем подтверждение:
    бот снимет права, выполнит мут/бан и вернёт права позже."""
    if not has_level(message.from_user.id, required_level("tg_admin_revoke")):
        if get_level(message.from_user.id) > 0:
            await message.reply(
                f"⛔ Этот человек — администратор Telegram. Чтобы "
                f"{'замутить' if action_type == 'mute' else 'забанить'} его, нужен уровень "
                f"«{level_name(required_level('tg_admin_revoke'))}» и выше (снятие тг-прав)."
            )
        return

    target_name = await display_name(message.chat.id, target)
    action_word = "замутить" if action_type == "mute" else "забанить"
    pending_confirmations[message.from_user.id] = {
        "action": "admin_action",
        "action_type": action_type,
        "chat_id": message.chat.id,
        "target_id": target.id,
        "until": until.isoformat() if until else None,
        "duration_seconds": duration.total_seconds() if duration else None,
        "reason": reason,
    }
    kb = confirm_kb(
        yes_data=f"adminact_yes:{message.from_user.id}",
        no_data=f"adminact_no:{message.from_user.id}",
        yes_text=f"✅ Да, снять права и {action_word}",
    )
    restore_line = (
        f"Права вернутся автоматически через {format_duration_ru(duration)}." if duration
        else f"Права вернутся, когда вы снимете {'мут' if action_type == 'mute' else 'бан'} вручную."
    )
    await message.reply(
        confirm_text(
            f"{target_name} — администратор Telegram",
            [f"Чтобы {action_word} этого человека, бот временно снимет с него права администратора.", restore_line],
            irreversible=False,
        ),
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("adminact_yes:"))
async def confirm_admin_action(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return

    payload = pending_confirmations.pop(initiator_id, None)
    if not payload or payload.get("action") != "admin_action":
        await callback.answer("Запрос устарел, попробуйте снова.", show_alert=True)
        return

    action_type = payload["action_type"]
    required_key = "mute" if action_type == "mute" else "ban"
    if not has_level(initiator_id, required_level(required_key)) or not has_level(initiator_id, required_level("tg_admin_revoke")):
        await callback.answer("⛔ Недостаточно прав.", show_alert=True)
        return

    chat_id = payload["chat_id"]
    target_id = payload["target_id"]
    reason = payload.get("reason")
    until = datetime.fromisoformat(payload["until"]) if payload.get("until") else None
    duration_seconds = payload.get("duration_seconds")

    try:
        member = await bot.get_chat_member(chat_id, target_id)
    except Exception as e:
        await callback.message.edit_text(f"⚠️ Не удалось проверить участника: {e}")
        await callback.answer()
        return
    if member.status != "administrator":
        await callback.message.edit_text("Пользователь больше не администратор Telegram — попробуйте команду заново.")
        await callback.answer()
        return

    rights = _snapshot_admin_rights(member)
    custom_title = getattr(member, "custom_title", None)

    if not await _demote_admin(chat_id, target_id):
        await callback.message.edit_text(
            "⚠️ Не удалось снять права администратора (возможно, его назначал не бот). Действие отменено."
        )
        await callback.answer()
        return

    if action_type == "mute":
        try:
            await bot.restrict_chat_member(
                chat_id=chat_id, user_id=target_id, permissions=MUTE_PERMISSIONS, until_date=until,
            )
        except (TelegramForbiddenError, TelegramBadRequest) as e:
            await _restore_admin_rights(chat_id, target_id, rights, custom_title)
            await callback.message.edit_text(f"⚠️ Не удалось замутить: {e}. Права администратора возвращены.")
            await callback.answer()
            return
        await db.add_mute(chat_id, target_id, initiator_id, until, reason)
    else:
        try:
            await bot.ban_chat_member(chat_id=chat_id, user_id=target_id)
        except (TelegramForbiddenError, TelegramBadRequest) as e:
            await _restore_admin_rights(chat_id, target_id, rights, custom_title)
            await callback.message.edit_text(f"⚠️ Не удалось забанить: {e}. Права администратора возвращены.")
            await callback.answer()
            return
        await db.add_ban(chat_id, target_id, initiator_id, reason)
        await db.remove_mute(chat_id, target_id)

    await db.add_admin_hold(
        chat_id, target_id, initiator_id, action_type,
        json.dumps(rights), custom_title, until, reason,
    )

    actor_name = await display_name_by_id(chat_id, initiator_id)
    target_name = await display_name_by_id(chat_id, target_id)
    reason_text = html.escape(reason) if reason else "не указана"
    if action_type == "mute":
        until_text = (
            f"{format_duration_ru(timedelta(seconds=duration_seconds))} (до {fmt_dt(until)})"
            if until else "навсегда"
        )
        card = (
            f"🔇 <b>Мут выдан</b>\n{DIVIDER}\n"
            f"👤 Кто: {actor_name}\n🎯 Кому: {target_name}\n⏳ Срок: {until_text}\n📝 Причина: {reason_text}\n\n"
            "⚠️ У пользователя временно сняты права администратора."
        )
    else:
        card = (
            f"🔨 <b>Бан выдан</b>\n{DIVIDER}\n"
            f"👤 Кто: {actor_name}\n🎯 Кому: {target_name}\n📝 Причина: {reason_text}\n\n"
            "⚠️ У пользователя сняты права администратора."
        )
    try:
        await callback.message.edit_text(card)
    except TelegramBadRequest:
        pass

    await db.add_log(f"admin_{action_type}", chat_id=chat_id, actor_id=initiator_id, target_id=target_id, details=reason)
    await callback.answer("Готово ✅")

    try:
        if action_type == "mute":
            dm_text = "🔇 В группе с вас сняты права администратора и выдан мут" + (
                f" на {format_duration_ru(timedelta(seconds=duration_seconds))}." if until else " (бессрочно)."
            )
        else:
            dm_text = "🔨 В группе с вас сняты права администратора, и вы были забанены."
        await bot.send_message(target_id, dm_text)
    except Exception:
        pass

    if until is not None:
        asyncio.create_task(_auto_restore_admin_hold(chat_id, target_id, until.isoformat()))


@router.callback_query(F.data.startswith("adminact_no:"))
async def cancel_admin_action(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id and not is_admin(callback.from_user.id):
        await callback.answer("Это не ваша кнопка 🙂", show_alert=True)
        return
    pending_confirmations.pop(initiator_id, None)
    try:
        await callback.message.edit_text("Отменено.")
    except TelegramBadRequest:
        pass
    await callback.answer()


def _tg_rights_kb(target_id: int, member) -> InlineKeyboardMarkup:
    buttons = [
        InlineKeyboardButton(
            text=f"{'✅' if getattr(member, field, False) else '❌'} {label}",
            callback_data=f"tgpriv:{target_id}:{field}",
        )
        for field, label in TG_RIGHTS_FIELDS
    ]
    rows = [buttons[i:i + 2] for i in range(0, len(buttons), 2)]
    rows.append([InlineKeyboardButton(text="✅ Готово", callback_data=f"tgprivclose:{target_id}")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[:2] in (["тг", "права"], ["тг", "право"])),
)
async def cmd_tg_rights_open(message: Message):
    if not has_level(message.from_user.id, required_level("tg_admin_rights")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('tg_admin_rights'))}» и выше.")
        return

    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после «тг права»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.is_bot:
        await message.reply("У ботов нет настраиваемых прав через эту команду.")
        return

    try:
        member = await bot.get_chat_member(message.chat.id, target.id)
    except Exception as e:
        await message.reply(f"⚠️ Не удалось получить информацию об участнике: {e}")
        return

    if member.status == "creator":
        await message.reply("У создателя чата все права по умолчанию, изменить их через бота нельзя.")
        return
    if member.status != "administrator":
        await message.reply("Этот пользователь не является администратором Telegram в этом чате. Сначала выдайте права: «+тг админ» (ответом на его сообщение).")
        return

    target_name = await display_name(message.chat.id, target)
    await message.reply(
        f"📡 <b>Права администратора {target_name}</b>\n{DIVIDER}\n"
        f"Нажимайте на кнопки, чтобы включить (✅) или выключить (❌) конкретное право.",
        reply_markup=_tg_rights_kb(target.id, member),
    )


@router.callback_query(F.data.startswith("tgpriv:"))
async def toggle_tg_right(callback: CallbackQuery):
    if not has_level(callback.from_user.id, required_level("tg_admin_rights")):
        await callback.answer("⛔ Недостаточно прав.", show_alert=True)
        return

    try:
        _, target_id_s, field = callback.data.split(":", 2)
        target_id = int(target_id_s)
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if field not in TG_RIGHTS_FIELD_SET:
        await callback.answer()
        return

    chat_id = callback.message.chat.id
    try:
        member = await bot.get_chat_member(chat_id, target_id)
    except Exception as e:
        await callback.answer(f"Ошибка: {e}", show_alert=True)
        return
    if member.status != "administrator":
        await callback.answer("Пользователь больше не администратор Telegram в этом чате.", show_alert=True)
        try:
            await callback.message.edit_text("Пользователь больше не администратор Telegram в этом чате.")
        except TelegramBadRequest:
            pass
        return

    new_rights = {f: getattr(member, f, False) for f, _ in TG_RIGHTS_FIELDS}
    new_rights[field] = not new_rights[field]

    try:
        # Telegram сбрасывает в False любое булево право, которое не передано
        # явно в promote_chat_member, поэтому передаём вообще все поля.
        await bot.promote_chat_member(
            chat_id=chat_id, user_id=target_id,
            can_post_messages=False, can_edit_messages=False,
            **new_rights,
        )
    except TelegramForbiddenError:
        await callback.answer("⚠️ Недостаточно прав у бота, либо этого администратора назначал не бот.", show_alert=True)
        return
    except TelegramBadRequest as e:
        await callback.answer(f"⚠️ {e.message}", show_alert=True)
        return

    await db.add_log(
        "tg_admin_right_toggled", chat_id=chat_id, actor_id=callback.from_user.id,
        target_id=target_id, details=f"{field}={new_rights[field]}",
    )

    try:
        member = await bot.get_chat_member(chat_id, target_id)
        await callback.message.edit_reply_markup(reply_markup=_tg_rights_kb(target_id, member))
    except TelegramBadRequest:
        pass
    await callback.answer("Обновлено ✅")


@router.callback_query(F.data.startswith("tgprivclose:"))
async def close_tg_rights(callback: CallbackQuery):
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except TelegramBadRequest:
        pass
    await callback.answer("Готово")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("тг админы", "тг админ")),
)
async def cmd_tg_admins_list(message: Message):
    try:
        members = await bot.get_chat_administrators(message.chat.id)
    except Exception as e:
        await message.reply(f"⚠️ Не удалось получить список: {e}")
        return

    lines = ["📡 <b>Администраторы Telegram в этом чате</b>", DIVIDER]
    for member in members:
        user = member.user
        if user.is_bot:
            continue
        escaped = html.escape(user.full_name or str(user.id))
        name = f'<a href="tg://user?id={user.id}">{escaped}</a>'
        icon = "🔱" if member.status == "creator" else "⭐"
        title = getattr(member, "custom_title", None)
        title_text = f" — <i>{html.escape(title)}</i>" if title else ""
        lines.append(f"{icon} {name}{title_text}")
    await message.reply("\n".join(lines))


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("права", "админы", "кто админ", "ктоадмин")),
)
async def cmd_rights(message: Message):
    if message.text.strip().casefold() == "права" and message.reply_to_message:
        target = message.reply_to_message.from_user
        lvl = get_level(target.id)
        name = await display_name(message.chat.id, target) if message.chat.type != "private" else str(target.id)
        await message.reply(f"👤 {name}: {level_name(lvl) if lvl else 'обычный пользователь'}")
        return
    if message.text.strip().casefold() == "права":
        lvl = get_level(message.from_user.id)
        await message.reply(f"Ваш уровень прав: {level_name(lvl) if lvl else 'обычный пользователь'}")
        return
    # "админы" / "кто админ" — полный список
    if not admin_levels and not OWNER_IDS:
        await message.reply("Администраторов пока нет.")
        return
    await message.reply(await admins_list_text(message.from_user.id))


# ============================================================================
# «застрелится» — человек добровольно покидает чат через бота: команда с
# ДВОЙНЫМ подтверждением (чтобы случайное сообщение/тап не сработало), после
# чего бот снимает с человека права администратора (если они были — и
# внутренние уровни бота, и реальный статус администратора Telegram, в
# пределах своих прав), банит его в чате и сообщает об этом. Действие — только
# над самим собой, целиться в другого нельзя.
# ============================================================================
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "застрелится"),
)
async def cmd_self_destruct(message: Message):
    user_id = message.from_user.id
    pending_confirmations[user_id] = {
        "action": "self_destruct_1",
        "chat_id": message.chat.id,
    }
    kb = confirm_kb(
        yes_data=f"selfdestruct1_yes:{user_id}",
        no_data=f"selfdestruct_no:{user_id}",
        yes_text="💥 Да, уверен(а)",
    )
    await message.reply(
        confirm_text(
            "застрелится",
            ["Вы уверены, что хотите покинуть этот чат навсегда?"],
        ),
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("selfdestruct1_yes:"))
async def confirm_self_destruct_step1(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return

    payload = pending_confirmations.get(initiator_id)
    if not payload or payload.get("action") != "self_destruct_1":
        await callback.answer("Запрос устарел, попробуйте снова.", show_alert=True)
        return

    pending_confirmations[initiator_id] = {
        "action": "self_destruct_2",
        "chat_id": payload["chat_id"],
    }
    kb = confirm_kb(
        yes_data=f"selfdestruct2_yes:{initiator_id}",
        no_data=f"selfdestruct_no:{initiator_id}",
        yes_text="💥 Да, точно уверен(а)",
    )
    try:
        await callback.message.edit_text(
            confirm_text(
                "Последнее подтверждение",
                ["Обратного пути не будет: вас удалят из чата прямо сейчас."],
            ),
            reply_markup=kb,
        )
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("selfdestruct2_yes:"))
async def confirm_self_destruct_step2(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return

    payload = pending_confirmations.pop(initiator_id, None)
    if not payload or payload.get("action") != "self_destruct_2":
        await callback.answer("Запрос устарел, попробуйте снова.", show_alert=True)
        return

    chat_id = payload["chat_id"]
    user_name = await display_name_by_id(chat_id, initiator_id)

    # Снимаем реальный статус администратора Telegram, если он есть у бота
    # достаточно прав это сделать (у создателя группы отобрать права нельзя —
    # это ограничение самого Telegram, не бота).
    try:
        member = await bot.get_chat_member(chat_id, initiator_id)
    except Exception:
        member = None
    if member is not None and member.status == "administrator":
        try:
            await bot.promote_chat_member(
                chat_id,
                initiator_id,
                can_manage_chat=False,
                can_delete_messages=False,
                can_manage_video_chats=False,
                can_restrict_members=False,
                can_promote_members=False,
                can_change_info=False,
                can_invite_users=False,
                can_pin_messages=False,
            )
        except Exception:
            pass

    # Снимаем внутренние права бота (уровень админа в БД), если были.
    if get_level(initiator_id) > 0 and not is_owner(initiator_id):
        await db.remove_admin(initiator_id)
        admin_levels.pop(initiator_id, None)

    ban_ok = True
    try:
        await bot.ban_chat_member(chat_id, initiator_id)
    except (TelegramForbiddenError, TelegramBadRequest):
        ban_ok = False

    if ban_ok:
        try:
            await callback.message.edit_text(f"💥 {user_name} нажал(а) на кнопку и самоликвидировался(лась). Прощай! 👋")
        except TelegramBadRequest:
            pass
    else:
        try:
            await callback.message.edit_text(
                f"💥 {user_name} снят(а) с прав, но удалить из чата автоматически не удалось "
                "(например, если это создатель группы) — выйдите вручную."
            )
        except TelegramBadRequest:
            pass
    await callback.answer()

    await db.add_log("self_destruct", chat_id=chat_id, actor_id=initiator_id)


@router.callback_query(F.data.startswith("selfdestruct_no:"))
async def cancel_self_destruct(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Это не ваша кнопка 🙂", show_alert=True)
        return
    pending_confirmations.pop(initiator_id, None)
    try:
        await callback.message.edit_text("Отменено — вы остаётесь в чате 🙂")
    except TelegramBadRequest:
        pass
    await callback.answer()



# ============================================================================
# Дерево команд: показать все команды бота, их слово-триггер и текущий
# требуемый уровень прав («команды»), и изменить его («право ID уровень»).
# Оформление — как у Iris: категории разворачиваются по кнопке, у каждой
# команды — короткий числовой ID вместо текстового ключа, список каждой
# категории при необходимости разбивается на страницы, чтобы не упереться в
# лимит Telegram на длину сообщения (4096 символов).
# ============================================================================
CATEGORY_EMOJI = {
    "Общее": "📋",
    "ДК": "🌳",
    "Статистика": "📊",
    "РП": "💞",
    "Модерация": "🛡",
    "Награды": "🏅",
    "Права": "👑",
    "БД": "🗄",
    "Настройка": "⚙️",
    "Созывы": "📣",
    "Разное": "🎲",
    "Экономика": "💰",
}

LEVEL_EMOJI = {
    0: "✅",
    LEVEL_MODERATOR: "1️⃣",
    LEVEL_ADMIN: "2️⃣",
    LEVEL_SENIOR: "3️⃣",
}

# Безопасный запас под лимит подписи/сообщения Telegram (4096 симв.) — с
# учётом заголовка и подвала страницы категории.
CMD_TREE_PAGE_CHAR_LIMIT = 3200


def _level_emoji(level: int) -> str:
    return LEVEL_EMOJI.get(level, "👑")


def _commands_by_category() -> dict[str, list[tuple[str, dict]]]:
    by_category: dict[str, list[tuple[str, dict]]] = {}
    for key, entry in COMMAND_REGISTRY.items():
        by_category.setdefault(entry["category"], []).append((key, entry))
    return by_category


def _paginate_lines(lines: list[str], limit: int = CMD_TREE_PAGE_CHAR_LIMIT) -> list[list[str]]:
    """Режет список строк на страницы так, чтобы суммарная длина каждой
    страницы не превышала `limit` — не по количеству строк, а по факту
    итоговой длины сообщения (важно для очень длинных фраз команд)."""
    pages: list[list[str]] = []
    current: list[str] = []
    current_len = 0
    for line in lines:
        line_len = len(line) + 1
        if current and current_len + line_len > limit:
            pages.append(current)
            current, current_len = [], 0
        current.append(line)
        current_len += line_len
    pages.append(current)
    return pages


def cmd_tree_root_text() -> str:
    by_category = _commands_by_category()
    lines = [
        "🗓 <b>Дерево команд бота</b>",
        "✅ всем · 1️⃣ модератор · 2️⃣ админ · 3️⃣ старший · 🔒 фиксировано",
        DIVIDER,
        "",
        "Выберите раздел ниже, чтобы посмотреть его команды и их ID.",
    ]
    for category in CATEGORY_ORDER:
        entries = by_category.get(category)
        if not entries:
            continue
        emoji = CATEGORY_EMOJI.get(category, "📁")
        lines.append(f"▶️ {emoji} <b>{category}</b> — {len(entries)}")
    return "\n".join(lines)


def cmd_tree_root_kb() -> InlineKeyboardMarkup:
    by_category = _commands_by_category()
    buttons = [
        InlineKeyboardButton(
            text=f"{CATEGORY_EMOJI.get(category, '📁')} {category} ({len(by_category[category])})",
            callback_data=f"cmdtree_cat:{category}:0",
        )
        for category in CATEGORY_ORDER
        if by_category.get(category)
    ]
    rows = [buttons[i:i + 2] for i in range(0, len(buttons), 2)]
    return InlineKeyboardMarkup(inline_keyboard=rows)


def cmd_tree_category_text_and_pages(category: str) -> list[list[str]]:
    by_category = _commands_by_category()
    entries = sorted(by_category.get(category, []), key=lambda kv: kv[1]["phrase"])
    body_lines = []
    for key, entry in entries:
        level = required_level(key)
        lock = " 🔒" if not entry.get("overridable", True) else ""
        body_lines.append(f"{_level_emoji(level)} {COMMAND_IDS[key]}. {entry['phrase']}{lock}")
    return _paginate_lines(body_lines)


def cmd_tree_category_message(category: str, page: int) -> tuple[str, InlineKeyboardMarkup]:
    emoji = CATEGORY_EMOJI.get(category, "📁")
    pages = cmd_tree_category_text_and_pages(category)
    total_pages = len(pages)
    page = max(0, min(page, total_pages - 1))

    lines = [f"🗓 Дерево раздела «{emoji} {category}»", DIVIDER, ""]
    lines.extend(pages[page])
    lines.append("")
    lines.append(DIVIDER)
    lines.append(
        "Изменить: <code>право ID уровень</code> (или <code>дк ID уровень</code>) — ID указан рядом с командой, "
        "уровни: 0 / 1 / 2 / 3 / сброс.\n"
        "Доступно от «Старшего администратора» и не выше своего уровня."
    )
    if total_pages > 1:
        lines.append(f"\nСтраница {page + 1}/{total_pages}")
    text = "\n".join(lines)

    nav_row = []
    if total_pages > 1:
        if page > 0:
            nav_row.append(InlineKeyboardButton(text="⬅️", callback_data=f"cmdtree_cat:{category}:{page - 1}"))
        nav_row.append(InlineKeyboardButton(text=f"{page + 1}/{total_pages}", callback_data="noop"))
        if page + 1 < total_pages:
            nav_row.append(InlineKeyboardButton(text="➡️", callback_data=f"cmdtree_cat:{category}:{page + 1}"))
    rows = [nav_row] if nav_row else []
    rows.append([InlineKeyboardButton(text="⬅️ Все разделы", callback_data="cmdtree_root")])
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("команды", "дерево команд", "дерево")),
)
async def cmd_tree(message: Message):
    await message.reply(cmd_tree_root_text(), reply_markup=cmd_tree_root_kb())


@router.callback_query(F.data == "cmdtree_root")
async def cmd_tree_show_root(callback: CallbackQuery):
    await callback.answer()
    try:
        await callback.message.edit_text(cmd_tree_root_text(), reply_markup=cmd_tree_root_kb())
    except TelegramBadRequest:
        pass


@router.callback_query(F.data.startswith("cmdtree_cat:"))
async def cmd_tree_show_category(callback: CallbackQuery):
    try:
        _, category, page_str = callback.data.split(":", maxsplit=2)
        page = int(page_str)
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if category not in CATEGORY_ORDER:
        await callback.answer("Раздел не найден.", show_alert=True)
        return
    await callback.answer()
    text, keyboard = cmd_tree_category_message(category, page)
    try:
        await callback.message.edit_text(text, reply_markup=keyboard)
    except TelegramBadRequest:
        pass


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] in ("право", "дк")),
)
async def cmd_set_permission(message: Message):
    if not has_level(message.from_user.id, LEVEL_SENIOR):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Настраивать права команд может только «{level_name(LEVEL_SENIOR)}» и выше.")
        return

    parts = message.text.strip().split()[1:]

    if parts and parts[0].casefold() == "степень":
        await _handle_reward_degree_permission(message, parts[1:])
        return

    if len(parts) < 2:
        await message.reply(
            "Использование: <code>право ID уровень</code> (или <code>дк ID уровень</code>)\n"
            "Уровни: <b>0</b> / <b>1</b> / <b>2</b> / <b>3</b> / <b>сброс</b>\n"
            "ID команды — цифра рядом с ней в списке «команды» (можно и текстовым ключом).\n"
            "Порог выдачи наград по степени — <code>право степень N уровень</code>.\n"
            "Например: <code>дк 9 2</code>"
        )
        return

    key_or_id, level_word = parts[0].casefold(), parts[1].casefold()
    if key_or_id.isdigit():
        key = COMMAND_ID_TO_KEY.get(int(key_or_id))
    else:
        key = key_or_id
    entry = COMMAND_REGISTRY.get(key) if key else None
    if entry is None:
        await message.reply(f"🔍 Команда с ID/ключом <code>{html.escape(key_or_id)}</code> не найдена. Список — словом «команды».")
        return
    if not entry.get("overridable", True):
        await message.reply("⛔ Уровень доступа этой команды зашит в логику прав и не может быть изменён.")
        return

    if level_word == "сброс":
        await db.reset_command_level(key)
        command_level_overrides.pop(key, None)
        default_text = level_name(entry["level"]) if entry["level"] else "доступно всем"
        await db.add_log("command_permission_reset", actor_id=message.from_user.id, details=key)
        await message.reply(f"✅ Уровень команды «{entry['phrase']}» сброшен на стандартный: {default_text}.")
        return

    if level_word not in PERMISSION_LEVEL_WORDS:
        await message.reply("⚠️ Не понял уровень. Варианты: 0 / 1 / 2 / 3 / сброс.")
        return

    new_level = PERMISSION_LEVEL_WORDS[level_word]
    actor_level = get_level(message.from_user.id)
    if actor_level < OWNER_LEVEL and new_level > actor_level:
        await message.reply("⛔ Нельзя выставить требование выше своего собственного уровня.")
        return

    await db.set_command_level(key, new_level, updated_by=message.from_user.id)
    command_level_overrides[key] = new_level
    await db.add_log("command_permission_set", actor_id=message.from_user.id, details=f"{key} -> {new_level}")
    level_text = level_name(new_level) if new_level else "доступно всем"
    await message.reply(f"✅ Теперь команда «{entry['phrase']}» требует уровень: {level_text}.")


# ============================================================================
# Награды (медали): 8 степеней (1 — низшая, 8 — высшая), выдаются модераторами
# по образцу модуля «Награды» бота Iris. Доступ к выдаче каждой степени
# ограничен уровнем модерации; порог переопределяем командой
# «право степень N уровень» (см. _handle_reward_degree_permission выше по коду,
# вызывается из cmd_set_permission) — аналогично command_level_overrides, но
# хранится отдельно (таблица reward_degree_levels, кэш reward_degree_level_overrides).
# ============================================================================
REWARD_DEGREE_EMOJI = {
    1: "🎗",
    2: "🥉",
    3: "🥈",
    4: "🥇",
    5: "🎖",
    6: "🏅",
    7: "🏆",
    8: "🏵",
}


def _default_reward_degree_level(degree: int) -> int:
    """Уровень доступа по умолчанию для выдачи награды степени degree, если нет override.

    1 — доступно всем, 2-3 — модератор, 4 — админ, 5 — старший админ, 6-8 — только владелец."""
    if degree == 1:
        return LEVEL_MEMBER
    if degree <= 3:
        return LEVEL_MODERATOR
    if degree == 4:
        return LEVEL_ADMIN
    if degree == 5:
        return LEVEL_SENIOR
    return OWNER_LEVEL


def required_reward_level(degree: int) -> int:
    """Требуемый уровень для выдачи награды данной степени: override из БД, иначе — по умолчанию."""
    return reward_degree_level_overrides.get(degree, _default_reward_degree_level(degree))


def reward_degree_emoji(degree: int) -> str:
    return REWARD_DEGREE_EMOJI.get(degree, "🏅")


_SUBSCRIPT_DIGITS = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")


def _subscript_number(n: int) -> str:
    return str(n).translate(_SUBSCRIPT_DIGITS)

async def _handle_reward_degree_permission(message: Message, args: list[str]) -> None:
    """Обрабатывает «право степень N уровень» — порог доступа для выдачи наград степени N."""
    if len(args) < 2:
        await message.reply(
            "Использование: <code>право степень N уровень</code>\n"
            "N — степень награды (1-8). Уровни: <b>модератор</b> / <b>админ</b> / <b>старший</b> / <b>сброс</b>.\n"
            "Например: <code>право степень 3 старший</code>"
        )
        return

    degree_token, level_word = args[0], args[1].casefold()
    if not degree_token.isdigit() or not (1 <= int(degree_token) <= 8):
        await message.reply("⚠️ Степень должна быть числом от 1 до 8.")
        return
    degree = int(degree_token)

    if level_word == "сброс":
        await db.reset_reward_degree_level(degree)
        reward_degree_level_overrides.pop(degree, None)
        default_text = level_name(_default_reward_degree_level(degree))
        await db.add_log("reward_degree_level_reset", actor_id=message.from_user.id, details=str(degree))
        await message.reply(
            f"✅ Порог для награды {reward_degree_emoji(degree)} степени {degree} "
            f"сброшен на стандартный: {default_text}."
        )
        return

    if level_word not in LEVEL_ALIASES:
        await message.reply("⚠️ Не понял уровень. Варианты: модератор / админ / старший / сброс.")
        return

    new_level = LEVEL_ALIASES[level_word]
    actor_level = get_level(message.from_user.id)
    if actor_level < OWNER_LEVEL and new_level > actor_level:
        await message.reply("⛔ Нельзя выставить требование выше своего собственного уровня.")
        return

    await db.set_reward_degree_level(degree, new_level, updated_by=message.from_user.id)
    reward_degree_level_overrides[degree] = new_level
    await db.add_log(
        "reward_degree_level_set", actor_id=message.from_user.id, details=f"{degree} -> {new_level}"
    )
    await message.reply(
        f"✅ Теперь награда {reward_degree_emoji(degree)} степени {degree} "
        f"требует уровень: {level_name(new_level)}."
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() in ("наградить", "!наградить")),
)
async def cmd_reward(message: Message):
    # allow_bare_id=False: число сразу после триггера — это степень награды
    # ("наградить 5"), а не ID цели, указать голым ID здесь нельзя в
    # принципе — только @username/text_mention/reply.
    target, remaining = await resolve_command_target(message, allow_bare_id=False)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username сразу после «наградить»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return

    lines = remaining.split("\n", 1)
    first_line_tokens = lines[0].strip().split()
    if len(first_line_tokens) < 2 or not first_line_tokens[1].isdigit() or not (1 <= int(first_line_tokens[1]) <= 8):
        try:
            first_line_tokens[1] = 1
        except:
            first_line_tokens.append(1)

        # await message.reply(
        #     "Использование: <code>наградить степень</code> (ответом на сообщение), "
        #     "степень — число от 1 до 8. Причину заслуги можно указать следующей строкой.\n"
        #     "Например:\n<code>наградить 5\nЗа помощь новичкам</code>"
        # )
        # return
    degree = int(first_line_tokens[1])
    reason = lines[1].strip() if len(lines) > 1 and lines[1].strip() else None

    if target.id == message.from_user.id:
        await message.reply("Нельзя наградить самого себя 🙂")
        return
    if target.is_bot:
        await message.reply("Ботов это не касается 🤖")
        return

    min_level = required_reward_level(degree)
    actor_level = get_level(message.from_user.id)
    if actor_level < min_level:
        max_available = 0
        for d in range(8, 0, -1):
            if actor_level >= required_reward_level(d):
                max_available = d
                break
        hint = (
            f"Вам доступна выдача наград до степени {reward_degree_emoji(max_available)} "
            f"{max_available} включительно."
            if max_available
            else "Вам пока недоступна выдача наград ни одной степени."
        )
        if actor_level > 0:
            await message.reply(
                f"⛔ Для награды {reward_degree_emoji(degree)} степени {degree} нужен уровень "
                f"«{level_name(min_level)}» и выше.\n{hint}"
            )
        return

    reward_id = await db.add_reward(message.chat.id, target.id, degree, reason, message.from_user.id)
    await db.add_log(
        "reward", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=f"degree={degree} id={reward_id}",
    )

    # actor_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    # reason_text = html.escape(reason) if reason else "не указана"
    emoji_degree = f"{reward_degree_emoji(degree)}{_subscript_number(degree)}"
    await message.reply(
        f"{emoji_degree} <b>Награда</b> {target_name} <b>вручена</b>\n"
        # f"👤 Выдал: {actor_name}\n"
        # f"📝 Заслуга: {reason_text}"
    )


REWARD_PAGE_SIZE = 10


async def reward_list_page(
    chat_id: int, user_id: int, page: int, requester_id: Optional[int] = None
) -> tuple[str, InlineKeyboardMarkup | None]:
    """requester_id задан только когда список открыт кнопкой «🏆 Награды» из
    карточки профиля — тогда под списком появляется «⬅️ Назад» к карточке,
    и пагинация использует отдельный префикс reward_profile_page, который
    несёт requester_id (чтобы «Назад» продолжал работать на любой странице).
    Без requester_id (обычная команда «награды») кнопки/страницы как раньше."""
    page = max(page, 0)
    rows = await db.list_rewards(chat_id, user_id)
    total = len(rows)
    name = await display_name_by_id(chat_id, user_id)
    back_row = (
        [InlineKeyboardButton(text="⬅️ Назад", callback_data=f"profile_back:{user_id}:{requester_id}")]
        if requester_id is not None
        else None
    )
    if not rows:
        text = f"🏅 У {name} пока нет наград."
        if back_row:
            return text, InlineKeyboardMarkup(inline_keyboard=[back_row])
        return text, None

    pages = (total + REWARD_PAGE_SIZE - 1) // REWARD_PAGE_SIZE
    if page >= pages:
        page = pages - 1
    start = page * REWARD_PAGE_SIZE
    page_rows = rows[start:start + REWARD_PAGE_SIZE]

    lines = [f"🏅 <b>Награды {name} — {total}</b>", DIVIDER]
    for index, row in enumerate(page_rows, start=start + 1):
        awarded_name = await display_name_by_id(chat_id, row["awarded_by"])
        when = fmt_date(row["created_at"])
        reason_text = f" — {html.escape(row['reason'])}" if row["reason"] else ""
        lines.append(
            f"{index}. {reward_degree_emoji(row['degree'])} степень {row['degree']}{reason_text}\n"
            f"    выдал: {awarded_name} · {when}"
        )
    text = "\n".join(lines)

    prefix = f"reward_profile_page:{user_id}:{requester_id}" if requester_id is not None else f"reward_page:{user_id}"
    rows_kb: list[list[InlineKeyboardButton]] = []
    if pages > 1:
        buttons = []
        if page > 0:
            buttons.append(InlineKeyboardButton(text="⬅️", callback_data=f"{prefix}:{page - 1}"))
        buttons.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
        if page + 1 < pages:
            buttons.append(InlineKeyboardButton(text="➡️", callback_data=f"{prefix}:{page + 1}"))
        rows_kb.append(buttons)
    if back_row:
        rows_kb.append(back_row)
    if not rows_kb:
        return text, None
    return text, InlineKeyboardMarkup(inline_keyboard=rows_kb)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("награды", "мои награды")),
)
async def cmd_rewards(message: Message):
    if message.text.strip().casefold() == "мои награды":
        target = message.from_user
    else:
        target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    if target.is_bot:
        await message.reply("У ботов наград не бывает 🤖")
        return

    text, keyboard = await reward_list_page(message.chat.id, target.id, 0)
    await message.reply(text, reply_markup=keyboard)


