@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("снять награду")),
)
async def cmd_reward_remove(message: Message):
    # allow_bare_id=False: следующее число в этой команде — номер награды
    # ("снять награду 3"), а не ID цели.
    target, remaining = await resolve_command_target(message, allow_bare_id=False)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username сразу после «снять награду»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return

    parts = remaining.strip().split()
    if len(parts) < 3 or not parts[2].isdigit():
        await message.reply(
            "Использование: <code>снять награду номер</code> (ответом на сообщение награждённого).\n"
            "Номер награды — из списка «награды»."
        )
        return
    number = int(parts[2])

    actor_level = get_level(message.from_user.id)
    required = required_level("reward_remove")
    removing_own = target.id == message.from_user.id
    if not removing_own and actor_level < required:
        await message.reply(f"⛔ Снимать чужие награды может только «{level_name(required)}» и выше.")
        return

    rows = await db.list_rewards(message.chat.id, target.id)
    if number < 1 or number > len(rows):
        await message.reply(f"⚠️ У этого пользователя нет награды под номером {number}. Список — «награды».")
        return

    reward = rows[number - 1]
    await db.remove_reward(reward["id"])
    await db.add_log(
        "reward_remove", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=f"degree={reward['degree']} id={reward['id']}",
    )

    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ Награда {reward_degree_emoji(reward['degree'])} №{number} снята у {target_name}.")


