def compute_streak(days: list) -> int:
    """Считает подряд идущие дни активности по списку дат (см. db.list_active_days,
    убывающих от сегодня назад). Отсчёт идёт от сегодня, если сегодня уже
    писали, иначе от вчера — чтобы не сбрасывать стрик тому, кто пока просто
    не успел написать сегодня."""
    if not days:
        return 0
    today = date.today()
    days_set = set(days)
    if today in days_set:
        cursor = today
    elif (today - timedelta(days=1)) in days_set:
        cursor = today - timedelta(days=1)
    else:
        return 0
    streak = 0
    while cursor in days_set:
        streak += 1
        cursor -= timedelta(days=1)
    return streak


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("стрик", "мой стрик", "стрик активности")),
)
async def cmd_streak(message: Message):
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    days = await db.list_active_days(message.chat.id, target.id)
    streak = compute_streak(days)
    name = await display_name(message.chat.id, target)
    if streak == 0:
        await message.reply(f"🔥 У {name} сейчас нет активного стрика — напишите сегодня, чтобы начать!")
        return
    await message.reply(f"🔥 Стрик активности {name}: <b>{streak}</b> дн. подряд")


STREAK_TOP_LIMIT = 10

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("топ стриков", "топ по стрику", "топ стрик")),
)
async def cmd_streak_top(message: Message):
    if not _check_misc_access(message.from_user.id, "streak_top"):
        return
    candidates = await db.list_recent_active_users(message.chat.id, limit=300)
    if not candidates:
        await message.reply("🔥 Пока ни у кого нет активного стрика.")
        return
    scored: list[tuple[int, dict]] = []
    for row in candidates:
        days = await db.list_active_days(message.chat.id, row["user_id"])
        streak = compute_streak(days)
        if streak > 0:
            scored.append((streak, row))
    if not scored:
        await message.reply("🔥 Пока ни у кого нет активного стрика.")
        return
    scored.sort(key=lambda x: -x[0])
    top = scored[:STREAK_TOP_LIMIT]
    medals = {0: "🥇", 1: "🥈", 2: "🥉"}
    lines = ["🔥 <b>Топ по стрикам</b>", DIVIDER]
    for i, (streak, row) in enumerate(top):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        place = medals.get(i, f"{i + 1}.")
        lines.append(f"{place} {name} — {streak} дн. подряд")
    await message.reply("\n".join(lines))

