NEW_MEMBERS_MAX_ROWS = 100  # предохранитель от гигантского списка в одном сообщении


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "нью"),
)
async def cmd_new_members(message: Message):
    """«нью {период}» — кто вступил в чат за последние {период} (по first_seen_at).
    Период в том же формате, что и везде в боте: «2д», «3ч», «1нед», «30м» и т.п.
    Без периода — по умолчанию сутки."""
    tokens = message.text.strip().split()[1:]
    duration = None
    period_text = "1д"
    if tokens:
        duration = parse_duration(tokens[0])
        if duration is not None:
            period_text = tokens[0]
        elif len(tokens) >= 2 and _LONE_NUMBER_RE.match(tokens[0]):
            # Раздельная запись вида «нью 3 дня»
            combined = parse_duration(tokens[0] + tokens[1])
            if combined is not None:
                duration = combined
                period_text = f"{tokens[0]} {tokens[1]}"
    if duration is None:
        duration = timedelta(days=1)

    since = datetime.utcnow() - duration
    rows = await db.list_new_members_since(message.chat.id, since, limit=NEW_MEMBERS_MAX_ROWS)

    title = f"🆕 <b>Вступили за последние {html.escape(period_text)}</b>"
    if not rows:
        await message.reply(f"{title}\n\nНикто не вступал за этот период.")
        return

    lines = [title, DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        seen: datetime = row["first_seen_at"]
        lines.append(f"{i}. {name} — {fmt_dt(seen)}")
    if len(rows) >= NEW_MEMBERS_MAX_ROWS:
        lines.append(f"\n… показаны первые {NEW_MEMBERS_MAX_ROWS}, возможно вступивших больше.")
    await message.reply("\n".join(lines))


# ---------- Ники чата: полный список и сброс ----------
NICK_PAGE_SIZE = 20


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "ники"),
)
async def cmd_nick_list(message: Message):
    parts = message.text.strip().split()
    page = 0
    if len(parts) > 1 and parts[1].isdigit():
        page = max(0, int(parts[1]) - 1)
    rows, total = await db.list_nicknames(message.chat.id, limit=NICK_PAGE_SIZE, offset=page * NICK_PAGE_SIZE)
    if not rows:
        await message.reply("✏️ В этом чате пока никто не установил себе ник (команда «+ник»).")
        return
    pages = (total + NICK_PAGE_SIZE - 1) // NICK_PAGE_SIZE
    lines = [f"✏️ <b>Ники чата</b> — {total} (стр. {page + 1}/{pages})", DIVIDER]
    lines.extend(f"• {mention_id(r['user_id'])} — {html.escape(r['nickname'])}" for r in rows)
    if pages > 1:
        lines.append(f"\nСледующая страница: <code>ники {page + 2}</code>")
    await message.reply("\n".join(lines))







@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split(maxsplit=1) or [""])[0].casefold() == "сетник"),
)
async def cmd_setnick(message: Message):
    """«сетник @username Ник» / «сетник Ник» (ответом на сообщение) —
    админ устанавливает ник ДРУГОМУ участнику. В отличие от «+ник», где
    цель всегда сам вызвавший, здесь цель обязательно кто-то другой:
    для себя по-прежнему используется «+ник»."""
    min_level = required_level("nick_set")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    target, remaining = await resolve_command_target(message)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Использование: <code>сетник @username Ник</code>, либо ответом на сообщение "
            "человека: <code>сетник Ник</code>."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.is_bot:
        await message.reply("Ботам ник не нужен 🤖")
        return

    # remaining может по-прежнему начинаться со слова-триггера «сетник»
    # (resolve_command_target вырезает только саму цель, а не сам триггер —
    # так же, как и в остальных командах бота, см. skip_words=1 у «варн»).
    rest_tokens = remaining.strip().split(maxsplit=1)
    if rest_tokens and rest_tokens[0].casefold() == "сетник":
        value = rest_tokens[1].strip() if len(rest_tokens) > 1 else ""
    else:
        value = remaining.strip()

    if not value:
        await message.reply("Укажите ник после цели, например: <code>сетник @username Крутыш</code>.")
        return
    if len(value) > 32:
        await message.reply("⚠️ Слишком длинный ник (максимум 32 символа).")
        return

    await db.set_nickname(message.chat.id, target.id, value)
    await db.add_log(
        "nickname_set", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=value,
    )
    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ Ник {target_name} в этом чате теперь: <b>{html.escape(value)}</b>")



@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "!сброс ников"),
)
async def cmd_nick_reset_all(message: Message):
    if not has_level(message.from_user.id, required_level("nick_reset_all")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('nick_reset_all'))}» и выше.")
        return
    kb = confirm_kb(
        yes_data=f"nickreset_yes:{message.from_user.id}",
        no_data=f"nickreset_no:{message.from_user.id}",
        yes_text="✅ Да, сбросить все ники",
    )
    await message.reply(
        confirm_text("Сбросить все ники в чате?", ["Все установленные никнеймы участников этого чата будут удалены."]),
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("nickreset_yes:"))
async def confirm_nick_reset_all(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return
    if not has_level(callback.from_user.id, required_level("nick_reset_all")):
        await callback.answer(f"⛔ Только «{level_name(required_level('nick_reset_all'))}» и выше может это сделать.", show_alert=True)
        return
    chat_id = callback.message.chat.id
    removed = await db.delete_all_nicknames(chat_id)
    await db.add_log("nickname_reset", chat_id=chat_id, actor_id=callback.from_user.id, details=f"все ({removed})")
    try:
        await callback.message.edit_text(f"🗑 <b>Готово</b>\nУдалено ников: {removed}.")
    except TelegramBadRequest:
        pass
    await callback.answer("Сброшено ✅")


@router.callback_query(F.data.startswith("nickreset_no:"))
async def cancel_nick_reset_all(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id and not is_admin(callback.from_user.id):
        await callback.answer("Это не ваша кнопка 🙂", show_alert=True)
        return
    try:
        await callback.message.edit_text("Отменено — ники не тронуты.")
    except TelegramBadRequest:
        pass
    await callback.answer()


# ---------- Неактивные участники и молчуны ----------
async def _inactive_silent_text(rows: list[dict], title: str, date_field: str) -> str:
    if not rows:
        return f"{title}\n\nТаких не нашлось 🎉"
    lines = [title, DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        ts: datetime = row[date_field]
        lines.append(f"{i}. {name} — {fmt_date(ts)}")
    return "\n".join(lines)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(
        lambda t: bool(t)
        and (t.strip().casefold().split(maxsplit=1) or [""])[0] in ("неактив", "кто", "список")
        and "неактив" in t.strip().casefold()
    ),
)
async def cmd_inactive_list(message: Message):
    if not has_level(message.from_user.id, required_level("inactive_list")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('inactive_list'))}» и выше.")
        return
    # Период — только если последний токен реально парсится как длительность.
    # Иначе (напр. «кто неактив» без времени) берём дефолтную неделю, а не ругаемся.
    tokens = message.text.strip().split()
    duration = parse_duration(tokens[-1]) if len(tokens) > 1 else None
    if duration is None:
        duration = timedelta(days=7)
    cutoff = datetime.utcnow() - duration
    rows = await db.list_inactive(message.chat.id, cutoff, limit=30)
    await message.reply(await _inactive_silent_text(rows, f"😴 <b>Неактивные с {fmt_date(cutoff)}</b>", "last_seen_at"))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(
        lambda t: bool(t)
        and (t.strip().casefold().split(maxsplit=1) or [""])[0] in ("молчун", "молчуны", "кто", "список")
        and "молчун" in t.strip().casefold()
    ),
)
async def cmd_silent_list(message: Message):
    if not has_level(message.from_user.id, required_level("inactive_list")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('inactive_list'))}» и выше.")
        return
    # Как и у неактива: нет валидного периода (напр. «кто молчун») → дефолтная неделя.
    tokens = message.text.strip().split()
    duration = parse_duration(tokens[-1]) if len(tokens) > 1 else None
    if duration is None:
        duration = timedelta(days=7)
    cutoff = datetime.utcnow() - duration
    rows = await db.list_silent(message.chat.id, cutoff, limit=30)
    await message.reply(
        await _inactive_silent_text(rows, f"🤐 <b>Молчуны, вступившие до {fmt_date(cutoff)}</b>", "first_seen_at")
    )


# ----------------------------------------------------------------------------
# Модуль «Норма»: еженедельная норма сообщений на участника, настраивается
# отдельно на каждый чат командой «+норма {число}» и снимается «-норма».
# «Не в норме» показывает, кто ещё не набрал нужное количество сообщений с
# начала текущей недели (суббота 00:00 UTC) — те же, кто в активном
# ресте, в список не попадают (см. db.list_below_norm), как и в «список
# неактив». Само число нормы хранится в общей таблице bot_data (см.
# db.set_data/get_data/delete_data) под ключом norm:{chat_id} — заводить
# отдельную таблицу под одно число не потребовалось.
# ----------------------------------------------------------------------------
def _norm_data_key(chat_id: int) -> str:
    return f"norm:{chat_id}"


async def get_chat_norm(chat_id: int) -> Optional[int]:
    row = await db.get_data(_norm_data_key(chat_id))
    if not row or row.get("data_value") is None:
        return None
    try:
        value = int(row["data_value"])
    except (TypeError, ValueError):
        return None
    return value if value > 0 else None


def _current_week_start():
    """Начало текущей недели — СУББОТА (UTC): от неё отсчитывается недельная
    норма (и чистка /clearUsers). Раньше неделя шла с понедельника — владелец
    попросил считать с субботы. weekday(): Пн=0…Сб=5, поэтому откатываемся к
    ближайшей прошедшей субботе через (weekday - 5) % 7."""
    today = datetime.utcnow().date()
    return today - timedelta(days=(today.weekday() - 5) % 7)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "+норма"),
)
async def cmd_set_norm(message: Message):
    if not has_level(message.from_user.id, required_level("set_norm")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('set_norm'))}» и выше.")
        return
    tokens = message.text.strip().split()
    if len(tokens) < 2 or not tokens[1].isdigit() or int(tokens[1]) <= 0:
        await message.reply("Укажите число сообщений в неделю, например: <code>+норма 100</code>.")
        return
    norm = int(tokens[1])
    await db.set_data(_norm_data_key(message.chat.id), str(norm), updated_by=message.from_user.id)
    await db.add_log("norm_set", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(norm))
    await message.reply(
        f"✅ Еженедельная норма установлена: <b>{norm}</b> сообщ./неделю.\n"
        "Проверить, кто не набрал — командой «не в норме». Снять норму — «-норма»."
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "-норма"),
)
async def cmd_unset_norm(message: Message):
    if not has_level(message.from_user.id, required_level("set_norm")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('set_norm'))}» и выше.")
        return
    removed = await db.delete_data(_norm_data_key(message.chat.id))
    if not removed:
        await message.reply("Норма в этом чате и так не была настроена.")
        return
    await db.add_log("norm_unset", chat_id=message.chat.id, actor_id=message.from_user.id)
    await message.reply("🗑 Еженедельная норма отключена.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ( "не в норме","вне нормы")),
)
async def cmd_norm_check(message: Message):
    if not has_level(message.from_user.id, required_level("norm_check")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('norm_check'))}» и выше.")
        return
    norm = await get_chat_norm(message.chat.id)
    if norm is None:
        await message.reply(
            "⚠️ Еженедельная норма ещё не настроена. Установите её командой «+норма 100» "
            "(вместо 100 — нужное число сообщений в неделю)."
        )
        return
    week_start = _current_week_start()
    rows = await db.list_below_norm(message.chat.id, week_start, norm, limit=200)
    if not rows:
        await message.reply(f"🎉 Все набрали норму ({norm} сообщ./неделю, с {fmt_date(week_start)}).")
        return
    lines = [
        f"📉 <b>Не в норме / Вне нормы</b> — норма {norm} сообщ./неделю, с {fmt_date(week_start)}",
        DIVIDER,
    ]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        lines.append(f"{i}. {name} — {int(row['message_count'])}/{norm}")
    await message.reply("\n".join(lines))


# ----------------------------------------------------------------------------
# Чистка «/clearUsers»: перманентный бан участников, не набравших недельную
# норму. Запускается ТОЛЬКО этой командой (без автопланировщика — по решению
# владельца) в чате, где настроена норма. Необратимо и массово, поэтому:
#   1) доступ — старший администратор и выше (clear_users, не понижается ДК);
#   2) обязательное подтверждение кнопкой (список пересчитывается на момент
#      подтверждения — вдруг кто-то дописал норму или уже вышел);
#   3) не трогаем наших админов/владельца и рестующих (их нет в выборке), а
#      также новичков — кто в чате меньше недели (list_below_norm_joined_before).
# Чат-админов Telegram бот забанить не сможет — их молча пропустит.
# ----------------------------------------------------------------------------
CLEANUP_BAN_DELAY = 0.1  # пауза между банами — не упираться в лимиты Telegram
CLEANUP_PREVIEW_LIMIT = 20


def _is_clear_users_command(text: Optional[str]) -> bool:
    if not text:
        return False
    first = (text.strip().split() or [""])[0].casefold()
    return first.split("@")[0] == "/clearusers"


async def _cleanup_candidates(chat_id: int, norm: int) -> list[dict]:
    """Кто под чистку: ниже нормы за текущую неделю, в чате дольше недели, не в
    ресте — и НЕ наш админ/владелец (их не баним, даже если молчали)."""
    week_start = _current_week_start()
    rows = await db.list_below_norm_joined_before(chat_id, week_start, norm, limit=1000)
    return [r for r in rows if not is_admin(r["user_id"])]


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_clear_users_command),
)
async def cmd_clear_users(message: Message):
    min_level = required_level("clear_users")
    if get_level(message.from_user.id) < min_level:
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    norm = await get_chat_norm(message.chat.id)
    if norm is None:
        await message.reply(
            "⚠️ В этом чате не настроена норма — чистить не по чему. "
            "Задайте её командой «+норма 100» (число сообщений в неделю)."
        )
        return

    candidates = await _cleanup_candidates(message.chat.id, norm)
    if not candidates:
        await message.reply(f"🎉 Чистить некого — все набрали норму ({norm} сообщ./неделю).")
        return

    week_start = _current_week_start()
    preview = []
    for row in candidates[:CLEANUP_PREVIEW_LIMIT]:
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        preview.append(f"• {name} — {int(row['message_count'])}/{norm}")
    more = len(candidates) - CLEANUP_PREVIEW_LIMIT
    if more > 0:
        preview.append(f"…и ещё {more}")

    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text=f"🧹 Забанить {len(candidates)}", callback_data=f"clearusers_go:{message.chat.id}"),
        InlineKeyboardButton(text="Отмена", callback_data="clearusers_cancel"),
    ]])
    await message.reply(
        f"🧹 <b>Чистка по норме</b> — {norm} сообщ./неделю, с {fmt_date(week_start)}.\n"
        f"Будет <b>перманентно забанено: {len(candidates)}</b> "
        "(админы, рестующие и новички не в счёт).\n"
        f"{DIVIDER}\n" + "\n".join(preview) + "\n\n"
        "⚠️ Действие необратимо. Подтвердите.",
        reply_markup=keyboard,
    )


@router.callback_query(F.data == "clearusers_cancel")
async def cb_clear_users_cancel(callback: CallbackQuery):
    if get_level(callback.from_user.id) < required_level("clear_users"):
        await callback.answer("Не для вас.", show_alert=True)
        return
    try:
        await callback.message.edit_text("🧹 Чистка отменена.")
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("clearusers_go:"))
async def cb_clear_users_go(callback: CallbackQuery):
    if get_level(callback.from_user.id) < required_level("clear_users"):
        await callback.answer("Команда доступна только старшим администраторам.", show_alert=True)
        return
    try:
        chat_id = int(callback.data.split(":", 1)[1])
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return

    norm = await get_chat_norm(chat_id)
    if norm is None:
        await callback.answer("Норма уже снята — чистка отменена.", show_alert=True)
        return

    # Пересчитываем на момент подтверждения — список мог измениться с показа.
    candidates = await _cleanup_candidates(chat_id, norm)
    await callback.answer()
    try:
        await callback.message.edit_text(f"🧹 Чистка запущена — кандидатов: {len(candidates)}…")
    except TelegramBadRequest:
        pass

    banned = skipped = 0
    for row in candidates:
        uid = row["user_id"]
        if is_admin(uid):  # ещё раз, на случай свежего повышения
            skipped += 1
            continue
        try:
            await bot.ban_chat_member(chat_id=chat_id, user_id=uid)
            await db.add_ban(chat_id, uid, callback.from_user.id, "чистка: не набрана недельная норма")
            await db.remove_mute(chat_id, uid)
            banned += 1
        except (TelegramForbiddenError, TelegramBadRequest):
            skipped += 1  # чат-админ Telegram, уже вышел и т.п.
        await asyncio.sleep(CLEANUP_BAN_DELAY)

    await db.add_log(
        "cleanup_run", chat_id=chat_id, actor_id=callback.from_user.id,
        details=f"norm={norm} banned={banned} skipped={skipped}",
    )
    try:
        await callback.message.edit_text(
            f"🧹 <b>Чистка завершена.</b>\nЗабанено: <b>{banned}</b>. "
            f"Пропущено (админы/ошибки): {skipped}."
        )
    except TelegramBadRequest:
        pass


# ----------------------------------------------------------------------------
# «Участники сообщения {период} {больше/меньше/равно} {число}» — гибкая
# выборка участников чата по количеству сообщений за неделю/месяц с любым
# сравнением. Обобщённый вариант «не в норме» (тот всегда «меньше нормы за
# неделю»). Отмечает через mention_id() — это ссылка (<a href=...>), а не
# текстовое @упоминание, поэтому людям НЕ прилетает уведомление/тег.
# ----------------------------------------------------------------------------
PARTICIPANTS_PERIODS = {
    "неделя": "week", "недели": "week", "неделю": "week",
    "месяц": "month", "месяца": "month",
}
PARTICIPANTS_METHODS = {
    "больше": ">", "меньше": "<", "равно": "=",
}
PARTICIPANTS_METHOD_LABELS = {">": "больше", "<": "меньше", "=": "равно"}
PARTICIPANTS_USAGE = (
    "Формат: <code>Участники сообщения {период} {больше/меньше/равно} {число}</code>\n"
    "Период — <b>неделя</b> или <b>месяц</b> (с начала текущей недели/месяца), либо\n"
    "произвольный срок в общем формате бота: <b>2дня</b>, <b>15часов</b>, <b>3нед</b>,\n"
    "<b>2 дня</b> (раздельно тоже работает) и т.п.\n"
    "Например: <code>Участники сообщения неделя меньше 10</code>, "
    "<code>Участники сообщения месяц больше 1000</code> или "
    "<code>Участники сообщения 15часов больше 5</code>"
)


def _participants_period_start(period: str):
    today = datetime.utcnow().date()
    if period == "month":
        return today.replace(day=1)
    return _current_week_start()


def _resolve_participants_period(text: str):
    """Разбирает период в «Участники сообщения {период} ...»: либо календарное
    слово («неделя»/«месяц» — с начала текущей недели/месяца, как раньше),
    либо произвольная длительность в общем формате бота («2дня», «15 часов»,
    «3нед» и т.п. — тот же parse_duration, что и у «нью»/«мут»/«бан»).

    Данные о сообщениях хранятся посуточно (message_daily), поэтому периоды
    короче суток всё равно округляются до текущих суток целиком — это предел
    точности имеющихся данных, а не искусственное ограничение здесь.

    Возвращает (since_day, period_label, число_токенов_под_период) или None,
    если период не распознан вообще."""
    tokens = text.strip().split()[2:]  # всё после «Участники сообщения»
    if not tokens:
        return None

    calendar_period = PARTICIPANTS_PERIODS.get(tokens[0].casefold())
    if calendar_period is not None:
        since_day = _participants_period_start(calendar_period)
        label_word = "неделю" if calendar_period == "week" else "месяц"
        label = f"за {label_word} (с {fmt_date(since_day)})"
        return since_day, label, 1

    duration, _rest = _extract_leading_duration(text, skip_words=2)
    if duration is None:
        return None
    consumed = 1 if parse_duration(tokens[0]) is not None else 2
    since_day = (datetime.utcnow() - duration).date()
    label = f"за последние {format_duration_ru(duration)} (с {fmt_date(since_day)})"
    return since_day, label, consumed


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "участники"),
)
async def cmd_participants(message: Message):
    if not has_level(message.from_user.id, required_level("participants")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('participants'))}» и выше.")
        return

    tokens = message.text.strip().split()
    if len(tokens) < 5 or tokens[1].casefold() != "сообщения":
        await message.reply(PARTICIPANTS_USAGE)
        return

    resolved = _resolve_participants_period(message.text)
    if resolved is None:
        await message.reply(PARTICIPANTS_USAGE)
        return
    since_day, period_label, consumed = resolved

    rest = tokens[2 + consumed:]
    if len(rest) != 2:
        await message.reply(PARTICIPANTS_USAGE)
        return

    method = PARTICIPANTS_METHODS.get(rest[0].casefold())
    if method is None or not rest[1].lstrip("-").isdigit():
        await message.reply(PARTICIPANTS_USAGE)
        return

    number = int(rest[1])
    rows = await db.list_by_message_count(message.chat.id, since_day, method, number, limit=200)

    method_label = PARTICIPANTS_METHOD_LABELS[method]
    header = (
        f"👥 <b>Участники</b> — сообщений {period_label} "
        f"<b>{method_label} {number}</b>"
    )
    if not rows:
        await message.reply(f"{header}\n{DIVIDER}\nНикого не нашлось.")
        return

    # Рестующих не исключаем из выборки (в отличие от «не в норме») — просто
    # помечаем: 🌴 перед именем и «(Рест)» в конце строки, чтобы было видно,
    # что человек не набрал норму по уважительной причине.
    resting_ids = await db.list_active_rest_user_ids(message.chat.id)

    lines = [header, DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        is_resting = row["user_id"] in resting_ids
        prefix = "🌴 " if is_resting else ""
        suffix = " (Рест)" if is_resting else ""
        lines.append(f"{i}. {prefix}{name} — {int(row['message_count'])}{suffix}")

    text = "\n".join(lines)
    # Telegram режет сообщения на 4096 символах — в очень больших чатах список
    # может не влезть, тогда показываем первых 50 и говорим, сколько ещё есть.
    if len(text) > 4000:
        lines = lines[:2] + lines[2:52] + [f"…и ещё {len(rows) - 50} участников"]
        text = "\n".join(lines)

    await message.reply(text)


# ----------------------------------------------------------------------------
# Модуль «Рест»: участник предупреждает заранее, что не будет писать
# какое-то время (болезнь/отпуск/сессия и т.п.) — заявку рассматривают
# админы (через кнопки в том же топике, куда падают заявки на вступление —
# «топик сюда»/«чат сюда»). Пока рест одобрен и не истёк, участник не
# попадает в «список неактив» (см. фильтр в db.list_inactive).
# ----------------------------------------------------------------------------
REST_MAX_DURATION = timedelta(days=366)  # с запасом на «1 год», чтобы не звать реста на десятилетия
REST_CANCEL_TRIGGERS = {"рест снять", "снять рест"}


def _rest_setting_int(key: str, default: int) -> int:
    """Числовой лимит реста из настроек. NULL в колонке (админ не трогал) и
    любой мусор в ней — это дефолт: настройку правят руками из панели и из
    лички, опечатка не должна ронять обработку заявки."""
    raw = settings.get(key)
    if raw is None:
        return default
    try:
        return int(raw)
    except (TypeError, ValueError):
        return default


def rest_limits() -> rest_rules.RestLimits:
    """Действующие правила реста — из настроек, с дефолтами RestLimits."""
    defaults = rest_rules.RestLimits()
    return rest_rules.RestLimits(
        max_days=_rest_setting_int("rest_max_days", defaults.max_days),
        cooldown_days=_rest_setting_int("rest_cooldown_days", defaults.cooldown_days),
        min_member_days=_rest_setting_int("rest_min_member_days", defaults.min_member_days),
        cleanup_date=rest_rules.parse_settings_date(settings.get("rest_cleanup_date")),
        cleanup_block_days=_rest_setting_int(
            "rest_cleanup_block_days", defaults.cleanup_block_days
        ),
    )


def rest_limit_display(key: str, limits: Optional[rest_rules.RestLimits] = None) -> str:
    """Значение лимита так, как оно выглядит на кнопке меню и в подсказке.

    Читается из действующих правил, а не из settings напрямую: админ должен
    видеть то же число, по которому бот отказывает, включая подставленный
    дефолт, если настройку ещё не трогали."""
    field = REST_LIMIT_FIELDS[key]
    value = getattr(limits or rest_limits(), field["attr"])
    if field["kind"] == "date":
        return value.strftime(rest_rules.DATE_FMT) if value else "не задана"
    return "выкл." if value == 0 else str(value)


def rest_template() -> str:
    return settings.get("rest_rules_template") or rest_rules.DEFAULT_REST_TEMPLATE


def rest_memo(
    *,
    start: datetime,
    end: datetime,
    reason: Optional[str],
    member: str,
    duration: timedelta,
) -> str:
    """Памятка о ресте с подставленными датами — её видит и участник при
    подаче заявки, и админ в карточке при одобрении (см. rest_rules.py)."""
    return rest_rules.render_rest_template(
        rest_template(),
        start=start,
        end=end,
        reason=reason,
        member=member,
        duration_text=format_duration_ru(duration),
    )


def rest_decision_kb(request_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[[
            InlineKeyboardButton(text="✅ Одобрить", callback_data=f"rest_yes:{request_id}"),
            InlineKeyboardButton(text="❌ Отклонить", callback_data=f"rest_no:{request_id}"),
        ]]
    )


def _is_rest_list_cmd(t: Optional[str]) -> bool:
    if not t:
        return False
    tokens = t.strip().casefold().split()
    if len(tokens) < 2:
        return False
    return (tokens[0] == "список" and tokens[1].startswith("рест")) or (
        tokens[0].startswith("рест") and tokens[1] in ("список", "лист")
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and " ".join(t.strip().casefold().split()[:2]) in REST_CANCEL_TRIGGERS),
)
async def cmd_rest_cancel(message: Message):
    if not has_level(message.from_user.id, required_level("rest_cancel")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Снимать рест может «{level_name(required_level('rest_cancel'))}» и выше.")
        return
    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message and message.reply_to_message.from_user:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте (reply) на сообщение того, кому нужно снять рест, "
            "либо укажите @username или ID сразу после «рест снять»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    cancelled = await db.cancel_active_rest(message.chat.id, target.id)
    name = mention_id(target.id, full_name=target.full_name, username=target.username)
    if not cancelled:
        await message.reply(f"У {name} сейчас нет активного реста.")
        return
    await db.add_log("rest_cancelled", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target.id)
    await sync_role_title(message.chat.id, target.id)
    await message.reply(f"✅ Рест снят для {name} — теперь снова считается активным/неактивным как обычно.")


async def rest_tag_expiry_loop() -> None:
    while True:
        try:
            rows = await db.list_data_by_prefix("roletag:")
            for row in rows:
                try:
                    _, chat_id_s, user_id_s = row["data_key"].split(":")
                    chat_id, user_id = int(chat_id_s), int(user_id_s)
                except ValueError:
                    continue
                rest = await db.get_active_rest(chat_id, user_id)
                if not rest:
                    await sync_role_title(chat_id, user_id)
        except Exception:
            logger.exception("Ошибка в rest_tag_expiry_loop")
        await asyncio.sleep(600)  # раз в 10 минут

async def _rest_list_text(rows: list[dict]) -> str:
    if not rows:
        return "🌴 <b>Рест</b>\n\nСейчас никто не в ресте."
    lines = ["🌴 <b>Сейчас в ресте</b>", DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        until: datetime = row["expires_at"]
        reason = f" — {html.escape(row['reason'])}" if row.get("reason") else ""
        lines.append(f"{i}. {name} — до {fmt_dt(until)}{reason}")
    return "\n".join(lines)


