# ---------- Итоги недели ----------
#
# Сводка «что произошло в чате» из уже накопленных данных: активность,
# ачивки, браки, приход-уход, репутация. Можно позвать руками («итоги»),
# можно включить автопост раз в неделю («+итоги»).

WEEKLY_DIGEST_DAYS = 7
WEEKLY_DIGEST_CHECK_INTERVAL = 3600  # как часто проверяем, не пора ли постить


def _digest_key(chat_id: int) -> str:
    return f"digest:{chat_id}"


def _digest_last_key(chat_id: int) -> str:
    return f"digestlast:{chat_id}"


async def is_digest_enabled(chat_id: int) -> bool:
    row = await db.get_data(_digest_key(chat_id))
    return row is not None and row.get("data_value") == "1"


async def build_weekly_digest(chat_id: int, days: int = WEEKLY_DIGEST_DAYS) -> Optional[str]:
    """Собирает текст сводки. None — если за период вообще ничего не было."""
    total_messages = await db.count_messages_since(chat_id, days)
    top_active = await db.get_top_active_since(chat_id, days, limit=5)
    newcomers = await db.get_new_members_since(chat_id, days)
    marriages = await db.get_marriages_since(chat_id, days)
    achievements = await db.get_achievements_since(chat_id, days)
    gainers = await db.get_reputation_gainers_since(chat_id, days, limit=5)

    if not total_messages and not newcomers and not marriages and not achievements:
        return None

    period = "неделю" if days == 7 else f"{days} дн."
    lines = [f"📊 <b>Итоги за {period}</b>"]

    if total_messages:
        lines.append(f"Сообщений в чате: <b>{total_messages}</b>")

    if top_active:
        lines.append("")
        lines.append("🔥 <b>Самые активные:</b>")
        medals = {1: "🥇", 2: "🥈", 3: "🥉"}
        for i, r in enumerate(top_active, 1):
            who = mention_id(r["user_id"], full_name=r.get("full_name"), username=r.get("username"))
            lines.append(f"{medals.get(i, f'{i}.')} {who} — {r['total']}")

    if gainers:
        lines.append("")
        lines.append("⭐ <b>Прибавили в репутации:</b>")
        for r in gainers:
            who = mention_id(r["user_id"], full_name=r.get("full_name"), username=r.get("username"))
            lines.append(f"• {who} — {int(r.get('gained') or 0):+d}")

    if achievements:
        lines.append("")
        lines.append("🏅 <b>Новые ачивки:</b>")
        shown = 0
        for r in achievements:
            meta = ACHIEVEMENTS.get(r["code"])
            if not meta:
                continue
            who = mention_id(r["user_id"])
            lines.append(f"{meta['emoji']} {who} — «{meta['title']}»")
            shown += 1
            if shown >= 8:
                break

    if marriages:
        lines.append("")
        lines.append("💍 <b>Новые пары:</b>")
        for r in marriages:
            lines.append(f"• {mention_id(r['user1_id'])} и {mention_id(r['user2_id'])}")

    if newcomers:
        lines.append("")
        names = ", ".join(
            mention_id(r["user_id"], full_name=r.get("full_name"), username=r.get("username"))
            for r in newcomers[:10]
        )
        tail = f" и ещё {len(newcomers) - 10}" if len(newcomers) > 10 else ""
        lines.append(f"👋 <b>Новеньких:</b> {len(newcomers)}\n{names}{tail}")

    return "\n".join(lines)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in (
        "итоги", "итоги недели", "сводка",
    )),
)
async def cmd_weekly_digest(message: Message):
    if not _check_misc_access(message.from_user.id, "digest"):
        return
    text = await build_weekly_digest(message.chat.id)
    if text is None:
        await message.reply("За неделю в чате ничего заметного не произошло.")
        return
    await message.answer(text)


