async def cmd_minus_toggle(message: Message):
    min_level = required_level("reputation_toggle")
    if not has_level(message.from_user.id, min_level):
        await message.reply(f"⛔ Включать минусы может «{level_name(min_level)}» и выше.")
        return
    enable = message.text.strip().casefold() == "+минусит"
