@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (
        t.strip().casefold() in ("моя репутация", "мой рейтинг", "репутация")
        or t.strip().casefold().startswith("репутация ")
    )),
)
async def cmd_reputation_show(message: Message):
    if not _check_misc_access(message.from_user.id, "reputation"):
        return
    low = message.text.strip().casefold()
    own = low in ("моя репутация", "мой рейтинг", "репутация")

    target_id = message.from_user.id
    if not own:
        target, _ = await resolve_command_target(message)
        if target is None and message.reply_to_message and message.reply_to_message.from_user:
            target = message.reply_to_message.from_user
        if target is None:
            await message.reply("Чью репутацию показать? Ответьте на сообщение или укажите @username.")
            return
        target_id = target.id
    elif message.reply_to_message and message.reply_to_message.from_user:
        target_id = message.reply_to_message.from_user.id

    points = await db.get_reputation(message.chat.id, target_id)
    who = await display_name_by_id(message.chat.id, target_id)
    if points == 0:
        await message.reply(f"⭐ У {who} пока нейтральная репутация — 0.")
        return
    rank = await db.get_reputation_rank(message.chat.id, target_id)
    rank_text = f" (место {rank} в чате)" if rank else ""
    await message.reply(f"⭐ Репутация {who}: <b>{points}</b>{rank_text}")


