# Бонус монет, который выдаётся ОДИН РАЗ вместе с соответствующей ачивкой
# стрика (grant_achievement идемпотентен — повторно не начислит).
STREAK_BONUS_COINS = {"streak_7": 100, "streak_30": 500, "streak_100": 2000}

async def _check_coin_achievements(chat_id: int, user_id: int) -> None:
    wallet = await db.get_wallet(chat_id, user_id)
    coins = int(wallet.get("coins") or 0)
    if coins >= 100_000:
        await grant_achievement(chat_id, user_id, "coins_100000")
    elif coins >= 10_000:
        await grant_achievement(chat_id, user_id, "coins_10000")


async def _increment_quote_count(chat_id: int, user_id: int) -> int:
    key = f"quotecount:{chat_id}:{user_id}"
    row = await db.get_data(key)
    count = int(row["data_value"]) + 1 if row and row.get("data_value") else 1
    await db.set_data(key, str(count))
    return count


async def _increment_gift_count(chat_id: int, user_id: int) -> int:
    key = f"giftcount:{chat_id}:{user_id}"
    row = await db.get_data(key)
    count = int(row["data_value"]) + 1 if row and row.get("data_value") else 1
    await db.set_data(key, str(count))
    return count

# Пороги сообщений → код ачивки. Проверяем только при точном попадании в
# порог, чтобы не дёргать базу на каждом сообщении.
_MSG_ACHIEVEMENTS = {1: "msg_1", 100: "msg_100", 1000: "msg_1000",
                     10000: "msg_10000", 50000: "msg_50000"}


def _achievement_key(chat_id: int, user_id: int) -> str:
    return f"achhide:{chat_id}:{user_id}"


async def are_achievements_hidden(chat_id: int, user_id: int) -> bool:
    row = await db.get_data(_achievement_key(chat_id, user_id))
    return row is not None and row.get("data_value") == "1"


async def grant_achievement(
    chat_id: int, user_id: int, code: str, announce: bool = True, bonus_coins: int = 0
) -> bool:
    """Выдаёт достижение и, если оно новое, объявляет об этом в чате.
    bonus_coins — опциональный бонус i¢, начисляется только при реальной
    (первой) выдаче — благодаря идемпотентности db.grant_achievement."""
    meta = ACHIEVEMENTS.get(code)
    if meta is None:
        return False
    if not await db.grant_achievement(chat_id, user_id, code):
        return False
    await db.add_log("achievement", chat_id=chat_id, actor_id=user_id, details=code)
    if bonus_coins:
        try:
            await db.add_coins(chat_id, user_id, bonus_coins)
        except Exception:
            logger.exception("Не удалось начислить бонус монет за ачивку %s", code)
    # НОВОЕ: если за эту ачивку положен титул — выдаём и его.
    try:
        for title in await db.list_titles():
            if title.get("achievement_code") == code:
                newly_titled = await db.grant_title(chat_id, user_id, title["title_key"])
                if newly_titled and announce:
                    try:
                        who = await display_name_by_id(chat_id, user_id)
                        await bot.send_message(chat_id, f"🎖 {who} получает титул «{title['name']}»!")
                    except Exception:
                        pass
    except Exception:
        logger.exception("Не удалось проверить/выдать титул за ачивку %s", code)

    if announce:
        try:
            who = await display_name_by_id(chat_id, user_id)
            bonus_line = f"\n☢️ Бонус: +{bonus_coins} i¢" if bonus_coins else ""
            await bot.send_message(
                chat_id,
                f"{meta['emoji']} <b>Новая ачивка!</b>\n{who} получает «{meta['title']}» — {meta['desc']}.{bonus_line}",
            )
        except Exception:
            logger.exception("Не удалось объявить ачивку %s", code)
    return True


async def check_message_achievements(chat_id: int, user_id: int, when: datetime) -> None:
    """Проверяет достижения, зависящие от сообщений: пороги, стаж, время суток.

    Вызывается из middleware на каждое сообщение, поэтому старается ходить в
    базу пореже: пороговые ачивки проверяются только при точном совпадении
    счётчика, ночные — только в соответствующие часы.
    """
    try:
        stats = await db.get_message_stats(chat_id, user_id)
        if not stats:
            return
        count = int(stats.get("message_count") or 0)

        code = _MSG_ACHIEVEMENTS.get(count)
        if code:
            await grant_achievement(chat_id, user_id, code)

        # ночные/утренние — час считаем по времени сообщения (UTC, как и вся
        # остальная статистика бота)
        hour = when.hour
        if 3 <= hour < 5:
            await grant_achievement(chat_id, user_id, "night_owl")
        elif 5 <= hour < 7:
            await grant_achievement(chat_id, user_id, "early_bird")

        # стаж — проверяем только на «круглых» сообщениях, чтобы не считать
        # разницу дат постоянно
        if count % 50 == 0:
            first_seen = stats.get("first_seen_at")
            if first_seen:
                days = (datetime.utcnow() - first_seen).days
                if days >= 365:
                    await grant_achievement(chat_id, user_id, "days_365")
                elif days >= 30:
                    await grant_achievement(chat_id, user_id, "days_30")
        # стрик — по посуточным данным (недорогой индексированный SELECT)
        days_rows = await db.list_active_days(chat_id, user_id)
        streak = compute_streak(days_rows)
        if streak >= 100:
            await grant_achievement(chat_id, user_id, "streak_100", bonus_coins=STREAK_BONUS_COINS["streak_100"])
        elif streak >= 30:
            await grant_achievement(chat_id, user_id, "streak_30", bonus_coins=STREAK_BONUS_COINS["streak_30"])
        elif streak >= 7:
            await grant_achievement(chat_id, user_id, "streak_7", bonus_coins=STREAK_BONUS_COINS["streak_7"])
    except Exception:
        logger.exception("Не удалось проверить ачивки для user_id=%s", user_id)


