def _is_other_achievements_cmd(text: Optional[str]) -> bool:
    """«твои ачивки» / «ачивки @username».

    Голое «ачивки» — это свои, а «ачивки чата» — общий топ; оба обрабатываются
    другими командами, поэтому сюда попадать не должны.
    """
    if not text:
        return False
    low = text.strip().casefold()
    if low.startswith("твои ачивки"):
        return True
    words = low.split()
    return len(words) > 1 and words[0] == "ачивки" and words[1] != "чата"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_other_achievements_cmd),
)
async def cmd_other_achievements(message: Message):
    if not _check_misc_access(message.from_user.id, "achievements"):
        return
    # «твои ачивки @user» — триггер из двух слов, «ачивки @user» — из одного
    words = 2 if message.text.strip().casefold().startswith("твои ") else 1
    target, _ = await resolve_command_target(message, trigger_words=words)
    if target is None and message.reply_to_message and message.reply_to_message.from_user:
        u = message.reply_to_message.from_user
        target = SimpleNamespace(id=u.id, full_name=u.full_name, username=u.username)
    if target is None:
        await message.reply("Ответьте этой командой на сообщение человека или укажите @username.")
        return
    if await are_achievements_hidden(message.chat.id, target.id) and target.id != message.from_user.id:
        name = await display_name_by_id(message.chat.id, target.id)
        await message.reply(f"{name} скрыл(а) свои достижения.")
        return
    await _send_achievements(message, target.id, own=False)


async def _send_achievements(message: Message, user_id: int, own: bool) -> None:
    earned = await db.get_achievements(message.chat.id, user_id)
    who = await display_name_by_id(message.chat.id, user_id)
    total = len(ACHIEVEMENTS)

    if not earned:
        await message.reply(
            f"🏅 У {'вас' if own else who} пока нет ачивок (0 из {total}).\n"
            "Они выдаются сами — за активность, стаж и события в чате."
        )
        return

    codes = {r["code"] for r in earned}
    got_lines = [
        f"{ACHIEVEMENTS[c]['emoji']} <b>{ACHIEVEMENTS[c]['title']}</b> (<code>{c}</code>) — {ACHIEVEMENTS[c]['desc']}"
        for c in ACHIEVEMENTS if c in codes
    ]
    left_lines = [
        f"🔒 {ACHIEVEMENTS[c]['title']} — {ACHIEVEMENTS[c]['desc']}"
        for c in ACHIEVEMENTS if c not in codes
    ]

    text = f"🏅 <b>Ачивки {'ваши' if own else who}</b> — {len(codes)} из {total}\n\n" + "\n".join(got_lines)
    if left_lines:
        text += "\n\n<blockquote expandable>Ещё не получено:\n" + "\n".join(left_lines) + "</blockquote>"
    await message.reply(text)


