ACHIEVEMENT_PIN_RE = re.compile(r"(?i)^закрепить\s+ачивку\s+(\S+)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(ACHIEVEMENT_PIN_RE.match(t.strip()))),
)
async def cmd_pin_achievement(message: Message):
    code = ACHIEVEMENT_PIN_RE.match(message.text.strip()).group(1).casefold()
    if code not in ACHIEVEMENTS:
        await message.reply("Такой ачивки не существует. Код смотрите в «мои ачивки».")
        return
    earned = await db.get_achievement_codes(message.chat.id, message.from_user.id)
    if code not in earned:
        await message.reply("У вас пока нет этой ачивки.")
        return
    await db.set_pinned_achievement(message.chat.id, message.from_user.id, code)
    meta = ACHIEVEMENTS[code]
