@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and [w.casefold() for w in t.strip().split(maxsplit=2)[0:2]] in (
        ["созвать", "своих"], ["позвать", "своих"],
    )),
)
async def cmd_call_my_subs(message: Message):
    if not _check_misc_access(message.from_user.id, "subscriptions"):
        return
    rows = await db.get_subscribers(message.chat.id, message.from_user.id, limit=SUBSCRIBERS_CALL_LIMIT)
    if not rows:
        await message.reply("На вас пока никто не подписан — звать некого.")
        return

    parts = message.text.strip().split(maxsplit=2)
    note = parts[2].strip() if len(parts) > 2 else ""

    who = await display_name_by_id(message.chat.id, message.from_user.id)
    mentions = " ".join(
        mention_id(r["user_id"], full_name=r.get("full_name"), username=r.get("username"))
        for r in rows
    )
    text = f"📣 {who} созывает своих:\n{mentions}"
    if note:
        text += f"\n\n{html.escape(note)}"
    await message.answer(text)


