# ============================================================================
# Анкета пользователя (пол, город, «о себе», видимость) — по образцу раздела
# «Анкета пользователя» у Iris | Чат-менеджера. Дополняет звание/девиз/
# гражданство (см. выше) и выводится отдельной карточкой командой «анкета» /
# «моя анкета», а также короткими значками в /профиль.
# ============================================================================
GENDER_LABEL = {"м": "мужской", "ж": "женский", "др": "другой"}
GENDER_EMOJI = {"м": "♂️", "ж": "♀️", "др": "⚧️"}
GENDER_ALIASES = {"м": "м", "муж": "м", "мужской": "м", "ж": "ж", "жен": "ж", "женский": "ж", "др": "др", "другой": "др"}
ABOUT_MAX_LEN = 1000
CITY_MAX_LEN = 64


def _is_gender_set_command(text: str | None) -> bool:
    if not text:
        return False
    parts = text.strip().casefold().split(maxsplit=2)
    return len(parts) >= 2 and parts[0] == "мой" and parts[1] == "пол"


def _is_city_set_command(text: str | None) -> bool:
    if not text:
        return False
    parts = text.strip().split(maxsplit=2)
    return len(parts) >= 2 and parts[0].casefold() == "!мой" and parts[1].casefold() == "город"


# ---------- Мой пол ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_gender_set_command),
)
async def cmd_gender(message: Message):
    parts = message.text.strip().split(maxsplit=2)
    value = parts[2].strip().casefold() if len(parts) > 2 else ""
    code = GENDER_ALIASES.get(value)
    if not code:
        await message.reply("Использование: <code>мой пол м</code> / <code>мой пол ж</code> / <code>мой пол др</code>")
        return
    await db.set_gender(message.chat.id, message.from_user.id, code)
    await message.reply(f"✅ Пол в анкете: <b>{GENDER_EMOJI[code]} {GENDER_LABEL[code]}</b>")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "-мой пол"),
)
async def cmd_gender_clear(message: Message):
    await db.clear_gender(message.chat.id, message.from_user.id)
    await message.reply("✅ Пол убран из анкеты.")


# «.мойпол м/ж/др» (или «мойпол м») — краткая запись установки пола, привычная
# по другим ботам; делает ровно то же, что «мой пол …». Пол нужен, в частности,
# для подбора картинки-реакции в РП-жестах пары (см. relationships_v2).
def _is_gender_compact_command(text: str | None) -> bool:
    if not text:
        return False
    first = (text.strip().casefold().split(maxsplit=1) or [""])[0]
    return first in (".мойпол", "мойпол")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_gender_compact_command),
)
async def cmd_gender_compact(message: Message):
    parts = message.text.strip().split(maxsplit=1)
    value = parts[1].strip().casefold() if len(parts) > 1 else ""
    code = GENDER_ALIASES.get(value)
    if not code:
        await message.reply(
            "Использование: <code>.мойпол м</code> / <code>.мойпол ж</code> / <code>.мойпол др</code>"
        )
        return
    await db.set_gender(message.chat.id, message.from_user.id, code)
    await message.reply(f"✅ Пол в анкете: <b>{GENDER_EMOJI[code]} {GENDER_LABEL[code]}</b>")


# ---------- Мой город ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_city_set_command),
)
async def cmd_city(message: Message):
    parts = message.text.strip().split(maxsplit=2)
    if len(parts) < 3 or not parts[2].strip():
        await message.reply("Использование: <code>!мой город Алматы</code>")
        return
    value = parts[2].strip()
    if len(value) > CITY_MAX_LEN:
        await message.reply(f"⚠️ Слишком длинное название города (максимум {CITY_MAX_LEN} символов).")
        return
    await db.set_city(message.chat.id, message.from_user.id, value)
    await message.reply(f"✅ Город в анкете: <b>{html.escape(value)}</b>")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "-мой город"),
)
async def cmd_city_clear(message: Message):
    await db.clear_city(message.chat.id, message.from_user.id)
    await message.reply("✅ Город убран из анкеты.")


# ---------- О себе (описание) ----------
def _is_about_set_command(text: str | None) -> bool:
    if not text or "\n" not in text.strip():
        return False
    first_line = text.strip().split("\n", 1)[0].strip().casefold()
    return first_line in ("о себе", "описание")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_about_set_command),
)
async def cmd_about_set(message: Message):
    _, _, rest = message.text.strip().partition("\n")
    value = rest.strip()
    if not value:
        await message.reply("Использование:\n<code>о себе\nТекст на новой строке</code>")
        return
    if len(value) > ABOUT_MAX_LEN:
        await message.reply(f"⚠️ Слишком длинное описание (максимум {ABOUT_MAX_LEN} символов).")
        return
    await db.set_about(message.chat.id, message.from_user.id, value)
    await message.reply("✅ Описание «о себе» сохранено.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "-о себе"),
)
async def cmd_about_clear(message: Message):
    await db.clear_about(message.chat.id, message.from_user.id)
    await message.reply("✅ Описание «о себе» удалено.")


async def about_text_for(chat_id: int, target, viewer_id: int) -> str:
    """Текст описания («о себе») пользователя target — общая логика для команды
    «описание» и для кнопки «📝 Описание» под карточкой профиля."""
    card = await db.get_profile_card(chat_id, target.id)
    if target.id != viewer_id and card and not card.get("anketa_visible", 1):
        return "🔒 Этот пользователь скрыл свою анкету."
    if card and card.get("about_text"):
        name = await display_name(chat_id, target)
        return f"📝 <b>О {name}</b>\n{DIVIDER}\n{html.escape(card['about_text'])}"
    return "Описание не установлено.\n\nЗадать: <code>о себе\nТекст</code>"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "описание"),
)
async def cmd_about_show(message: Message):
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    if target.is_bot:
        await message.reply("У ботов описания нет 🤖")
        return
    await message.reply(await about_text_for(message.chat.id, target, message.from_user.id))


