MARRIAGES_PAGE_SIZE = 10


async def marriages_page(chat_id: int, page: int) -> tuple[str, InlineKeyboardMarkup | None]:
    page = max(page, 0)
    rows, total = await db.list_marriages(
        chat_id, limit=MARRIAGES_PAGE_SIZE, offset=page * MARRIAGES_PAGE_SIZE
    )
    if not rows and page:
        page = 0
        rows, total = await db.list_marriages(chat_id, limit=MARRIAGES_PAGE_SIZE)
    if not rows:
        return (
            "💍 <b>Браки группы</b>\n\nПока нет ни одной пары.\n"
            "Ответьте на сообщение человека словом <b>Брак</b>, чтобы стать первой!",
            None,
        )

    lines = []
    for index, marriage in enumerate(rows, start=page * MARRIAGES_PAGE_SIZE + 1):
        first = await display_name_by_id(chat_id, marriage["user1_id"])
        second = await display_name_by_id(chat_id, marriage["user2_id"])
        date = fmt_date(marriage["married_at"])
        lines.append(f"{index}. {first} ❤️ {second} · <code>{date}</code>")

    pages = (total + MARRIAGES_PAGE_SIZE - 1) // MARRIAGES_PAGE_SIZE
    text = f"💍 <b>Браки группы — {total}</b>\n\n" + "\n".join(lines)
    if pages == 1:
        return text, None

    buttons = []
    if page > 0:
        buttons.append(InlineKeyboardButton(text="⬅️", callback_data=f"marriages_page:{page - 1}"))
    buttons.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        buttons.append(InlineKeyboardButton(text="➡️", callback_data=f"marriages_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[buttons])


