# ---------- «Топ браков» ----------
MARRIAGE_TOP_LIMIT = 10


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "топ браков"),
)
async def cmd_marriage_top(message: Message):
    if not _check_misc_access(message.from_user.id, "marriage_top"):
        return
    chat_id = message.chat.id
    conf = await db.get_marriage_settings(chat_id)
    if not conf["rating_enabled"]:
        await message.reply(
            "🏆 Рейтинг браков в этом чате выключен. Включить: <code>+брак рейтинг</code>."
        )
        return
    rows = await db.list_marriage_top(chat_id, limit=MARRIAGE_TOP_LIMIT)
    if not rows:
        await message.reply("Пока ни одной пары — станьте первыми 💍")
        return

    medals = {0: "🥇", 1: "🥈", 2: "🥉"}
    now = datetime.utcnow()
    lines = ["🏆 <b>Топ самых долгих браков</b>", DIVIDER]
    for i, row in enumerate(rows):
        first = await display_name_by_id(chat_id, row["user1_id"])
        second = await display_name_by_id(chat_id, row["user2_id"])
        place = medals.get(i, f"{i + 1}.")
        duration = format_duration_ru(now - row["married_at"])
        lines.append(f"{place} {first} ❤️ {second} — {duration}")
    await message.reply("\n".join(lines))


# ---------- «Развести пару {ссылка} {ссылка}» (модератор) ----------
def _is_divorce_pair_command(text: Optional[str]) -> bool:
    if not text:
        return False
    parts = text.strip().casefold().split()
    return len(parts) >= 2 and parts[0] == "развести" and parts[1] == "пару"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_divorce_pair_command),
)
async def cmd_divorce_pair(message: Message):
    """Зеркало «поженить пару»: модератор разводит двух ДРУГИХ людей."""
    min_level = required_level("divorce_pair")
    actor_level = get_level(message.from_user.id)
    if actor_level < min_level:
        if actor_level > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    targets = await _collect_pair_targets(message)
    unknown = next((t for t in targets if t.id is None), None)
    if unknown is not None:
        await message.reply(
            f"Не удалось найти @{html.escape(unknown.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение или укажите по ID."
        )
        return
    if not targets:
        await message.reply(
            "Укажите пару: <code>развести пару @первый @второй</code> — либо ответом на "
            "сообщение одного из супругов."
        )
        return

    # Достаточно одного из двоих: брак и так один на человека. Второго, если
    # он указан, используем как проверку — чтобы нельзя было развести не ту пару.
    first = targets[0]
    marriage = await db.get_marriage(message.chat.id, first.id)
    if not marriage:
        who = await display_name_by_id(message.chat.id, first.id)
        await message.reply(f"{who} ни с кем не в браке 🙂")
        return
    if len(targets) >= 2 and targets[1].id != marriage["partner_id"]:
        who = await display_name_by_id(message.chat.id, first.id)
        partner = await display_name_by_id(message.chat.id, marriage["partner_id"])
        await message.reply(f"Эти двое не женаты друг на друге: {who} состоит в браке с {partner}.")
        return

    partner_id = marriage["partner_id"]
    await db.snapshot_dissolution("marriage", message.chat.id, first.id, partner_id, "{}")
    await db.delete_marriage(message.chat.id, first.id)
    await db.add_log(
        "marriage_dissolved_by_admin", chat_id=message.chat.id,
        actor_id=message.from_user.id, target_id=first.id, details=str(partner_id),
    )
    a = await display_name_by_id(message.chat.id, first.id)
    b = await display_name_by_id(message.chat.id, partner_id)
    await message.reply(
        f"💔 {a} и {b} разведены модератором.\n"
        "Передумали? Вернуть брак можно 72 часа командой «вернуть брак»."
    )


# ---------- «Развести вышедших» (модератор) ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "развести вышедших"),
)
async def cmd_divorce_departed(message: Message):
    min_level = required_level("divorce_departed")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    rows = await db.list_marriages_with_departed(message.chat.id)
    if not rows:
        await message.reply("✅ Все супруги на месте — разводить некого.")
        return

    # Снимки для «вернуть брак» — по одному на пару, до удаления.
    for row in rows:
        await db.snapshot_dissolution(
            "marriage", message.chat.id, row["user1_id"], row["user2_id"], "{}"
        )
    removed = await db.delete_marriages_by_ids([row["id"] for row in rows])
    await db.add_log(
        "marriages_departed_cleanup", chat_id=message.chat.id,
        actor_id=message.from_user.id, details=str(removed),
    )
    await message.reply(
        f"💔 Расторгнуто браков, где один из супругов уже покинул чат: <b>{removed}</b>.\n"
        "Если человек вернётся — брак можно вернуть 72 часа командой «вернуть брак»."
    )


# ---------- «!Сброс браков» (старший админ, с подтверждением) ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("!сброс браков", "сброс браков")),
)
async def cmd_marriages_reset(message: Message):
    min_level = required_level("marriages_reset")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    _rows, total = await db.list_marriages(message.chat.id, limit=1)
    if not total:
        await message.reply("В чате и так нет ни одного брака 🙂")
        return
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(
            text="💔 Да, обнулить", callback_data=f"marriages_reset:{message.from_user.id}"
        ),
        InlineKeyboardButton(text="Отмена", callback_data=f"marriages_reset_no:{message.from_user.id}"),
    ]])
    await message.reply(
        f"⚠️ Обнулить <b>все</b> браки чата — сейчас их {total}?\n"
        "Действие необратимо: снимков для «вернуть брак» не будет.",
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("marriages_reset_no:"))
async def cb_marriages_reset_no(callback: CallbackQuery):
    try:
        initiator = int((callback.data or "").split(":")[1])
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator:
        await callback.answer("Это не ваше подтверждение 🙂", show_alert=True)
        return
    await callback.answer()
    try:
        await callback.message.edit_text("Сброс браков отменён 🙂")
    except TelegramBadRequest:
        pass


@router.callback_query(F.data.startswith("marriages_reset:"))
async def cb_marriages_reset_yes(callback: CallbackQuery):
    try:
        initiator = int((callback.data or "").split(":")[1])
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator:
        await callback.answer("Это не ваше подтверждение 🙂", show_alert=True)
        return
    # Уровень проверяем ещё раз: между командой и нажатием права могли снять.
    if not has_level(initiator, required_level("marriages_reset")):
        await callback.answer("Прав на это уже нет.", show_alert=True)
        return

    chat_id = callback.message.chat.id
    removed = await db.reset_marriages(chat_id)
    await db.add_log("marriages_reset", chat_id=chat_id, actor_id=initiator, details=str(removed))
    await callback.answer()
    try:
        await callback.message.edit_text(f"💔 Все браки чата обнулены. Расторгнуто: <b>{removed}</b>.")
    except TelegramBadRequest:
        pass


# ---------- «Брак цена продления {число}» (админ) ----------
MARRIAGE_PRICE_RE = re.compile(r"(?i)^брак\s+цена\s+продления(?:\s+(\S+))?$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(MARRIAGE_PRICE_RE.match(t.strip()))),
)
async def cmd_marriage_renew_price(message: Message):
    chat_id = message.chat.id
    raw = MARRIAGE_PRICE_RE.match(message.text.strip()).group(1)
    if raw is None:  # без числа — показываем текущую цену, это не правка
        conf = await db.get_marriage_settings(chat_id)
        await message.reply(
            f"💰 Продление брака стоит <b>{conf['renew_price']}</b> i¢ за сутки.\n"
            "Изменить: <code>брак цена продления 500</code>"
        )
        return

    min_level = required_level("marriage_price_set")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    price = parse_amount(raw)
    if price is None or price < 0:
        await message.reply("Не понял цену. Можно так: 500, 10к, 0 (бесплатно).")
        return
    if price > 10_000_000:
        await message.reply("Слишком много — не больше 10 000 000 i¢ за сутки.")
        return
    await db.set_marriage_setting(chat_id, "renew_price", price)
    await db.add_log("marriage_price_set", chat_id=chat_id, actor_id=message.from_user.id, details=str(price))
    await message.reply(f"💰 Цена продления брака: <b>{price}</b> i¢ за сутки.")


# ---------- «Брак продлить {кол-во дней}» ----------
MARRIAGE_EXTEND_RE = re.compile(r"(?i)^брак\s+продлить(?:\s+(\d{1,4}))?$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(MARRIAGE_EXTEND_RE.match(t.strip()))),
)
async def cmd_marriage_extend(message: Message):
    if not _check_misc_access(message.from_user.id, "marriage_extend"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    conf = await db.get_marriage_settings(chat_id)

    raw_days = MARRIAGE_EXTEND_RE.match(message.text.strip()).group(1)
    if raw_days is None:
        await message.reply(
            f"⏳ Продление брака: <code>брак продлить 7</code>\n"
            f"Цена — <b>{conf['renew_price']}</b> i¢ за сутки "
            f"(не больше {MARRIAGE_MAX_EXTEND_DAYS} суток за раз)."
        )
        return
    days = int(raw_days)
    if days <= 0:
        await message.reply("Продлевать нужно хотя бы на сутки.")
        return
    if days > MARRIAGE_MAX_EXTEND_DAYS:
        await message.reply(f"За раз можно продлить не больше чем на {MARRIAGE_MAX_EXTEND_DAYS} суток.")
        return

    marriage = await db.get_marriage(chat_id, user_id)
    if not marriage:
        await message.reply("Вы пока ни с кем не в браке 🙂")
        return

    cost = conf["renew_price"] * days
    if cost and not has_infinite_money(user_id):
        if await is_account_frozen(chat_id, user_id):
            await message.reply("🧊 Ваш счёт заморожен — продление недоступно.")
            return
        wallet = await db.get_wallet(chat_id, user_id)
        if int(wallet.get("coins", 0)) < cost:
            await message.reply(
                f"Недостаточно монет: продление на {days} сут. стоит {cost} i¢, "
                f"а у вас {wallet.get('coins', 0)} i¢."
            )
            return
        await db.add_coins(chat_id, user_id, -cost)

    new_expiry = await db.extend_marriage(chat_id, user_id, days)
    if new_expiry is None:
        await message.reply("Не удалось продлить брак — попробуйте ещё раз.")
        return
    await db.add_log(
        "marriage_extended", chat_id=chat_id, actor_id=user_id,
        target_id=marriage["partner_id"], details=f"{days}d/{cost}",
    )
    partner_name = await display_name_by_id(chat_id, marriage["partner_id"])
    paid = f" за <b>{cost}</b> i¢" if cost else ""
    await message.reply(
        f"💞 Брак с {partner_name} продлён на <b>{days}</b> сут.{paid}\n"
        f"{_marriage_expiry_line(new_expiry)}"
    )


# ---------- «+Брак рейтинг» / «-Брак рейтинг» (админ) ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() in ("+брак рейтинг", "-брак рейтинг")),
)
async def cmd_marriage_rating_toggle(message: Message):
    min_level = required_level("marriage_rating_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    enabled = message.text.strip().startswith("+")
    await db.set_marriage_setting(message.chat.id, "rating_enabled", enabled)
    await db.add_log(
        "marriage_rating_toggle", chat_id=message.chat.id,
        actor_id=message.from_user.id, details="on" if enabled else "off",
    )
    await message.reply(
        "🏆 Рейтинг браков включён — смотреть: <code>топ браков</code>." if enabled
        else "🏆 Рейтинг браков выключен — «топ браков» больше не показывается."
    )


# ---------- «Брак режим развода» (админ) ----------
MARRIAGE_MODE_RE = re.compile(r"(?i)^брак\s+режим\s+развода(?:\s+(\S+))?$")
_MARRIAGE_MODE_WORDS = {
    "авто": "auto", "автоматический": "auto", "вкл": "auto", "auto": "auto",
    "выкл": "off", "выключен": "off", "нет": "off", "off": "off",
}


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(MARRIAGE_MODE_RE.match(t.strip()))),
)
async def cmd_marriage_divorce_mode(message: Message):
    chat_id = message.chat.id
    raw = MARRIAGE_MODE_RE.match(message.text.strip()).group(1)
    if raw is None:
        conf = await db.get_marriage_settings(chat_id)
        current = MARRIAGE_DIVORCE_MODES.get(conf["divorce_mode"], conf["divorce_mode"])
        await message.reply(
            f"⚖️ Режим развода: <b>{current}</b>\n"
            "Переключить: <code>брак режим развода авто</code> / "
            "<code>брак режим развода выкл</code>\n"
            "В режиме «авто» брак с истёкшим сроком расторгается сам "
            "(вернуть — 72 часа командой «вернуть брак»)."
        )
        return

    min_level = required_level("marriage_mode_set")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    mode = _MARRIAGE_MODE_WORDS.get(raw.casefold())
    if mode is None:
        await message.reply("Режим бывает <b>авто</b> или <b>выкл</b>.")
        return
    await db.set_marriage_setting(chat_id, "divorce_mode", mode)
    await db.add_log("marriage_mode_set", chat_id=chat_id, actor_id=message.from_user.id, details=mode)
    await message.reply(f"⚖️ Режим развода: <b>{MARRIAGE_DIVORCE_MODES[mode]}</b>.")


# ---------- Фоновый авторазвод по истечении срока ----------
MARRIAGE_EXPIRY_CHECK_INTERVAL = 600  # раз в 10 минут — срок измеряется сутками


async def marriage_expiry_loop(interval_seconds: int = MARRIAGE_EXPIRY_CHECK_INTERVAL) -> None:
    """Расторгает браки, у которых вышел срок, — но только в чатах с режимом
    «авто» (выборку фильтрует сам запрос, см. db.list_expired_marriages).

    Снимок для «вернуть брак» снимается и здесь: авторазвод не должен быть
    жёстче обычного — 72 часа на передумать остаются.
    """
    while True:
        try:
            expired = await db.list_expired_marriages()
            for row in expired:
                chat_id = row["chat_id"]
                a, b = row["user1_id"], row["user2_id"]
                await db.snapshot_dissolution("marriage", chat_id, a, b, "{}")
                if not await db.delete_marriages_by_ids([row["id"]]):
                    continue
                await db.add_log("marriage_expired", chat_id=chat_id, actor_id=a, target_id=b)
                try:
                    na = await display_name_by_id(chat_id, a)
                    nb = await display_name_by_id(chat_id, b)
                    await bot.send_message(
                        chat_id,
                        f"⌛ Срок брака {na} и {nb} истёк — брак расторгнут.\n"
                        "Вернуть можно 72 часа командой «вернуть брак», "
                        "продлить заранее — «брак продлить {дней}».",
                    )
                except Exception:
                    # Бота могли выгнать или запретить писать — брак всё равно
                    # расторгнут, молчать об ошибке отправки здесь правильно.
                    logger.debug("Не удалось сообщить чату %s об истёкшем браке", chat_id)
        except Exception:
            logger.exception("Фоновая проверка сроков браков не удалась")
        await asyncio.sleep(interval_seconds)


# ============================================================================
# Отношения («Отношения» — как в Iris | Чат-менеджер). Отдельный, более лёгкий
# модуль, предшествующий браку: пара копит очки близости РП-действиями и
# поднимается по уровням. Никак не связан с логикой marriages/propose_marriage
# выше — обе системы работают независимо, /профиль может показать оба статуса.
# ============================================================================

# Уровни близости: (имя, порог очков). Финальный уровень НЕ включает брак —
# брак остаётся отдельной командой («Брак») и доступен независимо, как сейчас.
# Дефолт — сид/фолбэк (см. комментарий у _RP_ACTIONS_DEFAULT выше по коду).
_RELATIONSHIP_LEVELS_DEFAULT: list[tuple[str, int]] = [
    ("Симпатия", 0),
    ("Дружеские отношения", 1500),
    ("Влюблённость", 4000),
    ("Отношения", 8000),
    ("Крепкие отношения", 15000),
]

# Живой кэш — заполняется в load_caches() из db.list_relationship_levels().
RELATIONSHIP_LEVELS: list[tuple[str, int]] = list(_RELATIONSHIP_LEVELS_DEFAULT)


def relationship_level_index(points: int) -> int:
    """Индекс текущего уровня (0-based) по накопленным очкам."""
    index = 0
    for i, (_, threshold) in enumerate(RELATIONSHIP_LEVELS):
        if points >= threshold:
            index = i
    return index


def relationship_level_name(level_index: int) -> str:
    if 0 <= level_index < len(RELATIONSHIP_LEVELS):
        return RELATIONSHIP_LEVELS[level_index][0]
    return RELATIONSHIP_LEVELS[-1][0]


def relationship_next_level_info(points: int) -> Optional[tuple[str, int]]:
    """(имя следующего уровня, сколько очков до него) либо None, если уровень уже максимальный."""
    for name, threshold in RELATIONSHIP_LEVELS:
        if points < threshold:
            return name, threshold - points
    return None


# Очки близости за РП-действия. Действия из RP_ACTIONS (обнять/поцеловать/
# погладить/укусить/ударить) работают как и раньше на ком угодно (см.
# handle_rp_action выше по коду), но начисляют очки, только если цель —
# текущий партнёр по отношениям. Ниже — отдельные действия, доступные ТОЛЬКО
# с текущим партнёром (иначе бот откажет).
_REL_ACTION_POINTS_DEFAULT: dict[str, int] = {
    "обнять": 20,
    "погладить": 15,
    "укусить": 10,
    "поцеловать": 35,
    "ударить": -15,
    "комплимент": 25,
    "подарок": 50,
    "свидание": 70,
}

# Ключи из _REL_ACTION_POINTS_DEFAULT, которые считаются «партнёрскими» —
# нужно только для сида db.seed_relationship_actions_if_empty (какой
# partner_only проставить каждому действию при первой миграции); дальше
# источник истины — колонка partner_only в таблице relationship_actions.
_REL_PARTNER_ONLY_KEYS_DEFAULT: set[str] = {"комплимент", "подарок", "свидание"}

# Действия, доступные только с текущим партнёром (не работают на случайных
# людях вообще, в отличие от «общих» обнять/поцеловать/погладить/укусить/
# ударить, унаследованных из старого RP_ACTIONS).
_REL_ONLY_PARTNER_ACTIONS_DEFAULT: dict[str, list[str]] = {
    "комплимент": [
        "😊 {actor} делает {target} комплимент — не смущайся, это правда!",
        "💬 {actor} говорит {target} что-то очень приятное",
        "✨ {actor} восхищается {target} вслух",
    ],
    "подарок": [
        "🎁 {actor} дарит {target} подарок",
        "🎁 {actor} преподносит {target} сюрприз-подарок",
        "🎀 {actor} вручает {target} красиво упакованный подарок",
    ],
    "свидание": [
        "🌆 {actor} приглашает {target} на свидание",
        "🕯 {actor} и {target} проводят романтический вечер вместе",
        "🌹 {actor} устраивает для {target} свидание мечты",
    ],
}

# Живые кэши — заполняются в load_caches() из db.list_relationship_actions()
# и db.list_relationship_action_phrases().
REL_ACTION_POINTS: dict[str, int] = dict(_REL_ACTION_POINTS_DEFAULT)
REL_ONLY_PARTNER_ACTIONS: dict[str, list[str]] = dict(_REL_ONLY_PARTNER_ACTIONS_DEFAULT)


async def resolve_relationship_target(message: Message):
    """Определяет цель команды модуля «Отношения»: ответ на сообщение или
    ссылка-упоминание в самом тексте (кликабельное упоминание/@username).
    Возвращает Telegram User (или похожий на него объект с id/full_name/
    username/is_bot) либо None, если цель не найдена."""
    if message.reply_to_message and message.reply_to_message.from_user:
        return message.reply_to_message.from_user

    for entity in message.entities or []:
        if entity.type == "text_mention" and entity.user:
            return entity.user
        if entity.type == "mention":
            username = message.text[entity.offset : entity.offset + entity.length].lstrip("@")
            try:
                chat = await bot.get_chat(username)
            except Exception:
                continue
            if chat.type != "private":
                continue
            return SimpleNamespace(
                id=chat.id,
                full_name=chat.full_name or chat.first_name or username,
                username=chat.username,
                is_bot=False,
            )
    return None


def relationship_status_lines(chat_id_hint: str, rel: dict, partner_name: str) -> list[str]:
    level_index = rel["level"]
    level_name = relationship_level_name(level_index)
    started_at: datetime = rel["started_at"]
    lines = [
        f"💞 Партнёр: {partner_name}",
        f"🏵 Уровень: <b>{level_name}</b>",
        f"✨ Очки близости: <b>{rel['points']}</b>",
    ]
    nxt = relationship_next_level_info(rel["points"])
    if nxt:
        next_name, remaining = nxt
        lines.append(f"📈 До уровня «{next_name}»: {remaining} очк.")
    else:
        lines.append("📈 Достигнут максимальный уровень близости")
    lines.append(f"📅 Отношения начались: {fmt_date(started_at)}")
    return lines


# ОТКЛЮЧЕНО: модуль «Отношения» полностью заменён relationships_v2 (см.
# dp.include_router выше). Хендлер больше не зарегистрирован в router —
# команда «отн» теперь целиком обрабатывается relationships_v2.cmd_rel2_word.
# Код ниже оставлен как есть (не удалён) — на случай отката к старому модулю.
async def cmd_relationship_word(message: Message):
    """Единая точка входа для «отн»: без доп. слова — предложение/разрыв
    с целью из ответа/ссылки; «отн действия» — список действий; «отн топ» —
    топ пар чата."""
    parts = message.text.strip().split(maxsplit=1)
    sub = parts[1].strip().casefold() if len(parts) > 1 else ""

    if sub == "действия":
        await cmd_relationship_actions(message)
        return
    if sub == "топ":
        await cmd_relationship_top(message)
        return

    actor = message.from_user
    target = await resolve_relationship_target(message)
    if target is None:
        await message.reply(
            "💞 Чтобы сделать предложение отношений, ответьте на сообщение человека "
            "словом <b>отн</b> или отправьте <b>отн</b> с кликабельной ссылкой на него."
        )
        return

    if target.id == actor.id:
        await message.reply("Нельзя предложить отношения самому себе 🙂")
        return
    if target.is_bot:
        await message.reply("Боты пока не встречаются 🤖")
        return

    existing_actor = await db.get_relationship(message.chat.id, actor.id)
    if existing_actor and existing_actor["partner_id"] == target.id:
        # «отн» ответом на текущего партнёра — разрыв (как «-отн»)
        await _do_relationship_break(message, existing_actor)
        return

    if existing_actor:
        partner_name = await display_name_by_id(message.chat.id, existing_actor["partner_id"])
        await message.reply(f"Вы уже состоите в отношениях с {partner_name} 💞")
        return

    existing_target = await db.get_relationship(message.chat.id, target.id)
    if existing_target:
        target_name = await display_name(message.chat.id, target)
        await message.reply(f"{target_name} уже состоит в отношениях 💞")
        return

    await db.create_relationship_request(message.chat.id, actor.id, target.id)
    actor_name = await display_name(message.chat.id, actor)
    target_name = await display_name(message.chat.id, target)
    kb = InlineKeyboardMarkup(
        inline_keyboard=[[
            InlineKeyboardButton(text="💞 Принять", callback_data=f"rel_accept:{actor.id}:{target.id}"),
            InlineKeyboardButton(text="💔 Отказать", callback_data=f"rel_decline:{actor.id}:{target.id}"),
        ]]
    )
    await message.reply(
        "💌 <b>Предложение отношений</b>\n\n"
        f"{actor_name} предлагает {target_name} начать отношения 💞\n\n"
        f"{target_name}, выберите свой ответ (или напишите <b>+отн</b>):",
        reply_markup=kb,
    )


async def _do_relationship_break(message: Message, rel: dict) -> None:
    partner_id = rel["partner_id"]
    await db.delete_relationship(message.chat.id, message.from_user.id)
    actor_name = await display_name(message.chat.id, message.from_user)
    partner_name = await display_name_by_id(message.chat.id, partner_id)
    await message.reply(f"💔 {actor_name} и {partner_name} больше не встречаются.")
    await db.add_log(
        "relationship_broken", chat_id=message.chat.id,
        actor_id=message.from_user.id, target_id=partner_id,
    )


# ОТКЛЮЧЕНО: часть старого модуля «Отношения» (см. пометку у cmd_relationship_word).
async def accept_relationship_button(callback: CallbackQuery):
    try:
        _, proposer_id_s, target_id_s = (callback.data or "").split(":")
        proposer_id, target_id = int(proposer_id_s), int(target_id_s)
    except (TypeError, ValueError):
        await callback.answer("Это предложение повреждено или устарело.", show_alert=True)
        return

    if callback.from_user.id != target_id:
        await callback.answer("Это предложение адресовано не вам 🙂", show_alert=True)
        return

    chat_id = callback.message.chat.id

    request = await db.get_latest_relationship_request(chat_id, target_id)
    if not request or request["from_user_id"] != proposer_id:
        await callback.answer("Это предложение уже неактуально.", show_alert=True)
        try:
            await callback.message.edit_reply_markup(reply_markup=None)
        except TelegramBadRequest:
            pass
        return

    if await db.get_relationship(chat_id, proposer_id) or await db.get_relationship(chat_id, target_id):
        await db.delete_relationship_request(chat_id, proposer_id, target_id)
        await callback.answer("Похоже, кто-то из вас уже успел вступить в отношения 💞", show_alert=True)
        try:
            await callback.message.edit_reply_markup(reply_markup=None)
        except TelegramBadRequest:
            pass
        return

    if not await db.create_relationship(chat_id, proposer_id, target_id):
        await callback.answer("Похоже, кто-то из вас уже успел вступить в отношения 💞", show_alert=True)
        try:
            await callback.message.edit_reply_markup(reply_markup=None)
        except TelegramBadRequest:
            pass
        return

    await db.clear_relationship_requests_for(chat_id, target_id)
    await db.clear_relationship_requests_for(chat_id, proposer_id)

    proposer_name = await display_name_by_id(chat_id, proposer_id)
    target_name = await display_name_by_id(chat_id, target_id)
    try:
        await callback.message.edit_text(f"💞🎉 {proposer_name} и {target_name} теперь в отношениях! Поздравляем!")
    except TelegramBadRequest:
        pass
    await db.add_log("relationship_created", chat_id=chat_id, actor_id=proposer_id, target_id=target_id)
    await callback.answer("Поздравляем! 🎉")


# ОТКЛЮЧЕНО: часть старого модуля «Отношения» (см. пометку у cmd_relationship_word).
async def decline_relationship_button(callback: CallbackQuery):
    try:
        _, proposer_id_s, target_id_s = (callback.data or "").split(":")
        proposer_id, target_id = int(proposer_id_s), int(target_id_s)
    except (TypeError, ValueError):
        await callback.answer("Это предложение повреждено или устарело.", show_alert=True)
        return

    if callback.from_user.id != target_id:
        await callback.answer("Это предложение адресовано не вам 🙂", show_alert=True)
        return

    chat_id = callback.message.chat.id
    await db.delete_relationship_request(chat_id, proposer_id, target_id)

    actor_name = await display_name_by_id(chat_id, proposer_id)
    target_name = await display_name_by_id(chat_id, target_id)
    try:
        await callback.message.edit_text(f"💔 {target_name} отказал(а) {actor_name}.")
    except TelegramBadRequest:
        pass
    await db.add_log("relationship_declined", chat_id=chat_id, actor_id=proposer_id, target_id=target_id)
    await callback.answer("Предложение отклонено")


# ОТКЛЮЧЕНО: «+отн» теперь обрабатывает relationships_v2.cmd_rel2_accept_word.
async def cmd_relationship_accept(message: Message):
    actor = message.from_user
    request = await db.get_latest_relationship_request(message.chat.id, actor.id)
    if not request:
        await message.reply("У вас нет предложений отношений, ожидающих ответа 🙂")
        return

    proposer_id = request["from_user_id"]

    if await db.get_relationship(message.chat.id, actor.id) or await db.get_relationship(message.chat.id, proposer_id):
        await db.delete_relationship_request(message.chat.id, proposer_id, actor.id)
        await message.reply("Похоже, кто-то из вас уже успел вступить в отношения 💞")
        return

    if not await db.create_relationship(message.chat.id, proposer_id, actor.id):
        await message.reply("Похоже, кто-то из вас уже успел вступить в отношения 💞")
        return

    await db.clear_relationship_requests_for(message.chat.id, actor.id)
    await db.clear_relationship_requests_for(message.chat.id, proposer_id)

    proposer_name = await display_name_by_id(message.chat.id, proposer_id)
    actor_name = await display_name(message.chat.id, actor)
    await message.reply(f"💞🎉 {proposer_name} и {actor_name} теперь в отношениях! Поздравляем!")
    await db.add_log(
        "relationship_created", chat_id=message.chat.id, actor_id=proposer_id, target_id=actor.id,
    )


# ОТКЛЮЧЕНО: «-отн» теперь обрабатывает relationships_v2.cmd_rel2_break_word.
async def cmd_relationship_break(message: Message):
    rel = await db.get_relationship(message.chat.id, message.from_user.id)
    if not rel:
        await message.reply("Вы пока ни с кем не в отношениях 🙂")
        return
    await _do_relationship_break(message, rel)


def _is_relationship_status_command(t: Optional[str]) -> bool:
    if not t or not t.strip():
        return False
    words = t.strip().casefold().split()
    return len(words) >= 2 and words[0] == "статус" and words[1] == "отн"


# ОТКЛЮЧЕНО: аналог — «отн я» (relationships_v2.cmd_rel2_me).
async def cmd_relationship_status(message: Message):
    rest = message.text.strip().split(maxsplit=2)
    # rest = ["статус", "отн", (опционально ссылка/текст)]
    target = None
    if len(rest) > 2 or message.reply_to_message:
        target = await resolve_relationship_target(message)
    subject = target if target is not None else message.from_user

    if subject.is_bot:
        await message.reply("У ботов отношений не бывает 🤖")
        return

    rel = await db.get_relationship(message.chat.id, subject.id)
    if not rel:
        if target is None:
            await message.reply(
                "Вы пока ни с кем не в отношениях. Ответьте на сообщение человека словом "
                "<b>отн</b>, чтобы сделать предложение."
            )
        else:
            subject_name = await display_name(message.chat.id, subject)
            await message.reply(f"{subject_name} пока ни с кем не в отношениях.")
        return

    subject_name = await display_name(message.chat.id, subject)
    partner_name = await display_name_by_id(message.chat.id, rel["partner_id"])
    lines = [f"💞 <b>Отношения — {subject_name}</b>", DIVIDER]
    lines += relationship_status_lines(str(message.chat.id), rel, partner_name)
    await message.reply("\n".join(lines))


async def cmd_relationship_actions(message: Message):
    lines = ["🎭 <b>Действия в отношениях</b>", DIVIDER,
             "Работают ответом на сообщение партнёра и начисляют очки близости:"]
    for action, points in REL_ACTION_POINTS.items():
        sign = "+" if points >= 0 else ""
        only_partner = " (только с партнёром)" if action in REL_ONLY_PARTNER_ACTIONS else ""
        lines.append(f"・{action} — {sign}{points} очк.{only_partner}")
    lines.append("")
    lines.append("Действия без пометки работают на ком угодно (просто эффект), но очки")
    lines.append("близости начисляются, только если цель — ваш текущий партнёр.")
    await message.reply("\n".join(lines))


RELATIONSHIPS_PAGE_SIZE = 10


async def relationships_page(chat_id: int, page: int) -> tuple[str, InlineKeyboardMarkup | None]:
    page = max(page, 0)
    rows, total = await db.list_relationships(
        chat_id, limit=RELATIONSHIPS_PAGE_SIZE, offset=page * RELATIONSHIPS_PAGE_SIZE
    )
    if not rows and page:
        page = 0
        rows, total = await db.list_relationships(chat_id, limit=RELATIONSHIPS_PAGE_SIZE)
    if not rows:
        return (
            "💞 <b>Топ пар чата</b>\n\nПока нет ни одной пары.\n"
            "Ответьте на сообщение человека словом <b>отн</b>, чтобы стать первой!",
            None,
        )

    lines = []
    for index, rel in enumerate(rows, start=page * RELATIONSHIPS_PAGE_SIZE + 1):
        first = await display_name_by_id(chat_id, rel["user1_id"])
        second = await display_name_by_id(chat_id, rel["user2_id"])
        level_name = relationship_level_name(rel["level"])
        lines.append(f"{index}. {first} 💞 {second} · <b>{rel['points']}</b> очк. · {level_name}")

    pages = (total + RELATIONSHIPS_PAGE_SIZE - 1) // RELATIONSHIPS_PAGE_SIZE
    text = f"💞 <b>Топ пар чата — {total}</b>\n\n" + "\n".join(lines)
    if pages == 1:
        return text, None

    buttons = []
    if page > 0:
        buttons.append(InlineKeyboardButton(text="⬅️", callback_data=f"relationships_page:{page - 1}"))
    buttons.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        buttons.append(InlineKeyboardButton(text="➡️", callback_data=f"relationships_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[buttons])


async def cmd_relationship_top(message: Message):
    text, keyboard = await relationships_page(message.chat.id, 0)
    await message.reply(text, reply_markup=keyboard)


# ОТКЛЮЧЕНО: аналог — «отн список» (relationships_v2.paginate_rel2_list).
async def paginate_relationships(callback: CallbackQuery):
    try:
        page = int((callback.data or "").split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось открыть эту страницу.", show_alert=True)
        return
    text, keyboard = await relationships_page(callback.message.chat.id, page)
    try:
        await callback.message.edit_text(text, reply_markup=keyboard)
    except TelegramBadRequest:
        pass
    await callback.answer()


async def award_relationship_points(chat_id: int, actor_id: int, target_id: int, action: str) -> Optional[str]:
    """Если actor и target — текущая пара, начисляет очки за действие и
    возвращает текст об уровне, если он повысился (иначе None). Ничего не
    делает, если пара не является текущими партнёрами."""
    points_delta = REL_ACTION_POINTS.get(action)
    if points_delta is None:
        return None
    rel = await db.get_relationship(chat_id, actor_id)
    if not rel or rel["partner_id"] != target_id:
        return None

    old_level = rel["level"]
    new_points = max(rel["points"] + points_delta, 0)
    new_level = relationship_level_index(new_points)
    await db.set_relationship_progress(chat_id, actor_id, target_id, new_points, new_level)

    if new_level > old_level:
        return f"🏵 Уровень отношений повышен до «{relationship_level_name(new_level)}»!"
    return None


# ОТКЛЮЧЕНО: партнёрские действия (комплимент/подарок/свидание) были частью
# старого модуля «Отношения» и его очков близости — в relationships_v2 такого
# отдельного набора действий нет (см. вместо этого «дом действие», «отн пт
# действие», «ребенок действие»).
async def handle_relationship_only_action(message: Message):
    action = (message.text.strip().split() or [""])[0].casefold()

    target_user, _remaining = await resolve_command_target(message)
    if target_user is None and message.reply_to_message:
        target_user = message.reply_to_message.from_user
    if target_user is None:
        await message.reply(
            "Ответьте этой командой на сообщение партнёра, "
            "либо укажите @username или ID сразу после действия."
        )
        return
    if target_user.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target_user.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return

    if target_user.id == message.from_user.id:
        await message.reply("Действие направлено на самого себя? Пожалуй, воздержимся 🙂")
        return
    if target_user.is_bot:
        await message.reply("Боты пока не участвуют в отношениях 🤖")
        return

    rel = await db.get_relationship(message.chat.id, message.from_user.id)
    if not rel or rel["partner_id"] != target_user.id:
        await message.reply(f"Это действие доступно только с вашим текущим партнёром по отношениям 💞")
        return

    actor_name = await display_name_link(message.chat.id, message.from_user)
    target_name = await display_name_link(message.chat.id, target_user)
    phrase = random.choice(REL_ONLY_PARTNER_ACTIONS[action]).format(actor=actor_name, target=target_name)

    level_up_text = await award_relationship_points(
        message.chat.id, message.from_user.id, target_user.id, action
    )
    if level_up_text:
        phrase += f"\n\n{level_up_text}"

    if message.reply_to_message:
        await message.answer(phrase, reply_to_message_id=message.reply_to_message.message_id)
    else:
        await message.answer(phrase)
    await db.add_log(
        f"relationship_{action}", chat_id=message.chat.id,
        actor_id=message.from_user.id, target_id=target_user.id,
    )


