@router.message(F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "запомни"))
async def cmd_setval(message: Message):
    if not has_level(message.from_user.id, required_level("setval")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('setval'))}» и выше.")
        return
    args = message.text.split(maxsplit=2)[1:] if message.text else []
    if len(args) < 2:
        await message.reply(
            "Использование: <code>запомни ключ значение</code>\n"
            "Например: <code>запомни site_url https://example.com</code>"
        )
        return
    key, value = args[0], args[1]
    if len(key) > 191:
        await message.reply("⚠️ Ключ слишком длинный (максимум 191 символ).")
        return
    await db.set_data(key, value, updated_by=message.from_user.id)
    await db.add_log("db_set", actor_id=message.from_user.id, details=f"{key} = {value[:100]}")
    await message.reply(f"✅ Записано в БД:\n<code>{html.escape(key)}</code> = {html.escape(value)}")


