@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("названия рангов\n")))
async def cmd_rank_names_set(message: Message):
    if not has_level(message.from_user.id, required_level("mod_themes")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('mod_themes'))}» и выше.")
        return
    body = message.text.split("\n", 1)[1]
    new_names: dict[int, str] = {}
    for raw_line in body.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        parts = line.split(maxsplit=1)
        if len(parts) != 2 or not parts[0].isdigit():
            await message.reply(f"⚠️ Не понял строку: <code>{html.escape(line)}</code>\nФормат: <code>{{уровень}} {{название}}</code>")
            return
        lvl, name = int(parts[0]), parts[1].strip()
        if lvl not in (LEVEL_MODERATOR, LEVEL_ADMIN, LEVEL_SENIOR):
            await message.reply(f"⚠️ Уровень должен быть 1, 2 или 3 (получено: {lvl}).")
            return
        if len(name) > 30:
            await message.reply("⚠️ Название ранга не должно превышать 30 символов.")
            return
        new_names[lvl] = name
    if not new_names:
        await message.reply("Не удалось разобрать ни одной строки с названием ранга.")
        return
    global custom_level_names
    custom_level_names.update(new_names)
    await db.save_setting("level_names", json.dumps(custom_level_names, ensure_ascii=False))
    await db.add_log("themes_changed", actor_id=message.from_user.id, details="кастомные названия рангов")
    preview = "\n".join(f"{lvl} — {level_name(lvl)}" for lvl in (LEVEL_MODERATOR, LEVEL_ADMIN, LEVEL_SENIOR))
    await message.reply(f"✅ Названия рангов обновлены:\n{preview}")


