async def _call_targets(chat_id: int, only_admins: bool) -> list[dict]:
    """Собирает список целей созыва: либо реальные админы Telegram, либо
    известные боту участники чата (см. ограничение Bot API, описанное в
    README — бот не может получить полный список участников группы).
    Обычный созыв (не калладминс) также не трогает тех, кто сейчас в
    анреге или в активном ресте — они пропускаются, как будто их нет
    (см. db.list_callable_users). Каждому, у кого ещё нет своего
    позывного-эмодзи, он назначается и сохраняется здесь же — созыв
    всегда отображает эмодзи, а не имя/юзернейм."""
    if only_admins:
        try:
            members = await bot.get_chat_administrators(chat_id)
        except Exception:
            return []
        out = []
        for m in members:
            if m.user.is_bot:
                continue
            if await db.is_unregistered(chat_id, m.user.id):
                continue
            emoji = await db.get_or_assign_call_emoji(chat_id, m.user.id, CALL_EMOJI_POOL)
            out.append({"user_id": m.user.id, "full_name": m.user.full_name, "username": m.user.username, "emoji": emoji})
        return out

    # Обычный «созыв» тоже подтягивает реальных админов чата в known_users
    # (они доступны боту всегда, в отличие от рядовых молчаливых участников) —
    # иначе админ, который сам ни разу не писал в чат, был бы не виден
    # созыву, хотя виден команде «калладминс».
    await sync_known_admins(chat_id)
    rows = await db.list_callable_users(chat_id, limit=CALL_MAX_TARGETS)
    out = []
    for row in rows:
        emoji = row.get("emoji") or await db.get_or_assign_call_emoji(chat_id, row["user_id"], CALL_EMOJI_POOL)
        out.append({**row, "emoji": emoji})
    return out


def _call_mention(target: dict) -> str:
    """Упоминание в созыве — всегда кликабельный эмодзи-позывной (реальный тег
    через tg://user?id=, уведомление приходит так же, как от обычного @-меня,
    даже без юзернейма), никогда имя/юзернейм — это выбор оформления, а не
    просто запасной вариант.

    Если позывной — кастомный (Premium) эмодзи (HTML-фрагмент вида
    '<tg-emoji ...>...</tg-emoji>', см. _extract_custom_emoji_html), не
    вкладываем его внутрь <a>...</a> — Telegram официально не гарантирует
    рендер вложенных entity такого вида. Вместо этого кликабельная ссылка
    делается на невидимый символ-разделитель (word joiner), а сам кастомный
    эмодзи ставится рядом обычным текстом — уведомление всё равно приходит
    (сама ссылка на tg://user?id= — это и есть упоминание), а видно при этом
    именно кастомный эмодзи."""
    emoji = target.get("emoji") or CALL_EMOJI_POOL[target["user_id"] % len(CALL_EMOJI_POOL)]
    user_id = target["user_id"]
    if emoji.startswith("<tg-emoji"):
        return f'<a href="tg://user?id={user_id}">\u2060</a>{emoji}'
    return f'<a href="tg://user?id={user_id}">{emoji}</a>'


async def _run_call(chat_id: int, targets: list[dict], header_text: Optional[str]):
    try:
        for i in range(0, len(targets), CALL_BATCH_SIZE):
            batch = targets[i : i + CALL_BATCH_SIZE]
            line = " ".join(_call_mention(t) for t in batch)
            text = f"{html.escape(header_text)}\n{line}" if header_text else line
            try:
                await bot.send_message(chat_id, text)
            except TelegramForbiddenError:
                break
            except TelegramBadRequest:
                pass
            await asyncio.sleep(CALL_BATCH_DELAY)
        try:
            await bot.send_message(chat_id, "📣 Созыв окончен.")
        except Exception:
            pass
    except asyncio.CancelledError:
        try:
            await bot.send_message(chat_id, "⏹ Созыв остановлен.")
        except Exception:
            pass
    finally:
        active_calls.pop(chat_id, None)


CALL_CONFIRM_THRESHOLD = 30  # созывы больше этого размера требуют подтверждения кнопкой


async def _launch_call(chat_id: int, targets: list[dict], header_text: Optional[str], actor_id: int, only_admins: bool) -> None:
    task = asyncio.create_task(_run_call(chat_id, targets, header_text))
    active_calls[chat_id] = task
    await db.add_log(
        "call_start" if not only_admins else "call_admins_start",
        chat_id=chat_id, actor_id=actor_id, details=header_text,
    )


async def _start_call(message: Message, command_key: str, only_admins: bool):
    if not has_level(message.from_user.id, required_level(command_key)):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level(command_key))}» и выше.")
        return
    if message.chat.id in active_calls:
        await message.reply("В этом чате уже идёт созыв. Остановить его: «стоп».")
        return

    header_text = call_commands.call_header(call_command_text(message))

    targets = await _call_targets(message.chat.id, only_admins)
    if not targets:
        if only_admins:
            await message.reply("Не удалось получить список администраторов чата.")
        else:
            await message.reply(
                "Пока не знаю ни одного участника этого чата для созыва — бот запоминает "
                "только тех, кто писал в чат, вступал при боте, или является администратором "
                "(полный список участников недоступен ботам в Telegram)."
            )
        return

    truncated = len(targets) > CALL_MAX_TARGETS
    targets = targets[:CALL_MAX_TARGETS]
    note = f"\n(созываю первых {CALL_MAX_TARGETS} — чтобы не флудить в чате)" if truncated else ""

    if len(targets) > CALL_CONFIRM_THRESHOLD:
        pending_confirmations[message.from_user.id] = {
            "action": "call",
            "chat_id": message.chat.id,
            "targets": targets,
            "header_text": header_text,
            "only_admins": only_admins,
        }
        kb = confirm_kb(
            yes_data=f"call_yes:{message.from_user.id}",
            no_data=f"call_no:{message.from_user.id}",
            yes_text="📣 Да, начать созыв",
        )
        await message.reply(
            confirm_text(
                "Начать большой созыв?",
                [f"👥 Будет упомянуто: {len(targets)} чел.{note}"],
                irreversible=False,
            ),
            reply_markup=kb,
        )
        return

    await message.reply(f"📣 Начинаю созыв: {len(targets)} чел.{note}")
    await _launch_call(message.chat.id, targets, header_text, message.from_user.id, only_admins)


@router.callback_query(F.data.startswith("call_yes:"))
async def confirm_call(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return

    payload = pending_confirmations.pop(initiator_id, None)
    if not payload or payload.get("action") != "call":
        await callback.answer("Запрос устарел, попробуйте снова.", show_alert=True)
        return

    chat_id = payload["chat_id"]
    if chat_id in active_calls:
        await callback.answer("В этом чате уже идёт другой созыв.", show_alert=True)
        try:
            await callback.message.edit_text("Отменено — в этом чате уже запущен другой созыв.")
        except TelegramBadRequest:
            pass
        return
    if not has_level(initiator_id, required_level("call_admins" if payload["only_admins"] else "call_all")):
        await callback.answer("⛔ Недостаточно прав.", show_alert=True)
        return

    targets = payload["targets"]
    try:
        await callback.message.edit_text(f"📣 Начинаю созыв: {len(targets)} чел.")
    except TelegramBadRequest:
        pass
    await _launch_call(chat_id, targets, payload["header_text"], initiator_id, payload["only_admins"])
    await callback.answer()


@router.callback_query(F.data.startswith("call_no:"))
async def cancel_call(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id and not is_admin(callback.from_user.id):
        await callback.answer("Это не ваша кнопка 🙂", show_alert=True)
        return
    pending_confirmations.pop(initiator_id, None)
    try:
        await callback.message.edit_text("Отменено — созыв не запущен.")
    except TelegramBadRequest:
        pass
    await callback.answer()


# Фильтры смотрят на само сообщение (F.func), а не на F.text: команду созыва
# нередко пишут подписью к фото, и по .text её не видно — см. call_command_text.
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.func(lambda m: _is_call_admins_cmd(call_command_text(m))),
)
async def cmd_call_admins(message: Message):
    await _start_call(message, "call_admins", only_admins=True)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.func(lambda m: _is_call_all_cmd(call_command_text(m))),
)
async def cmd_call_all(message: Message):
    await _start_call(message, "call_all", only_admins=False)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.func(lambda m: _is_call_stop_cmd(call_command_text(m))),
)
async def cmd_call_stop(message: Message):
    task = active_calls.get(message.chat.id)
    if not task:
        await message.reply("Сейчас в этом чате нет активного созыва.")
        return
    if not has_level(message.from_user.id, required_level("call_stop")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Остановить созыв может «{level_name(required_level('call_stop'))}» и выше.")
        return
    task.cancel()
    await db.add_log("call_stop", chat_id=message.chat.id, actor_id=message.from_user.id)


# ----------------------------------------------------------------------------
# Модуль «Роли»: ограниченный набор именных ролей чата, которые может носить
# только один человек одновременно. См. ТЗ для полного описания сценариев.
#
# Принятые по умолчанию решения по открытым вопросам ТЗ (можно поменять):
#  1. Бронь сгорает через ROLE_RESERVE_TIMEOUT_HOURS часов (по умолчанию 72) —
#     см. role_reservation_expiry_loop().
#  2. Если бронь «протухла» из-за ручного вмешательства админа — бронирующий
#     просто не получает роль автоматически; ему нужно будет взять любую
#     другую свободную роль через «сменить роль».
#  3. Одобряют новые роли модераторы и выше (LEVEL_MODERATOR) — см. role_approve
#     в COMMAND_REGISTRY, переопределяется командой «право» как обычно.
#  4. Участник группы берёт свободную роль сам, без подтверждения админом —
#     назначение мгновенное (сценарий 1 ТЗ).
#  5. Держателя роли видно только внутри группы; тем, кто пишет боту в личку
#     (то есть потенциально не состоит в группе), имя не показывается —
#     только статус.
#  6. «Сменить роль» работает и в группе, и в личке с ботом (в личке — по
#     единственному управляемому чату, settings.notify_chat_id, как и другие
#     разделы бота, см. cmd_setchat).
#  7. Участник может освободить роль без выбора новой — «снять роль».
# ----------------------------------------------------------------------------
ROLE_STATUS_EMOJI = {"free": "", "taken": "⚔️", "reserved": "🗡"}


def roles_status_emoji(status: str) -> str:
    return ROLE_STATUS_EMOJI.get(status, "⚪")


async def roles_context_chat_id(message) -> Optional[int]:
    """Чат, роли которого имеются в виду. Всегда один и тот же — тот,
    что закреплён командой «чат сюда» (settings.notify_chat_id), — и
    неважно, откуда пришло сообщение: из группы или из личных сообщений
    боту. Раньше при обращении из группы бралась именно та группа, из
    которой писали, из-за чего список ролей мог отличаться от списка
    в личке (если «чат сюда» была написана в другой группе). Теперь
    список ролей всегда один — синхронизирован между чатом и лс."""
    return settings.get("complaint_chat_id")


async def is_chat_member(chat_id: int, user_id: int) -> bool:
    try:
        member = await bot.get_chat_member(chat_id, user_id)
    except Exception:
        return False
    return member.status in ("member", "administrator", "creator", "restricted")


async def roles_list_text(chat_id: int, show_holder: bool) -> str:
    rows = await db.list_roles(chat_id)
    if not rows:
        return "📃 <b>ROLES</b>\n\nВ этом чате пока не настроено ни одной роли (см. «предложить роль» + название)."
    by_category: dict = {}
    for r in rows:
        by_category.setdefault(r["category"], []).append(r)
    header = [
        "📃 <b>ROLES</b>",
        "",
        "занят –⚔️",
        "бронь –🗡",
        "свободно – пустое место",
    ]
    body: list[str] = []
    for category, items in by_category.items():
        if body:
            body.append("")
        if category:
            body.append(f"<code>{html.escape(category)}</code>")
        for r in items:
            emoji = roles_status_emoji(r["status"])
            # номер = id из базы, тот самый, что принимает «роль удалить {номер}»;
            # без него админ ориентировался на позицию в списке и удалял не ту роль
            line = f"<code>{r['id']}</code> {html.escape(r['name'])} –{emoji}"
            if r["status"] == "taken" and show_holder and r["holder_user_id"]:
                line += f" {mention_id(r['holder_user_id'])}"
            body.append(line)
    # Раскрывающаяся цитата (Bot API "blockquote expandable") — список свёрнут
    # по умолчанию и не занимает весь экран, разворачивается тапом по ней.
    return "\n".join(header) + "\n\n<blockquote expandable>" + "\n".join(body) + "</blockquote>"


# ----------------------------------------------------------------------------
# Отдельные списки: «свободные роли» / «занятые роли» — та же группировка по
# категориям, что и в общем списке «роли», но отфильтровано по одному статусу.
# ----------------------------------------------------------------------------
async def roles_status_list_text(chat_id: int, status: str, show_holder: bool) -> str:
    rows = [r for r in await db.list_roles(chat_id) if r["status"] == status]
    title = "🟢 <b>Свободные роли</b>" if status == "free" else "⚔️ <b>Занятые роли</b>"
    if not rows:
        empty = "Свободных ролей сейчас нет." if status == "free" else "Занятых ролей сейчас нет."
        return f"{title}\n\n{empty}"
    by_category: dict = {}
    for r in rows:
        by_category.setdefault(r["category"], []).append(r)
    body: list[str] = []
    for category, items in by_category.items():
        if body:
            body.append("")
        if category:
            body.append(f"<code>{html.escape(category)}</code>")
        for r in items:
            line = html.escape(r["name"])
            if status == "taken" and show_holder and r["holder_user_id"]:
                line += f" — {mention_id(r['holder_user_id'])}"
            body.append(line)
    return f"{title} ({len(rows)})\n\n<blockquote expandable>" + "\n".join(body) + "</blockquote>"


def role_pick_kb(rows: list[dict], page: int, total_pages: int) -> InlineKeyboardMarkup:
    buttons = [[InlineKeyboardButton(text=r["name"][:64], callback_data=f"rpick:{r['id']}")] for r in rows]
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"rpick_page:{page - 1}"))
    if total_pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{total_pages}", callback_data="noop"))
    if page + 1 < total_pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"rpick_page:{page + 1}"))
    if nav:
        buttons.append(nav)
    return InlineKeyboardMarkup(inline_keyboard=buttons)


def _unavailable_roles_block(rows: list[dict]) -> str:
    lines = ["🔒 <b>Занято / забронировано</b> (недоступно для выбора):"]
    for r in rows:
        emoji = roles_status_emoji(r["status"])
        lines.append(f"{html.escape(r['name'])} –{emoji}")
    return "\n".join(lines)


async def role_pick_page(chat_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    free = await db.list_free_roles(chat_id)
    all_rows = await db.list_roles(chat_id)
    unavailable = [r for r in all_rows if r["status"] != "free"]
    unavailable_text = f"\n\n{_unavailable_roles_block(unavailable)}" if unavailable else ""
    if not free:
        return f"Свободных ролей сейчас нет.{unavailable_text}", None
    page = max(page, 0)
    total_pages = max((len(free) + ROLE_PICK_PAGE_SIZE - 1) // ROLE_PICK_PAGE_SIZE, 1)
    page = min(page, total_pages - 1)
    chunk = free[page * ROLE_PICK_PAGE_SIZE: (page + 1) * ROLE_PICK_PAGE_SIZE]
    return f"Свободно ролей: {len(free)}. Выберите одну:{unavailable_text}", role_pick_kb(chunk, page, total_pages)


# ----------------------------------------------------------------------------
# Удаление свободных ролей из списка — админам удобнее тапнуть по названию,
# чем искать номер роли для «роль удалить {id}». Показывает только свободные
# роли (занятые/забронированные удалять отсюда нельзя — их сначала нужно
# снять через «роль снять», чтобы не потерять держателя незаметно).
# ----------------------------------------------------------------------------
def role_delete_kb(rows: list[dict], page: int, total_pages: int) -> InlineKeyboardMarkup:
    buttons = [[InlineKeyboardButton(text=f"🗑 {r['name'][:60]}", callback_data=f"rdel:{r['id']}")] for r in rows]
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"rdel_page:{page - 1}"))
    if total_pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{total_pages}", callback_data="noop"))
    if page + 1 < total_pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"rdel_page:{page + 1}"))
    if nav:
        buttons.append(nav)
    return InlineKeyboardMarkup(inline_keyboard=buttons)


async def role_delete_page(chat_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    free = await db.list_free_roles(chat_id)
    if not free:
        return "Свободных ролей нет — удалять нечего.", None
    page = max(page, 0)
    total_pages = max((len(free) + ROLE_PICK_PAGE_SIZE - 1) // ROLE_PICK_PAGE_SIZE, 1)
    page = min(page, total_pages - 1)
    chunk = free[page * ROLE_PICK_PAGE_SIZE: (page + 1) * ROLE_PICK_PAGE_SIZE]
    return (
        f"🗑 Свободных ролей: {len(free)}. Нажмите, чтобы удалить из списка:",
        role_delete_kb(chunk, page, total_pages),
    )


@router.callback_query(F.data.startswith("rdel_page:"))
async def role_delete_paginate(callback: CallbackQuery):
    if not has_level(callback.from_user.id, required_level("role_delete")):
        await callback.answer(f"⛔ Удалять роли может «{level_name(required_level('role_delete'))}» и выше.", show_alert=True)
        return
    try:
        page = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Чат для ролей не настроен.", show_alert=True)
        return
    text, kb = await role_delete_page(chat_id, page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("rdel:"))
async def role_delete_select(callback: CallbackQuery):
    if not has_level(callback.from_user.id, required_level("role_delete")):
        await callback.answer(f"⛔ Удалять роли может «{level_name(required_level('role_delete'))}» и выше.", show_alert=True)
        return
    try:
        role_id = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Чат для ролей не настроен.", show_alert=True)
        return
    role = await db.get_role(chat_id, role_id)
    if role is None:
        await callback.answer("Эта роль уже удалена.", show_alert=True)
        text, kb = await role_delete_page(chat_id, 0)
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except TelegramBadRequest:
            pass
        return
    if role["status"] != "free":
        # Роль успели занять/забронировать, пока открыто меню — не удаляем
        # молча то, что на самом деле уже не свободно.
        await callback.answer("Роль больше не свободна — удаление отменено. Список обновлён.", show_alert=True)
        text, kb = await role_delete_page(chat_id, 0)
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except TelegramBadRequest:
            pass
        return
    await db.delete_role(chat_id, role_id)
    await db.add_log("role_delete", chat_id=chat_id, actor_id=callback.from_user.id, details=role["name"])
    await callback.answer(f"🗑 Роль «{role['name']}» удалена.")
    text, kb = await role_delete_page(chat_id, 0)
    try:
        if kb is None:
            await callback.message.edit_text(text)
        else:
            await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass



# Первичный импорт готового списка ролей (RP-состав чата на момент внедрения
# модуля) — одноразовая команда для старших админов. Держатель для уже
# «занятых» ролей неизвестен (в исходном списке есть только статус, не
# Telegram id) и остаётся пустым — его нужно проставить вручную по каждому
# персонажу через «роль отдать <название>» (ответом на сообщение игрока).
