@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLUB_DELETE_RE.match(t.strip()))),
)
async def cmd_club_delete(message: Message):
    club_id = int(CLUB_DELETE_RE.match(message.text.strip()).group(1))
    club = await db.get_club(message.chat.id, club_id)
    if club is None:
        await message.reply("Кружок с таким номером не найден.")
        return
    is_owner_actor = club["owner_id"] == message.from_user.id
    if not is_owner_actor:
        min_level = required_level("club_delete_admin")
        if not has_level(message.from_user.id, min_level):
            await message.reply(f"⛔ Удалять чужие кружки может только «{level_name(min_level)}» и выше.")
            return
    kb = confirm_kb(
        yes_data=f"clubdel_yes:{message.from_user.id}:{club_id}",
        no_data=f"clubdel_no:{message.from_user.id}:{club_id}",
        yes_text="✅ Да, удалить",
    )
    members = await db.count_club_members(message.chat.id, club_id)
    await message.reply(
        confirm_text(
            f"Удалить кружок «{club['name']}»?",
            [f"Участников в кружке: <b>{members}</b>."],
        ),
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("clubdel_yes:"))
async def confirm_club_delete(callback: CallbackQuery):
    try:
        _, initiator_str, club_id_str = callback.data.split(":", maxsplit=2)
        initiator_id, club_id = int(initiator_str), int(club_id_str)
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return
    chat_id = callback.message.chat.id
    club = await db.get_club(chat_id, club_id)
    if club is None:
        await callback.answer("Кружок уже удалён.", show_alert=True)
        try:
            await callback.message.edit_text("Кружок уже удалён.")
        except TelegramBadRequest:
            pass
        return
    await db.delete_club(chat_id, club_id)
    await db.add_log("club_delete", chat_id=chat_id, actor_id=initiator_id, details=club["name"])
    try:
        await callback.message.edit_text(f"🗑 Кружок «{html.escape(club['name'])}» удалён.")
    except TelegramBadRequest:
        pass
    await callback.answer("Удалено ✅")


@router.callback_query(F.data.startswith("clubdel_no:"))
async def cancel_club_delete(callback: CallbackQuery):
    try:
        _, initiator_id_str, _ = callback.data.split(":", maxsplit=2)
        initiator_id = int(initiator_id_str)
    except (ValueError, IndexError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Отменить может только тот, кто вызвал команду.", show_alert=True)
        return
    try:
        await callback.message.edit_text("Отменено.")
    except TelegramBadRequest:
        pass
    await callback.answer()


