@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "+зам"),
)
async def cmd_clan_deputy_add(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] != "leader":
        await message.reply("⛔ Назначать замов может только лидер клана.")
        return
    target = await resolve_relationship_target(message)
    if target is None:
        await message.reply("Укажите цель: ответом на сообщение участника клана или его @username.")
        return
    target_membership = await db.get_user_clan(message.chat.id, target.id)
    if target_membership is None or target_membership["id"] != membership["id"]:
        await message.reply("Этот пользователь не состоит в вашем клане.")
        return
    if target_membership["role"] == "leader":
        await message.reply("Лидер не может назначить самого себя замом.")
        return
    await db.set_clan_member_role(message.chat.id, membership["id"], target.id, "deputy")
    await message.reply(f"⭐ {mention_id(target.id, target.full_name, target.username)} назначен(а) замом клана.")


