async def cmd_clan_kick(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] not in ("leader", "deputy"):
        await message.reply("⛔ Исключать из клана может только лидер или зам.")
        return
    target = await resolve_relationship_target(message)
    if target is None:
        await message.reply("Укажите цель: ответом на сообщение участника клана или его @username.")
        return
    target_membership = await db.get_user_clan(message.chat.id, target.id)
    if target_membership is None or target_membership["id"] != membership["id"]:
        await message.reply("Этот пользователь не состоит в вашем клане.")
        return
    if target_membership["role"] == "leader":
        await message.reply("⛔ Нельзя исключить лидера клана.")
        return
    if target_membership["role"] == "deputy" and membership["role"] != "leader":
        await message.reply("⛔ Исключить зама может только лидер клана.")
        return
    await db.kick_clan_member(message.chat.id, membership["id"], target.id)
    await message.reply(
        f"🚪 {mention_id(target.id, target.full_name, target.username)} исключён(а) из клана "
        f"«{html.escape(membership['name'])}»."
    )


