async def cmd_clan_transfer(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] != "leader":
        await message.reply("⛔ Передать клан может только его лидер.")
        return
    target = await resolve_relationship_target(message)
    if target is None:
        await message.reply("Укажите цель: ответом на сообщение участника клана или его @username.")
        return
    if target.id == message.from_user.id:
        await message.reply("Вы уже лидер этого клана 🙂")
        return
    target_membership = await db.get_user_clan(message.chat.id, target.id)
    if target_membership is None or target_membership["id"] != membership["id"]:
        await message.reply("Этот пользователь не состоит в вашем клане.")
        return
    await db.transfer_clan_leadership(message.chat.id, membership["id"], target.id)
    await db.add_log(
        "clan_transfer", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=membership["name"],
    )
    await message.reply(
        f"👑 Лидерство клана «{html.escape(membership['name'])}» передано "
        f"{mention_id(target.id, target.full_name, target.username)}."
    )


