@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_WAR_CHALLENGE_RE.match(t.strip()))),
)
async def cmd_clan_war_challenge(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] not in ("leader", "deputy"):
        await message.reply("⛔ Объявлять войну может только лидер или зам клана.")
        return
    target_clan_id = int(CLAN_WAR_CHALLENGE_RE.match(message.text.strip()).group(1))
    if target_clan_id == membership["id"]:
        await message.reply("Нельзя объявить войну своему же клану 🙂")
        return
    target_clan = await db.get_clan(message.chat.id, target_clan_id)
    if target_clan is None:
        await message.reply("Клан с таким номером не найден.")
        return
    if await db.get_pending_clan_war_for(message.chat.id, membership["id"]) is not None:
        await message.reply("У вашего клана уже есть незавершённый вызов на войну.")
        return
    if await db.get_pending_clan_war_for(message.chat.id, target_clan_id) is not None:
        await message.reply("У этого клана уже есть незавершённый вызов на войну.")
        return
    await db.create_clan_war(message.chat.id, membership["id"], target_clan_id, message.from_user.id)
    await message.reply(
        f"⚔️ Клан «{html.escape(membership['name'])}» вызывает клан «{html.escape(target_clan['name'])}» "
        "на войну!\nЛидеру или заму клана-цели: «война да» — принять, «война нет» — отклонить.\n"
        "Отменить вызов: «война отмена»."
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_WAR_YES_RE.match(t.strip()))),
)
async def cmd_clan_war_yes(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] not in ("leader", "deputy"):
        await message.reply("⛔ Принять вызов может только лидер или зам клана.")
        return
    war = await db.get_pending_clan_war_for(message.chat.id, membership["id"])
    if war is None or war["target_clan_id"] != membership["id"]:
        await message.reply("Нет ожидающего вас вызова на войну.")
        return
    challenger = await db.get_clan(message.chat.id, war["challenger_clan_id"])
    target = await db.get_clan(message.chat.id, war["target_clan_id"])
    await db.delete_clan_war(war["id"])
    if challenger is None or target is None:
        await message.reply("Один из кланов уже не существует — война отменена.")
        return

    roll_challenger, roll_target = random.randint(1, 6), random.randint(1, 6)
    if roll_challenger > roll_target:
        winner, loser = challenger, target
    elif roll_target > roll_challenger:
        winner, loser = target, challenger
    else:
        winner = loser = None

    if winner is not None:
        await db.record_clan_war_result(message.chat.id, winner["id"], loser["id"])
        await db.add_log(
            "clan_war_result", chat_id=message.chat.id, actor_id=message.from_user.id,
            details=f"{winner['name']} > {loser['name']}",
        )
        await message.reply(
            f"⚔️ <b>Война кланов!</b>\n«{html.escape(challenger['name'])}» 🎲{roll_challenger} — "
            f"🎲{roll_target} «{html.escape(target['name'])}»\n\n"
            f"🏆 Победил клан «{html.escape(winner['name'])}»! +3 очка."
        )
    else:
        await db.record_clan_war_result(message.chat.id, None, None)
        await message.reply(
            f"⚔️ <b>Война кланов!</b>\n«{html.escape(challenger['name'])}» 🎲{roll_challenger} — "
            f"🎲{roll_target} «{html.escape(target['name'])}»\n\n🤝 Ничья, очки не начислены."
        )


