@router.callback_query(F.data.startswith("clanmenu_edit:"))
async def clanmenu_edit_cb(callback: CallbackQuery, state: FSMContext):
    clan_id = int(callback.data.split(":", maxsplit=1)[1])
    membership = await db.get_user_clan(callback.message.chat.id, callback.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await callback.answer("⛔ Изменять клан может только его лидер или зам.", show_alert=True)
        return
    await state.set_state(ClanMenuStates.waiting_edit)
    await state.update_data(clan_id=clan_id, menu_chat_id=callback.message.chat.id, menu_message_id=callback.message.message_id)
    try:
        await callback.message.edit_text(
            "✏️ Пришлите новое название клана (и, если нужно, описание отдельной строкой ниже — "
            "первая строка станет названием, остальное — описанием).\n\n"
            f"Максимум {CLAN_NAME_MAX} символов на название и {CLAN_DESCRIPTION_MAX} на описание.",
            reply_markup=_clan_back_kb(clan_id),
        )
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.message(StateFilter(ClanMenuStates.waiting_edit), F.chat.type.in_({"group", "supergroup"}))
async def clanmenu_edit_process(message: Message, state: FSMContext):
    data = await state.get_data()
    clan_id = data.get("clan_id")
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await state.clear()
        return
    name, description = _split_clan_name_and_description(message.text or "")
    if not name:
        await message.reply("Название не может быть пустым. Пришлите название ещё раз.", reply_markup=_clan_back_kb(clan_id))
        return
    await db.update_clan(message.chat.id, clan_id, name=name, description=description)
    await db.add_log("clan_edit", chat_id=message.chat.id, actor_id=message.from_user.id, details=name)
    await state.clear()
    clan = await db.get_clan(message.chat.id, clan_id)
    text = await clan_info_text(message.chat.id, clan) if clan else "Клан обновлён."
    await message.reply(f"✅ Клан обновлён.\n\n{text}", reply_markup=clan_menu_kb(clan_id, membership["role"]))


