@router.callback_query(F.data.startswith("clanmenu_members:"))
async def clanmenu_members_cb(callback: CallbackQuery):
    _, clan_id_str, page_str = callback.data.split(":", maxsplit=2)
    clan_id, page = int(clan_id_str), int(page_str)
    text, kb = await clan_members_text(callback.message.chat.id, clan_id, page)
    rows = kb.inline_keyboard if kb else []
    # переиспользуем пагинацию clan_members_text, но callback у неё "clanmembers_page:" —
    # переносим её кнопки как есть (совместимы), плюс добавляем «назад в меню».
    fixed_rows = []
    for row in rows:
        fixed_rows.append(row)
    fixed_rows.append([InlineKeyboardButton(text="⬅️ Назад в меню клана", callback_data=f"clanmenu_open:{clan_id}")])
    try:
        await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=fixed_rows))
    except TelegramBadRequest:
        pass
    await callback.answer()


# --- Управление участниками (кик / замы / передача лидерства) ---------------

async def clan_manage_page(chat_id: int, clan_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    clan = await db.get_clan(chat_id, clan_id)
    if clan is None:
        return "Клан уже не существует.", None
    page = max(page, 0)
    rows, total = await db.list_clan_members(chat_id, clan_id, CLAN_MANAGE_PAGE_SIZE, page * CLAN_MANAGE_PAGE_SIZE)
    if not rows and page:
        page = 0
        rows, total = await db.list_clan_members(chat_id, clan_id, CLAN_MANAGE_PAGE_SIZE, 0)
    buttons: list[list[InlineKeyboardButton]] = []
    for r in rows:
        mark = _clan_role_mark(r["role"])
        label = await _clan_member_label(chat_id, r["user_id"])
        text = f"{mark} {label}".strip()
        buttons.append([InlineKeyboardButton(text=text[:64], callback_data=f"clanmenu_mpick:{clan_id}:{r['user_id']}:{page}")])
    pages = max((total + CLAN_MANAGE_PAGE_SIZE - 1) // CLAN_MANAGE_PAGE_SIZE, 1)
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"clanmenu_manage:{clan_id}:{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"clanmenu_manage:{clan_id}:{page + 1}"))
    if nav:
        buttons.append(nav)
    buttons.append([InlineKeyboardButton(text="⬅️ Назад в меню клана", callback_data=f"clanmenu_open:{clan_id}")])
    text = f"🛡 <b>Управление участниками клана «{html.escape(clan['name'])}»</b> ({total})\n\nВыберите участника:"
    return text, InlineKeyboardMarkup(inline_keyboard=buttons)


@router.callback_query(F.data.startswith("clanmenu_manage:"))
async def clanmenu_manage_cb(callback: CallbackQuery, state: FSMContext):
    await state.clear()
    _, clan_id_str, page_str = callback.data.split(":", maxsplit=2)
    clan_id, page = int(clan_id_str), int(page_str)
    membership = await db.get_user_clan(callback.message.chat.id, callback.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await callback.answer("⛔ Доступно только лидеру или заму клана.", show_alert=True)
        return
    text, kb = await clan_manage_page(callback.message.chat.id, clan_id, page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("clanmenu_mpick:"))
async def clanmenu_mpick_cb(callback: CallbackQuery):
    _, clan_id_str, target_id_str, page_str = callback.data.split(":", maxsplit=3)
    clan_id, target_id, page = int(clan_id_str), int(target_id_str), int(page_str)
    chat_id = callback.message.chat.id
    membership = await db.get_user_clan(chat_id, callback.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await callback.answer("⛔ Доступно только лидеру или заму клана.", show_alert=True)
        return
    target_membership = await db.get_user_clan(chat_id, target_id)
    if target_membership is None or target_membership["id"] != clan_id:
        await callback.answer("Этот пользователь уже не в клане.", show_alert=True)
        text, kb = await clan_manage_page(chat_id, clan_id, page)
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except TelegramBadRequest:
            pass
        return
    label = await _clan_member_label(chat_id, target_id)
    role_label = {"leader": "👑 Лидер", "deputy": "⭐ Зам", "member": "Участник"}.get(target_membership["role"], "Участник")
    lines = [f"👤 <b>{html.escape(label)}</b>", f"Роль: {role_label}"]
    buttons: list[list[InlineKeyboardButton]] = []
    is_self = target_id == callback.from_user.id
    if membership["role"] == "leader" and not is_self:
        if target_membership["role"] == "member":
            buttons.append([InlineKeyboardButton(text="⭐ Назначить замом", callback_data=f"clanmenu_dep_add:{clan_id}:{target_id}:{page}")])
        elif target_membership["role"] == "deputy":
            buttons.append([InlineKeyboardButton(text="⭐ Снять зама", callback_data=f"clanmenu_dep_remove:{clan_id}:{target_id}:{page}")])
        buttons.append([InlineKeyboardButton(text="👑 Передать лидерство", callback_data=f"clanmenu_transfer:{clan_id}:{target_id}:{page}")])
    can_kick = (
        not is_self
        and target_membership["role"] != "leader"
        and (membership["role"] == "leader" or target_membership["role"] != "deputy")
    )
    if can_kick:
        buttons.append([InlineKeyboardButton(text="🚪 Исключить из клана", callback_data=f"clanmenu_kick:{clan_id}:{target_id}:{page}")])
    buttons.append([InlineKeyboardButton(text="⬅️ Назад к списку", callback_data=f"clanmenu_manage:{clan_id}:{page}")])
    try:
        await callback.message.edit_text("\n".join(lines), reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    except TelegramBadRequest:
        pass
    await callback.answer()


