@router.callback_query(F.data.startswith("clanmenu_kick_yes:"))
async def clanmenu_kick_yes_cb(callback: CallbackQuery):
    _, clan_id_str, target_id_str, page_str, initiator_str = callback.data.split(":", maxsplit=4)
    clan_id, target_id, page, initiator_id = int(clan_id_str), int(target_id_str), int(page_str), int(initiator_str)
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал действие.", show_alert=True)
        return
    chat_id = callback.message.chat.id
    membership = await db.get_user_clan(chat_id, callback.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await callback.answer("⛔ Исключать из клана может только лидер или зам.", show_alert=True)
        return
    target_membership = await db.get_user_clan(chat_id, target_id)
    if target_membership is None or target_membership["id"] != clan_id:
        await callback.answer("Этот пользователь уже не в клане.", show_alert=True)
    elif target_membership["role"] == "leader":
        await callback.answer("⛔ Нельзя исключить лидера клана.", show_alert=True)
        return
    elif target_membership["role"] == "deputy" and membership["role"] != "leader":
        await callback.answer("⛔ Исключить зама может только лидер клана.", show_alert=True)
        return
    else:
        await db.kick_clan_member(chat_id, clan_id, target_id)
        await callback.answer("🚪 Исключён ✅")
    text, kb = await clan_manage_page(chat_id, clan_id, page)
    try:
        await callback.message.edit_text(text, reply_markup=kb)
    except TelegramBadRequest:
        pass


