# --- Война кланов (из меню) --------------------------------------------------

async def clan_war_menu_text(chat_id: int, clan_id: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    clan = await db.get_clan(chat_id, clan_id)
    if clan is None:
        return "Клан уже не существует.", None
    war = await db.get_pending_clan_war_for(chat_id, clan_id)
    buttons: list[list[InlineKeyboardButton]] = []
    if war is None:
        text = f"⚔️ У клана «{html.escape(clan['name'])}» нет активных вызовов на войну."
        buttons.append([InlineKeyboardButton(text="⚔️ Объявить войну", callback_data=f"clanmenu_war_pick:{clan_id}:0")])
    elif war["target_clan_id"] == clan_id:
        challenger = await db.get_clan(chat_id, war["challenger_clan_id"])
        cname = html.escape(challenger["name"]) if challenger else "неизвестный клан"
        text = f"⚔️ Клан «{html.escape(cname)}» вызывает ваш клан на войну!"
        buttons.append([
            InlineKeyboardButton(text="✅ Принять", callback_data=f"clanmenu_war_yes:{clan_id}"),
            InlineKeyboardButton(text="❌ Отклонить", callback_data=f"clanmenu_war_no:{clan_id}"),
        ])
    else:
        target = await db.get_clan(chat_id, war["target_clan_id"])
        tname = html.escape(target["name"]) if target else "неизвестный клан"
        text = f"⚔️ Ваш клан вызвал «{html.escape(tname)}» на войну — ожидаем ответа."
        buttons.append([InlineKeyboardButton(text="🚫 Отменить вызов", callback_data=f"clanmenu_war_cancel:{clan_id}")])
    buttons.append([InlineKeyboardButton(text="⬅️ Назад в меню клана", callback_data=f"clanmenu_open:{clan_id}")])
    return text, InlineKeyboardMarkup(inline_keyboard=buttons)


